window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["水利部"] = {"sanxiashuikudiaoduhekuqushuiziyuanyuhedaoguanliban0d8807":[{"i":1,"n":"第一条","txt":"为加强三峡水库调度和库区水资源与河道管理，合理开发利用和保护水资源，发挥三峡水库的综合效益，根据《中华人民共和国水法》、《中华人民共和国防洪法》和有关法律、法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于三峡水库调度，三峡水利枢纽工程管理和安全运行的监督，三峡库区水资源和河道的管理以及水行政监督检查等。 前款所称三峡水库调度，是指三峡水库汛期的防洪调度以及汛前消落期、汛后蓄水期和枯水运用期的水量调度。"},{"i":3,"n":"第三条","txt":"三峡水库调度和库区水资源与河道管理，应当坚持全面规划，统筹兼顾，科学调度，合理配置水资源，保护水环境，充分发挥三峡水库的防洪、发电、航运、供水、灌溉、旅游等综合功能。"},{"i":4,"n":"第四条","txt":"水利部负责三峡水库水量的统一调度和库区水资源与河道管理的监督工作。 长江水利委员会按照法律、行政法规规定和水利部的授权，负责三峡水库水量的统一调度和库区水资源与河道管理工作。 重庆市、湖北省县级以上地方人民政府水行政主管部门按照规定的权限，负责本行政区域内三峡库区水资源和河道管理工作。 县级以上人民政府有关部门按照职责分工，依法负责三峡库区相关管理工作。"},{"i":5,"n":"第五条","txt":"长江水利委员会应当按照有关规定，商重庆市和湖北省人民政府划定三峡水库管理和保护范围。"},{"i":6,"n":"第六条","txt":"长江水利委员会和有关县级以上地方人民政府水行政主管部门负责三峡水库管理和保护范围内的水行政执法，并按照管理权限，对管辖范围内各项水事活动进行监督检查，依法查处水事违法活动。"},{"i":7,"n":"第七条","txt":"长江水利委员会和有关县级以上地方人民政府水行政主管部门应当建立联合执法制度、信息通报制度和巡查制度。"},{"i":8,"n":"第八条","txt":"三峡水库的防洪调度，应当依据经批准的长江流域防御洪水方案、洪水调度方案和三峡水库洪水调度方案、调度规程、年度汛期调度运用计划以及防洪调度指令进行，并服从国家防汛抗旱指挥机构和长江防汛抗旱指挥机构的调度指挥和监督管理。"},{"i":9,"n":"第九条","txt":"三峡水库的洪水调度方案，应当依据经批准的长江流域防御洪水方案和洪水调度方案，由长江水利委员会组织三峡水利枢纽管理单位编制，征求重庆市、湖北省以及三峡水库下游有关省、直辖市人民政府的意见后，报国家防汛抗旱指挥机构批准。"},{"i":10,"n":"第十条","txt":"三峡水库的年度汛期调度运用计划，应当依据工程规划设计、经批准的长江流域防御洪水方案和洪水调度方案、三峡水库洪水调度方案以及工程实际状况，由三峡水利枢纽管理单位在兴利服从防洪，保证安全的前提下编制，经长江防汛抗旱指挥机构审查同意后，报国家防汛抗旱指挥机构批准。"},{"i":11,"n":"第十一条","txt":"三峡水利枢纽管理单位按照国家防汛抗旱指挥机构或者长江防汛抗旱指挥机构下达的三峡水库防洪调度指令，具体负责三峡水库防洪调度的实施。 三峡水库的发电与航运调度应当服从防洪调度。"},{"i":12,"n":"第十二条","txt":"三峡水库的水量调度，应当依据经批准的三峡库区及下游河段水量分配方案（或者长江流域取水许可总量控制指标）、三峡水库调度规程以及汛前消落期、汛后蓄水期和枯水运用期的水量调度运用计划、水量实时调度指令进行，并服从水利部和长江水利委员会的调度指挥和监督管理。"},{"i":13,"n":"第十三条","txt":"三峡水库的水量分配与调度，应当首先满足城乡居民生活用水，并兼顾农业、工业、生态与环境用水以及航运等需要，注意维持三峡库区及下游河段的合理水位和流量，维护水体的自然净化能力。"},{"i":14,"n":"第十四条","txt":"三峡库区及下游河段水量分配方案，由长江水利委员会商重庆市、湖北省以及三峡水库下游有关省、直辖市人民政府制订，经水利部审查，报国务院或者其授权的部门批准。"},{"i":15,"n":"第十五条","txt":"长江水利委员会应当组织三峡水利枢纽管理单位编制汛前消落期、汛后蓄水期和枯水运用期的水量调度运用计划，征求重庆市、湖北省以及三峡水库下游有关省、直辖市人民政府的意见后，报水利部批准。"},{"i":16,"n":"第十六条","txt":"长江水利委员会应当依据经批准的三峡库区及下游河段水量分配方案（或者长江流域取水许可总量控制指标）以及汛前消落期、汛后蓄水期和枯水运用期的水量调度运用计划，下达水量实时调度指令。 三峡水利枢纽管理单位应当按照水量实时调度指令，具体负责三峡水库水量调度的实施，并按照水量调度指令做好发电计划的安排。"},{"i":17,"n":"第十七条","txt":"三峡库区及下游河段发生干旱灾害时，国家防汛抗旱指挥机构或者长江防汛抗旱指挥机构应当按照旱情紧急情况下的水量调度预案，实施应急水量调度。"},{"i":18,"n":"第十八条","txt":"三峡水库发生重大水污染事件时，长江水利委员会和重庆市、湖北省人民政府水行政主管部门应当按照有关应急预案，及时采取必要的应急调度措施。"},{"i":19,"n":"第十九条","txt":"三峡水利枢纽管理单位应当加强枢纽工程的安全运行与管理养护，按照水库大坝安全管理的有关规定，对枢纽工程进行安全监测和检查，做好枢纽工程的养护修理工作。 水利部或者长江水利委员会应当加强对三峡水利枢纽工程安全运行的监督管理工作。"},{"i":20,"n":"第二十条","txt":"直接从三峡库区取用水资源的，应当按照取水许可和水资源费征收管理的有关规定，向有关县级以上地方人民政府水行政主管部门或者长江水利委员会申请领取取水许可证，缴纳水资源费。 直接从三峡库区取用水资源的，应当按照取水许可和水资源费征收管理的有关规定，向有关县级以上地方人民政府水行政主管部门或者长江水利委员会申请领取取水许可证，缴纳水资源费。在取水许可申请受理阶段需一并提交建设项目水资源论证报告书（表），作为取水许可审批的重要依据。"},{"i":21,"n":"第二十一条","txt":"三峡库区水资源保护规划由水利部组织编制，报国务院批准。 长江水利委员会应当会同重庆市、湖北省人民政府水行政主管部门和环境保护行政主管部门等拟定三峡库区水功能区划，分别经重庆市、湖北省人民政府审查提出意见后，由水利部会同环境保护部审核，报国务院或者其授权的部门批准。"},{"i":22,"n":"第二十二条","txt":"长江水利委员会应当会同重庆市、湖北省人民政府水行政主管部门，按照水功能区对水质的要求和水体的自然净化能力，核定三峡库区的水域纳污能力，向重庆市、湖北省人民政府环境保护行政主管部门提出库区的限制排污总量意见，同时抄报水利部和环境保护部。 经核定的水域纳污能力和限制排污总量意见，是对三峡库区水资源保护实施监督管理的基本依据。"},{"i":23,"n":"第二十三条","txt":"在三峡库区从事水资源的开发利用活动，应当符合三峡库区水功能区划的要求，保护水质。 禁止向三峡库区排放、倾倒工业废渣、垃圾等有毒有害物质。"},{"i":24,"n":"第二十四条","txt":"禁止在饮用水水源保护区内设置入河排污口。 在三峡库区新建、改建或者扩大入河排污口的，应当按照入河排污口监督管理的有关规定，报有关县级以上地方人民政府水行政主管部门或者长江水利委员会审查同意。"},{"i":25,"n":"第二十五条","txt":"有关县级以上地方人民政府水行政主管部门和长江水利委员会应当加强对三峡库区水质状况的监测工作。发现发生重大水污染事件或者发现水质变化可能造成重大水污染事件时，应当及时报告水利部和当地人民政府，并向有关环境保护行政主管部门通报。"},{"i":26,"n":"第二十六条","txt":"在三峡水库管理范围内建设水工程的，应当按照水工程建设规划同意书管理的有关规定，向有关县级以上地方人民政府水行政主管部门或者长江水利委员会申请取得水工程建设规划同意书。"},{"i":27,"n":"第二十七条","txt":"长江水利委员会应当会同重庆市、湖北省人民政府水行政主管部门，编制三峡水库岸线利用管理规划，分别征求重庆市、湖北省人民政府意见后报水利部批准。 三峡水库岸线利用管理规划，应当服从流域综合规划和防洪规划，并与河道整治规划和航道整治规划相协调。"},{"i":28,"n":"第二十八条","txt":"三峡库区有关城乡规划的岸线近水利用线，由三峡库区县级以上地方人民政府水行政主管部门会同有关部门依据经批准的三峡水库岸线利用管理规划确定。 三峡库区河道岸线的利用和建设，应当服从河道整治规划、航道整治规划和三峡水库岸线利用管理规划。河道岸线的界限，由三峡库区县级以上地方人民政府水行政主管部门会同交通等有关部门报县级以上地方人民政府划定。"},{"i":29,"n":"第二十九条","txt":"在三峡水库管理范围内建设桥梁、码头、道路、渡口、管道、缆线、取水、排水等工程设施，应当符合国家规定的防洪标准、三峡水库岸线利用管理规划、航运要求和其他有关的技术要求，其工程建设方案应当按照河道管理范围内建设项目管理的有关规定，报经有关县级以上地方人民政府水行政主管部门或者长江水利委员会审查同意。"},{"i":30,"n":"第三十条","txt":"在三峡水库管理范围内从事采砂活动的，应当按照长江河道采砂管理的有关规定，向重庆市、湖北省人民政府水行政主管部门或者长江水利委员会申请领取河道采砂许可证，缴纳长江河道砂石资源费。"},{"i":31,"n":"第三十一条","txt":"三峡水库消落区的利用，应当服从三峡水库的防洪安全和工程安全，满足库区水土保持、水质保护和生态与环境保护的需要。"},{"i":32,"n":"第三十二条","txt":"在三峡水库管理和保护范围内禁止从事下列活动： （一）围垦库区； （二）倾倒垃圾、渣土； （三）在25度以上陡坡地开垦种植农作物； （四）弃置、堆放阻碍行洪的物体； （五）种植阻碍行洪的林木和高秆作物； （六）其他可能危害水库安全的行为。"},{"i":33,"n":"第三十三条","txt":"凡涉及土石方开挖、填筑或者排弃，可能造成水土流失的生产建设项目，应当依法编制水土保持方案，报县级以上人民政府水行政主管部门审批。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府水行政主管部门和长江水利委员会及其工作人员，在三峡水库调度和库区水资源与河道管理过程中，违反本办法规定的，按照《中华人民共和国水法》、《中华人民共和国防洪法》和《中华人民共和国水污染防治法》等法律、法规的有关规定予以处理。"},{"i":35,"n":"第三十五条","txt":"三峡水利枢纽管理单位违反本办法规定，拒不执行三峡水库防洪调度指令或者水量实时调度指令的，由水利部或者长江水利委员会责令改正；对负有责任的主管人员和其他直接责任人员，由其所在单位或者上级主管机关依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"在三峡库区从事水资源开发利用、河道建设等活动的单位和个人，违反本办法规定的，由县级以上人民政府水行政主管部门或者长江水利委员会按照《中华人民共和国水法》、《中华人民共和国防洪法》、《中华人民共和国水土保持法》和《中华人民共和国水污染防治法》等法律、法规的有关规定予以处罚。"},{"i":37,"n":"第三十七条","txt":"本办法所称三峡库区，是指三峡水库校核洪水位以下受淹没影响的区域。 本办法所称消落区，是指三峡水库正常蓄水位175米的库区土地征用线以下因水库调度运用导致库区临时性出露的陆地。"},{"i":38,"n":"第三十八条","txt":"本办法自公布之日起施行。"}],"ruhepaiwukoujianduguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强入河排污口监督管理，保护水资源，保障防洪和工程设施安全，促进水资源的可持续利用，根据《中华人民共和国水法》、《中华人民共和国防洪法》和《中华人民共和国河道管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在江河、湖泊（含运河、渠道、水库等水域，下同）新建、改建或者扩大排污口，以及对排污口使用的监督管理，适用本办法。 前款所称排污口，包括直接或者通过沟、渠、管道等设施向江河、湖泊排放污水的排污口，以下统称入河排污口；新建，是指入河排污口的首次建造或者使用，以及对原来不具有排污功能或者已废弃的排污口的使用；改建，是指已有入河排污口的排放位置、排放方式等事项的重大改变；扩大，是指已有入河排污口排污能力的提高。入河排污口的新建、改建和扩大，以下统称入河排污口设置。"},{"i":3,"n":"第三条","txt":"入河排污口的设置应当符合水功能区划、水资源保护规划和防洪规划的要求。"},{"i":4,"n":"第四条","txt":"国务院水行政主管部门负责全国入河排污口监督管理的组织和指导工作，县级以上地方人民政府水行政主管部门和流域管理机构按照本办法规定的权限负责入河排污口设置和使用的监督管理工作。 县级以上地方人民政府水行政主管部门和流域管理机构可以委托下级地方人民政府水行政主管部门或者其所属管理单位对其管理权限内的入河排污口实施日常监督管理。"},{"i":5,"n":"第五条","txt":"依法应当办理河道管理范围内建设项目审查手续的，其入河排污口设置由县级以上地方人民政府水行政主管部门和流域管理机构按照河道管理范围内建设项目的管理权限审批；依法不需要办理河道管理范围内建设项目审查手续的， 除下列情况外，其入河排污口设置由入河排污口所在地县级水行政主管部门负责审批： （一）在流域管理机构直接管理的河道（河段）、湖泊上设置入河排污口的，由该流域管理机构负责审批； （二）设置入河排污口需要同时办理取水许可手续的，其入河排污口设置由县级以上地方人民政府水行政主管部门和流域管理机构按照取水许可管理权限审批； （三）设置入河排污口不需要办理取水许可手续，但是按规定需要编制环境影响报告书（表）的，其入河排污口设置由与负责审批环境影响报告书（表）的环境保护部门同级的水行政主管部门审批。其中环境影响报告书（表）需要报国务院环境保护行政主管部门审批的，其入河排污口设置由所在流域的流域管理机"},{"i":6,"n":"第六条","txt":"设置入河排污口的单位（下称排污单位），应当在向环境保护行政主管部门报送建设项目环境影响报告书（表）之前，向有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构提出入河排污口设置申请。 依法需要办理河道管理范围内建设项目审查手续或者取水许可审批手续的，排污单位应当根据具体要求，分别在提出河道管理范围内建设项目申请或者取水许可申请的同时，提出入河排污口设置申请。 依法不需要编制环境影响报告书（表）以及依法不需要办理河道管理范围内建设项目审查手续和取水许可手续的，排污单位应当在设置入河排污口前，向有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构提出入河排污口设置申请。"},{"i":7,"n":"第七条","txt":"设置入河排污口应当提交以下材料： （一）入河排污口设置申请书； （二）建设项目依据文件； （三）入河排污口设置论证报告； （四）其他应当提交的有关文件。 设置入河排污口对水功能区影响明显轻微的，经有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构同意，可以不编制入河排污口设置论证报告，只提交设置入河排污口对水功能区影响的简要分析材料。"},{"i":8,"n":"第八条","txt":"设置入河排污口依法应当办理河道管理范围内建设项目审查手续的，排污单位提交的河道管理范围内工程建设申请中应当包含入河排污口设置的有关内容，不再单独提交入河排污口设置申请书。 设置入河排污口需要同时办理取水许可和入河排污口设置申请的，排污单位提交的建设项目水资源论证报告中应当包含入河排污口设置论证报告的有关内容，不再单独提交入河排污口设置论证报告。"},{"i":9,"n":"第九条","txt":"入河排污口设置论证报告应当包括下列内容： （一）入河排污口所在水域水质、接纳污水及取水现状； （二）入河排污口位置、排放方式； （三）入河污水所含主要污染物种类及其排放浓度和总量； （四）水域水质保护要求，入河污水对水域水质和水功能区的影响； （五）入河排污口设置对有利害关系的第三者的影响； （六）水质保护措施及效果分析； （七）论证结论。 设置入河排污口依法应当办理河道管理范围内建设项目审查手续的，还应当按照有关规定就建设项目对防洪的影响进行论证。"},{"i":10,"n":"第十条","txt":"排污单位应当按照有关技术要求，自行或者委托有关单位编制入河排污口设置论证报告。"},{"i":11,"n":"第十一条","txt":"有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构对申请材料齐全、符合法定形式的入河排污口设置申请，应当予以受理。 对申请材料不齐全或者不符合法定形式的，应当当场或者在五日内一次告知需要补正的全部内容，排污单位按照要求提交全部补正材料的，应当受理；逾期不告知补正内容的，自收到申请材料之日起即为受理。 受理或者不受理入河排污口设置申请，应当出具加盖印章和注明日期的书面凭证。"},{"i":12,"n":"第十二条","txt":"有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构应当自受理入河排污口设置申请之日起二十日内作出决定。同意设置入河排污口的，应当予以公告，公众有权查询；不同意设置入河排污口的，应当说明理由，并告知排污单位享有依法申请行政复议或者提起行政诉讼的权利。对于依法应当编制环境影响报告书（表）的建设项目，还应当将有关决定抄送负责该报告书（表）审批的环境保护行政主管部门。 有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构根据需要，可以对入河排污口设置论证报告组织专家评审，并将所需时间告知排污单位。 入河排污口设置直接关系他人重大利益的，应当告知该利害关系人。排污单位、利害关系人有权进行陈述和申辩。 入河排污口的设置需要听证或者应当听证的，依法举行听证。 有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构作出决定前，应当征求入河排污口所在地有关水行政主管部门的意见。"},{"i":13,"n":"第十三条","txt":"设置入河排污口依法应当办理河道管理范围内建设项目审查手续的，有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构在对该工程建设申请和工程建设对防洪的影响评价进行审查的同时，还应当对入河排污口设置及其论证的内容进行审查，并就入河排污口设置对防洪和水资源保护的影响一并出具审查意见。 设置入河排污口需要同时办理取水许可和入河排污口设置申请的，有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构应当就取水许可和入河排污口设置申请一并出具审查意见。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，不予同意设置入河排污口： （一）在饮用水水源保护区内设置入河排污口的； （二）在省级以上人民政府要求削减排污总量的水域设置入河排污口的； （三）入河排污口设置可能使水域水质达不到水功能区要求的； （四）入河排污口设置直接影响合法取水户用水安全的； （五）入河排污口设置不符合防洪要求的； （六）不符合法律、法规和国家产业政策规定的； （七）其他不符合国务院水行政主管部门规定条件的。"},{"i":15,"n":"第十五条","txt":"同意设置入河排污口的决定应当包括以下内容： （一）入河排污口设置地点、排污方式和对排污口门的要求； （二）特别情况下对排污的限制； （三）水资源保护措施要求； （四）对建设项目入河排污口投入使用前的验收要求； （五）其他需要注意的事项。"},{"i":16,"n":"第十六条","txt":"发生严重干旱或者水质严重恶化等紧急情况时，有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构应当及时报告有关人民政府，由其对排污单位提出限制排污要求。"},{"i":17,"n":"第十七条","txt":"《中华人民共和国水法》施行前已经设置入河排污口的单位，应当在本办法施行后到入河排污口所在地县级人民政府水行政主管部门或者流域管理机构所属管理单位进行入河排污口登记，由其汇总并逐级报送有管辖权的水行政主管部门或者流域管理机构。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府水行政主管部门应当对饮用水水源保护区内的排污口现状情况进行调查，并提出整治方案报同级人民政府批准后实施。"},{"i":19,"n":"第十九条","txt":"县级以上地方人民政府水行政主管部门和流域管理机构应当对管辖范围内的入河排污口设置建立档案制度和统计制度。"},{"i":20,"n":"第二十条","txt":"县级以上地方人民政府水行政主管部门和流域管理机构应当对入河排污口设置情况进行监督检查。被检查单位应当如实提供有关文件、证照和资料。 监督检查机关有为被检查单位保守技术和商业秘密的义务。"},{"i":21,"n":"第二十一条","txt":"未经有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构审查同意，擅自在江河、湖泊设置入河排污口的，依照《中华人民共和国水法》第六十七条第二款追究法律责任。 虽经审查同意，但未按要求设置入河排污口的，依照《中华人民共和国水法》第六十五条第三款和《中华人民共和国防洪法》第五十八条追究法律责任。 在饮用水水源保护区内设置排污口的，以及已设排污口不依照整治方案限期拆除的，依照《中华人民共和国水法》第六十七条第一款追究法律责任。"},{"i":22,"n":"第二十二条","txt":"入河排污口设置和使用的监督管理，本办法有规定的，依照本办法执行；本办法未规定，需要办理河道管理范围内建设项目审查手续的，依照河道管理范围内建设项目管理的有关规定执行。"},{"i":23,"n":"第二十三条","txt":"入河排污口设置申请书和入河排污口登记表等文书格式，由国务院水行政主管部门统一制定。"},{"i":24,"n":"第二十四条","txt":"各省、自治区、直辖市水行政主管部门和流域管理机构，可以根据本办法制定实施细则。"},{"i":25,"n":"第二十五条","txt":"本办法由国务院水行政主管部门负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2005年1月1日起施行。"}],"zhanyongnongyeguangaishuiyuanguanpaigongchengsheshaf8710":[{"i":1,"n":"第一条","txt":"为了加强对农业灌溉水源、灌排工程设施的管理和保护，保障灌排面积的稳定和发展，维护国家、集体和个人管理、经营灌排工程设施的合法权益。根据《中华人民共和国水法》和有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"凡占用国家所有的农业灌溉水源、灌排工程设施，或人为造成农业灌溉水量减少和灌排工程报废或失去部分功能的行为，均适用本办法。"},{"i":3,"n":"第三条","txt":"国家对占用农业灌溉水源、灌排工程设施，或人为造成农业灌溉水量减少和灌排工程报废或失去部分功能的，实行有偿占用与等效替代相结合的原则。"},{"i":4,"n":"第四条","txt":"国务院水行政主管部门负责本办法在全国的组织实施、检查和监督，其所属的流域机构负责本办法在其流域管理范围内组织实施、检查和监督。 县以上地方各级人民政府的水行政主管部门，负责本办法在其管辖和授权管理范围内组织实施、检查和监督。"},{"i":5,"n":"第五条","txt":"占用跨省级行政区受益的农业灌溉水源、灌排工程设施，并涉及到相邻省级行政区利害关系的，占用一方省级水行政主管部门在作出准予行政许可的决定之前，应当征求有关省级水行政主管部门和所在流域机构意见，重大项目还应当征求国务院水行政主管部门意见。"},{"i":6,"n":"第六条","txt":"任何单位或个人占用农业灌溉水源、灌排工程设施，必须事先向有管辖权的或管理权的水行政主管部门提出申请，并提交有关文件资料，经审查批准后，发给同意占用的文件，并报上一级水行政主管部门备案。"},{"i":7,"n":"第七条","txt":"从事各项建设，需要占用农业灌溉水源、灌排工程设施及造成灌排工程报废或失去部分功能的，占用者必须在申报建设项目可行性研究报告时，附具管辖该灌排工程的水行政主管部门批准的文件。"},{"i":8,"n":"第八条","txt":"占用农业灌溉水源、灌排工程设施3年以上的（含3年），占用者应当负责兴建与被占用的农业灌溉水源工程、灌排工程设施效益相当的替代工程。 无条件兴建替代工程的，占用者应当按照新建被占用等量等效替代工程设施的总投资额缴纳开发补偿费。具体补偿数额，由被占用工程的管理单位编制提出占用补偿方案，经法定的评估机构评定后，由管辖被占用农业灌溉水源工程、灌排工程设施的水行政主管部门审核后，报同级物价、财政部门审定。"},{"i":9,"n":"第九条","txt":"由国家财政投资建设的项目，需占用农业灌溉水源、灌排工程设施的，按照水利工程的现值，由占用单位负责补偿。"},{"i":10,"n":"第十条","txt":"国家建设征用城市郊区菜地的，按《国家建设征用菜地缴纳新菜地开发建设基金暂行管理办法》执行，不再交纳开发补偿费。"},{"i":11,"n":"第十一条","txt":"凡占用农业灌溉水源、灌排工程设施（包括占用期3年以上和3年以下），给工程管理单位造成的经济损失，经法定的评估机构评定后，报相应的水行政主管部门和同级物价、财政部门核准，由占用者给予赔偿。并交付被占用的水源工程、灌排工程设施管理单位，用于弥补损失，不得挪作他用。 对3年以下临时占用期满的，占用者必须负责恢复工程被占用前的原貌，经原批准占用的水行政主管部门和有关部门验收合格后，方可办理交接手续。"},{"i":12,"n":"第十二条","txt":"占用农业灌溉水源、灌排工程设施计收的开发补偿费，由县级以上地方水行政主管部门会同财政部门依照管辖权限核收，纳入同级财政预算管理，专款专用。"},{"i":13,"n":"第十三条","txt":"被占用农业灌溉水源、灌排工程设施核收的开发补偿费，专项用于农业灌溉水源工程、灌排工程开发项目和灌排技术设备改造。 使用时由水行政主管部门编制项目计划，报同级财政部门核准后列支。 对于没有开发条件的地区，应当将核收的开发补偿费交上一级财政部门，按照本条第一、二款规定使用。"},{"i":14,"n":"第十四条","txt":"利用开发补偿费兴建的灌溉水源工程和灌排工程设施及其占用者补偿兴建的替代工程的所有权、使用权，由水行政主管部门会同同级财政部门确定。"},{"i":15,"n":"第十五条","txt":"对违反本办法的单位和个人，县以上各级水行政主管部门依照本办法和有关法律、法规的规定，追究其行政法律责任。 对于发生的治安、民事、刑事违法案件，应报公安、司法部门依法查处。"},{"i":16,"n":"第十六条","txt":"本办法的实施细则和占用集体、个人所有和管理的农业灌溉水源、灌排工程设施的补偿办法，由省、自治区、直辖市人民政府结合各地实际情况制定。 国务院水行政主管部门所属的各流域机构可根据本办法制订实施细则、报国务院水行政主管部门批准，并报财政部、国家计委备案后实施。"},{"i":17,"n":"第十七条","txt":"劳改、农垦等其他部门因被占用农业灌溉水源、灌排工程设施核收开发补偿费，应参照本办法执行。"},{"i":18,"n":"第十八条","txt":"凡县以上地方各级政府制定的规章和规范性文件，与本办法不一致的，均应按本办法执行。"},{"i":19,"n":"第十九条","txt":"本办法由国务院水行政主管部门、财政、计划部门负责解释。"},{"i":20,"n":"第二十条","txt":"本办法自发布之日起施行。"}],"qushuixukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强取水许可管理，规范取水的申请、审批和监督管理，根据《中华人民共和国水法》和《取水许可和水资源费征收管理条例》（以下简称《取水条例》）等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"取用水资源的单位和个人以及从事取水许可管理活动的水行政主管部门和流域管理机构及其工作人员，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"水利部负责全国取水许可制度的组织实施和监督管理。 水利部所属流域管理机构（以下简称流域管理机构），依照法律法规和水利部规定的管理权限，负责所管辖范围内取水许可制度的组织实施和监督管理。 县级以上地方人民政府水行政主管部门按照省、自治区、直辖市人民政府规定的分级管理权限，负责本行政区域内取水许可制度的组织实施和监督管理。"},{"i":4,"n":"第四条","txt":"流域内批准取水的总耗水量不得超过国家批准的本流域水资源可利用量。 行政区域内批准取水的总水量，不得超过流域管理机构或者上一级水行政主管部门下达的可供本行政区域取用的水量。"},{"i":5,"n":"第五条","txt":"建设项目取得取水许可申请批准文件，申请人方可兴建取水工程或者设施。"},{"i":6,"n":"第六条","txt":"申请取水并需要设置入河排污口的，申请人在提出取水申请的同时，应当按照《入河排污口监督管理办法》的有关规定一并提出入河排污口设置申请。"},{"i":7,"n":"第七条","txt":"直接取用其他取水单位或者个人的退水或者排水的，应当依法办理取水许可申请。"},{"i":8,"n":"第八条","txt":"需要申请取水的建设项目，申请人应当按照《建设项目水资源论证管理办法》要求，自行或者委托有关单位编制建设项目水资源论证报告书。其中，取水量较少且对周边环境影响较小的建设项目，申请人可不编制建设项目水资源论证报告书，但应当填写建设项目水资源论证表。 不需要编制建设项目水资源论证报告书的情形以及建设项目水资源论证表的格式及填报要求，由水利部规定。"},{"i":9,"n":"第九条","txt":"县级以上人民政府水行政主管部门或者流域管理机构应当组织有关专家对建设项目水资源论证报告书进行审查，并提出书面审查意见，作为审批取水申请的技术依据。"},{"i":10,"n":"第十条","txt":"《取水条例》第十一条第一款第四项所称的国务院水行政主管部门规定的其他材料包括： （一）取水单位或者个人的法定身份证明文件； （二）有利害关系第三者的承诺书或者其他文件； （三）建设项目水资源论证报告书； （四）不需要编制建设项目水资源论证报告书的，应当提交建设项目水资源论证表； （五）利用已批准的入河排污口退水的，应当出具具有管辖权的县级以上地方人民政府水行政主管部门或者流域管理机构的同意文件。"},{"i":11,"n":"第十一条","txt":"申请人应当向具有审批权限的审批机关提出申请。申请利用多种水源，且各种水源的取水审批机关不同的，应当向其中最高一级审批机关提出申请。 申请在地下水限制开采区开采利用地下水的，应当向取水口所在地的省、自治区、直辖市人民政府水行政主管部门提出申请。 取水许可权限属于流域管理机构的，应当向取水口所在地的省、自治区、直辖市人民政府水行政主管部门提出申请；其中，取水口跨省、自治区、直辖市的，应当分别向相关省、自治区、直辖市人民政府水行政主管部门提出申请。"},{"i":12,"n":"第十二条","txt":"取水许可权限属于流域管理机构的，接受申请材料的省、自治区、直辖市人民政府水行政主管部门应当自收到申请之日起20个工作日内提出初审意见，并连同全部申请材料转报流域管理机构。申请利用多种水源，且各种水源的取水审批机关为不同流域管理机构的，接受申请材料的省、自治区、直辖市人民政府水行政主管部门应当同时分别转报有关流域管理机构。 初审意见应当包括建议审批水量、取水和退水的水质指标要求，以及申请取水项目所在水系本行政区域已审批取水许可总量、水功能区水质状况等内容。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府水行政主管部门或者流域管理机构，应当按照《取水条例》第十三条的规定对申请材料进行审查，并作出处理决定。"},{"i":14,"n":"第十四条","txt":"《取水条例》第四条规定的为保障矿井等地下工程施工安全和生产安全必须进行临时应急取（排）水的以及为消除对公共安全或者公共利益的危害临时应急取水的，取水单位或者个人应当在危险排除或者事后10日内，将取水情况报取水口所在地县级以上地方人民政府水行政主管部门或者流域管理机构备案。"},{"i":15,"n":"第十五条","txt":"《取水条例》第四条规定的为农业抗旱和维护生态与环境必须临时应急取水的，取水单位或者个人应当在开始取水前向取水口所在地县级人民政府水行政主管提出申请，经其同意后方可取水；涉及到跨行政区域的，须经共同的上一级地方人民政府水行政主管部门或者流域管理机构同意后方可取水。"},{"i":16,"n":"第十六条","txt":"申请在地下水限制开采区开采利用地下水的，由取水口所在地的省、自治区、直辖市人民政府水行政主管部门负责审批；其中，由国务院或者国务院投资主管部门审批、核准的大型建设项目取用地下水限制开采区地下水的，由流域管理机构负责审批。"},{"i":17,"n":"第十七条","txt":"取水审批机关审批的取水总量，不得超过本流域或者本行政区域的取水许可总量控制指标。 在审批的取水总量已经达到取水许可总量控制指标的流域和行政区域，不得再审批新增取水。"},{"i":18,"n":"第十八条","txt":"取水审批机关应当根据本流域或者本行政区域的取水许可总量控制指标，按照统筹协调、综合平衡、留有余地的原则核定申请人的取水量。所核定的取水量不得超过按照行业用水定额核定的取水量。"},{"i":19,"n":"第十九条","txt":"取水审批机关在审查取水申请过程中，需要征求取水口所在地有关地方人民政府水行政主管部门或者流域管理机构意见的，被征求意见的地方人民政府水行政主管部门或者流域管理机构应当自收到征求意见材料之日起10个工作日内提出书面意见并转送取水审批机关。"},{"i":20,"n":"第二十条","txt":"《取水条例》第二十条第一款第三项、第四项规定的不予批准的情形包括： （一）因取水造成水量减少可能使取水口所在水域达不到水功能区水质标准的； （二）在饮用水水源保护区内设置入河排污口的； （三）退水中所含主要污染物浓度超过国家或者地方规定的污染物排放标准的； （四）退水可能使排入水域达不到水功能区水质标准的； （五）退水不符合排入水域限制排污总量控制要求的； （六）退水不符合地下水回补要求的。"},{"i":21,"n":"第二十一条","txt":"取水审批机关决定批准取水申请的，应当签发取水申请批准文件。取水申请批准文件应当包括下列内容： （一）水源地水量水质状况，取水用途，取水量及其对应的保证率； （二）退水地点、退水量和退水水质要求； （三）用水定额及有关节水要求； （四）计量设施的要求； （五）特殊情况下的取水限制措施； （六）蓄水工程或者水力发电工程的水量调度和合理下泄流量的要求； （七）申请核发取水许可证的事项； （八）其他注意事项。 申请利用多种水源，且各种水源的取水审批机关为不同流域管理机构的，有关流域管理机构应当联合签发取水申请批准文件。"},{"i":22,"n":"第二十二条","txt":"取水工程或者设施建成并试运行满30日的，申请人应当向取水审批机关报送以下材料，申请核发取水许可证： （一）建设项目的批准或者核准文件； （二）取水申请批准文件； （三）取水工程或者设施的建设和试运行情况； （四）取水计量设施的计量认证情况； （五）节水设施的建设和试运行情况； （六）污水处理措施落实情况； （七）试运行期间的取水、退水监测结果。 拦河闸坝等蓄水工程，还应当提交经地方人民政府水行政主管部门或者流域管理机构批准的蓄水调度运行方案。 地下水取水工程，还应当提交包括成井抽水试验综合成果图、水质分析报告等内容的施工报告。 取水申请批准文件由不同流域管理机构联合签发的，申请人可以向其中任何一个流域管理机构报送材料。"},{"i":23,"n":"第二十三条","txt":"取水审批机关应当自收到前条规定的有关材料后20日内，对取水工程或者设施进行现场核验，出具验收意见；对验收合格的，应当核发取水许可证。 取水申请批准文件由不同流域管理机构联合签发的，有关流域管理机构应当联合核验取水工程或者设施；对验收合格的，应当联合核发取水许可证。"},{"i":24,"n":"第二十四条","txt":"同一申请人申请取用多种水源的，经统一审批后，取水审批机关应当区分不同的水源，分别核发取水许可证。"},{"i":25,"n":"第二十五条","txt":"取水审批机关在核发取水许可证时，应当同时明确取水许可监督管理机关，并书面通知取水单位或者个人取水许可监督管理和水资源费征收管理的有关事项。"},{"i":26,"n":"第二十六条","txt":"按照《取水条例》第二十五条规定，取水单位或者个人向原取水审批机关提出延续取水申请时应当提交下列材料： （一）延续取水申请书； （二）原取水申请批准文件和取水许可证。 取水审批机关应当对原批准的取水量、实际取水量、节水水平和退水水质状况以及取水单位或者个人所在行业的平均用水水平、当地水资源供需状况等进行全面评估，在取水许可证届满前决定是否批准延续。批准延续的，应当核发新的取水许可证；不批准延续的，应当书面说明理由。"},{"i":27,"n":"第二十七条","txt":"在取水许可证有效期限内，取水单位或者个人需要变更其名称（姓名）的或者因取水权转让需要办理取水权变更手续的，应当持法定身份证明文件和有关取水权转让的批准文件，向原取水审批机关提出变更申请。取水审批机关审查同意的，应当核发新的取水许可证；其中，仅变更取水单位或者个人名称（姓名）的，可以在原取水许可证上注明。"},{"i":28,"n":"第二十八条","txt":"在取水许可证有效期限内出现下列情形之一的，取水单位或者个人应当重新提出取水申请： （一）取水量或者取水用途发生改变的（因取水权转让引起的取水量改变的情形除外）； （二）取水水源或者取水地点发生改变的； （三）退水地点、退水量或者退水方式发生改变的； （四）退水中所含主要污染物及污水处理措施发生变化的。"},{"i":29,"n":"第二十九条","txt":"连续停止取水满2年的，由原取水审批机关注销取水许可证。由于不可抗力或者进行重大技术改造等原因造成停止取水满2年且取水许可证有效期尚未届满的，经原取水审批机关同意，可以保留取水许可证。"},{"i":30,"n":"第三十条","txt":"取水审批机关应当于每年的1月31日前向社会公告其上一年度新发放取水许可证以及注销和吊销取水许可证的情况。"},{"i":31,"n":"第三十一条","txt":"流域管理机构审批的取水，可以委托其所属管理机构或者取水口所在地省、自治区、直辖市人民政府水行政主管部门实施日常监督管理。 县级以上地方人民政府水行政主管部门审批的取水，可以委托其所属具有管理公共事务职能的单位或者下级地方人民政府水行政主管部门实施日常监督管理。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府水行政主管部门应当按照上一级地方人民政府水行政主管部门规定的时间，向其报送本行政区域下一年度取水计划建议。 省、自治区、直辖市人民政府水行政主管部门应当按照流域管理机构规定的时间，按水系向所在流域管理机构报送本行政区域该水系下一年度取水计划建议。"},{"i":33,"n":"第三十三条","txt":"流域管理机构应当会同有关省、自治区、直辖市人民政府水行政主管部门制定国家确定的重要江河、湖泊的流域年度水量分配方案和年度取水计划，并报水利部备案。 县级以上地方人民政府水行政主管部门应当根据上一级地方人民政府水行政主管部门或者流域管理机构下达的年度水量分配方案和年度取水计划，制定本行政区域的年度水量分配方案和年度取水计划，并报上一级人民政府水行政主管部门或者流域管理机构备案。"},{"i":34,"n":"第三十四条","txt":"取水单位或者个人应当在每年的12月31日前向取水审批机关报送其本年度的取水情况总结（表）和下一年度的取水计划建议（表）。 水力发电工程，还应当报送其下一年度发电计划。 公共供水工程，还应当附具供水范围内重要用水户下一年度用水需求计划。 取水情况总结（表）和取水计划建议（表）的格式及填报要求，由省、自治区、直辖市水行政主管部门或者流域管理机构制定。"},{"i":35,"n":"第三十五条","txt":"取水审批机关应当于每年的1月31日前向取水单位或者个人下达当年取水计划。 取水审批机关下达的年度取水计划的取水总量不得超过取水许可证批准的取水量，并应当明确可能依法采取的限制措施。"},{"i":36,"n":"第三十六条","txt":"新建、改建、扩建建设项目，取水单位或者个人应当在取水工程或者设施经验收合格后、开始取水前30日内，向取水审批机关提出其该年度的取水计划建议。取水审批机关批准后，应当及时向取水单位或者个人下达年度取水计划。"},{"i":37,"n":"第三十七条","txt":"取水单位或者个人应当严格按照批准的年度取水计划取水。因扩大生产等特殊原因需要调整年度取水计划的，应当报经原取水审批机关同意。"},{"i":38,"n":"第三十八条","txt":"取水单位或者个人应当按照取水审批机关下达的年度取水计划核定的退水量，在规定的退水地点退水。 因取水单位或者个人的责任，致使退水量减少的，取水审批机关应当责令其限期改正；期满无正当理由不改正的，取水审批机关可以根据年度取水计划核定的应当退水量相应核减其取水量。"},{"i":39,"n":"第三十九条","txt":"流域管理机构应当商相关省、自治区、直辖市人民政府水行政主管部门及其他相关单位，根据流域下一年度水量分配方案和年度预测来水量、水库蓄水量，按照总量控制、丰增枯减、以丰补枯的原则，统筹考虑地表水和地下水，制订本流域重要水系的年度水量调度计划或者枯水时段的调度方案。 县级以上地方人民政府水行政主管部门应当根据上一级地方人民政府水行政主管部门或者流域管理机构下达的年度水量分配方案和年度水量调度计划，制订本行政区域的年度水量调度计划或者枯水时段的调度方案，并报上一级人民政府水行政主管部门或者流域管理机构备案。"},{"i":40,"n":"第四十条","txt":"县级以上地方人民政府水行政主管部门和流域管理机构按照管理权限，负责所辖范围内的水量调度工作。 蓄水工程或者水力发电工程，应当服从下达的调度计划或者调度方案，确保下泄流量达到规定的控制指标。"},{"i":41,"n":"第四十一条","txt":"取水单位或者个人应当安装符合国家法律法规或者技术标准要求的计量设施，对取水量和退水量进行计量，并定期进行检定或者核准，保证计量设施正常使用和量值的准确、可靠。 利用闸坝等水工建筑物系数或者泵站开机时间、电表度数计算水量的，应当由具有相应资质的单位进行率定。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，可以按照取水设施日最大取水能力计算取（退）水量： （一）未安装取（退）水计量设施的； （二）取（退）水计量设施不合格或者不能正常运行的； （三）取水单位或者个人拒不提供或者伪造取（退）水数据资料的。"},{"i":43,"n":"第四十三条","txt":"取水许可监督管理机关应当按月或者按季抄录取水单位或者个人的实际取水量、退水量或者实际发电量，一式二份，双方签字认可，取水许可监督管理机关和取水单位或者个人各持一份。 取水单位或者个人拒绝签字的，取水许可监督管理机关应当派两名以上工作人员到现场查验，记录存档，并当场留置一份给取水单位或者个人。"},{"i":44,"n":"第四十四条","txt":"取水单位或者个人应当根据国家技术标准对用水情况进行水平衡测试，改进用水工艺或者方法，提高水的重复利用率和再生水利用率。"},{"i":45,"n":"第四十五条","txt":"省、自治区、直辖市人民政府水行政主管部门应当按照流域管理机构的要求，定期报送由其负责监督管理的取水单位或者个人的取用水情况；流域管理机构应当定期将由其所属管理机构负责监督管理的取水单位或者个人的取用水情况抄送省、自治区、直辖市人民政府水行政主管部门。"},{"i":46,"n":"第四十六条","txt":"省、自治区、直辖市人民政府水行政主管部门应当于每年的2月25日前向流域管理机构报送本行政区域相关水系上一年度保有的、新发放的和吊销的取水许可证数量以及审批的取水总量等取水审批的情况。 流域管理机构应当按流域水系分区建立取水许可登记簿，于每年的4月15日前向水利部报送本流域水系分区取水审批情况和取水许可证发放情况。"},{"i":47,"n":"第四十七条","txt":"水行政主管部门和流域管理机构及其工作人员，违反本办法规定的，按照《中华人民共和国水法》和《取水条例》的有关规定予以处理。"},{"i":48,"n":"第四十八条","txt":"取水单位或者个人违反本办法规定的，按照《中华人民共和国水法》和《取水条例》的有关规定予以处罚。"},{"i":49,"n":"第四十九条","txt":"取水单位或者个人违反本办法规定，有下列行为之一的，由取水审批机关责令其限期改正，并可处1000元以下罚款： （一）擅自停止使用节水设施的； （二）擅自停止使用取退水计量设施的； （三）不按规定提供取水、退水计量资料的。"},{"i":50,"n":"第五十条","txt":"本办法自公布之日起施行。1994年6月9日水利部发布的《取水许可申请审批程序规定》（水利部令第4号）、1996年7月29日水利部发布的《取水许可监督管理办法》（水利部令第6号）以及1995年12月23日水利部发布并经1997年12月23日水利部修正的《取水许可水质管理规定》（水政资〔1995〕485号、水政资〔1997〕525号）同时废止。"}],"jianshexiangmushuiziyuanlunzhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进水资源的优化配置和可持续利用，保障建设项目的合理用水要求，根据《取水许可和水资源费征收管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"对于直接从江河、湖泊或地下取水并需申请取水许可证的新建、改建、扩建的建设项目（以下简称建设项目），建设项目业主单位（以下简称业主单位）应当按照本办法的规定进行建设项目水资源论证，编制建设项目水资源论证报告书。"},{"i":3,"n":"第三条","txt":"建设项目利用水资源，必须遵循合理开发、节约使用、有效保护的原则；符合江河流域或区域的综合规划及水资源保护规划等专项规划；遵守经批准的水量分配方案或协议。"},{"i":4,"n":"第四条","txt":"县级以上人民政府水行政主管部门负责建设项目水资源论证工作的组织实施和监督管理。"},{"i":5,"n":"第五条","txt":"业主单位应当按照建设项目水资源论证报告书编制基本要求，自行或者委托有关单位对其建设项目进行水资源论证。"},{"i":6,"n":"第六条","txt":"建设项目水资源论证报告书，应当包括下列主要内容： （一）建设项目概况； （二）取水水源论证； （三）用水合理性论证； （四）退（排）水情况及其对水环境影响分析； （五）对其他用水户权益的影响分析； （六）其他事项。 建设项目水资源论证报告书编制基本要求见附件。"},{"i":7,"n":"第七条","txt":"业主单位在向具有审批权限的取水许可审批机关提交取水许可申请材料时，应当一并提交建设项目水资源论证报告书，作为取水许可审批的重要依据。未提交建设项目水资源论证报告书且经一次告知仍不补正的，视为放弃取水许可申请。"},{"i":8,"n":"第八条","txt":"建设项目水资源论证报告书，由具有审查权限的水行政主管部门或流域管理机构组织有关专家和单位进行审查，并根据取水的急需程度适时提出审查意见。 建设项目水资源论证报告书技术审查意见和审定后的报告书是审批取水许可申请的重要依据。"},{"i":9,"n":"第九条","txt":"水利部或流域管理机构负责对以下建设项目水资源论证报告书进行审查： （一）水利部授权流域管理机构审批取水许可申请的建设项目； （二）兴建大型地下水集中供水水源地（日取水量5万吨以上）的建设项目。 其他建设项目水资源论证报告书的分级审查权限，由省、自治区、直辖市人民政府水行政主管部门确定。"},{"i":10,"n":"第十条","txt":"水行政主管部门或流域管理机构应严格依据国家发布的有关政策法规、技术标准、规程和规范，客观、公正、合理地组织报告书审查工作，提出技术审查意见，并对审查结论的真实性、科学性负责。"},{"i":11,"n":"第十一条","txt":"建设项目水资源论证报告书审查通过后，有下列情况之一的，业主单位应重新或补充编制水资源论证报告书，并提交原审查机关重新审查： （一）建设项目的性质、规模、地点或取水标的发生重大变化的； （二）自审查通过之日起满三年，建设项目未批准的。"},{"i":12,"n":"第十二条","txt":"业主单位或者其委托的从事建设项目水资源论证工作的单位，在建设项目水资源论证工作中弄虚作假的，由水行政主管部门处违法所得3倍以下，最高不超过3万元的罚款。违反《取水许可和水资源费征收管理条例》第五十条的，依照其规定处罚。"},{"i":13,"n":"第十三条","txt":"从事建设项目水资源论证报告书审查的工作人员滥用职权，玩忽职守，造成重大损失的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"建设项目取水量较少且对周边影响较小的，可不编制建设项目水资源论证报告书。具体要求由省、自治区、直辖市人民政府水行政主管部门规定。"},{"i":15,"n":"第十五条","txt":"本办法由水利部负责解释。"},{"i":16,"n":"第十六条","txt":"本办法自2002年5月1日起施行。 附件： 建设项目水资源论证报告书编制基本要求 本附件是对建设项目水资源论证报告书编制的基本要求。由于建设项目规模不等，取水水源类型不同，水资源论证的内容也有区别。承担建设项目水资源论证报告书编制的单位，可根据项目及取水水源类型，选择其中相应内容开展论证工作。 一、总论 1、编制论证报告书的目的； 2、编制依据； 3、项目选址情况，有关部门审查意见； 4、项目建议书中提出的取水水源与取水地点； 5、论证委托书或合同， 委托单位与承担单位。 二、建设项目概况 1、建设项目名称、项目性质； 2、建设地点，占地面积和土地利用情况； 3、建设规模及分期实施意见，职工人数与生活区建设； 4、主要产品及用水工艺； 5、建设项目用水保证率及水位、水量、水质、水温等要求，取水地点，水源类型，取水口设置情况； 6、建设项目废污水浓度、排放方式、排放总量、排污口设置情况。"}],"shuilijibenjianshexiangmujichazanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范水利基本建设行为，加强国家水利基本建设投资管理，提高建设资金使用效益，确保工程质量，保证稽察工作客观、公正、高效开展，特制定本办法。"},{"i":2,"n":"第二条","txt":"水利基本建设项目稽察的基本任务是对水利工程建设活动全过程进行监督检查。"},{"i":3,"n":"第三条","txt":"对国家出资为主的水利基本建设项目的稽察，适用本办法。"},{"i":4,"n":"第四条","txt":"水利部所属流域机构和地方各级水行政主管部门应对稽察工作给予协助和支持。 项目法人及所有参建单位都应配合水利基本建设稽察工作。并提供必要的工作条件。"},{"i":5,"n":"第五条","txt":"水利部水利工程建设稽察办公室（以下简称“稽察办”）负责水利基本建设项目的稽察工作，其主要职责是： （一）开展对水利基本建设项目的稽察； （二）对水利建设项目违规违纪事件进行调查； （三）负责稽察特派员的日常管理； （四）配合国家计委重大建设项目稽察特派员办公室工作； （五）承担部交办的其它任务。"},{"i":6,"n":"第六条","txt":"稽察工作实行稽察特派员负责制。稽察特派员主要职责是： （一）全面负责稽察项目的稽察工作； （二）迅速、真实、准确、公正地评价被稽察项目情况，并提出建议和整改意见，以书面形式及时向稽察办提交稽察报告； （三）督促有关整改意见的落实； （四）完成稽察办交办的其他任务。 根据需要，一名稽察特派员可配若干名专家或工作人员协助其工作。"},{"i":7,"n":"第七条","txt":"稽察特派员由水利部聘任。聘期一般为一年，可以连聘。 稽察特派员应当具备下列条件： （一）熟悉国家有关政策、法律、法规、规章和技术标准； （二）具有较强的组织管理、综合分析和判断能力； （三）具有较丰富的水利工程建设和施工管理、投资计划、财会、审计等方面的综合管理知识和经验； （四）坚持原则，清正廉洁，忠实履行职责，自觉维护国家利益； （五）具有高级专业技术职称； （六）身体健康，年龄在65岁以下。"},{"i":8,"n":"第八条","txt":"稽察人员执行稽察任务时遵循回避原则，不得稽察曾直接管辖区城内的建设项目，也不得稽察与其有利害关系的人担任高级管理职务的建设项目。 稽察人员不得在被稽察项目及其相关单位兼职。"},{"i":9,"n":"第九条","txt":"稽察人员与被稽察项目是监督与被监督的关系。稽察人员不参与、不干预被稽察项目的建设活动。"},{"i":10,"n":"第十条","txt":"稽察人员依照本办法的规定，按照国家有关政策、法律、法规、规章和技术标准等，对项目基本建设活动进行稽察。"},{"i":11,"n":"第十一条","txt":"对建设项目的稽察，主要包括项目前期工作与设计工作、项目建设管理、项目计划下达与执行、资金使用、工程质量、国家有关政策、法律、法规、规章和技术标准执行情况等方面的内容。"},{"i":12,"n":"第十二条","txt":"对项目前期工作、设计工作的稽察，包括项目报建，初步设计审批，可研报告审批，前期施工准备，总概算批复，建设资金落实情况；勘测设计单位质量保证体系，设计深度和质量，设计变更，现场设计服务，供图进度与质量等情况。"},{"i":13,"n":"第十三条","txt":"对项目建设管理的稽察，包括项目法人责任制、招标投标制、建设监理制和合同管理实施情况，设计、监理、施工、设备材料供应等有关单位资质和人员资格等情况。"},{"i":14,"n":"第十四条","txt":"对建设项目计划下达与执行的稽察，包括计划管理和年度计划下达与执行，投资控制与概预算执行，工程投资完成情况、工程进度、形象面貌和实物工程量完成情况，汛前施工安排和安全度汛措施等方面情况。"},{"i":15,"n":"第十五条","txt":"对资金使用的稽察，包括资金来源、到位和使用，合同执行和费用结算，各项费用支出，财务制度执行等情况。"},{"i":16,"n":"第十六条","txt":"对工程质量的稽察，包括参建各单位的质量保证体系，工程质量管理，质量检测，质量评定，原材料、中间产品和设备质量检验数据和资料情况，工程质量现状和质量事故处理情况，工程验收等情况。"},{"i":17,"n":"第十七条","txt":"稽察工作结束后，稽察特派员须对项目建设活动进行评价，并提出整改意见或处理建议。"},{"i":18,"n":"第十八条","txt":"根据工作需要，稽察特派员可以就第十一条所述部分内容或其他事项组织专项稽察。"},{"i":19,"n":"第十九条","txt":"稽察办根据年度水利基本建设计划安排，结合工程规模、工程投资结构、工程重要性和工程建设情况等因素，选定稽察项目，下达稽察通知书。"},{"i":20,"n":"第二十条","txt":"在某一时段内，为了保证稽察工作的连贯性，每个稽察特派员可负责相对固定区域内的水利基本建设项目的稽察工作。"},{"i":21,"n":"第二十一条","txt":"被稽察项目的项目法人向有关主管部门报送建设管理、计划执行和资金使用情况等方面的文件、报表及有关资料时，应同时抄送稽察办。"},{"i":22,"n":"第二十二条","txt":"稽察特派员根据稽察办部署和稽察项目有关情况，制订项目稽察工作提纲，深入项目现场进行稽察。"},{"i":23,"n":"第二十三条","txt":"现场稽察结束，稽察特派员应就稽察情况与项目法人或现场管理机构交换意见，通报稽察情况。"},{"i":24,"n":"第二十四条","txt":"稽察特派员应及时向稽察办提交事实清楚、客观公正的稽察报告。"},{"i":25,"n":"第二十五条","txt":"对水利基本建设项目实施稽察，可以采取事先通知与不通知两种方式。"},{"i":26,"n":"第二十六条","txt":"稽察人员执行稽察任务时应出示证明其身份的有效证件或文件。"},{"i":27,"n":"第二十七条","txt":"稽察人员开展稽察工作，可以采取下列方法和手段： （一）听取建设项目法人就有关建设管理、前期工作、计划执行、资金使用、工程施工和工程质量等情况的汇报，并可以提出质询； （二）查阅建设项目有关文件、合同、记录、报表、帐簿及其他资料，并可以要求有关单位和人员作出必要的说明，可以合法取得或复制有关的文件、资料； （三）查勘工程施工现场、检查工程质量，必要时，可以责令有关方面进行质量检测； （四）在任何时间进入施工、仓储、办公、检测、试验等与建设项目有关的场所或地点，向建设项目设计、施工、监理、咨询及其他相关单位和人员了解情况，听取意见，进行查验、取证、质询； （五）对发现的问题进行延伸调查、取证、核实。"},{"i":28,"n":"第二十八条","txt":"稽察特派员在稽察工作中发现紧急情况，应立即向稽察办专项报告。"},{"i":29,"n":"第二十九条","txt":"稽察报告一般应当包括下列内容： （一）项目前期工作、设计工作情况及分析评价； （二）项目建设管理情况及分析评价； （三）项目计划下达与执行情况及分析评价； （四）项目资金使用情况及分析评价； （五）工程质量保证体系和工程质量现状等情况及分析评价； （六）存在的主要问题及整改建议； （七）稽察办要求报告的或者稽察特派员认为需要报告的其他内容。 专项稽察报告的内容根据专项稽察工作具体任务和要求确定。"},{"i":30,"n":"第三十条","txt":"稽察报告由稽察特派员签署，经由稽察办分别报送部有关司局征求意见。 根据稽察报告和有关司局意见，稽察办依照规定程序下发整改意见通知书，并向有关单位提出处理建议。"},{"i":31,"n":"第三十一条","txt":"项目法人及有关单位必须按整改意见通知书的要求进行整改，并在规定时间内将整改情况向稽察办报告。"},{"i":32,"n":"第三十二条","txt":"对严重违反国家基本建设有关规定的项目，根据情节轻重提出以下单项或多项处理建议： （一）通报批评； （二）建议有关部门降低设计、监理、施工、咨询、设备材料供应等有关单位的资质，吊销其资质证书； （三）建议有关部门暂停拨付项目建设资金； （四）建议有关部门批准暂停施工； （五）建议有关部门追究主要责任人员的责任。"},{"i":33,"n":"第三十三条","txt":"对项目的整改情况，稽察特派员应适时跟踪落实，必要时可进行再次稽察。"},{"i":34,"n":"第三十四条","txt":"稽察人员依法执行公务受法律保护，任何组织和个人不得拒绝、阻碍稽察人员依法执行公务，不得打击报复稽察人员。"},{"i":35,"n":"第三十五条","txt":"稽察人员开展稽察工作有以下权利： （一）向项目法人及参建单位、相关人员调查、了解情况和取证； （二）要求被稽察项目的项目法人及参建单位提供并查阅与建设项目有关的文件、资料、合同、数据、帐簿、凭证、报表，依法复制、录音、拍照或摄像有关的证词、证据； （三）在任何时间进入与建设项目相关的场所或地点，进行查验、取证、质询等工作。"},{"i":36,"n":"第三十六条","txt":"稽察人员开展稽察工作，应当履行　以下义务： （一）依法行使职责，坚持原则，秉公办事，自觉　维护国家利益； （二）深入项目现场，客观公正、实事求是地反映　建设的情况和问题，认真完成稽察任务； （三）自觉遵守廉洁自律的有关规定； （四）保守国家秘密和被稽察单位的商业秘密。"},{"i":37,"n":"第三十七条","txt":"稽察人员为保证水利工程质量、提高投资效益、避免重大质量事故做出重要贡献的，给予表彰。"},{"i":38,"n":"第三十八条","txt":"稽察人员有下列行为之一的，解除聘任；视情节轻重给予党纪、政纪处分；构成犯罪的，依法追究法律责任： （一）对被稽察项目的重大问题隐匿不报，严重失职的， （二）与被稽察项目有关的单位串通，编造虚假稽察报告的； （三）干预被稽察项目的建设管理活动，致使被稽察项目的正常工作受到损害的； （四）接受与被稽察项目有关单位的馈赠、报酬等费用，参加有可能影响公正履行职责的宴请、娱乐、旅游等违纪活动，或者通过稽察工作为自己、亲友及他人谋取私利的。"},{"i":39,"n":"第三十九条","txt":"被稽察单位应自觉按照稽察办的要求及时提供或报送有关文件、资料。"},{"i":40,"n":"第四十条","txt":"被稽察单位应积极协助稽察人员的工作，如实提供稽察工作需要的文件、资料、数据、合同、帐簿、凭证和报表，不得拒绝、隐匿和弄虚作假。"},{"i":41,"n":"第四十一条","txt":"对稽察提出的问题，被稽察单位可以向稽察人员进行申辩；对整改或处理意见有异议的，可以向稽察办或水利部提出申诉。申诉期间，仍执行原整改或处理意见。"},{"i":42,"n":"第四十二条","txt":"被稽察项目的项目法人及有关单位发现稽察人员有本办法第三十八条所列行为时，有权向稽察办报告。"},{"i":43,"n":"第四十三条","txt":"被稽察项目有关单位和人员有下列行为之一的，对单位主要负责人员和直接责任人员，由稽察办建议有关方面给予党纪政纪处分；构成犯罪的，移交司法机关依法追究法律责任： （一）拒绝、阻碍稽察人员依法执行稽察任务或者打击报复稽察人员的； （二）拒不提供与项目建设有关的文件、资料、合同、协议、财务状况和建设管理馈况的资料或者隐匿、伪报资料，或提供假情况、假证词的； （三）可能影响稽察人员公正履行职责的其他行为。"},{"i":44,"n":"第四十四条","txt":"已按本办法规定进行稽察的基本建设项目，水利部一般不再组织内容重复的检查。"},{"i":45,"n":"第四十五条","txt":"本办法由水利部负责解释。"},{"i":46,"n":"第四十六条","txt":"本办法自颁布之日起施行，《水利工程建设项目巡视检查办法》同时废止。"}],"shuiligongchengjiansheanquanshengchanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强水利工程建设安全生产监督管理，明确安全生产责任，防止和减少安全生产事故，保障人民群众生命和财产安全，根据《中华人民共和国安全生产法》、《建设工程安全生产管理条例》等法律、法规，结合水利工程的特点，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于水利工程的新建、扩建、改建、加固和拆除等活动及水利工程建设安全生产的监督管理。 前款所称水利工程，是指防洪、除涝、灌溉、水力发电、供水、围垦等（包括配套与附属工程）各类水利工程。"},{"i":3,"n":"第三条","txt":"水利工程建设安全生产管理，坚持安全第一，预防为主的方针。"},{"i":4,"n":"第四条","txt":"发生生产安全事故，必须查清事故原因，查明事故责任，落实整改措施，做好事故处理工作，并依法追究有关人员的责任。"},{"i":5,"n":"第五条","txt":"项目法人（或者建设单位，下同）、勘察（测）单位、设计单位、施工单位、建设监理单位及其他与水利工程建设安全生产有关的单位，必须遵守安全生产法律、法规和本规定，保证水利工程建设安全生产，依法承担水利工程建设安全生产责任。"},{"i":6,"n":"第六条","txt":"项目法人在对施工投标单位进行资格审查时，应当对投标单位的主要负责人、项目负责人以及专职安全生产管理人员是否经水行政主管部门安全生产考核合格进行审查。有关人员未经考核合格的，不得认定投标单位的投标资格。"},{"i":7,"n":"第七条","txt":"项目法人应当向施工单位提供施工现场及施工可能影响的毗邻区域内供水、排水、供电、供气、供热、通讯、广播电视等地下管线资料，气象和水文观测资料，拟建工程可能影响的相邻建筑物和构筑物、地下工程的有关资料，并保证有关资料的真实、准确、完整，满足有关技术规范的要求。对可能影响施工报价的资料，应当在招标时提供。"},{"i":8,"n":"第八条","txt":"项目法人不得调减或挪用批准概算中所确定的水利工程建设有关安全作业环境及安全施工措施等所需费用。工程承包合同中应当明确安全作业环境及安全施工措施所需费用。"},{"i":9,"n":"第九条","txt":"项目法人应当组织编制保证安全生产的措施方案，并自工程开工之日起15个工作日内报有管辖权的水行政主管部门、流域管理机构或者其委托的水利工程建设安全生产监督机构（以下简称安全生产监督机构）备案。建设过程中安全生产的情况发生变化时，应当及时对保证安全生产的措施方案进行调整，并报原备案机关。 保证安全生产的措施方案应当根据有关法律法规、强制性标准和技术规范的要求并结合工程的具体情况编制，应当包括以下内容： （一）项目概况； （二）编制依据； （三）安全生产管理机构及相关负责人； （四）安全生产的有关规章制度制定情况； （五）安全生产管理人员及特种作业人员持证上岗情况等； （六）生产安全事故的应急救援预案； （七）工程度汛方案、措施； （八）其他有关事项。"},{"i":10,"n":"第十条","txt":"项目法人在水利工程开工前，应当就落实保证安全生产的措施进行全面系统的布置，明确施工单位的安全生产责任。"},{"i":11,"n":"第十一条","txt":"项目法人应当将水利工程中的拆除工程和爆破工程发包给具有相应水利水电工程施工资质等级的施工单位。 项目法人应当在拆除工程或者爆破工程施工15日前，将下列资料报送水行政主管部门、流域管理机构或者其委托的安全生产监督机构备案： （一）拟拆除或拟爆破的工程及可能危及毗邻建筑物的说明； （二）施工组织方案； （三）堆放、清除废弃物的措施； （四）生产安全事故的应急救援预案。"},{"i":12,"n":"第十二条","txt":"勘察（测）单位应当按照法律、法规和工程建设强制性标准进行勘察（测），提供的勘察（测）文件必须真实、准确，满足水利工程建设安全生产的需要。 勘察（测）单位在勘察（测）作业时，应当严格执行操作规程，采取措施保证各类管线、设施和周边建筑物、构筑物的安全。 勘察（测）单位和有关勘察（测）人员应当对其勘察（测）成果负责。"},{"i":13,"n":"第十三条","txt":"设计单位应当按照法律、法规和工程建设强制性标准进行设计，并考虑项目周边环境对施工安全的影响，防止因设计不合理导致生产安全事故的发生。 设计单位应当考虑施工安全操作和防护的需要，对涉及施工安全的重点部位和环节在设计文件中注明，并对防范生产安全事故提出指导意见。 采用新结构、新材料、新工艺以及特殊结构的水利工程，设计单位应当在设计中提出保障施工作业人员安全和预防生产安全事故的措施建议。 设计单位和有关设计人员应当对其设计成果负责。 设计单位应当参与与设计有关的生产安全事故分析，并承担相应的责任。"},{"i":14,"n":"第十四条","txt":"建设监理单位和监理人员应当按照法律、法规和工程建设强制性标准实施监理，并对水利工程建设安全生产承担监理责任。 建设监理单位应当审查施工组织设计中的安全技术措施或者专项施工方案是否符合工程建设强制性标准。 建设监理单位在实施监理过程中，发现存在生产安全事故隐患的，应当要求施工单位整改；对情况严重的，应当要求施工单位暂时停止施工，并及时向水行政主管部门、流域管理机构或者其委托的安全生产监督机构以及项目法人报告。"},{"i":15,"n":"第十五条","txt":"为水利工程提供机械设备和配件的单位，应当按照安全施工的要求提供机械设备和配件，配备齐全有效的保险、限位等安全设施和装置，提供有关安全操作的说明，保证其提供的机械设备和配件等产品的质量和安全性能达到国家有关技术标准。"},{"i":16,"n":"第十六条","txt":"施工单位从事水利工程的新建、扩建、改建、加固和拆除等活动，应当具备国家规定的注册资本、专业技术人员、技术装备和安全生产等条件，依法取得相应等级的资质证书，并在其资质等级许可的范围内承揽工程。"},{"i":17,"n":"第十七条","txt":"施工单位应当依法取得安全生产许可证后，方可从事水利工程施工活动。"},{"i":18,"n":"第十八条","txt":"施工单位主要负责人依法对本单位的安全生产工作全面负责。施工单位应当建立健全安全生产责任制度和安全生产教育培训制度，制定安全生产规章制度和操作规程，保证本单位建立和完善安全生产条件所需资金的投入，对所承担的水利工程进行定期和专项安全检查，并做好安全检查记录。 施工单位的项目负责人应当由取得相应执业资格的人员担任，对水利工程建设项目的安全施工负责，落实安全生产责任制度、安全生产规章制度和操作规程，确保安全生产费用的有效使用，并根据工程的特点组织制定安全施工措施，消除安全事故隐患，及时、如实报告生产安全事故。"},{"i":19,"n":"第十九条","txt":"施工单位在工程报价中应当包含工程施工的安全作业环境及安全施工措施所需费用。对列入建设工程概算的上述费用，应当用于施工安全防护用具及设施的采购和更新、安全施工措施的落实、安全生产条件的改善，不得挪作他用。"},{"i":20,"n":"第二十条","txt":"施工单位应当设立安全生产管理机构，按照国家有关规定配备专职安全生产管理人员。施工现场必须有专职安全生产管理人员。 专职安全生产管理人员负责对安全生产进行现场监督检查。发现生产安全事故隐患，应当及时向项目负责人和安全生产管理机构报告；对违章指挥、违章操作的，应当立即制止。"},{"i":21,"n":"第二十一条","txt":"施工单位在建设有度汛要求的水利工程时，应当根据项目法人编制的工程度汛方案、措施制定相应的度汛方案，报项目法人批准；涉及防汛调度或者影响其它工程、设施度汛安全的，由项目法人报有管辖权的防汛指挥机构批准。"},{"i":22,"n":"第二十二条","txt":"垂直运输机械作业人员、安装拆卸工、爆破作业人员、起重信号工、登高架设作业人员等特种作业人员，必须按照国家有关规定经过专门的安全作业培训，并取得特种作业操作资格证书后，方可上岗作业。"},{"i":23,"n":"第二十三条","txt":"施工单位应当在施工组织设计中编制安全技术措施和施工现场临时用电方案，对下列达到一定规模的危险性较大的工程应当编制专项施工方案，并附具安全验算结果，经施工单位技术负责人签字以及总监理工程师核签后实施，由专职安全生产管理人员进行现场监督： （一）基坑支护与降水工程； （二）土方和石方开挖工程； （三）模板工程； （四）起重吊装工程； （五）脚手架工程； （六）拆除、爆破工程； （七）围堰工程； （八）其他危险性较大的工程。 对前款所列工程中涉及高边坡、深基坑、地下暗挖工程、高大模板工程的专项施工方案，施工单位还应当组织专家进行论证、审查。"},{"i":24,"n":"第二十四条","txt":"施工单位在使用施工起重机械和整体提升脚手架、模板等自升式架设设施前，应当组织有关单位进行验收，也可以委托具有相应资质的检验检测机构进行验收；使用承租的机械设备和施工机具及配件的，由施工总承包单位、分包单位、出租单位和安装单位共同进行验收。验收合格的方可使用。"},{"i":25,"n":"第二十五条","txt":"施工单位的主要负责人、项目负责人、专职安全生产管理人员应当经水行政主管部门对其安全生产知识和管理能力考核合格。 施工单位应当对管理人员和作业人员每年至少进行一次安全生产教育培训，其教育培训情况记入个人工作档案。安全生产教育培训考核不合格的人员，不得上岗。 施工单位在采用新技术、新工艺、新设备、新材料时，应当对作业人员进行相应的安全生产教育培训。"},{"i":26,"n":"第二十六条","txt":"水行政主管部门和流域管理机构按照分级管理权限，负责水利工程建设安全生产的监督管理。水行政主管部门或者流域管理机构委托的安全生产监督机构，负责水利工程施工现场的具体监督检查工作。"},{"i":27,"n":"第二十七条","txt":"水利部负责全国水利工程建设安全生产的监督管理工作，其主要职责是： （一）贯彻、执行国家有关安全生产的法律、法规和政策，制定有关水利工程建设安全生产的规章、规范性文件和技术标准； （二）监督、指导全国水利工程建设安全生产工作，组织开展对全国水利工程建设安全生产情况的监督检查； （三）组织、指导全国水利工程建设安全生产监督机构的建设、管理以及水利水电工程施工单位的主要负责人、项目负责人和专职安全生产管理人员的安全生产考核工作。"},{"i":28,"n":"第二十八条","txt":"流域管理机构负责所管辖的水利工程建设项目的安全生产监督工作。"},{"i":29,"n":"第二十九条","txt":"省、自治区、直辖市人民政府水行政主管部门负责本行政区域内所管辖的水利工程建设安全生产的监督管理工作，其主要职责是： （一）贯彻、执行有关安全生产的法律、法规、规章、政策和技术标准，制定地方有关水利工程建设安全生产的规范性文件； （二）监督、指导本行政区域内所管辖的水利工程建设安全生产工作，组织开展对本行政区域内所管辖的水利工程建设安全生产情况的监督检查； （三）组织、指导本行政区域内水利工程建设安全生产监督机构的建设工作以及有关的水利水电工程施工单位的主要负责人、项目负责人和专职安全生产管理人员的安全生产考核工作。 市、县级人民政府水行政主管部门水利工程建设安全生产的监督管理职责，由省、自治区、直辖市人民政府水行政主管部门规定。"},{"i":30,"n":"第三十条","txt":"水行政主管部门或者流域管理机构委托的安全生产监督机构，应当严格按照有关安全生产的法律、法规、规章和技术标准，对水利工程施工现场实施监督检查。 安全生产监督机构应当配备一定数量的专职安全生产监督人员。"},{"i":31,"n":"第三十一条","txt":"水行政主管部门或者其委托的安全生产监督机构应当自收到本规定第九条和第十一条规定的有关备案资料后20日内，将有关备案资料抄送同级安全生产监督管理部门。流域管理机构抄送项目所在地省级安全生产监督管理部门，并报水利部备案。"},{"i":32,"n":"第三十二条","txt":"水行政主管部门、流域管理机构或者其委托的安全生产监督机构依法履行安全生产监督检查职责时，有权采取下列措施： （一）要求被检查单位提供有关安全生产的文件和资料； （二）进入被检查单位施工现场进行检查； （三）纠正施工中违反安全生产要求的行为； （四）对检查中发现的安全事故隐患，责令立即排除；重大安全事故隐患排除前或者排除过程中无法保证安全的，责令从危险区域内撤出作业人员或者暂时停止施工。"},{"i":33,"n":"第三十三条","txt":"各级水行政主管部门和流域管理机构应当建立举报制度，及时受理对水利工程建设生产安全事故及安全事故隐患的检举、控告和投诉；对超出管理权限的，应当及时转送有管理权限的部门。举报制度应当包括以下内容： （一）公布举报电话、信箱或者电子邮件地址，受理对水利工程建设安全生产的举报； （二）对举报事项进行调查核实，并形成书面材料； （三）督促落实整顿措施，依法作出处理。"},{"i":34,"n":"第三十四条","txt":"各级地方人民政府水行政主管部门应当根据本级人民政府的要求，制定本行政区域内水利工程建设特大生产安全事故应急救援预案，并报上一级人民政府水行政主管部门备案。流域管理机构应当编制所管辖的水利工程建设特大生产安全事故应急救援预案，并报水利部备案。"},{"i":35,"n":"第三十五条","txt":"项目法人应当组织制定本建设项目的生产安全事故应急救援预案，并定期组织演练。应急救援预案应当包括紧急救援的组织机构、人员配备、物资准备、人员财产救援措施、事故分析与报告等方面的方案。"},{"i":36,"n":"第三十六条","txt":"施工单位应当根据水利工程施工的特点和范围，对施工现场易发生重大事故的部位、环节进行监控，制定施工现场生产安全事故应急救援预案。实行施工总承包的，由总承包单位统一组织编制水利工程建设生产安全事故应急救援预案，工程总承包单位和分包单位按照应急救援预案，各自建立应急救援组织或者配备应急救援人员，配备救援器材、设备，并定期组织演练。"},{"i":37,"n":"第三十七条","txt":"施工单位发生生产安全事故，应当按照国家有关伤亡事故报告和调查处理的规定，及时、如实地向负责安全生产监督管理的部门以及水行政主管部门或者流域管理机构报告；特种设备发生事故的，还应当同时向特种设备安全监督管理部门报告。接到报告的部门应当按照国家有关规定，如实上报。 实行施工总承包的建设工程，由总承包单位负责上报事故。 发生生产安全事故，项目法人及其他有关单位应当及时、如实地向负责安全生产监督管理的部门以及水行政主管部门或者流域管理机构报告。"},{"i":38,"n":"第三十八条","txt":"发生生产安全事故后，有关单位应当采取措施防止事故扩大，保护事故现场。需要移动现场物品时，应当做出标记和书面记录，妥善保管有关证物。"},{"i":39,"n":"第三十九条","txt":"水利工程建设生产安全事故的调查、对事故责任单位和责任人的处罚与处理，按照有关法律、法规的规定执行。"},{"i":40,"n":"第四十条","txt":"违反本规定，需要实施行政处罚的，由水行政主管部门或者流域管理机构按照《建设工程安全生产管理条例》的规定执行。"},{"i":41,"n":"第四十一条","txt":"省、自治区、直辖市人民政府水行政主管部门可以结合本地区实际制定本规定的实施办法，报水利部备案。"},{"i":42,"n":"第四十二条","txt":"本规定自2005年9月1日起施行。"}],"shuiligongchengjianshejianlidanweizizhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强水利工程建设监理单位的资质管理，规范水利工程建设市场秩序，保证水利工程建设质量，根据《建设工程质量管理条例》、《国务院对确需保留的行政审批项目设定行政许可的决定》等规定，制定本办法。"},{"i":2,"n":"第二条","txt":"水利工程建设监理单位（以下简称监理单位） 资质的认定与管理，适用本办法。"},{"i":3,"n":"第三条","txt":"从事水利工程建设监理业务的单位，应当按照本办法取得资质，并在资质等级许可的范围内承揽水利工程建设监理业务。"},{"i":4,"n":"第四条","txt":"申请监理资质的单位（以下简称申请人），应当按照其拥有的技术负责人、专业技术人员和工程监理业绩等条件，申请相应的资质等级。"},{"i":5,"n":"第五条","txt":"水利部负责监理单位资质的认定与管理工作。 水利部所属流域管理机构（以下简称流域管理机构）和省、自治区、直辖市人民政府水行政主管部门依照管理权限，负责有关的监理单位资质申请材料的接收、转报以及相关管理工作。"},{"i":6,"n":"第六条","txt":"监理单位资质分为水利工程施工监理、水土保持工程施工监理、机电及金属结构设备制造监理和水利工程建设环境保护监理四个专业。其中，水利工程施工监理专业资质和水土保持工程施工监理专业资质分为甲级、乙级和丙级三个等级，机电及金属结构设备制造监理专业资质分为甲级、乙级两个等级，水利工程建设环境保护监理专业资质暂不分级。"},{"i":7,"n":"第七条","txt":"各专业资质等级可以承担的业务范围如下： （一）水利工程施工监理专业资质 甲级可以承担各等级水利工程的施工监理业务。 乙级可以承担Ⅱ等（堤防2级）以下各等级水利工程的施工监理业务。 丙级可以承担Ⅲ等（堤防3级）以下各等级水利工程的施工监理业务。 适用本办法的水利工程等级划分标准按照《水利水电工程等级划分及洪水标准》（SL252-2017）执行。 （二）水土保持工程施工监理专业资质 甲级可以承担各等级水土保持工程的施工监理业务。 乙级可以承担Ⅱ等以下各等级水土保持工程的施工监理业务。 丙级可以承担Ⅲ等水土保持工程的施工监理业务。 同时具备水利工程施工监理专业资质和乙级以上水土保持工程施工监理专业资质的，方可承担淤地坝中的骨干坝施工监理业务。 适用本办法的水土保持工程等级划分标准见附件二。 （三）机电及金属结构设备制造监理专业资质 甲级可以承担水利工程中的各类型机电及金属结构设备制造监理业务"},{"i":8,"n":"第八条","txt":"申请监理单位资质，应当具备 “水利工程建设监理单位资质等级标准”（附件一）规定的资质条件。 监理单位资质一般按照专业逐级申请。 申请人可以申请一个或者两个以上专业资质。"},{"i":9,"n":"第九条","txt":"监理单位资质每年集中认定一次，受理时间由水利部提前三个月向社会公告。 监理单位分立后申请重新认定监理单位资质以及监理单位申请资质证书变更或者资质延续的，不适用前款规定。"},{"i":10,"n":"第十条","txt":"申请人应当向其注册地的省、自治区、直辖市人民政府水行政主管部门提交申请材料。但是，水利部直属单位独资或者控股成立的企业申请监理单位资质的，应当向水利部提交申请材料；流域管理机构直属单位独资或者控股成立的企业申请监理单位资质的，应当向该流域管理机构提交申请材料。 省、自治区、直辖市人民政府水行政主管部门和流域管理机构应当自收到申请材料之日起20个工作日内提出意见，并连同申请材料转报水利部。水利部按照《中华人民共和国行政许可法》第三十二条的规定办理受理手续。"},{"i":11,"n":"第十一条","txt":"首次申请监理单位资质，申请人应当提交以下材料： （一）《水利工程建设监理单位资质等级申请表》； （二）企业章程； （三）法定代表人身份证明； （四）《水利工程建设监理单位资质等级申请表》中所列监理工程师、造价工程师的申请人同意注册证明文件（已在其他单位注册的，还需提供原注册单位同意变更注册的证明），以及上述人员的劳动合同和社会保险凭证。 申请晋升、重新认定、延续监理单位资质等级的，除提交前款规定的材料外，还应当提交以下材料： （一）原《水利工程建设监理单位资质等级证书》（副本）； （二）近三年承担的水利工程建设监理合同书，以及已完工程的建设单位评价意见。 申请人应当如实提交有关材料和反映真实情况，并对申请材料的真实性负责。"},{"i":12,"n":"第十二条","txt":"水利部应当自受理申请之日起20个工作日内作出认定或者不予认定的决定；20个工作日内不能作出决定的，经本机关负责人批准，可以延长10个工作日。决定予以认定的，应当在10个工作日内颁发《水利工程建设监理单位资质等级证书》；不予认定的，应当书面通知申请人并说明理由。"},{"i":13,"n":"第十三条","txt":"水利部在作出决定前，应当组织对申请材料进行评审，并将评审结果在水利部网站公示，公示时间不少于7日。 水利部应当制作《水行政许可除外时间告知书》，将评审和公示时间告知申请人。"},{"i":14,"n":"第十四条","txt":"《水利工程建设监理单位资质等级证书》包括正本一份、副本四份，正本和副本具有同等法律效力，有效期为5年。"},{"i":15,"n":"第十五条","txt":"资质等级证书有效期内，监理单位的名称、地址、法定代表人等工商注册事项发生变更的，应当在变更后30个工作日内向水利部提交水利工程监理单位资质等级证书变更申请并附工商注册事项变更的证明材料，办理资质等级证书变更手续。水利部自收到变更申请材料之日起3个工作日内办理变更手续。"},{"i":16,"n":"第十六条","txt":"监理单位发生合并、重组、分立的，可以确定由一家单位承继原单位资质，该单位应当自合并、重组、分立之日起30个工作日内，按照本办法第十条、第十一条的规定，提交有关申请材料以及合并、重组、分立决议和监理业绩分割协议。经审核，注册人员等事项满足资质标准要求的，直接进行证书变更。重组、分立后其他单位申请获得水利工程建设监理单位资质的，按照首次申请办理。"},{"i":17,"n":"第十七条","txt":"资质等级证书有效期届满，需要延续的，监理单位应当在有效期届满30个工作日前，按照本办法第十条、第十一条的规定，向水利部提出延续资质等级的申请。水利部在资质等级证书有效期届满前，作出是否准予延续的决定。"},{"i":18,"n":"第十八条","txt":"水利部应当将资质等级证书的发放、变更、延续等情况及时通知有关省、自治区、直辖市人民政府水行政主管部门或者流域管理机构，并定期在水利部网站公告。"},{"i":19,"n":"第十九条","txt":"水利部建立监理单位资质监督检查制度，对监理单位资质实行动态管理。"},{"i":20,"n":"第二十条","txt":"水利部履行监督检查职责时，有关单位和人员应当客观、如实反映情况，提供相关材料。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府水行政主管部门和流域管理机构发现监理单位资质条件不符合相应资质等级标准的，应当向水利部报告，水利部按照本办法核定其资质等级。"},{"i":22,"n":"第二十二条","txt":"违反本办法应当给予处罚的，依照《中华人民共和国行政许可法》、《建设工程质量管理条例》、《水利工程建设监理规定》的有关规定执行。"},{"i":23,"n":"第二十三条","txt":"监理单位被吊销资质等级证书的，三年内不得重新申请；因违法违规行为被降低资质等级的，两年内不得申请晋升资质等级；受到其他行政处罚，受到通报批评、情节严重，被计入不良行为档案，或者在审计、监察、稽察、检查中发现存在严重问题的，一年内不得申请晋升资质等级。法律法规另有规定的，从其规定。"},{"i":24,"n":"第二十四条","txt":"水利工程建设监理单位资质等级申请表、受理凭证、申请材料补正通知书、不予受理告知书等文书格式由水利部统一制定，《水利工程建设监理单位资质等级证书》由水利部统一印制。"},{"i":25,"n":"第二十五条","txt":"本办法施行前已经取得的水利工程建设监理单位资质等级证书，本办法施行后在有效期内继续有效。本办法施行后申请晋升、变更、延续和重新认定资质等级的，依照本办法执行。"},{"i":26,"n":"第二十六条","txt":"本办法自2007年2月1日起施行。《水利工程建设监理单位管理办法》（水建管〔1999〕637号）同时废止。 附件一： 水利工程建设监理单位资质等级标准 一、甲级监理单位资质条件 （一）具有健全的组织机构、完善的组织章程和管理制度。技术负责人具有高级专业技术职称，并取得监理工程师资格证书。 （二）专业技术人员。监理工程师以及其中具有高级专业技术职称的人员，均不少于附表1规定的人数。造价工程师不少于3人。 （三）具有五年以上水利工程建设监理经历，且近三年监理业绩分别为： 1、申请水利工程施工监理专业资质，应当承担过（含正在承担，下同）1项Ⅱ等水利枢纽工程，或者2项Ⅱ等（堤防2级）其他水利工程的施工监理业务；该专业资质许可的监理范围内的近三年累计合同额不少于600万元。 承担过水利枢纽工程中的挡、泄、导流、发电工程之一的，可视为承担过水利枢纽工程。 2、申请水土保持工程施工监理专业资质，应当"}],"shuiligongchengjianshejianliguiding":[{"i":1,"n":"第一条","txt":"为规范水利工程建设监理活动，保证工程建设质量和安全，根据《中华人民共和国建筑法》《建设工程质量管理条例》《建设工程安全生产管理条例》等法律法规，结合水利工程建设实际，制定本规定。"},{"i":2,"n":"第二条","txt":"从事水利工程建设监理以及对水利工程建设监理实施监督管理，适用本规定。 本规定所称水利工程建设监理，是指具有水利工程建设监理资质的监理单位（以下简称监理单位），受项目法人或者建设单位（以下统称项目法人）委托，按照监理合同的约定，对水利工程建设项目实施中的质量、进度、资金、安全生产等进行的管理活动，包括水利工程施工监理、水土保持工程施工监理、机电及金属结构设备制造监理。"},{"i":3,"n":"第三条","txt":"水利工程建设项目总投资400万元以上，且符合下列条件之一的，必须实行监理： （一）关系社会公共利益、公众安全的； （二）使用国有资金投资或者国家融资的； （三）使用外国政府或者国际组织贷款、援助资金的。 铁路、公路、城镇建设、矿山、电力、石油天然气、建材等建设项目的配套水土保持工程，应当按照本规定和水土保持有关规定，开展水土保持工程施工监理。 其他水利工程建设项目是否实行监理，由项目法人自行决定。"},{"i":4,"n":"第四条","txt":"水利部对全国水利工程建设监理实施统一监督管理。 水利部所属流域管理机构（以下简称流域管理机构）按照管理权限对其所管辖的水利工程建设监理实施监督管理。 县级以上地方人民政府水行政主管部门对其所管辖的水利工程建设监理实施监督管理。"},{"i":5,"n":"第五条","txt":"监理单位应当按照水利部的规定，取得《水利工程建设监理单位资质等级证书》，并在其资质等级许可的范围内承担监理业务。"},{"i":6,"n":"第六条","txt":"监理单位应当依照有关法律、法规、规章、技术标准、批准的设计文件和合同，对水利工程质量、进度、资金、安全生产等实施监理，承担相应的监理责任。"},{"i":7,"n":"第七条","txt":"鼓励监理单位采用先进的科学技术、设备和管理方法，提升水利工程建设监理水平。"},{"i":8,"n":"第八条","txt":"实行监理的水利工程建设项目，项目法人应当依照有关法律、法规和规定，委托具有相应水利工程建设监理资质等级的单位进行监理。 项目法人可以向由两个以上具有水利工程建设监理资质的单位组成的联合体委托监理业务。项目法人有多个同类型小型水利工程项目的，可以打捆为一个项目，统一委托实施监理。 设计单位具有相应监理资质等级，并与被监理工程的施工单位没有隶属关系或者其他利害关系的，可以依法承担监理业务。"},{"i":9,"n":"第九条","txt":"项目法人应当与监理单位签订书面委托监理合同。合同价格应当合理反映监理成本。"},{"i":10,"n":"第十条","txt":"项目法人按照监理合同约定，加强对监理单位监理履职等情况的检查，对发现的问题组织责任单位进行整改落实；对发生严重违规行为和质量事故的，应当及时报告有管辖权的水行政主管部门或者流域管理机构。 项目法人对监理单位提出并落实的合理化建议，可以给予奖励。"},{"i":11,"n":"第十一条","txt":"项目法人应当按照监理合同约定，做好以下工作： （一）向监理单位提供与工程监理有关的资料，资料必须真实、准确、完整； （二）向监理单位提供必要的工作条件，及时足额支付监理酬金，支持监理单位开展监理业务； （三）将监理单位及其监理人员、监理服务内容、监理工作权限等情况书面告知被监理单位。"},{"i":12,"n":"第十二条","txt":"项目法人及其工作人员不得明示或者暗示监理单位违反法律、法规和工程建设强制性标准，不得更改总监理工程师依法发出的指令，不得索取、收受监理单位的贿赂。"},{"i":13,"n":"第十三条","txt":"联合体监理各方应当签订协议，明确各方拟承担的工作和责任，并将协议提交项目法人。联合体的资质等级，按照同一专业内资质等级较低的一方确定。联合体中标的，联合体各方应当共同与项目法人签订监理合同，就中标项目向项目法人承担连带责任。"},{"i":14,"n":"第十四条","txt":"监理单位不得超越资质等级许可范围或者以其他监理单位的名义承担监理业务，不得允许其他单位或者个人以本单位的名义承担监理业务。 监理单位不得转让监理业务。 监理单位不得以串通、欺诈、胁迫、贿赂等不正当手段承担监理业务。 监理单位不得通过降低监理服务质量、减少服务内容等手段进行恶性竞争，扰乱正常市场秩序。"},{"i":15,"n":"第十五条","txt":"监理单位应当按照工程监理需要和合同约定在施工现场设置监理机构，配备满足工程需要的监理人员。监理人员包括总监理工程师、监理工程师和监理员。 总监理工程师、监理工程师应当具有水利工程专业监理工程师执业资格，并在其注册监理单位从事注册专业对应范围内的水利工程建设监理执业活动。 总监理工程师由监理单位任命符合合同约定条件的注册监理工程师担任。 大中型水利工程以及工程条件复杂、技术难度较大的小型水利工程的总监理工程师应当具有工程类高级专业技术职称。 监理员应当具有工程类中专以上学历，且经水利工程建设监理业务培训后从业。 监理人员应当遵守有关法律、法规和规定，恪守职业道德和从业规范，保守秘密，主动接受水行政主管部门和流域管理机构的监督检查。"},{"i":16,"n":"第十六条","txt":"水利工程建设监理实行总监理工程师负责制。 总监理工程师负责全面履行监理合同约定的监理单位职责，发布有关指令，签署监理文件，协调有关各方之间的关系。 监理工程师在总监理工程师授权范围内开展监理工作，并对总监理工程师负责。 监理员在监理工程师或者总监理工程师授权范围内从事监理辅助工作。"},{"i":17,"n":"第十七条","txt":"总监理工程师和监理工程师一般不得更换；确需更换的，应当经项目法人书面同意，且更换后的人员资格不得低于合同约定的条件。"},{"i":18,"n":"第十八条","txt":"监理单位应当编制监理规划和监理实施细则，明确监理工作范围、内容、目标、依据、制度、程序、方法和措施等，加强对工程建设重点部位和关键环节的监理。"},{"i":19,"n":"第十九条","txt":"监理单位应当按照有关技术标准和合同要求，通过旁站、巡视、平行检验和见证取样检测等方式开展监理工作，如实填写监理工作记录，发现问题应当及时纠正、报告。 监理业务完成后，监理单位按照监理合同向项目法人提交监理工作报告、移交档案资料。"},{"i":20,"n":"第二十条","txt":"监理单位应当按照监理合同的约定，组织或者参加工程勘察、设计交底。 监理单位应当组织核查并签发施工图，未经总监理工程师签字的施工图不得用于施工。发现工程设计不符合水利工程质量标准或者合同约定的质量要求的，应当报告项目法人要求设计单位改正。监理单位不得修改工程设计文件。"},{"i":21,"n":"第二十一条","txt":"监理单位应当审查被监理单位的质量管理体系，检查并复核原材料、中间产品和设备的质量，不得将质量检验不合格的按照合格签字。未经监理工程师签字，原材料、中间产品和设备不得在工程上使用或者安装。 监理单位应当按照合同约定，组织或者参与工程相关验收，不得将质量检验不合格的建设工程按照合格签字。 监理单位平行检验中需要进行检测的项目，应当按照有关规定由具有相应水利工程质量检测资质等级的单位承担。"},{"i":22,"n":"第二十二条","txt":"监理单位应当审查被监理单位的施工组织设计和施工进度计划，并督促实施。"},{"i":23,"n":"第二十三条","txt":"监理单位应当审查被监理单位的资金使用计划，复核并签认工程量，签发工程款支付凭证。未经总监理工程师签字，项目法人不得支付工程款。"},{"i":24,"n":"第二十四条","txt":"监理单位应当审查被监理单位的安全技术措施和专项施工方案是否符合工程建设强制性标准要求，旁站、巡视并检查现场安全生产状况。"},{"i":25,"n":"第二十五条","txt":"监理单位在实施监理过程中，发现存在质量问题或者安全事故隐患的，应当要求被监理单位及时整改；情况严重的，应当要求被监理单位暂时停止施工，并及时报告项目法人。 对存在的质量问题或者安全事故隐患，被监理单位拒不整改或者不停止施工的，监理单位应当及时向有关水行政主管部门或者流域管理机构报告。"},{"i":26,"n":"第二十六条","txt":"监理单位与被监理工程的施工单位以及原材料、中间产品、设备供应单位和施工自检单位不得有隶属关系或者其他利害关系。 监理单位不得与项目法人或者被监理单位串通，弄虚作假、降低工程或者设备质量。"},{"i":27,"n":"第二十七条","txt":"监理单位合并或者分立的，依照相关法律法规或者监理合同的约定，承担相应的监理责任。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府水行政主管部门和流域管理机构应当加强对水利工程建设监理的监督管理，对项目法人和监理单位执行国家法律、法规、工程建设强制性标准以及履行监理合同的情况进行监督检查。实施监督检查时，不得妨碍监理单位和监理人员正常的监理活动，不得索取或者收受被监督检查单位和人员的贿赂，不得谋取其他不正当利益。"},{"i":29,"n":"第二十九条","txt":"有关单位和个人对县级以上人民政府水行政主管部门和流域管理机构的监督检查应当支持与配合，不得拒绝或者阻碍监督检查人员依法履行职责。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府水行政主管部门和流域管理机构履行监督检查职责时，有权采取下列措施： （一）要求相关单位和个人提供水利工程建设监理等方面的文件和资料； （二）进入工程现场和其他相关场所进行检查、取证等； （三）发现问题时，责令改正并依法采取处理措施。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人有权举报和控告水利工程建设监理中的违法违规行为。有关水行政主管部门和流域管理机构以及有关单位应当及时调查处理。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府水行政主管部门和流域管理机构的工作人员在水利工程建设监理的监督管理中玩忽职守、滥用职权、徇私舞弊的，依法依规给予处分；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"项目法人将监理业务委托给不具有相应资质等级的监理单位，或者必须实行水利工程建设监理而未实行的，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，按照《建设工程质量管理条例》第五十四条、第五十六条的规定予以处罚。 项目法人对监理单位提出不符合安全生产法律、法规和工程建设强制性标准规定要求的，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，按照《建设工程安全生产管理条例》第五十五条的规定予以处罚。"},{"i":34,"n":"第三十四条","txt":"项目法人及其工作人员索取、收受监理单位的贿赂，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，没收违法所得，处违法所得3倍以下且不超过10万元的罚款；构成犯罪的，依法追究有关责任人员的刑事责任。"},{"i":35,"n":"第三十五条","txt":"监理单位有下列行为之一的，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，按照《建设工程质量管理条例》有关规定予以处罚： （一）超越本单位资质等级、未取得相应资质等级证书或者以欺骗手段取得资质等级证书承担监理业务的，按照《建设工程质量管理条例》第六十条的规定予以处罚； （二）允许其他单位或者个人以本单位名义承担监理业务的，按照《建设工程质量管理条例》第六十一条的规定予以处罚； （三）转让监理业务的，按照《建设工程质量管理条例》第六十二条的规定予以处罚； （四）与项目法人或者被监理单位串通，弄虚作假、降低工程质量，或者将不合格的建设工程、原材料、中间产品和设备按照合格签字的，按照《建设工程质量管理条例》第六十七条的规定予以处罚； （五）与被监理工程的施工单位以及原材料、中间产品和设备供应单位有隶属关系或者其他利害关系的，按照《建设工程质量管理条例》第六十八条的规定予以处罚。"},{"i":36,"n":"第三十六条","txt":"监理单位有下列行为之一的，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，按照《建设工程安全生产管理条例》第五十七条的规定予以处罚： （一）未对施工组织设计中的安全技术措施或者专项施工方案进行审查的； （二）发现安全事故隐患未及时要求施工单位整改或者暂时停止施工的； （三）施工单位拒不整改或者不停止施工，未及时向有关水行政主管部门或者流域管理机构报告的； （四）未按照法律、法规和工程建设强制性标准实施监理的。"},{"i":37,"n":"第三十七条","txt":"监理单位有下列行为之一的，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，责令改正或者停止违法行为，处合同约定的监理酬金1倍以上3倍以下且不超过10万元的罚款；造成损失的，依法承担赔偿责任： （一）以串通、欺诈、胁迫、贿赂等不正当手段承担监理业务的； （二）聘用无相应资格或者不符合条件的监理人员从事监理业务的； （三）安排本单位注册监理工程师超出其注册专业对应范围从事监理执业活动的； （四）拒绝提供或者篡改、伪造工程建设监理文件和资料的； （五）拒绝或者阻碍监督检查人员依法履行职责的； （六）因过错造成质量事故的。"},{"i":38,"n":"第三十八条","txt":"监理单位有下列行为之一的，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，责令改正，给予警告或者通报批评；情节严重的，处1万元以上3万元以下的罚款： （一）未检查并复核原材料、中间产品和设备质量的； （二）未如实复核并签认工程量的。"},{"i":39,"n":"第三十九条","txt":"监理工程师因过错造成质量事故的，责令停止执业1年；造成重大质量事故的，吊销注册证书，5年内不予注册；情节特别严重的，终身不予注册。 监理工程师未执行法律、法规和工程建设强制性标准的，责令停止执业3个月以上1年以下；情节严重的，吊销注册证书，5年内不予注册；造成重大安全事故的，终身不予注册；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"监理人员有下列行为之一的，由县级以上地方人民政府水行政主管部门或者流域管理机构依据职权，责令改正，给予警告或者通报批评；情节严重的，处1万元以上5万元以下的罚款；造成损失的，依法承担赔偿责任： （一）利用执（从）业上的便利，索取或者收受被监理工程的施工单位以及原材料、中间产品和设备供应单位贿赂的； （二）与被监理工程的项目法人、施工单位以及原材料、中间产品和设备供应单位串通，谋取不正当利益的； （三）非法泄露执（从）业中应当保守的秘密的。"},{"i":41,"n":"第四十一条","txt":"依法给予监理单位罚款处罚的，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额5%以上10%以下的罚款。 监理单位的工作人员因调动工作、退休等原因离开该单位后，被发现在该单位工作期间违反国家有关工程建设质量管理规定，造成重大工程质量事故的，仍应当依法追究法律责任。"},{"i":42,"n":"第四十二条","txt":"县级以上人民政府水行政主管部门和流域管理机构应当依照有关规定加强对水利工程建设监理单位和监理人员的信用监管，对相关单位和人员的行政处罚、行政处理决定信息，依照有关规定记入其信用记录。"},{"i":43,"n":"第四十三条","txt":"本规定自2026年2月1日起施行。2006年12月18日水利部发布的《水利工程建设监理规定》同时废止。"}],"shuiligongchengjianshechengxuguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为加强水利建设市场管理，进一步规范水利工程建设程序，推进项目法人责任制、建设监理制、招标投标制的实施，促进水利建设实现经济体制和经济增长方式的两个根本性转变，根据国家有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"水利工程建设程序，按《水利工程建设项目管理规定》（水利部水建〔1995〕128号）明确的建设程序执行，水利工程建设程序一般分为：项目建议书、可行性研究报告、施工准备、初步设计、建设实施、生产准备、竣工验收、后评价等阶段。"},{"i":3,"n":"第三条","txt":"本暂行规定适用于由国家投资、中央和地方合资、企事业单位独资或合资以及其它投资方式兴建的防洪、除涝、灌溉、发电、供水、围垦等大中型（包括新建、续建、改建、加固、修复）工程建设项目。小型水利工程建设项目可以参照执行。利用外资项目的建设程序，同时还应执行有关外资项目管理的规定。"},{"i":4,"n":"第四条","txt":"项目建议书阶段 1.项目建议书应根据国民经济和社会发展长远规划、流域综合规划、区域综合规划、专业规划，按照国家产业政策和国家有关投资建设方针进行编制，是对拟进行建设项目的初步说明。 2.项目建议书应按照《水利水电工程项目建议书编制暂行规定》（水利部水规计〔1996〕608号）编制。 3.项目建议书编制一般由政府委托有相应资格的设计单位承担，并按国家现行规定权限向主管部门申报审批。项目建议书被批准后，由政府向社会公布，若有投资建设意向，应及时组建项目法人筹备机构，开展下一建设程序工作。"},{"i":5,"n":"第五条","txt":"可行性研究报告阶段 1.可行性研究应对项目进行方案比较，在技术上是否可行和经济上是否合理进行科学的分析和论证。经过批准的可行性研究报告，是项目决策和进行初步设计的依据。可行性研究报告，由项目法人（或筹备机构）组织编制。 2.可行性研究报告应按照《水利水电工程可行性研究报告编制规程》（电力部、水利部电办〔1993〕112号）编制。 3.可行性研究报告，按国家现行规定的审批权限报批。申报项目可行性研究报告，必须同时提出项目法人组建方案及运行机制、资金筹措方案、资金结构及回收资金的办法。 4.可行性研究报告经批准后，不得随意修改和变更，在主要内容上有重要变动，应经原批准机关复审同意。项目可行性报告批准后，应正式成立项目法人，并按项目法人责任制实行项目管理。"},{"i":6,"n":"第六条","txt":"施工准备阶段 1.项目可行性研究报告已经批准，年度水利投资计划下达后，项目法人即可开展施工准备工作，其主要内容包括： （1）施工现场的征地、拆迁； （2）完成施工用水、电、通信、路和场地平整等工程； （3）必须的生产、生活临时建筑工程； （4）实施经批准的应急工程、试验工程等专项工程； （5）组织招标设计、咨询、设备和物资采购等服务； （6）组织相关监理招标，组织主体工程招标准备工作。 2.工程建设项目施工，除某些不适应招标的特殊工程项目外（须经水行政主管部门批准），均须实行招标投标。水利工程建设项目的招标投标，按有关法律、行政法规和《水利工程建设项目招标投标管理规定》等规章规定执行。"},{"i":7,"n":"第七条","txt":"初步设计阶段 1.初步设计是根据批准的可行性研究报告和必要而准确的设计资料，对设计对象进行通盘研究，阐明拟建工程在技术上的可行性和经济上的合理性，规定项目的各项基本技术参数，编制项目的总概算。初步设计任务应择优选择有项目相应资格的设计单位承担，依照有关初步设计编制规定进行编制。 2.初步设计报告应按照《水利水电工程初步设计报告编制规程》（电力部、水利部电办〔1993〕113号）编制。 3.初步设计文件报批前，一般须由项目法人对初步设计中的重大问题组织论证。设计单位根据论证意见，对初步设计文件进行补充、修改、优化。初步设计由项目法人组织审查后，按国家现行规定权限向主管部门申报审批。 4.设计单位必须严格保证设计质量，承担初步设计的合同责任。初步设计文件经批准后，主要内容不得随意修改、变更，并作为项目建设实施的技术文件基础。如有重要修改、变更，须经原审批机关复审同意。"},{"i":8,"n":"第八条","txt":"建设实施阶段 1.建设实施阶段是指主体工程的建设实施，项目法人按照批准的建设文件，组织工程建设，保证项目建设目标的实现； 2.水利工程具备《水利工程建设项目管理规定（试行）》规定的开工条件后，主体工程方可开工建设。项目法人或者建设单位应当自工程开工之日起15个工作日内，将开工情况的书面报告报项目主管单位和上一级主管单位备案。 3.项目法人要充分发挥建设管理的主导作用，为施工创造良好的建设条件。项目法人要充分授权工程监理，使之能独立负责项目的建设工期、质量、投资的控制和现场施工的组织协调。监理单位选择必须符合《水利工程建设监理规定》（水利部水建〔1996〕396号）的要求； 4.要按照“政府监督、项目法人负责、社会监理、企业保证”的要求，建立健全质量管理体系，重要建设项目，须设立质量监督项目站，行使政府对项目建设的监督职能。"},{"i":9,"n":"第九条","txt":"生产准备阶段 1.生产准备是项目投产前所要进行的一项重要工作，是建设阶段转入生产经营的必要条件。项目法人应按照建管结合和项目法人责任制的要求，适时做好有关生产准备工作。 2.生产准备应根据不同类型的工程要求确定，一般应包括如下主要内容： （1）生产组织准备。建立生产经营的管理机构及相应管理制度； （2）招收和培训人员。按照生产运营的要求，配备生产管理人员，并通过多种形式的培训，提高人员素质，使之能满足运营要求。生产管理人员要尽早介入工程的施工建设，参加设备的安装调试，熟悉情况，掌握好生产技术和工艺流程，为顺利衔接基本建设和生产经营阶段做好准备； （3）生产技术准备。主要包括技术资料的汇总、运行技术方案的制定、岗位操作规程制定和新技术准备； （4）生产的物资准备。主要是落实投产运营所需要的原材料、协作产品、工器具、备品备件和其他协作配合条件的准备； （5）正常的生活福利设施准备。 3.及"},{"i":10,"n":"第十条","txt":"竣工验收 1.竣工验收是工程完成建设目标的标志，是全面考核基本建设成果、检验设计和工程质量的重要步骤。竣工验收合格的项目即从基本建设转入生产或使用。 2.当建设项目的建设内容全部完成，并经过单位工程验收（包括工程档案资料的验收），符合设计要求并按《水利基本建设项目（工程）档案资料管理暂行规定》（水利部水办〔1997〕275号）的要求完成了档案资料的整理工作；完成竣工报告、竣工决算等必须文件的编制后，项目法人按《水利工程建设项目管理规定（试行）》（水利部水建〔1995〕128号）规定，向验收主管部门，提出申请，根据国家和部颁验收规程，组织验收。 3.竣工决算编制完成后，须由审计机关组织竣工审计，其审计报告作为竣工验收的基本资料。 4.工程规模较大、技术较复杂的建设项目可先进行初步验收。不合格的工程不予验收；有遗留问题的项目，对遗留问题必须有具体处理意见，且有限期处理的明确要求并落实责任人"},{"i":11,"n":"第十一条","txt":"后评价 1.建设项目竣工投产后，一般经过1至2年生产运营后，要进行一次系统的项目后评价，主要内容包括：影响评价——项目投产后对各方面的影响进行评价；经济效益评价一一项目投资、国民经济效益、财务效益、技术进步和规模效益、可行性研究深度等进行评价；过程评价——对项目的立项、设计施工、建设管理、竣工投产、生产运营等全过程进行评价。 2.项目后评价一般按三个层次组织实施，即项目法人的自我评价、项目行业的评价、计划部门（或主要投资方）的评价。 3.建设项目后评价工作必须遵循客观、公正、科学的原则，做到分析合理、评价公正。通过建设项目的后评价以达到肯定成绩、总结经验、研究问题、吸取教训、提出建议、改进工作，不断提高项目决策水平和投资效果的目的。"},{"i":12,"n":"第十二条","txt":"凡违反工程建设程序管理规定的，按照有关法律、法规、规章的规定，由项目行业主管部门，根据情节轻重，对责任者进行处理。"},{"i":13,"n":"第十三条","txt":"本暂行规定是《水利工程建设项目管理规定（试行）》（水利部水建〔1995〕128号）的补充。"},{"i":14,"n":"第十四条","txt":"本暂行规定由水利部负责解释。"},{"i":15,"n":"第十五条","txt":"本暂行规定自发布之日起试行。"}],"shuiligongchengjianshexiangmuzhaobiaotoubiaoguanli133d91":[{"i":1,"n":"第一条","txt":"为加强水利工程建设项目招标投标工作的管理，规范招标投标活动，根据《中华人民共和国招标投标法》和国家有关规定，结合水利工程建设的特点，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于水利工程建设项目的勘察设计、施工、监理以及与水利工程建设有关的重要设备、材料采购等的招标投标活动。"},{"i":3,"n":"第三条","txt":"符合下列具体范围并达到规模标准之一的水利工程建设项目必须进行招标。 （一）具体范围 1、关系社会公共利益、公共安全的防洪、排涝、灌溉、水力发电、引（供）水、滩涂治理、水土保持、水资源保护等水利工程建设项目； 2、使用国有资金投资或者国家融资的水利工程建设项目； 3、使用国际组织或者外国政府贷款、援助资金的水利工程建设项目。 （二）规模标准 1、施工单项合同估算价在200万元人民币以上的； 2、重要设备、材料等货物的采购，单项合同估算价在100万元人民币以上的； 3、勘察设计、监理等服务的采购，单项合同估算价在50万元人民币以上的； 4、项目总投资额在3000万元人民币以上，但分标单项合同估算价低于本项第1、2、3目规定的标准的项目原则上都必须招标。"},{"i":4,"n":"第四条","txt":"招标投标活动应当遵循公开、公平、公正和诚实信用的原则。建设项目的招标工作由招标人负责，任何单位和个人不得以任何方式非法干涉招标投标活动。"},{"i":5,"n":"第五条","txt":"水利部是全国水利工程建设项目招标投标活动的行政监督与管理部门，其主要职责是： （一）负责组织、指导、监督全国水利行业贯彻执行国家有关招标投标的法律、法规、规章和政策； （二）依据国家有关招标投标法律、法规和政策，制定水利工程建设项目招标投标的管理规定和办法； （三）受理有关水利工程建设项目招标投标活动的投诉，依法查处招标投标活动中的违法违规行为； （四）对水利工程建设项目招标代理活动进行监督； （五）对水利工程建设项目评标专家资格进行监督与管理； （六）负责国家重点水利项目和水利部所属流域管理机构（以下简称流域管理机构）主要负责人兼任项目法人代表的中央项目的招标投标活动的行政监督。"},{"i":6,"n":"第六条","txt":"流域管理机构受水利部委托，对除第五条第六项规定以外的中央项目的招标投标活动进行行政监督。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市人民政府水行政主管部门是本行政区域内地方水利工程建设项目招标投标活动的行政监督与管理部门，其主要职责是： （一）贯彻执行有关招标投标的法律、法规、规章和政策； （二）依照有关法律、法规和规章，制定地方水利工程建设项目招标投标的管理办法； （三）受理管理权限范围内的水利工程建设项目招标投标活动的投诉，依法查处招标投标活动中的违法违规行为； （四）对本行政区域内地方水利工程建设项目招标代理活动进行监督； （五）组建并管理省级水利工程建设项目评标专家库； （六）负责本行政区域内除第五条第六项规定以外的地方项目的招标投标活动的行政监督。"},{"i":8,"n":"第八条","txt":"水行政主管部门依法对水利工程建设项目的招标投标活动进行行政监督，内容包括： （一）接受招标人招标前提交备案的招标报告； （二）可派员监督开标、评标、定标等活动。对发现的招标投标活动的违法违规行为，应当立即责令改正，必要时可做出包括暂停开标或评标以及宣布开标、评标结果无效的决定，对违法的中标结果予以否决； （三）接受招标人提交备案的招标投标情况书面总结报告。"},{"i":9,"n":"第九条","txt":"招标分为公开招标和邀请招标。"},{"i":10,"n":"第十条","txt":"依法必须招标的项目中，国家重点水利项目、地方重点水利项目及全部使用国有资金投资或者国有资金投资占控股或者主导地位的项目应当公开招标，但有下列情况之一的，按第十一条的规定经批准后可采用邀请招标： （一）属于第三条第二项第4目规定的项目； （二）项目技术复杂，有特殊要求或涉及专利权保护，受自然资源或环境限制，新技术或技术规格事先难以确定的项目； （三）应急度汛项目； （四）其它特殊项目。"},{"i":11,"n":"第十一条","txt":"符合第十条规定，采用邀请招标的，招标前招标人必须履行下列批准手续： （一）国家重点水利项目经水利部初审后，报国家发展计划委员会批准；其他中央项目报水利部或其委托的流域管理机构批准； （二）地方重点水利项目经省、自治区、直辖市人民政府水行政主管部门会同同级发展计划行政主管部门审核后，报本级人民政府批准；其它地方项目报省、自治区、直辖市人民政府水行政主管部门批准。"},{"i":12,"n":"第十二条","txt":"下列项目可不进行招标，但须经项目主管部门批准： （一）涉及国家安全、国家秘密的项目； （二）应急防汛、抗旱、抢险、救灾等项目； （三）项目中经批准使用农民投工、投劳施工的部分（不包括该部分中勘察设计、监理和重要设备、材料采购）； （四）不具备招标条件的公益性水利工程建设项目的项目建议书和可行性研究报告； （五）采用特定专利技术或特有技术的； （六）其它特殊项目。"},{"i":13,"n":"第十三条","txt":"当招标人具备以下条件时，按有关规定和管理权限经核准可自行办理招标事宜： （一）具有项目法人资格（或法人资格）； （二）具有与招标项目规模和复杂程度相适应的工程技术、概预算、财务和工程管理等方面专业技术力量； （三）具有编制招标文件和组织评标的能力； （四）具有从事同类工程建设项目招标的经验； （五）设有专门的招标机构或者拥有3名以上专职招标业务人员； （六）熟悉和掌握招标投标法律、法规、规章。"},{"i":14,"n":"第十四条","txt":"当招标人不具备第十三条的条件时，应当委托符合相应条件的招标代理机构办理招标事宜。"},{"i":15,"n":"第十五条","txt":"招标人申请自行办理招标事宜时，应当报送以下书面材料： （一）项目法人营业执照、法人证书或者项目法人组建文件； （二）与招标项目相适应的专业技术力量情况； （三）内设的招标机构或者专职招标业务人员的基本情况； （四）拟使用的评标专家库情况； （五）以往编制的同类工程建设项目招标文件和评标报告，以及招标业绩的证明材料； （六）其它材料。"},{"i":16,"n":"第十六条","txt":"水利工程建设项目招标应当具备以下条件： （一）勘察设计招标应当具备的条件 1、勘察设计项目已经确定； 2、勘察设计所需资金已落实； 3、必需的勘察设计基础资料已收集完成。 （二）监理招标应当具备的条件 1、初步设计已经批准； 2、监理所需资金已落实； 3、项目已列入年度计划。 （三）施工招标应当具备的条件 1、初步设计已经批准； 2、建设资金来源已落实，年度投资计划已经安排； 3、监理单位已确定； 4、具有能满足招标要求的设计文件，已与设计单位签订适应施工进度要求的图纸交付合同或协议； 5、有关建设项目永久征地、临时征地和移民搬迁的实施、安置工作已经落实或已有明确安排。 （四）重要设备、材料招标应当具备的条件 1、初步设计已经批准； 2、重要设备、材料技术经济指标已基本确定； 3、设备、材料所需资金已落实。"},{"i":17,"n":"第十七条","txt":"招标工作一般按下列程序进行： （一）招标前，按项目管理权限向水行政主管部门提交招标报告备案。报告具体内容应当包括：招标已具备的条件、招标方式、分标方案、招标计划安排、投标人资质（资格）条件、评标方法、评标委员会组建方案以及开标、评标的工作具体安排等； （二）编制招标文件； （三）发布招标信息（招标公告或投标邀请书）； （四）发售资格预审文件； （五）按规定日期接受潜在投标人编制的资格预审文件； （六）组织对潜在投标人资格预审文件进行审核； （七）向资格预审合格的潜在投标人发售招标文件； （八）组织购买招标文件的潜在投标人现场踏勘； （九）接受投标人对招标文件有关问题要求澄清的函件，对问题进行澄清，并书面通知所有潜在投标人； （十）组织成立评标委员会，并在中标结果确定前保密； （十一）在规定时间和地点，接受符合招标文件要求的投标文件； （十二）组织开标评标会； （十三）在评标委员会推荐的"},{"i":18,"n":"第十八条","txt":"采用公开招标方式的项目，招标人应当在国家发展计划委员会指定的媒介发布招标公告，其中大型水利工程建设项目以及国家重点项目、中央项目、地方重点项目同时还应当在《中国水利报》发布招标公告，公告正式媒介发布至发售资格预审文件（或招标文件）的时间间隔一般不少于10日。招标人应当对招标公告的真实性负责。招标公告不得限制潜在投标人的数量。 采用邀请招标方式的，招标人应当向3个以上有投标资格的法人或其它组织发出投标邀请书。 投标人少于3个的，招标人应当依照本规定重新招标。"},{"i":19,"n":"第十九条","txt":"招标人应当根据国家有关规定，结合项目特点和需要编制招标文件。"},{"i":20,"n":"第二十条","txt":"招标人应当对投标人进行资格审查，并提出资格审查报告，经参审人员签字后存档备查。"},{"i":21,"n":"第二十一条","txt":"在一个项目中，招标人应当以相同条件对所有潜在投标人的资格进行审查，不得以任何理由限制或者排斥部分潜在投标人。"},{"i":22,"n":"第二十二条","txt":"招标人对已发出的招标文件进行必要澄清或者修改的，应当在招标文件要求提交投标文件截止日期至少15日前，以书面形式通知所有投标人。该澄清或者修改的内容为招标文件的组成部分。"},{"i":23,"n":"第二十三条","txt":"依法必须进行招标的项目，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不应当少于20日。"},{"i":24,"n":"第二十四条","txt":"招标文件应当按其制作成本确定售价，一般可按1000元至3000元人民币标准控制。"},{"i":25,"n":"第二十五条","txt":"招标文件中应当明确投标保证金金额，一般可按以下标准控制： （一）合同估算价10000万元人民币以上，投标保证金金额不超过合同估算价的千分之五； （二）合同估算价3000万元至10000万元人民币之间，投标保证金金额不超过合同估算价的千分之六； （三）合同估算价3000万元人民币以下，投标保证金金额不超过合同估算价的千分之七，但最低不得少于1万元人民币。"},{"i":26,"n":"第二十六条","txt":"投标人必须具备水利工程建设项目所需的资质（资格）。"},{"i":27,"n":"第二十七条","txt":"投标人应当按照招标文件的要求编写投标文件，并在招标文件规定的投标截止时间之前密封送达招标人。在投标截止时间之前，投标人可以撤回已递交的投标文件或进行更正和补充，但应当符合招标文件的要求。"},{"i":28,"n":"第二十八条","txt":"投标人必须按招标文件规定投标，也可附加提出“替代方案”，且应当在其封面上注明\"替代方案\"字样，供招标人选用，但不作为评标的主要依据。"},{"i":29,"n":"第二十九条","txt":"两个或两个以上单位联合投标的，应当按资质等级较低的单位确定联合体资质（资格）等级。招标人不得强制投标人组成联合体共同投标。"},{"i":30,"n":"第三十条","txt":"投标人在递交投标文件的同时，应当递交投标保证金。 招标人与中标人签订合同后5个工作日内，应当退还投标保证金。"},{"i":31,"n":"第三十一条","txt":"投标人应当对递交的资质（资格）预审文件及投标文件中有关资料的真实性负责。"},{"i":32,"n":"第三十二条","txt":"评标标准和方法应当在招标文件中载明，在评标时不得另行制定或修改、补充任何评标标准和方法。"},{"i":33,"n":"第三十三条","txt":"招标人在一个项目中，对所有投标人评标标准和方法必须相同。"},{"i":34,"n":"第三十四条","txt":"评标标准分为技术标准和商务标准，一般包含以下内容： （一）勘察设计评标标准 1、投标人的业绩和资信； 2、勘察总工程师、设计总工程师的经历； 3、人力资源配备； 4、技术方案和技术创新； 5、质量标准及质量管理措施； 6、技术支持与保障； 7、投标价格和评标价格； 8、财务状况； 9、组织实施方案及进度安排。 （二）监理评标标准 1、投标人的业绩和资信； 2、项目总监理工程师经历及主要监理人员情况； 3、监理规划（大纲）； 4、投标价格和评标价格； 5、财务状况。 （三）施工评标标准 1、施工方案（或施工组织设计）与工期； 2、投标价格和评标价格； 3、施工项目经理及技术负责人的经历； 4、组织机构及主要管理人员； 5、主要施工设备； 6、质量标准、质量和安全管理措施； 7、投标人的业绩、类似工程经历和资信； 8、财务状况。 （四）设备、材料评标标准 1、投标价格和评标价格； 2、质量"},{"i":35,"n":"第三十五条","txt":"评标方法可采用综合评分法、综合最低评标价法、合理最低投标价法、综合评议法及两阶段评标法。"},{"i":36,"n":"第三十六条","txt":"施工招标设有标底的，评标标底可采用： （一）招标人组织编制的标底Ａ； （二）以全部或部分投标人报价的平均值作为标底Ｂ； （三）以标底Ａ和标底Ｂ的加权平均值作为标底； （四）以标底Ａ值作为确定有效标的标准，以进入有效标内投标人的报价平均值作为标底。 施工招标未设标底的，按不低于成本价的有效标进行评审。"},{"i":37,"n":"第三十七条","txt":"开标由招标人主持，邀请所有投标人参加。"},{"i":38,"n":"第三十八条","txt":"开标应当按招标文件中确定的时间和地点进行。开标人员至少由主持人、监标人、开标人、唱标人、记录人组成，上述人员对开标负责。"},{"i":39,"n":"第三十九条","txt":"开标一般按以下程序进行： （一）主持人在招标文件确定的时间停止接收投标文件，开始开标； （二）宣布开标人员名单； （三）确认投标人法定代表人或授权代表人是否在场； （四）宣布投标文件开启顺序； （五）依开标顺序，先检查投标文件密封是否完好，再启封投标文件； （六）宣布投标要素，并作记录，同时由投标人代表签字确认； （七）对上述工作进行纪录，存档备查。"},{"i":40,"n":"第四十条","txt":"评标工作由评标委员会负责。评标委员会由招标人的代表和有关技术、经济、合同管理等方面的专家组成，成员人数为七人以上单数，其中专家（不含招标人代表人数）不得少于成员总数的三分之二。"},{"i":41,"n":"第四十一条","txt":"公益性水利工程建设项目中，中央项目的评标专家应当从水利部或流域管理机构组建的评标专家库中抽取；地方项目的评标专家应当从省、自治区、直辖市人民政府水行政主管部门组建的评标专家库中抽取，也可从水利部或流域管理机构组建的评标专家库中抽取。"},{"i":42,"n":"第四十二条","txt":"评标专家的选择应当采取随机的方式抽取。根据工程特殊专业技术需要，经水行政主管部门批准，招标人可以指定部分评标专家，但不得超过专家人数的三分之一。"},{"i":43,"n":"第四十三条","txt":"评标委员会成员不得与投标人有利害关系。所指利害关系包括：是投标人或其代理人的近亲属；在5年内与投标人曾有工作关系；或有其他社会关系或经济利益关系。 评标委员会成员名单在招标结果确定前应当保密。"},{"i":44,"n":"第四十四条","txt":"评标工作一般按以下程序进行： （一）招标人宣布评标委员会成员名单并确定主任委员； （二）招标人宣布有关评标纪律； （三）在主任委员主持下，根据需要，讨论通过成立有关专业组和工作组； （四）听取招标人介绍招标文件； （五）组织评标人员学习评标标准和方法； （六）经评标委员会讨论，并经二分之一以上委员同意，提出需投标人澄清的问题，以书面形式送达投标人； （七）对需要文字澄清的问题，投标人应当以书面形式送达评标委员会； （八）评标委员会按招标文件确定的评标标准和方法，对投标文件进行评审，确定中标候选人推荐顺序； （九）在评标委员会三分之二以上委员同意并签字的情况下，通过评标委员会工作报告，并报招标人。评标委员会工作报告附件包括有关评标的往来澄清函、有关评标资料及推荐意见等。"},{"i":45,"n":"第四十五条","txt":"招标人对有下列情况之一的投标文件，可以拒绝或按无效标处理： （一）投标文件密封不符合招标文件要求的； （二）逾期送达的； （三）投标人法定代表人或授权代表人未参加开标会议的； （四）未按招标文件规定加盖单位公章和法定代表人（或其授权人）的签字（或印鉴）的； （五）招标文件规定不得标明投标人名称，但投标文件上标明投标人名称或有任何可能透露投标人名称的标记的； （六）未按招标文件要求编写或字迹模糊导致无法确认关键技术方案、关键工期、关键工程质量保证措施、投标价格的； （七）未按规定交纳投标保证金的； （八）超出招标文件规定，违反国家有关规定的； （九）投标人提供虚假资料的。"},{"i":46,"n":"第四十六条","txt":"评标委员会经过评审，认为所有投标文件都不符合招标文件要求时，可以否决所有投标，招标人应当重新组织招标。对已参加本次投标的单位，重新参加投标不应当再收取招标文件费。"},{"i":47,"n":"第四十七条","txt":"评标委员会应当进行秘密评审，不得泄露评审过程、中标候选人的推荐情况以及与评标有关的其他情况。"},{"i":48,"n":"第四十八条","txt":"在评标过程中，评标委员会可以要求投标人对投标文件中含义不明确的内容采取书面方式作出必要的澄清或说明，但不得超出投标文件的范围或改变投标文件的实质性内容。"},{"i":49,"n":"第四十九条","txt":"评标委员会经过评审，从合格的投标人中排序推荐中标候选人。"},{"i":50,"n":"第五十条","txt":"中标人的投标应当符合下列条件之一： （一）能够最大限度地满足招标文件中规定的各项综合评价标准； （二）能够满足招标文件的实质性要求，并且经评审的投标价格合理最低；但投标价格低于成本的除外。"},{"i":51,"n":"第五十一条","txt":"招标人可授权评标委员会直接确定中标人，也可根据评标委员会提出的书面评标报告和推荐的中标候选人顺序确定中标人。当招标人确定的中标人与评标委员会推荐的中标候选人顺序不一致时，应当有充足的理由，并按项目管理权限报水行政主管部门备案。"},{"i":52,"n":"第五十二条","txt":"自中标通知书发出之日起30日内，招标人和中标人应当按照招标文件和中标人的投标文件订立书面合同，中标人提交履约保函。招标人和中标人不得另行订立背离招标文件实质性内容的其他协议。"},{"i":53,"n":"第五十三条","txt":"招标人在确定中标人后，应当在15日之内按项目管理权限向水行政主管部门提交招标投标情况的书面报告。"},{"i":54,"n":"第五十四条","txt":"当确定的中标人拒绝签订合同时，招标人可与确定的候补中标人签订合同，并按项目管理权限向水行政主管部门备案。"},{"i":55,"n":"第五十五条","txt":"由于招标人自身原因致使招标工作失败（包括未能如期签订合同），招标人应当按投标保证金双倍的金额赔偿投标人，同时退还投标保证金。"},{"i":56,"n":"第五十六条","txt":"在招标投标活动中出现的违法违规行为，按照《中华人民共和国招标投标法》和国务院的有关规定进行处罚。"},{"i":57,"n":"第五十七条","txt":"各省、自治区、直辖市可以根据本规定，结合本地区实际制订相应的实施办法。"},{"i":58,"n":"第五十八条","txt":"本规定由水利部负责解释。"},{"i":59,"n":"第五十九条","txt":"本规定自2002年1月1日起施行，《水利工程建设项目施工招标投标管理规定》（水建〔1994〕130号1995年4月21日颁发，水政资〔1998〕51号1998年2月9日修正）同时废止。"}],"shuiligongchengjianshexiangmuguanliguiding":[{"i":1,"n":"第一条","txt":"为适应建立社会主义市场经济体制的需要，进一步加强水利工程建设的行业管理，使水利工程建设项目管理逐步走上法制化、规范化的道路，保证水利工程建设的工期、质量、安全和投资效益。根据国家有关政策法规，结合水利水电行业特点，制定本规定。"},{"i":2,"n":"第二条","txt":"本管理规定适用于由国家投资、中央和地方合资、企事业单位独资、合资以及其它投资方式兴建的防洪、除涝、灌溉、发电、供水、围垦等大中型（包括新建、续建、改建、加固、修复）工程建设项目，小型水利工程建设项目可以参照执行。"},{"i":3,"n":"第三条","txt":"水利工程建设项目管理实行统一管理、分级管理和目标管理。逐步建立水利部、流域机构和地方水行政主管部门以及建设项目法人分级、分层次管理的管理体系。"},{"i":4,"n":"第四条","txt":"水利工程建设项目管理要严格按建设程序进行，实行全过程的管理、监督、服务。"},{"i":5,"n":"第五条","txt":"水利工程建设要推行项目法人责任制、招标投标制和建设监理制。积极推行项目管理。"},{"i":6,"n":"第六条","txt":"水利部是国务院水行政主管部门，对全国水利工程建设实行宏观管理。水利部建设司是水利部主管水利建设的综合管理部门，在水利工程建设项目管理方法，其主要管理职责是： 1、贯彻执行国家的方针政策，研究制订水利工程建设的政策法规，并组织实施； 2、对全国水利工程建设项目进行行业管理； 3、组织和协调部属重点水利工程的建设； 4、积极推行水利建设管理体制的改革，培育和完善水利建设市场； 5、指导或参与省属重点大中型工程、中央参与投资的地方大中型工程建设的项目管理。"},{"i":7,"n":"第七条","txt":"流域机构是水利部的派出机构，对其所在流域行使水行政主管部门的职责。负责本流域水利工程建设的行业管理； 1、以水利部投资为主的水利工程建设项目，除少数特别重大项目由水利部直接管理外，其余项目均由所在流域机构负责组织建设和管理。逐步实现按流域综合规划、组织建设、生产经营、滚动开发； 2、流域机构按照国家投资政策，通过多渠道筹集资金，逐步建立流域水利建设投资主体，从而实现国家对流域水利建设项目的管理。"},{"i":8,"n":"第八条","txt":"省（自治区、直辖市）水利（水电）厅（局）是本地区的水行政主管部门，负责本地区水利工程建设的行业管理。 1、负责本地区以地方投资为主的大中型水利工程建设项目的组织建设和管理； 2、支持本地区的国家和部属重点水利工程建设，积极为工程创造良好的建设环境。"},{"i":9,"n":"第九条","txt":"水利工程项目法人对建设项目的立项、筹资、建设、生产经营、还本付息以及资产保值增值的全过程负责，并承担投资风险。代表项目法人对建设项目进行管理的建设单位是项目建设的直接组织者和实施者。负责按项目的建设规模、投资总额、建设工期、工程质量，实行项目建设的全过程管理，对国家或投资各方负责。"},{"i":10,"n":"第十条","txt":"水利是国民经济的基础设施和基础产业。水利工程建设要严格按建设程序进行。水利工程建设程序一般分为：项目建议书、可行性研究报告、施工准备、初步设计、建设实施、生产准备、竣工验收、后评价等阶段。"},{"i":11,"n":"第十一条","txt":"建设前期根据国家总体规划以及流域综合规划，开展前期工作，包括提出项目建议书、可行性研究报告和初步设计（或扩大初步设计）。"},{"i":12,"n":"第十二条","txt":"水利工程建设项目可行性研究报告已经批准，年度水利投资计划下达后，项目法人即可开展施工准备。"},{"i":13,"n":"第十三条","txt":"水利工程具备开工条件后，主体工程方可开工建设。项目法人或者建设单位应当自工程开工之日起15个工作日内，将开工情况的书面报告报项目主管单位和上一级主管单位备案。 主体工程开工，必须具备以下条件： 1.项目法人或者建设单位已经设立； 2.初步设计已经批准，施工详图设计满足主体工程施工需要； 3.建设资金已经落实； 4.主体工程施工单位和监理单位已经确定，并分别订立了合同； 5.质量安全监督单位已经确定，并办理了质量安全监督手续； 6.主要设备和材料已经落实来源； 7.施工准备和征地移民等工作满足主体工程开工需要。"},{"i":14,"n":"第十四条","txt":"项目建设单位要按批准的建设文件，充分发挥管理的主导作用，协调设计、监理、施工以及地方等各方面的关系，实行目标管理。建设单位与设计、监理、工程承包单位是合同关系，各方面应严格履行合同。 1、项目建设单位要建立严格的现场协调或调度制度。及时研究解决设计、施工的关键技术问题。从整体效益出发，认真履行合同，积极处理好工程建设各方的关系，为施工创造良好的外部条件。 2、监理单位受项目建设单位委托，按合同规定在现场从事组织、管理、协调、监督工作。同时，监理单位要站在独立公正的立场上，协调建设单位与设计、施工等单位之间的关系。 3、设计单位应按合同及时提供施工详图，并确保设计质量。按工程规模，派出设计代表组进驻施工现场解决施工中出现的设计问题。 施工详图经监理单位审核后交施工单位施工。设计单位对不涉及重大设计原则问题的合理意见应当采纳并修改设计。若有分歧意见，由建设单位决定。如涉及初步设计重大变更问"},{"i":15,"n":"第十五条","txt":"工程验收要严格按国家和水利部颁布的验收规程进行。 1、工程阶段验收： 阶段验收是工程竣工验收的基础和重要内容，凡能独立发挥作用的单项工程均应进行阶段验收，如：截流（包括分期导流）、下闸蓄水、机组起动、通水等是重要的阶段验收。 2、工程竣工验收： （1）工程基本竣工时，项目建设单位应按验收规程要求组织监理、设计、施工等单位提出有关报告，并按规定将施工过程中的有关资料、文件、图纸造册归档。 （2）在正式竣工验收之前，应根据工程规模由主管部门或由主管部门委托项目建设单位组织初步验收，对初验查出的问题应在正式验收前解决。 （3）质量监督机构要对工程质量提出评价意见。 （4）根据初验情况和项目建设单位的申请验收报告，决定竣工验收有关事宜。 国家重点水利建设项目由国家计委会同水利部主持验收。 部属重点水利建设项目由水利部主持验收。部属其它水利建设项目由流域机构主持验收，水利部进行指导。 中央参与投"},{"i":16,"n":"第十六条","txt":"对生产经营性的水利工程建设项目要积极推行项目法人责任制；其它类型的项目应积极创造条件，逐步实行项目法人责任制。 1、工程建设现场的管理可由项目法人直接负责，也可由项目法人组建或委托一个组织具体负责。负责现场建设管理的机构履行建设单位职能。 2、组建建设单位由项目主管部门或投资各方负责； 建设单位需具备下列条件： （1）具有相对独立的组织形式。内部机构设置，人员配备能满足工程建设的需要； （2）经济上独立核算或分级核算； （3）主要行政和技术、经济负责人是专职人员，并保持相对稳定。"},{"i":17,"n":"第十七条","txt":"凡符合本规定第二条要求的大中型水利建设项目都要实行招标投标制： 1、水利建设项目施工招标投标工作按国家有关规定或国际采购导则进行，并根据工程的规模，投资方式以及工程特点，决定招标方式。 2、主体工程施工招标应具备的必要条件： （1）项目的初步设计已经批准，项目建设已列入计划，投资基本落实； （2）项目建设单位已经组建，并具备应有的建设管理能力； （3）招标文件已经编制完成，施工招标申请书已经批准； （4）施工准备工作已满足主体工程开工的要求。 3、水利建设项目招标工作，由项目建设单位具体组织实施。招标管理按第二章明确的分级管理原则和管理范围，划分如下： （1）水利部负责招标工作的行业管理，直接参与或组织少数特别重大建设项目的招标工作，并做好国家有关部门的协调工作； （2）其他国家和部属重点建设项目以及中央参与投资的地方水利建设项目的招标工作，由流域机构负责管理； （3）地方大中型水利建"},{"i":18,"n":"第十八条","txt":"水利工程建设，要全面推行建设监理制。 1、水利部主管全国水利工程的建设监理工作。 2、水利工程建设监理单位的选择，应采取招标投标的方式确定。 3、要加强对建设监理单位的管理，监理工程师必须持证上岗，监理单位必须持证营业。"},{"i":19,"n":"第十九条","txt":"水利施工企业要积极推行项目管理。项目管理是施工企业走向市场，深化内部改革，转换经营机制，提高管理水平的一种科学的管理方式。 1、施工企业要按项目管理的原则和要求组织施工，在组织结构上，实行项目经理负责制；在经营管理上，建立以经济效益为目标的项目独立核算管理体制；在生产要素配置上，实行优化配置，动态管理；在施工管理上，实行目标管理。 2、项目经理是项目实施过程中的最高组织者和责任者。项目经理必须按国家有关规定，经过专门培训、持证上岗。"},{"i":20,"n":"第二十条","txt":"水利建设项目要贯彻“百年大计，质量第一”的方针，建立健全质量管理体系。 1、水利部水利工程质量监督总站及各级质量监督机构，要认真履行质量监督职责，项目建设各方（建设、监理、设计、施工）必须接受和尊重其监督，支持质量监督机构的工作； 2、建设单位要建立健全施工质量检查体系，按国家和行业技术标准、设计合同文件，检查和控制工程施工质量； 3、施工单位在施工中要推行全面质量管理，建立健全施工质量保证体系，严格执行国家行业技术标准和水利部施工质量管理规定、质量评定标准。 4、发生施工质量事故，必须认真严肃处理。严重质量事故，应由建设单位（或监理单位）组织有关各方联合分析处理，并及时向主管部门报告。"},{"i":21,"n":"第二十一条","txt":"水利工程建设必须贯彻“安全第一，预防为主”的方针。项目主管单位要加强检查、监督；项目建设单位要加强安全宣传和教育工作，督促参加工程建设的各有关单位搞好安全生产。所有的工程合同都要有安全管理条款，所有的工作计划都要有安全生产措施。"},{"i":22,"n":"第二十二条","txt":"要加强水利工程建设的信息交流管理工作。 1、积极利用和发挥中国水利学会水利建设管理专业委员会等学术团体作用，组织学术活动，开展调查研究，推动管理体制改革和科技进步，加强水利建设队伍联络和管理。 2、建立水利工程建设情况报告制度。 （1）项目建设单位定期向主管部门报送工程项目的建设情况。其中：重点工程情况应在水利部月生产协调会5天前报告工程完成情况，包括完成实物工作量，关键进度、投资到位情况和存在的主要问题，月报和年报按有关统计报表规定及时报送，年报内容应增加建设管理情况总结。 （2）部属大中型水利工程建设情况，由项目建设单位定期向流域机构和水利部直接报告；地方大型水利工程建设情况，项目建设单位在报地方水行政主管部门的同时抄报水利部；各流域机构和水利（水电）厅（局）应将所属水利工程建设概况，工程进度和建设管理经验总结，于每年年终向水利部报告一次。"},{"i":23,"n":"第二十三条","txt":"本规定由水利部负责解释。"},{"i":24,"n":"第二十四条","txt":"本规定自公布之日起试行。"}],"shuiligongchengjianshexiangmuyanshouguanliguiding":[{"i":1,"n":"第一条","txt":"为加强水利工程建设项目验收管理，明确验收责任，规范验收行为，结合水利工程建设项目的特点，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于由中央或者地方财政全部投资或者部分投资建设的大中型水利工程建设项目（含1、2、3级堤防工程）的验收活动。"},{"i":3,"n":"第三条","txt":"水利工程建设项目验收，按验收主持单位性质不同分为法人验收和政府验收两类。 法人验收是指在项目建设过程中由项目法人组织进行的验收。法人验收是政府验收的基础。 政府验收是指由有关人民政府、水行政主管部门或者其他有关部门组织进行的验收，包括专项验收、阶段验收和竣工验收。"},{"i":4,"n":"第四条","txt":"水利工程建设项目具备验收条件时，应当及时组织验收。未经验收或者验收不合格的，不得交付使用或者进行后续工程施工。"},{"i":5,"n":"第五条","txt":"水利工程建设项目验收的依据是： （一）国家有关法律、法规、规章和技术标准； （二）有关主管部门的规定； （三）经批准的工程立项文件、初步设计文件、调整概算文件； （四）经批准的设计文件及相应的工程变更文件； （五）施工图纸及主要设备技术说明书等。 法人验收还应当以施工合同为验收依据。"},{"i":6,"n":"第六条","txt":"验收主持单位应当成立验收委员会（验收工作组）进行验收，验收结论应当经三分之二以上验收委员会（验收工作组）成员同意。 验收委员会（验收工作组）成员应当在验收鉴定书上签字。验收委员会（验收工作组）成员对验收结论持有异议的，应当将保留意见在验收鉴定书上明确记载并签字。"},{"i":7,"n":"第七条","txt":"验收中发现的问题，其处理原则由验收委员会（验收工作组）协商确定。主任委员（组长）对争议问题有裁决权。但是，半数以上验收委员会（验收工作组）成员不同意裁决意见的，法人验收应当报请验收监督管理机关决定，政府验收应当报请竣工验收主持单位决定。"},{"i":8,"n":"第八条","txt":"验收委员会（验收工作组）对工程验收不予通过的，应当明确不予通过的理由并提出整改意见。有关单位应当及时组织处理有关问题，完成整改，并按照程序重新申请验收。"},{"i":9,"n":"第九条","txt":"项目法人以及其他参建单位应当提交真实、完整的验收资料，并对提交的资料负责。"},{"i":10,"n":"第十条","txt":"水利部负责全国水利工程建设项目验收的监督管理工作。 水利部所属流域管理机构（以下简称流域管理机构）按照水利部授权，负责流域内水利工程建设项目验收的监督管理工作。 县级以上地方人民政府水行政主管部门按照规定权限负责本行政区域内水利工程建设项目验收的监督管理工作。"},{"i":11,"n":"第十一条","txt":"法人验收监督管理机关对项目的法人验收工作实施监督管理。 由水行政主管部门或者流域管理机构组建项目法人的，该水行政主管部门或者流域管理机构是本项目的法人验收监督管理机关；由地方人民政府组建项目法人的，该地方人民政府水行政主管部门是本项目的法人验收监督管理机关。"},{"i":12,"n":"第十二条","txt":"工程建设完成分部工程、单位工程、单项合同工程，或者中间机组启动前，应当组织法人验收。项目法人可以根据工程建设的需要增设法人验收的环节。"},{"i":13,"n":"第十三条","txt":"项目法人应当自工程开工之日起60个工作日内，制定法人验收工作计划，报法人验收监督管理机关和竣工验收主持单位备案。"},{"i":14,"n":"第十四条","txt":"施工单位在完成相应工程后，应当向项目法人提出验收申请。项目法人经检查认为建设项目具备相应的验收条件的，应当及时组织验收。"},{"i":15,"n":"第十五条","txt":"法人验收由项目法人主持。验收工作组由项目法人、设计、施工、监理等单位的代表组成；必要时可以邀请工程运行管理单位等参建单位以外的代表及专家参加。 项目法人可以委托监理单位主持分部工程验收，有关委托权限应当在监理合同或者委托书中明确。"},{"i":16,"n":"第十六条","txt":"法人验收后，质量评定结论应当报该项目的质量监督机构核备。未经核备的，不得组织下一阶段验收。"},{"i":17,"n":"第十七条","txt":"项目法人应当自法人验收通过之日起30个工作日内，制作法人验收鉴定书，发送参加验收单位并报送法人验收监督管理机关备案。 法人验收鉴定书是政府验收的备查资料。"},{"i":18,"n":"第十八条","txt":"单位工程投入使用验收和单项合同工程完工验收通过后，项目法人应当与施工单位办理工程的有关交接手续。 工程保修期从通过单项合同工程完工验收之日算起，保修期限按合同约定执行。"},{"i":19,"n":"第十九条","txt":"阶段验收、竣工验收由竣工验收主持单位主持。竣工验收主持单位可以根据工作需要委托其他单位主持阶段验收。 专项验收依照国家有关规定执行。"},{"i":20,"n":"第二十条","txt":"国家重点水利工程建设项目，竣工验收主持单位依照国家有关规定确定。 除前款规定以外，在国家确定的重要江河、湖泊建设的流域控制性工程、流域重大骨干工程建设项目，竣工验收主持单位为水利部。 除前两款规定以外的其他水利工程建设项目，竣工验收主持单位按照以下原则确定： （一）水利部或者流域管理机构负责初步设计审批的中央项目，竣工验收主持单位为水利部或者流域管理机构； （二）水利部负责初步设计审批的地方项目，以中央投资为主的，竣工验收主持单位为水利部或者流域管理机构，以地方投资为主的，竣工验收主持单位为省级人民政府（或者其委托的单位）或者省级人民政府水行政主管部门（或者其委托的单位）； （三）地方负责初步设计审批的项目，竣工验收主持单位为省级人民政府水行政主管部门（或者其委托的单位）。 竣工验收主持单位为水利部或者流域管理机构的，可以根据工程实际情况，会同省级人民政府或者有关部门共同主持。 竣工验"},{"i":21,"n":"第二十一条","txt":"枢纽工程导（截）流、水库下闸蓄水等阶段验收前，涉及移民安置的，应当完成相应的移民安置专项验收。 工程竣工验收前，应当按照国家有关规定，进行环境保护、水土保持、移民安置以及工程档案等专项验收。经商有关部门同意，专项验收可以与竣工验收一并进行。"},{"i":22,"n":"第二十二条","txt":"项目法人应当自收到专项验收成果文件之日起10个工作日内，将专项验收成果文件报送竣工验收主持单位备案。 专项验收成果文件是阶段验收或者竣工验收成果文件的组成部分。"},{"i":23,"n":"第二十三条","txt":"工程建设进入枢纽工程导（截）流、水库下闸蓄水、引（调）排水工程通水、首（末）台机组启动等关键阶段，应当组织进行阶段验收。 竣工验收主持单位根据工程建设的实际需要，可以增设阶段验收的环节。"},{"i":24,"n":"第二十四条","txt":"阶段验收的验收委员会由验收主持单位、该项目的质量监督机构和安全监督机构、运行管理单位的代表以及有关专家组成；必要时，应当邀请项目所在地的地方人民政府以及有关部门参加。 工程参建单位是被验收单位，应当派代表参加阶段验收工作。"},{"i":25,"n":"第二十五条","txt":"大型水利工程在进行阶段验收前，可以根据需要进行技术预验收。技术预验收参照本章第四节有关竣工技术预验收的规定进行。"},{"i":26,"n":"第二十六条","txt":"水库下闸蓄水验收前，项目法人应当按照有关规定完成蓄水安全鉴定。"},{"i":27,"n":"第二十七条","txt":"验收主持单位应当自阶段验收通过之日起30个工作日内，制作阶段验收鉴定书，发送参加验收的单位并报送竣工验收主持单位备案。 阶段验收鉴定书是竣工验收的备查资料。"},{"i":28,"n":"第二十八条","txt":"竣工验收应当在工程建设项目全部完成并满足一定运行条件后1年内进行。不能按期进行竣工验收的，经竣工验收主持单位同意，可以适当延长期限，但最长不得超过6个月。逾期仍不能进行竣工验收的，项目法人应当向竣工验收主持单位作出专题报告。"},{"i":29,"n":"第二十九条","txt":"竣工财务决算应当由竣工验收主持单位组织审查和审计。竣工财务决算审计通过15日后，方可进行竣工验收。"},{"i":30,"n":"第三十条","txt":"工程具备竣工验收条件的，项目法人应当提出竣工验收申请，经法人验收监督管理机关审查后报竣工验收主持单位。竣工验收主持单位应当自收到竣工验收申请之日起20个工作日内决定是否同意进行竣工验收。"},{"i":31,"n":"第三十一条","txt":"竣工验收原则上按照经批准的初步设计所确定的标准和内容进行。 项目有总体初步设计又有单项工程初步设计的，原则上按照总体初步设计的标准和内容进行，也可以先进行单项工程竣工验收，最后按照总体初步设计进行总体竣工验收。 项目有总体可行性研究但没有总体初步设计而有单项工程初步设计的，原则上按照单项工程初步设计的标准和内容进行竣工验收。 建设周期长或者因故无法继续实施的项目，对已完成的部分工程可以按单项工程或者分期进行竣工验收。"},{"i":32,"n":"第三十二条","txt":"竣工验收分为竣工技术预验收和竣工验收两个阶段。"},{"i":33,"n":"第三十三条","txt":"大型水利工程在竣工技术预验收前，项目法人应当按照有关规定对工程建设情况进行竣工验收技术鉴定。中型水利工程在竣工技术预验收前，竣工验收主持单位可以根据需要决定是否进行竣工验收技术鉴定。"},{"i":34,"n":"第三十四条","txt":"竣工技术预验收由竣工验收主持单位以及有关专家组成的技术预验收专家组负责。 工程参建单位的代表应当参加技术预验收，汇报并解答有关问题。"},{"i":35,"n":"第三十五条","txt":"竣工验收的验收委员会由竣工验收主持单位、有关水行政主管部门和流域管理机构、有关地方人民政府和部门、该项目的质量监督机构和安全监督机构、工程运行管理单位的代表以及有关专家组成。工程投资方代表可以参加竣工验收委员会。"},{"i":36,"n":"第三十六条","txt":"竣工验收主持单位可以根据竣工验收的需要，委托具有相应资质的工程质量检测机构对工程质量进行检测。"},{"i":37,"n":"第三十七条","txt":"项目法人全面负责竣工验收前的各项准备工作，设计、施工、监理等工程参建单位应当做好有关验收准备和配合工作，派代表出席竣工验收会议，负责解答验收委员会提出的问题，并作为被验收单位在竣工验收鉴定书上签字。"},{"i":38,"n":"第三十八条","txt":"竣工验收主持单位应当自竣工验收通过之日起30个工作日内，制作竣工验收鉴定书，并发送有关单位。 竣工验收鉴定书是项目法人完成工程建设任务的凭据。"},{"i":39,"n":"第三十九条","txt":"项目法人和其他有关单位应当按照竣工验收鉴定书的要求妥善处理竣工验收遗留问题和完成尾工。 验收遗留问题处理完毕和尾工完成并通过验收后，项目法人应当将处理情况和验收成果报送竣工验收主持单位。"},{"i":40,"n":"第四十条","txt":"项目法人与工程运行管理单位不同的，工程通过竣工验收后，应当及时办理移交手续。 工程移交后，项目法人以及其他参建单位应当按照法律法规的规定和合同约定，承担后续的相关质量责任。项目法人已经撤消的，由撤消该项目法人的部门承接相关的责任。"},{"i":41,"n":"第四十一条","txt":"违反本规定，项目法人不按时限要求组织法人验收或者不具备验收条件而组织法人验收的，由法人验收监督管理机关责令改正。"},{"i":42,"n":"第四十二条","txt":"项目法人以及其他参建单位提交验收资料不真实导致验收结论有误的，由提交不真实验收资料的单位承担责任。竣工验收主持单位收回验收鉴定书，对责任单位予以通报批评；造成严重后果的，依照有关法律法规处罚。"},{"i":43,"n":"第四十三条","txt":"参加验收的专家在验收工作中玩忽职守、徇私舞弊的，由验收监督管理机关予以通报批评；情节严重的，取消其参加验收的资格；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"国家机关工作人员在验收工作中玩忽职守、滥用职权、徇私舞弊，尚不构成犯罪的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"本规定所称项目法人，包括实行代建制项目中，经项目法人委托的项目代建机构。"},{"i":46,"n":"第四十六条","txt":"水利工程建设项目验收应当具备的条件、验收程序、验收主要工作以及有关验收资料和成果性文件等具体要求，按照有关验收规程执行。"},{"i":47,"n":"第四十七条","txt":"政府验收所需费用应当列入工程投资，由项目法人列支。"},{"i":48,"n":"第四十八条","txt":"其他水利工程建设项目的验收活动，可以参照本规定执行。"},{"i":49,"n":"第四十九条","txt":"流域管理机构、省级人民政府水行政主管部门可以根据本规定制定验收管理实施细则。"},{"i":50,"n":"第五十条","txt":"现行水利工程建设项目有关验收规定以及标准与本规定不一致的，按照本规定执行。"},{"i":51,"n":"第五十一条","txt":"本规定自2007年4月1日起施行。"}],"shuiligongchengzhiliangshiguchuliguiding":[{"i":1,"n":"第一条","txt":"为了加强水利工程质量管理，规范水利工程质量事故处理，落实质量责任，根据《中华人民共和国建筑法》《建设工程质量管理条例》《建设工程勘察设计管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称水利工程质量事故，是指水利工程在建设过程中因建设管理、勘察、设计、施工、监理、检测等原因造成工程质量不满足法律法规、强制性标准和工程设计文件的质量要求，影响工程主要功能正常使用，造成一定经济损失，必须进行工程处理的事件。"},{"i":3,"n":"第三条","txt":"本规定适用于水利工程质量事故处理。因质量事故造成的生产安全事故，还应当执行生产安全事故处理相关规定。"},{"i":4,"n":"第四条","txt":"水利工程质量事故调查处理，应当实事求是、尊重科学、依法依规，坚持事故原因未查清不放过、责任人员未处理不放过、整改措施未落实不放过、有关人员未受到教育不放过的“四不放过”原则。"},{"i":5,"n":"第五条","txt":"水利部负责监督管理全国水利工程质量事故处理工作。 水利部所属流域管理机构（以下简称流域管理机构）负责监督管理其管辖范围内的水利工程质量事故处理工作。 县级以上地方人民政府水行政主管部门在职责范围内负责监督管理本行政区域水利工程质量事故处理工作。"},{"i":6,"n":"第六条","txt":"任何单位和个人对水利工程质量事故和事故调查处理中的违法行为有权检举、控告、投诉。"},{"i":7,"n":"第七条","txt":"水利工程质量事故按直接经济损失、事故处理所需合理工期，分为特别重大质量事故、重大质量事故、较大质量事故、一般质量事故。 （一）特别重大质量事故，是指造成直接经济损失1亿元（人民币，下同）以上，或者事故处理所需合理工期6个月以上； （二）重大质量事故，是指造成直接经济损失5000万元以上1亿元以下，或者事故处理所需合理工期3个月以上6个月以下； （三）较大质量事故，是指造成直接经济损失1000万元以上5000万元以下，或者事故处理所需合理工期1个月以上3个月以下的事故； （四）一般质量事故，是指造成直接经济损失100万元以上1000万元以下，或者事故处理所需合理工期15日以上1个月以下的事故。 不构成一般质量事故的，按照《水利工程质量管理规定》和有关技术标准处理。 前款所称直接经济损失，是指事故处理所需的材料、设备、人工等直接费用；所称的“以上”包括本数，“以下”不包括本数。"},{"i":8,"n":"第八条","txt":"发现质量事故后，项目法人和相关事故单位应当及时采取有效措施，防止事故扩大并进行拍照、录像，严格保护现场，妥善保管现场重要痕迹、物证；因事故救援等原因需移动现场物件时，应当作出标志、绘制现场简图并书面记录；及时封存相关记录、检测、检验等证据资料。"},{"i":9,"n":"第九条","txt":"质量事故现场有关人员应当立即报告本单位负责人和项目法人。项目法人应当在质量事故发现2小时内，向负责项目监督管理的县级以上地方人民政府水行政主管部门或者流域管理机构（以下统称项目监督管理部门）报告，并在24小时内报送事故报告。 任何单位和个人不得迟报、谎报、瞒报。事故报告后出现新情况，应当及时续报。"},{"i":10,"n":"第十条","txt":"事故报告应当包括以下内容： （一）工程概况。主要包括工程名称、工程等级、建设地点、主要功能、批复工期，项目法人及其主要负责人姓名、电话； （二）质量事故情况。主要包括事故发生的时间、工程部位、事故发生的简要经过以及相应的参建单位； （三）事故发生原因初步分析； （四）估算事故等级。主要包括初步估算的直接经济损失、事故处理所需合理工期、事故等级； （五）事故发生后采取的措施及事故控制情况； （六）其他应该报告的情况。"},{"i":11,"n":"第十一条","txt":"项目监督管理部门接到事故报告后，应当及时指导项目法人和相关事故单位做好现场处置等相关工作，核实事故情况，初步判断事故等级，并按照以下规定逐级上报： 县级以上地方人民政府水行政主管部门初步判断为特别重大、重大质量事故的，应当立即报告同级人民政府和上一级水行政主管部门，并逐级报告至流域管理机构、水利部；初步判断为较大质量事故的，应当逐级报告至省级水行政主管部门、流域管理机构。每级上报的时间不得超过2小时。 流域管理机构初步判断为特别重大、重大质量事故的，应当立即报告水利部。"},{"i":12,"n":"第十二条","txt":"上级水行政主管部门、流域管理机构接到质量事故报告后，应当加强对事故调查处理工作的跟踪、督促、指导。"},{"i":13,"n":"第十三条","txt":"水利工程质量事故实行分级调查，按照初步判断的事故等级确定事故调查单位。 （一）特别重大质量事故由水利部组织调查； （二）重大质量事故，由省级水行政主管部门、流域管理机构按照项目监督管理权限组织调查； （三）较大质量事故，由县级以上地方人民政府水行政主管部门、流域管理机构按照项目监督管理权限组织调查； （四）一般质量事故由项目法人组织调查。"},{"i":14,"n":"第十四条","txt":"上级水行政主管部门认为有必要的，可以组织调查由下级水行政主管部门或者项目法人负责调查的质量事故。"},{"i":15,"n":"第十五条","txt":"事故调查单位应当组织成立事故调查组，确定调查组成员，指定调查组组长。事故调查组成员应当具有事故调查所需要的专业和专长，并与所调查的事故项目没有直接利害关系。 事故调查组组长主持事故调查组的工作。事故调查组的主要任务是： （一）查明事故发生的原因、过程、直接经济损失情况、事故处理所需合理工期和对后续工程的影响，对事故等级进行认定； （二）必要时组织具备相关技术能力的单位或者专家进行技术鉴定； （三）提出事故处理和防范措施建议； （四）查明事故的责任单位和责任人应负的责任，提出处理建议； （五）提交事故调查报告。 事故调查组认定事故等级超出调查单位权限范围的，应当提请事故调查单位报告上一级水行政主管部门。"},{"i":16,"n":"第十六条","txt":"事故调查组有权向工程参建单位和个人了解事故情况，并要求提供相关文件、资料，有关单位和个人不得拒绝或者隐瞒。"},{"i":17,"n":"第十七条","txt":"事故相关单位的负责人和有关人员在事故调查期间不得擅离职守，并应当接受事故调查组的询问，如实提供有关情况。 不得以任何方式阻碍或者干扰事故调查组正常工作。"},{"i":18,"n":"第十八条","txt":"事故调查组成员在事故调查工作中应当诚信公正、恪尽职守，遵守纪律、保守秘密，不得向无关人员透露或者擅自发布事故相关信息。"},{"i":19,"n":"第十九条","txt":"事故调查组应当自成立之日起60日内提交事故调查报告；情况复杂，不能在规定期限内提交事故调查报告的，经事故调查单位批准，可以适当延长；但延长的期限最多不超过60日。因技术复杂需要组织技术鉴定的，技术鉴定所需时间不计入事故调查期限。"},{"i":20,"n":"第二十条","txt":"事故调查报告应当包括下列内容： （一）工程项目概况； （二）事故发生和处置； （三）技术分析与鉴定； （四）事故原因分析； （五）事故等级认定； （六）事故责任认定和事故责任处理建议； （七）事故处理和防范措施建议。 事故调查报告应当附具有关证据材料，包括现场调查记录、图纸、照片，有关质量检测报告和技术分析报告，直接经济损失材料，发生事故部位的工艺条件、操作情况和设计文件等附件资料。 事故调查组成员应当在事故调查报告上签名。"},{"i":21,"n":"第二十一条","txt":"事故调查组提交的调查报告经事故调查单位同意后，调查工作即告结束。事故调查单位应当归档保存事故调查有关资料。"},{"i":22,"n":"第二十二条","txt":"事故调查完成30日内，省级水行政主管部门和流域管理机构应当组织将事故调查报告报送至水利部。"},{"i":23,"n":"第二十三条","txt":"事故调查费用由项目法人先行垫付，查清责任后，由事故责任单位负担。"},{"i":24,"n":"第二十四条","txt":"项目法人应当组织勘察、设计等单位制订工程处理方案，征求事故调查组意见，并报经事故调查单位同意后实施。 县级以上人民政府水行政主管部门、流域管理机构应当按照项目管理权限督促项目法人按照要求全面完成事故处理任务。项目法人应当将事故处理结果报事故调查单位备案。"},{"i":25,"n":"第二十五条","txt":"工程处理所需费用原则上由事故责任单位承担。对因质量事故造成的其他损失和工期延误等，按合同约定进行处置。"},{"i":26,"n":"第二十六条","txt":"工程处理需要进行设计变更的，应当按照设计变更管理相关规定组织编制设计变更文件、履行设计变更程序。涉及事故应急抢险的，可按要求实施后再履行相关变更手续。"},{"i":27,"n":"第二十七条","txt":"事故部位处理完成后，应当按规定进行质量验收，合格后方可投入使用或者进入下一阶段施工。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府水行政主管部门、流域管理机构等单位的工作人员在水利工程质量事故报告、调查和处理工作中玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予政务处分。"},{"i":29,"n":"第二十九条","txt":"违反本规定，事故相关单位迟报、谎报、瞒报水利工程质量事故的，由项目监督管理部门依据职权责令改正，给予警告或者通报批评；情节严重的，处5万元以上10万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"项目法人、勘察单位、设计单位、施工单位、监理单位、检测单位和有关人员违反建设管理相关规定，工程质量不符合规定的质量标准的，或者处理后不依照有关规定进行质量验收的，依据有关法律法规和规章的规定给予行政处罚、行政处理。"},{"i":31,"n":"第三十一条","txt":"因原材料、中间产品和设备供应单位供应的产品质量问题造成质量事故的，事故调查单位应当将质量问题移交有关主管部门依法处理。"},{"i":32,"n":"第三十二条","txt":"在水利工程运行过程中发现的工程建设质量问题，依据《中华人民共和国建筑法》《建设工程质量管理条例》《建设工程勘察设计管理条例》《水利工程质量管理规定》等法律法规规章和本规定追究有关责任。"},{"i":33,"n":"第三十三条","txt":"国家对重特大突发事件或者重要紧急情况信息报送、特别重大质量事故调查有规定的，从其规定。"},{"i":34,"n":"第三十四条","txt":"本规定自2025年1月1日起施行。1999年3月4日水利部发布的《水利工程质量事故处理暂行规定》同时废止。"}],"shuiligongchengzhiliangjianceguanliguiding":[{"i":1,"n":"第一条","txt":"为加强水利工程质量检测管理，规范水利工程质量检测行为，根据《建设工程质量管理条例》、《国务院对确需保留的行政审批项目设定行政许可的决定》，制定本规定。"},{"i":2,"n":"第二条","txt":"从事水利工程质量检测活动以及对水利工程质量检测实施监督管理，适用本规定。 本规定所称水利工程质量检测（以下简称质量检测），是指水利工程质量检测单位（以下简称检测单位）依据国家有关法律、法规和标准，对水利工程实体以及用于水利工程的原材料、中间产品、金属结构和机电设备等进行的检查、测量、试验或者度量，并将结果与有关标准、要求进行比较以确定工程质量是否合格所进行的活动。"},{"i":3,"n":"第三条","txt":"检测单位应当按照本规定取得资质，并在资质等级许可的范围内承担质量检测业务。 检测单位资质分为岩土工程、混凝土工程、金属结构、机械电气和量测共5个类别，每个类别分为甲级、乙级2个等级。检测单位资质等级标准由水利部另行制定并向社会公告。 取得甲级资质的检测单位可以承担各等级水利工程的质量检测业务。大型水利工程（含一级堤防）主要建筑物以及水利工程质量与安全事故鉴定的质量检测业务，必须由具有甲级资质的检测单位承担。取得乙级资质的检测单位可以承担除大型水利工程（含一级堤防）主要建筑物以外的其他各等级水利工程的质量检测业务。 前款所称主要建筑物是指失事以后将造成下游灾害或者严重影响工程功能和效益的建筑物，如堤坝、泄洪建筑物、输水建筑物、电站厂房和泵站等。"},{"i":4,"n":"第四条","txt":"从事水利工程质量检测的专业技术人员（以下简称检测人员），应当具备相应的质量检测知识和能力，并按照国家职业资格管理的规定取得从业资格。"},{"i":5,"n":"第五条","txt":"水利部负责审批检测单位甲级资质；省、自治区、直辖市人民政府水行政主管部门负责审批检测单位乙级资质。 检测单位资质原则上采用集中审批方式，受理时间由审批机关提前三个月向社会公告。"},{"i":6,"n":"第六条","txt":"检测单位应当向审批机关提交下列申请材料：      （一）《水利工程质量检测单位资质等级申请表》； 　　（二）计量认证资质证书和证书附表复印件； 　　（三）主要试验检测仪器、设备清单； 　　（四）主要负责人、技术负责人的职称证书复印件； 　　（五）管理制度及质量控制措施。 　　具有乙级资质的检测单位申请甲级资质的，还需提交近三年承担质量检测业务的业绩及相关证明材料。 　　检测单位可以同时申请不同专业类别的资质。"},{"i":7,"n":"第七条","txt":"审批机关收到检测单位的申请材料后，应当依法作出是否受理的决定，并向检测单位出具书面凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次告知检测单位需要补正的全部内容。 审批机关应当在法定期限内作出批准或者不予批准的决定。听证、专家评审及公示所需时间不计算在法定期限内，行政机关应当将所需时间书面告知申请人。决定予以批准的，颁发《水利工程质量检测单位资质等级证书》（以下简称《资质等级证书》）；不予批准的，应当书面通知检测单位并说明理由。"},{"i":8,"n":"第八条","txt":"审批机关在作出决定前，应当组织对申请材料进行评审，必要时可以组织专家进行现场评审，并将评审结果公示，公示时间不少于7日。"},{"i":9,"n":"第九条","txt":"《资质等级证书》有效期为3年。有效期届满，需要延续的，检测单位应当在有效期届满30日前，向原审批机关提出申请。原审批机关应当在有效期届满前作出是否延续的决定。 原审批机关应当重点核查检测单位仪器设备、检测人员、场所的变动情况，检测工作的开展情况以及质量保证体系的执行情况，必要时，可以组织专家进行现场核查。"},{"i":10,"n":"第十条","txt":"检测单位变更名称、地址、法定代表人、技术负责人的，应当自发生变更之日起60日内到原审批机关办理资质等级证书变更手续。"},{"i":11,"n":"第十一条","txt":"检测单位发生分立的，应当按照本规定重新申请资质等级。"},{"i":12,"n":"第十二条","txt":"任何单位和个人不得涂改、倒卖、出租、出借或者以其他形式非法转让《资质等级证书》。"},{"i":13,"n":"第十三条","txt":"检测单位应当建立健全质量保证体系，采用先进、实用的检测设备和工艺，完善检测手段，提高检测人员的技术水平，确保质量检测工作的科学、准确和公正。"},{"i":14,"n":"第十四条","txt":"检测单位不得转包质量检测业务；未经委托方同意，不得分包质量检测业务。"},{"i":15,"n":"第十五条","txt":"检测单位应当按照国家和行业标准开展质量检测活动；没有国家和行业标准的，由检测单位提出方案，经委托方确认后实施。 检测单位违反法律、法规和强制性标准，给他人造成损失的，应当依法承担赔偿责任。"},{"i":16,"n":"第十六条","txt":"质量检测试样的取样应当严格执行国家和行业标准以及有关规定。 提供质量检测试样的单位和个人，应当对试样的真实性负责。"},{"i":17,"n":"第十七条","txt":"检测单位应当按照合同和有关标准及时、准确地向委托方提交质量检测报告并对质量检测报告负责。 任何单位和个人不得明示或者暗示检测单位出具虚假质量检测报告，不得篡改或者伪造质量检测报告。"},{"i":18,"n":"第十八条","txt":"检测单位应当将存在工程安全问题、可能形成质量隐患或者影响工程正常运行的检测结果以及检测过程中发现的项目法人（建设单位）、勘测设计单位、施工单位、监理单位违反法律、法规和强制性标准的情况，及时报告委托方和具有管辖权的水行政主管部门或者流域管理机构。"},{"i":19,"n":"第十九条","txt":"检测单位应当建立档案管理制度。检测合同、委托单、原始记录、质量检测报告应当按年度统一编号，编号应当连续，不得随意抽撤、涂改。 检测单位应当单独建立检测结果不合格项目台账。"},{"i":20,"n":"第二十条","txt":"检测人员应当按照法律、法规和标准开展质量检测工作，并对质量检测结果负责。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府水行政主管部门应当加强对检测单位及其质量检测活动的监督检查，主要检查下列内容： （一）是否符合资质等级标准； （二）是否有涂改、倒卖、出租、出借或者以其他形式非法转让《资质等级证书》的行为； （三）是否存在转包、违规分包检测业务及租借、挂靠资质等违规行为； （四）是否按照有关标准和规定进行检测； （五）是否按照规定在质量检测报告上签字盖章，质量检测报告是否真实； （六）仪器设备的运行、检定和校准情况； （七）法律、法规规定的其他事项。 流域管理机构应当加强对所管辖的水利工程的质量检测活动的监督检查。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府水行政主管部门和流域管理机构实施监督检查时，有权采取下列措施： （一）要求检测单位或者委托方提供相关的文件和资料； （二）进入检测单位的工作场地（包括施工现场）进行抽查； （三）组织进行比对试验以验证检测单位的检测能力； （四）发现有不符合国家有关法律、法规和标准的检测行为时，责令改正。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府水行政主管部门和流域管理机构在监督检查中，可以根据需要对有关试样和检测资料采取抽样取证的方法；在证据可能灭失或者以后难以取得的情况下，经负责人批准，可以先行登记保存，并在5日内作出处理，在此期间，当事人和其他有关人员不得销毁或者转移试样和检测资料。"},{"i":24,"n":"第二十四条","txt":"违反本规定，未取得相应的资质，擅自承担检测业务的，其检测报告无效，由县级以上人民政府水行政主管部门责令改正，可并处1万元以上3万元以下的罚款。"},{"i":25,"n":"第二十五条","txt":"隐瞒有关情况或者提供虚假材料申请资质的，审批机关不予受理或者不予批准，并给予警告或者通报批评,二年之内不得再次申请资质。"},{"i":26,"n":"第二十六条","txt":"以欺骗、贿赂等不正当手段取得《资质等级证书》的，由审批机关予以撤销，3年内不得再次申请，可并处1万元以上3万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"检测单位违反本规定，有下列行为之一的，由县级以上人民政府水行政主管部门责令改正，有违法所得的，没收违法所得，可并处1万元以上3万元以下的罚款；构成犯罪的，依法追究刑事责任： （一）超出资质等级范围从事检测活动的； （二）涂改、倒卖、出租、出借或者以其他形式非法转让《资质等级证书》的； （三）使用不符合条件的检测人员的； （四）未按规定上报发现的违法违规行为和检测不合格事项的； （五）未按规定在质量检测报告上签字盖章的； （六）未按照国家和行业标准进行检测的； （七）档案资料管理混乱，造成检测数据无法追溯的； （八）转包、违规分包检测业务的。"},{"i":28,"n":"第二十八条","txt":"检测单位伪造检测数据，出具虚假质量检测报告的，由县级以上人民政府水行政主管部门给予警告，并处3万元罚款；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"违反本规定，委托方有下列行为之一的，由县级以上人民政府水行政主管部门责令改正，可并处1万元以上3万元以下的罚款： （一）委托未取得相应资质的检测单位进行检测的； （二）明示或暗示检测单位出具虚假检测报告，篡改或伪造检测报告的； （三）送检试样弄虚作假的。"},{"i":30,"n":"第三十条","txt":"检测人员从事质量检测活动中，有下列行为之一的，由县级以上人民政府水行政主管部门责令改正，给予警告，可并处1千元以下罚款： （一）不如实记录，随意取舍检测数据的； （二）弄虚作假、伪造数据的； （三）未执行法律、法规和强制性标准的。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府水行政主管部门、流域管理机构及其工作人员，有下列行为之一的，由其上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）对符合法定条件的申请不予受理或者不在法定期限内批准的； （二）对不符合法定条件的申请人签发《资质等级证书》的； （三）利用职务上的便利，收受他人财物或者其他好处的； （四）不依法履行监督管理职责，或者发现违法行为不予查处的。"},{"i":32,"n":"第三十二条","txt":"本规定自2009年1月1日起施行。2000年《水利工程质量检测管理规定》（水建管〔2000〕2号）同时废止。"}],"shuiligongchengzhiliangjianduguanliguiding":[{"i":1,"n":"第一条","txt":"根据《质量振兴纲要（1996年～2010年）》和《中华人民共和国水法》，为加强水行政主管部门对水利工程质量的监督管理，保证工程质量，确保工程安全，发挥投资效益，制订本规定。"},{"i":2,"n":"第二条","txt":"水行政主管部门主管水利工程质量监督工作。水利工程质量监督机构是水行政主管部门对水利工程质量进行监督管理的专职机构，对水利工程质量进行强制性的监督管理。"},{"i":3,"n":"第三条","txt":"在我国境内新建、扩建、改建、加固各类水利水电工程和城镇供水、滩涂围垦等工程（以下简称水利工程）及其技术改造，包括配套与附属工程，均必须由水利工程质量监督机构负责质量监督。工程建设、监理、设计和施工单位在工程建设阶段，必须接受质量监督机构的监督。"},{"i":4,"n":"第四条","txt":"工程质量监督的依据： （一）国家有关的法律、法规。 （二）水利水电行业有关技术规程、规范，质量标准。 （三）经批准的设计文件等。"},{"i":5,"n":"第五条","txt":"工程竣工验收前，必须经质量监督机构对工程质量进行等级核验。未经工程质量等级核验或者核验不合格的工程，不得交付使用。 工程在申报优秀设计、优秀施工、优质工程项目时，必须有相应质量监督机构签署的工程质量评定意见。"},{"i":6,"n":"第六条","txt":"水利部主管全国水利工程质量监督工作，水利工程质量监督机构按总站、中心站、站三级设置。 （一）水利部设置全国水利工程质量监督总站，办事机构设在建设司。水利水电规划设计管理局设置水利工程设计质量监督分站，各流域机构设置流域水利工程质量监督分站作为总站的派出机构。 （二）各省、自治区、直辖市水利（水电）厅（局），新疆生产建设兵团水利局设置水利工程质量监督中心站。 （三）各地（市）水利（水电）局设置水利工程质量监督站。各级质量监督机构隶属于同级水行政主管部门，业务上接受上一级质量监督机构的指导。"},{"i":7,"n":"第七条","txt":"水利工程质量监督项目站（组），是相应质量监督机构的派出单位。"},{"i":8,"n":"第八条","txt":"各级质量监督机构的站长一般应由同级水行政主管部门主管工程建设的领导兼任，有条件的可配备相应级别的专职副站长。各级质量监督机构的正副站长由其主管部门任命，并报上一级质量监督机构备案。"},{"i":9,"n":"第九条","txt":"各级质量监督机构应配备一定数量的专职质量监督员。质量监督员的数量由同级水行政主管部门根据工作需要和专业配套的原则确定。"},{"i":10,"n":"第十条","txt":"水利工程质量监督员必须具备以下条件： （一）取得工程师职称，或具有大专以上学历并有5年以上从事水利水电工程设计、施工、监理、咨询或建设管理工作的经历。 （二）坚持原则，秉公办事，认真执法，责任心强。 （三）经过培训并通过考核取得“水利工程质量监督员证”。"},{"i":11,"n":"第十一条","txt":"质量监督机构可聘任符合条件的工程技术人员作为工程项目的兼职质量监督员。为保证质量监督工作的公正性、权威性，凡从事该工程监理、设计、施工、设备制造的人员不得担任该工程的兼职质量监督员。"},{"i":12,"n":"第十二条","txt":"各质量监督分站、中心站、地（市）站和质量监督员必须经上一级质量监督机构考核、认证，取得合格证书后，方可从事质量监督工作。质量监督机构资质每4年复核一次，质量监督员证有效期为4年。"},{"i":13,"n":"第十三条","txt":"“水利工程质量监督机构合格证书”和“水利工程质量监督员证”由水利部统一印制。"},{"i":14,"n":"第十四条","txt":"全国水利工程质量监督总站的主要职责： （一）贯彻执行国家和水利部有关工程建设质量管理的方针、政策。 （二）制订水利工程质量监督、检测有关规定和办法，并监督实施。 （三）归口管理全国水利工程的质量监督工作，指导各分站、中心站的质量监督工作。 （四）对部直属重点工程组织实施质量监督。参加工程的阶段验收和竣工验收。 （五）监督有争议的重大工程质量事故的处理； （六）掌握全国水利工程质量动态，组织交流全国水利工程质量监督工作经验，组织培训质量监督人员。开展全国水利工程质量检查活动。"},{"i":15,"n":"第十五条","txt":"水利工程设计质量监督分站受总站委托承担的主要任务： （一）归口管理全国水利工程的设计质量监督工作。 （二）负责设计全面质量管理工作。 （三）掌握全国水利工程的设计质量动态，定期向总站报告设计质量监督情况。"},{"i":16,"n":"第十六条","txt":"各流域水利工程质量监督分站的主要职责： （一）对本流域内下列工程项目实施质量监督。 1.总站委托监督的部属水利工程。 2.中央与地方合资项目，监督方式由分站和中心站协商确定。 3.省（自治区、直辖市）界及国际边界河流上的水利工程。 （二）监督受监督水利工程质量事故的处理。 （三）参加受监督水利工程的阶段验收和竣工验收。 （四）掌握本流域内水利工程质量动态，及时上报质量监督工作中发现的重大问题，开展水利工程质量检查活动，组织交流本流域内的质量监督工作经验。"},{"i":17,"n":"第十七条","txt":"各省、自治区、直辖市，新疆生产建设兵团水利工程质量监督中心站的职责： （一）贯彻执行国家、水利部和省、自治区、直辖市有关工程建设质量管理的方针、政策。 （二）管理辖区内水利工程的质量监督工作；指导本省、自治区、直辖市的市（地）质量监督站工作。 （三）对辖区内除第十四条、第十六条规定以外的水利工程实施质量监督；协助配合由部总站和流域分站组织监督的水利工程的质量监督工作。 （四）参加受监督水利工程的阶段验收和竣工验收。 （五）监督受监督水利工程质量事故的处理。 （六）掌握辖区内水利工程质量动态和质量监督工作情况，定期向总站报告，同时抄送流域分站；组织培训质量监督人员，开展水利工程质量检查活动，组织交流质量监督工作经验。"},{"i":18,"n":"第十八条","txt":"市（地）水利工程质量监督站的职责，由各中心站根据本规定制订。"},{"i":19,"n":"第十九条","txt":"水利工程建设项目质量监督方式以抽查为主。大型水利工程应建立质量监督项目站，中、小型水利工程可根据需要建立质量监督项目站（组），或进行巡回监督。"},{"i":20,"n":"第二十条","txt":"从工程开工前办理质量监督手续始，到工程竣工验收委员会同意工程交付使用止，为水利工程建设项目的质量监督期（含合同质量保修期）。"},{"i":21,"n":"第二十一条","txt":"项目法人（或建设单位）应在工程开工前到相应的水利工程质量监督机构办理监督手续，签订《水利工程质量监督书》，并按规定缴纳质量监督费，同时提交以下材料： （一）工程项目建设审批文件。 （二）项目法人（或建设单位）与监理、设计、施工单位签订的合同（或协议）副本。 （三）建设、监理、设计、施工等单位的基本情况和工程质量管理组织情况等资料。"},{"i":22,"n":"第二十二条","txt":"质量监督机构根据受监督工程的规模、重要性等，制订质量监督计划，确定质量监督的组织形式。在工程施工中，根据本规定对工程项目实施质量监督。"},{"i":23,"n":"第二十三条","txt":"工程质量监督的主要内容为： （一）对监理、设计、施工和有关产品制作单位的资质进行复核。 （二）对建设、监理单位的质量检查体系和施工单位的质量保证体系以及设计单位现场服务等实施监督检查。 （三）对工程项目的单位工程、分部工程、单元工程的划分进行监督检查。 （四）监督检查技术规程、规范和质量标准的执行情况。 （五）检查施工单位和建设、监理单位对工程质量检验和质量评定情况。 （六）在工程竣工验收前，对工程质量进行等级核定，编制工程质量评定报告，并向工程竣工验收委员令提出工程质量等级的建议。"},{"i":24,"n":"第二十四条","txt":"工程质量监督权限如下： （一）对监理、设计、施工等单位的资质等级、经营范围进行核查，发现越级承包工程等不符合规定要求的，责成建设单位限期改正，并向水行政主管部门报告。 （二）质量监督人员需持“水利工程质量监督员证”进入施工现场执行质量监督。对工程有关部位进行检查，调阅建设、监理单位和施工单位的检测试验成果、检查记录和施工记录。 （三）对违反技术规程、规范、质量标准或设计文件的施工单位，通知建设、监理单位采取纠正措施。问题严重时，可向水行政主管部门提出整顿的建议。 （四）对使用未经检验或检验不合格的建筑材料、构配件及设备等，责成建设单位采取措施纠正。 （五）提请有关部门奖励先进质量管理单位及个人。 （六）提请有关部门或司法机关追究造成重大工程质量事故的单位和个人的行政、经济、刑事责任。"},{"i":25,"n":"第二十五条","txt":"工程质量检测是工程质量监督和质量检查的重要手段。水利工程质量检测单位，必须取得省级以上计量认证合格证书，并经水利工程质量监督机构授权，方可从事水利工程质量检测工作，检测人员必须持证上岗。"},{"i":26,"n":"第二十六条","txt":"质量监督机构根据工作需要，可委托水利工程质量检测单位承担以下主要任务： （一）核查受监督工程参建单位的试验室装备、人员资质、试验方法及成果等。 （二）根据需要对工程质量进行抽样检测，提出检测报告。 （三）参与工程质量事故分析和研究处理方案。 （四）质量监督机构委托的其他任务。"},{"i":27,"n":"第二十七条","txt":"质量检测单位所出具的检测鉴定报告必须实事求是，数据准确可靠，并对出具的数据和报告负法律责任。"},{"i":28,"n":"第二十八条","txt":"工程质量检测实行有偿服务，检测费用由委托方支付。收费标准按有关规定确定。在处理工程质量争端时，发生的一切费用由责任方支付。"},{"i":29,"n":"第二十九条","txt":"项目法人（或建设单位）应向质量监督机构缴纳工程质量监督费。工程质量监督费属事业性收费。工程质量监督收费，根据国家计委等部门的有关文件规定，收费标准按水利工程所在地域确定。原则上，大城市按受监工程建筑安装工作量的0.15%，中等城市按受监工程建筑安装工作量的0.20%，小城市按受监工程建筑安装工作量的0.25%收取。城区以外的水利工程可比照小城市的收费标准适当提高。"},{"i":30,"n":"第三十条","txt":"工程质量监督费由工程建设单位负责缴纳。大中型工程在办理质量监督手续时，应确定缴纳计划，每年按年度投资计划，年初一次结清年度工程质量监督费。中小型水利工程在办理质量监督手续时缴纳工程质量监督费的50%，余额由质量监督部门根据工程进度收缴。 水利工程在工程竣工验收前必须缴清全部的工程质量监督费。"},{"i":31,"n":"第三十一条","txt":"质量监督费应用于质量监督工作的正常经费开支，不得挪作它用。其使用范围主要为：工程质量监督、检测开支以及必要的差旅费开支等。"},{"i":32,"n":"第三十二条","txt":"项目法人（或建设单位）未按第二十一条规定要求办理质量监督手续的，水行政主管部门依据《中华人民共和国行政处罚法》对建设单位进行处罚，并责令限期改正或按有关规定处理。"},{"i":33,"n":"第三十三条","txt":"质量检测单位伪造检测数据，检测结论的，视情节轻重，报上级水行政主管部门对责任单位和责任人按有关规定进行处罚，构成犯罪的由司法机关依法追究其刑事责任。"},{"i":34,"n":"第三十四条","txt":"质量监督员滥用职权、玩忽职守、徇私舞弊的，由质量监督机构提交水行政主管部门视情节轻重，给予行政处分，构成犯罪的由司法机关依法追究其刑事责任。"},{"i":35,"n":"第三十五条","txt":"对在工程质量管理和质量监督工作中做出突出成绩的单位和个人，由质量管理部门或报请水行政主管部门给予表彰和奖励。"},{"i":36,"n":"第三十六条","txt":"各水利工程质量监督中心站可根据本规定制订实施细则，并报全国水利工程质量监督总站核备。"},{"i":37,"n":"第三十七条","txt":"本规定由水利部负责解释。"},{"i":38,"n":"第三十八条","txt":"本规定自发布之日起施行，原《水利基本建设工程质量监督暂行规定》同时废止。"}],"shuiligongchengzhiliangguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强水利工程质量管理，保证水利工程质量，推动水利工程建设高质量发展，根据《中华人民共和国建筑法》、《建设工程质量管理条例》、《建设工程勘察设计管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"从事水利工程建设（包括新建、扩建、改建、除险加固等）有关活动及其质量监督管理，应当遵守本规定。"},{"i":3,"n":"第三条","txt":"水利工程建设应当严格执行基本建设程序，不得超越权限审批建设项目或者擅自简化基本建设程序。"},{"i":4,"n":"第四条","txt":"水利部负责全国水利工程质量的监督管理。  水利部所属流域管理机构（以下简称流域管理机构）依照法律、行政法规规定和水利部授权，负责所管辖范围内水利工程质量的监督管理。  县级以上地方人民政府水行政主管部门在职责范围内负责本行政区域水利工程质量的监督管理。"},{"i":5,"n":"第五条","txt":"项目法人或者建设单位（以下统称项目法人）对水利工程质量承担首要责任。勘察、设计、施工、监理单位对水利工程质量承担主体责任，分别对工程的勘察质量、设计质量、施工质量和监理质量负责。检测、监测单位以及原材料、中间产品、设备供应商等单位依据有关规定和合同，分别对工程质量承担相应责任。  项目法人、勘察、设计、施工、监理、检测、监测单位以及原材料、中间产品、设备供应商等单位的法定代表人及其工作人员，按照各自职责对工程质量依法承担相应责任。"},{"i":6,"n":"第六条","txt":"水利工程实行工程质量终身责任制。项目法人、勘察、设计、施工、监理、检测、监测等单位人员，依照法律法规和有关规定，在工程合理使用年限内对工程质量承担相应责任。"},{"i":7,"n":"第七条","txt":"任何单位和个人对水利工程建设中发生的质量事故、质量缺陷和影响工程质量的行为均有权检举、控告、投诉。"},{"i":8,"n":"第八条","txt":"鼓励水利工程项目法人、勘察、设计、施工、监理等参建单位采用先进的科学技术和管理方法，推行全面质量管理，提升工程质量水平，创建优质工程。  县级以上人民政府水行政主管部门或者流域管理机构按照国家有关规定对提升水利工程质量做出突出贡献的单位和个人进行奖励。"},{"i":9,"n":"第九条","txt":"水利工程各参建单位应当建立健全教育培训制度，对职工进行质量管理教育培训，按照规定开展上岗作业考核，强化质量意识，提高质量管理能力。"},{"i":10,"n":"第十条","txt":"项目法人应当根据水利工程的规模和技术复杂程度明确质量管理机构，建立健全质量管理制度，落实质量责任，实施工程建设的全过程质量管理。"},{"i":11,"n":"第十一条","txt":"项目法人应当将工程依法发包给具有相应资质等级的单位。  项目法人与参建单位签订的合同文件中，应当包括工程质量条款，明确工程质量要求，并约定合同各方的质量责任。  项目法人应当依法向有关的勘察、设计、施工、监理等单位提供与工程有关的原始资料。原始资料必须真实、准确、齐全。"},{"i":12,"n":"第十二条","txt":"项目法人不得迫使市场主体以低于成本的价格竞标，不得任意压缩合理工期。  项目法人不得明示或者暗示勘察、设计、施工单位违反工程建设强制性标准，降低工程质量；不得明示或者暗示施工单位使用不合格的原材料、中间产品和设备。"},{"i":13,"n":"第十三条","txt":"项目法人应当按照国家有关规定办理工程质量监督及开工备案手续，并书面明确各参建单位项目负责人和技术负责人。"},{"i":14,"n":"第十四条","txt":"项目法人应当依据经批准的设计文件，组织编制工程建设执行技术标准清单，明确工程建设质量标准。"},{"i":15,"n":"第十五条","txt":"项目法人应当组织开展施工图设计文件审查。未经审查合格的施工图设计文件，不得使用。  项目法人应当组织或者委托监理单位组织有关参建单位进行勘察、设计交底。  项目法人应当加强设计变更管理，按照规定履行设计变更程序。设计变更未经审查同意的，不得擅自实施。"},{"i":16,"n":"第十六条","txt":"项目法人应当严格依照有关法律、法规、规章、技术标准、批准的设计文件和合同开展验收工作。工程质量符合相关要求的，方可通过验收。"},{"i":17,"n":"第十七条","txt":"项目法人应当对参建单位的质量行为和工程实体质量进行检查，对发现的问题组织责任单位进行整改落实。对发生严重违规行为和质量事故的，项目法人应当及时报告具有管辖权的水行政主管部门或者流域管理机构。"},{"i":18,"n":"第十八条","txt":"工程开工后，项目法人应当在工程施工现场明显部位设立质量责任公示牌，公示项目法人、勘察、设计、施工、监理等参建单位的名称、项目负责人姓名以及质量举报电话，接受社会监督。  工程竣工验收后，项目法人应当在工程明显部位设置永久性标志，载明项目法人、勘察、设计、施工、监理等参建单位名称、项目负责人姓名。"},{"i":19,"n":"第十九条","txt":"项目法人应当按照档案管理的有关规定，及时收集、整理并督促指导其他参建单位收集、整理工程建设各环节的文件资料，建立健全项目档案，并在工程竣工验收后，办理移交手续。"},{"i":20,"n":"第二十条","txt":"水利工程建设实行代建、项目管理总承包等管理模式的，代建、项目管理总承包等单位按照合同约定承担相应质量责任，不替代项目法人的质量责任。"},{"i":21,"n":"第二十一条","txt":"勘察、设计单位应当在其资质等级许可的范围内承揽水利工程勘察、设计业务，禁止超越资质等级许可的范围或者以其他勘察、设计单位的名义承揽水利工程勘察、设计业务，禁止允许其他单位或者个人以本单位的名义承揽水利工程勘察、设计业务，不得转包或者违法分包所承揽的水利工程勘察、设计业务。"},{"i":22,"n":"第二十二条","txt":"勘察、设计单位应当依据有关法律、法规、规章、技术标准、规划、项目批准文件进行勘察、设计，严格执行工程建设强制性标准，保障工程勘察、设计质量。"},{"i":23,"n":"第二十三条","txt":"勘察、设计单位应当依照有关规定建立健全勘察、设计质量管理体系，加强勘察、设计过程质量控制，严格执行勘察、设计文件的校审、会签、批准制度。"},{"i":24,"n":"第二十四条","txt":"勘察单位提供的地质、测量、水文等勘察成果必须真实、准确，符合国家和相关行业规定的勘察深度要求。"},{"i":25,"n":"第二十五条","txt":"设计单位应当根据勘察成果文件进行设计，提交的设计文件应当符合相关技术标准规定的设计深度要求，并注明工程及其水工建筑物合理使用年限。  水利工程施工图设计文件，应当以批准的初步设计文件以及设计变更文件为依据。"},{"i":26,"n":"第二十六条","txt":"设计单位在设计文件中选用的原材料、中间产品和设备，应当注明规格、型号、性能等技术指标，其质量要求必须符合国家规定的标准。  除有特殊要求的原材料、中间产品和设备外，设计单位不得指定生产厂家和供应商。"},{"i":27,"n":"第二十七条","txt":"勘察、设计单位应当在工程施工前，向施工、监理等有关参建单位进行交底，对施工图设计文件作出详细说明，并对涉及工程结构安全的关键部位进行明确。"},{"i":28,"n":"第二十八条","txt":"勘察、设计单位应当及时解决施工中出现的勘察、设计问题。  设计单位应当根据工程建设需要和合同约定，在施工现场设立设计代表机构或者派驻具备相应技术能力的人员担任设计代表，及时提供设计文件，按照规定做好设计变更。  设计单位发现违反设计文件施工的情况，应当及时通知项目法人和监理单位。"},{"i":29,"n":"第二十九条","txt":"勘察、设计单位应当按照有关规定参加工程验收，并在验收中对施工质量是否满足设计要求提出明确的评价意见。"},{"i":30,"n":"第三十条","txt":"设计单位应当参与水利工程质量事故分析，提出相应的技术处理方案。"},{"i":31,"n":"第三十一条","txt":"施工单位应当在其资质等级许可的范围内承揽水利工程施工业务，禁止超越资质等级许可的业务范围或者以其他施工单位的名义承揽水利工程施工业务，禁止允许其他单位或者个人以本单位的名义承揽水利工程施工业务，不得转包或者违法分包所承揽的水利工程施工业务。"},{"i":32,"n":"第三十二条","txt":"施工单位必须按照批准的设计文件和有关技术标准施工，不得擅自修改设计文件，不得偷工减料。  施工单位发现设计文件和图纸有差错的，应当及时向项目法人、设计单位、监理单位提出意见和建议。  施工单位应当严格施工过程质量控制，保证施工质量。"},{"i":33,"n":"第三十三条","txt":"施工单位应当建立健全施工质量管理体系，根据工程施工需要和合同约定，设置现场施工管理机构，配备满足施工需要的管理人员，落实质量责任制。  施工单位一般不得更换派驻现场的项目经理和技术负责人；确需更换的，应当经项目法人书面同意，且更换后的人员资格不得低于合同约定的条件。"},{"i":34,"n":"第三十四条","txt":"水利工程的勘察、设计、施工、设备采购的一项或者多项实行总承包的，总承包单位对其承包的工程或者采购的设备质量负责。  总承包单位依法将工程分包给其他单位的，分包单位按照分包合同的约定对其分包工程的质量向总承包单位负责，总承包单位与分包单位对分包工程的质量承担连带责任。分包单位应当接受总承包单位的质量管理。  禁止分包单位将其承包的工程再分包。"},{"i":35,"n":"第三十五条","txt":"施工单位必须按照经批准的设计文件、有关技术标准和合同约定，对原材料、中间产品、设备以及单元工程（工序）等进行质量检验，检验应当有检查记录或者检测报告，并有专人签字，确保数据真实可靠。对涉及结构安全的试块、试件以及有关材料，应当在项目法人或者监理单位监督下现场取样。未经检验或者检验不合格的，不得使用。  前款规定的质量检测业务按照有关规定由具有相应资质等级的水利工程质量检测单位承担。"},{"i":36,"n":"第三十六条","txt":"施工单位应当严格执行工程验收制度。单元工程（工序）未经验收或者验收不通过的，不得进行下一单元工程（工序）施工。  施工单位应当做好隐蔽工程的质量检查和记录，隐蔽工程在隐蔽前，施工单位应当通知项目法人和水利工程质量监督机构。隐蔽工程未经验收或者验收不通过的，不得隐蔽。"},{"i":37,"n":"第三十七条","txt":"施工单位应当加强施工过程质量控制，形成完整、可追溯的施工质量管理文件资料，并按照档案管理的有关规定进行收集、整理和归档。主体工程的隐蔽部位施工、质量问题处理等，必须保留照片、音视频文件资料并归档。"},{"i":38,"n":"第三十八条","txt":"对出现施工质量问题的工程或者验收不合格的工程，施工单位应当负责返修或者重建。"},{"i":39,"n":"第三十九条","txt":"水利工程在保修范围和保修期限内发生质量问题的，施工单位应当履行保修义务，并对造成的损失承担赔偿责任。  水利工程的保修范围、期限，应当在施工合同中约定。"},{"i":40,"n":"第四十条","txt":"发生质量事故时，施工单位应当采取措施防止事故扩大，保护事故现场，并及时通知项目法人、监理单位，接受质量事故调查。"},{"i":41,"n":"第四十一条","txt":"监理单位应当在其资质等级许可的范围内承担水利工程监理业务，禁止超越资质等级许可的范围或者以其他监理单位的名义承担水利工程监理业务，禁止允许其他单位或者个人以本单位的名义承担水利工程监理业务，不得转让其承担的水利工程监理业务。"},{"i":42,"n":"第四十二条","txt":"监理单位应当依照国家有关法律、法规、规章、技术标准、批准的设计文件和合同，对水利工程质量实施监理。"},{"i":43,"n":"第四十三条","txt":"监理单位应当建立健全质量管理体系，按照工程监理需要和合同约定，在施工现场设置监理机构，配备满足工程建设需要的监理人员，落实质量责任制。  现场监理人员应当按照规定持证上岗。总监理工程师和监理工程师一般不得更换；确需更换的，应当经项目法人书面同意，且更换后的人员资格不得低于合同约定的条件。"},{"i":44,"n":"第四十四条","txt":"监理单位应当对施工单位的施工质量管理体系、施工组织设计、专项施工方案、归档文件等进行审查。"},{"i":45,"n":"第四十五条","txt":"监理单位应当按照有关技术标准和合同要求，采取旁站、巡视、平行检验和见证取样检测等形式，复核原材料、中间产品、设备和单元工程（工序）质量。  未经监理工程师签字，原材料、中间产品和设备不得在工程上使用或者安装，施工单位不得进行下一单元工程（工序）的施工。未经总监理工程师签字，项目法人不拨付工程款，不进行竣工验收。  平行检验中需要进行检测的项目按照有关规定由具有相应资质等级的水利工程质量检测单位承担。"},{"i":46,"n":"第四十六条","txt":"监理单位不得与被监理工程的施工单位以及原材料、中间产品和设备供应商等单位存在隶属关系或者其他利害关系。  监理单位不得与项目法人或者被监理工程的施工单位串通，弄虚作假、降低工程质量。"},{"i":47,"n":"第四十七条","txt":"水利工程质量检测单位应当在资质等级许可的范围内承揽水利工程质量检测业务，禁止超越资质等级许可的范围或者以其他单位的名义承揽水利工程质量检测业务，禁止允许其他单位或者个人以本单位的名义承揽水利工程质量检测业务，不得转让承揽的水利工程质量检测业务。原材料、中间产品和设备供应商等单位应当在生产经营许可范围内承担相应业务。"},{"i":48,"n":"第四十八条","txt":"质量检测单位应当依照有关法律、法规、规章、技术标准和合同，及时、准确地向委托方提交质量检测报告并对质量检测成果负责。  质量检测单位应当建立检测结果不合格项目台账，并将可能形成质量隐患或者影响工程正常运行的检测结果及时报告委托方。"},{"i":49,"n":"第四十九条","txt":"监测单位应当依照有关法律、法规、规章、技术标准和合同，做好监测仪器设备检验、埋设、安装、调试和保护工作，保证监测数据连续、可靠、完整，并对监测成果负责。  监测单位应当按照合同约定进行监测资料分析，出具监测报告，并将可能反映工程安全隐患的监测数据及时报告委托方。"},{"i":50,"n":"第五十条","txt":"质量检测单位、监测单位不得出具虚假和不实的质量检测报告、监测报告，不得篡改或者伪造质量检测数据、监测数据。  任何单位和个人不得明示或者暗示质量检测单位、监测单位出具虚假和不实的质量检测报告、监测报告，不得篡改或者伪造质量检测数据、监测数据。"},{"i":51,"n":"第五十一条","txt":"原材料、中间产品和设备供应商等单位提供的原材料、中间产品和设备应当满足有关技术标准、经批准的设计文件和合同要求。"},{"i":52,"n":"第五十二条","txt":"县级以上人民政府水行政主管部门、流域管理机构在管辖范围内负责对水利工程质量的监督管理：  （一）贯彻执行水利工程质量管理的法律、法规、规章和工程建设强制性标准，并组织对贯彻落实情况实施监督检查；  （二）制定水利工程质量管理制度；  （三）组织实施水利工程建设项目的质量监督；  （四）组织、参与水利工程质量事故的调查与处理；  （五）建立举报渠道，受理水利工程质量投诉、举报；  （六）履行法律法规规定的其他职责。"},{"i":53,"n":"第五十三条","txt":"县级以上人民政府水行政主管部门可以委托水利工程质量监督机构具体承担水利工程建设项目的质量监督工作。  县级以上人民政府水行政主管部门、流域管理机构可以采取购买技术服务的方式对水利工程建设项目实施质量监督。"},{"i":54,"n":"第五十四条","txt":"县级以上人民政府水行政主管部门、流域管理机构、受委托的水利工程质量监督机构应当采取抽查等方式，对水利工程建设有关单位质量行为和工程实体质量进行监督检查。有关单位和个人应当支持与配合，不得拒绝或者阻碍质量监督检查人员依法执行职务。  水利工程质量监督工作主要包括以下内容：  （一）核查项目法人、勘察、设计、施工、监理、质量检测等单位和人员的资质或者资格；  （二）检查项目法人、勘察、设计、施工、监理、质量检测、监测等单位履行法律、法规、规章规定的质量责任情况；  （三）检查工程建设强制性标准执行情况；  （四）检查工程项目质量检验和验收情况；  （五）检查原材料、中间产品、设备和工程实体质量情况；  （六）实施其他质量监督工作。  质量监督工作不代替项目法人、勘察、设计、施工、监理及其他单位的质量管理工作。"},{"i":55,"n":"第五十五条","txt":"县级以上人民政府水行政主管部门、流域管理机构、受委托的水利工程质量监督机构履行监督检查职责时，依法采取下列措施：  （一）要求被监督检查单位提供有关工程质量等方面的文件和资料；  （二）进入被监督检查工程现场和其他相关场所进行检查、抽样检测等。"},{"i":56,"n":"第五十六条","txt":"县级以上人民政府水行政主管部门、流域管理机构、受委托的水利工程质量监督机构履行监督检查职责时，发现有下列行为之一的，责令改正，采取处理措施:  （一）项目法人质量管理机构和人员设置不满足工程建设需要，质量管理制度不健全，未组织编制工程建设执行技术标准清单，未组织或者委托监理单位组织勘察、设计交底，未按照规定履行设计变更手续，对发现的质量问题未组织整改落实的；  （二）勘察、设计单位未严格执行勘察、设计文件的校审、会签、批准制度，未按照规定进行勘察、设计交底，未按照规定在施工现场设立设计代表机构或者派驻具有相应技术能力的人员担任设计代表，未按照规定参加工程验收，未按照规定执行设计变更，对发现的质量问题未组织整改落实的；   （三）施工单位未经项目法人书面同意擅自更换项目经理或者技术负责人，委托不具有相应资质等级的水利工程质量检测单位对检测项目实施检测，单元工程（工序）施工质量未经验收或者"},{"i":57,"n":"第五十七条","txt":"项目法人应当将重要隐蔽单元工程及关键部位单元工程、分部工程、单位工程质量验收结论报送承担项目质量监督的水行政主管部门或者流域管理机构。"},{"i":58,"n":"第五十八条","txt":"县级以上人民政府水行政主管部门、流域管理机构、水利工程质量监督机构的工作人员在水利工程质量监督管理工作中玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予政务处分。"},{"i":59,"n":"第五十九条","txt":"违反本规定，项目法人将工程发包给不具有相应资质等级的勘察、设计、施工单位或者委托给不具有相应资质等级的监理单位的，依照《建设工程质量管理条例》第五十四条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处50万元以上100万元以下的罚款。"},{"i":60,"n":"第六十条","txt":"违反本规定，项目法人有下列行为之一的，依照《建设工程质量管理条例》第五十六条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处20万元以上50万元以下的罚款：  （一）迫使市场主体以低于成本的价格竞标的；  （二）任意压缩合理工期的；  （三）明示或者暗示勘察、设计、施工单位违反工程建设强制性标准，降低工程质量的；  （四）施工图设计文件未经审查或者审查不合格，擅自施工的；  （五）未按照国家规定办理工程质量监督手续的；  （六）明示或者暗示施工单位使用不合格的原材料、中间产品和设备的。"},{"i":61,"n":"第六十一条","txt":"违反本规定，水利工程竣工验收后，项目法人未移交建设项目档案的，依照《建设工程质量管理条例》第五十九条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处1万元以上10万元以下的罚款。"},{"i":62,"n":"第六十二条","txt":"违反本规定，勘察、设计、施工、监理单位超越本单位资质等级承揽工程的，依照《建设工程质量管理条例》第六十条规定，由水行政主管部门或者流域管理机构依据职权责令停止违法行为，对勘察、设计或者监理单位处合同约定的勘察费、设计费或者监理酬金1倍以上2倍以下的罚款；对施工单位处工程合同价款2%以上4%以下的罚款；有违法所得的，予以没收。"},{"i":63,"n":"第六十三条","txt":"违反本规定，勘察、设计、施工、监理单位允许其他单位或者个人以本单位名义承揽工程的，依照《建设工程质量管理条例》第六十一条规定，由水行政主管部门或者流域管理机构依据职权责令改正，没收违法所得，对勘察、设计或者监理单位处合同约定的勘察费、设计费或者监理酬金1倍以上2倍以下的罚款；对施工单位处工程合同价款2%以上4%以下的罚款。"},{"i":64,"n":"第六十四条","txt":"违反本规定，承包单位将承包的工程转包或者违法分包的，依照《建设工程质量管理条例》第六十二条规定，由水行政主管部门或者流域管理机构依据职权责令改正，没收违法所得，对勘察、设计单位处合同约定的勘察费、设计费25%以上50%以下的罚款；对施工单位处工程合同价款0.5%以上1%以下的罚款。  监理单位转让工程监理业务的，依照《建设工程质量管理条例》第六十二条规定，由水行政主管部门或者流域管理机构依据职权责令改正，没收违法所得，处合同约定的监理酬金25%以上50%以下的罚款。"},{"i":65,"n":"第六十五条","txt":"违反本规定，勘察、设计单位未依据项目批准文件，相关规划，国家规定的勘察、设计深度要求编制水利工程勘察、设计文件的，依照《建设工程勘察设计管理条例》第四十条规定，由水行政主管部门或者流域管理机构依据职权责令限期改正；逾期不改正的，处10万元以上30万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":66,"n":"第六十六条","txt":"违反本规定，勘察、设计单位有下列行为之一的，依照《建设工程质量管理条例》第六十三条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处10万元以上30万元以下的罚款；造成损失的，依法承担赔偿责任：  （一）勘察单位未按照工程建设强制性标准进行勘察的；  （二）设计单位未根据勘察成果文件进行工程设计的；  （三）设计单位指定原材料、中间产品和设备的生产厂、供应商的；  （四）设计单位未按照工程建设强制性标准进行设计的。"},{"i":67,"n":"第六十七条","txt":"违反本规定，施工单位在施工中偷工减料的，使用不合格的原材料、中间产品和设备的，或者有不按照批准的设计文件或者技术标准施工的其他行为的，依照《建设工程质量管理条例》第六十四条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处工程合同价款2%以上4%以下的罚款；造成水利工程质量不符合规定的质量标准的，负责返工、修理，并赔偿因此造成的损失。"},{"i":68,"n":"第六十八条","txt":"违反本规定，施工单位未对原材料、中间产品、设备进行检验，或者未对涉及结构安全的试块、试件以及有关材料取样检测的，依照《建设工程质量管理条例》第六十五条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处10万元以上20万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":69,"n":"第六十九条","txt":"违反本规定，施工单位不履行保修义务或者拖延履行保修义务的，依照《建设工程质量管理条例》第六十六条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处10万元以上20万元以下的罚款，并对在保修期内因质量缺陷造成的损失承担赔偿责任。"},{"i":70,"n":"第七十条","txt":"违反本规定，监理单位有下列行为之一的，依照《建设工程质量管理条例》第六十七条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处50万元以上100万元以下的罚款；有违法所得的，予以没收；造成损失的，承担连带赔偿责任：  （一）与项目法人或者施工单位串通，弄虚作假、降低工程质量的；  （二）将不合格的水利工程、原材料、中间产品和设备按照合格签字的。"},{"i":71,"n":"第七十一条","txt":"违反本规定，监理单位与被监理工程的施工单位以及原材料、中间产品和设备供应商等单位有隶属关系或者其他利害关系承担该项工程的监理业务的，依照《建设工程质量管理条例》第六十八条规定，由水行政主管部门或者流域管理机构依据职权责令改正，处5万元以上10万元以下的罚款；有违法所得的，予以没收。"},{"i":72,"n":"第七十二条","txt":"水利工程质量检测单位伪造检测数据，出具虚假质量检测报告的，由水行政主管部门或者流域管理机构依据职权责令改正，给予警告或者通报批评，处10万元以下罚款；给他人造成损失的，依法承担赔偿责任。"},{"i":73,"n":"第七十三条","txt":"有关单位违反本规定，依法应当责令停业整顿、降低资质等级或者吊销资质证书的，依照《建设工程质量管理条例》第七十五条、《建设工程勘察设计管理条例》第四十二条的规定处罚。  依照《建设工程质量管理条例》给予单位罚款处罚的，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额5%以上10%以下的罚款。"},{"i":74,"n":"第七十四条","txt":"违反工程质量管理的行为，《中华人民共和国建筑法》、《建设工程质量管理条例》、《建设工程勘察设计管理条例》等法律、行政法规另有规定的，依照其规定执行。"},{"i":75,"n":"第七十五条","txt":"县级以上人民政府水行政主管部门、流域管理机构应当依照有关规定加强对水利工程建设项目法人、勘察、设计、施工、监理、检测、监测等单位的信用监管，对相关单位的行政处罚、行政处理决定信息，依照有关规定记入其信用记录。"},{"i":76,"n":"第七十六条","txt":"本规定自2023年3月1日起施行。1997年12月21日水利部发布的《水利工程质量管理规定》同时废止。"}],"shuilishuidianjianshegongchengxushuianquanjianding91033e":[{"i":1,"n":"第一条","txt":"为加强水利水电建设工程的安全管理，提高工程蓄水验收工作质量，保障工程及上下游人民生命财产的安全，根据《中华人民共和国防洪法》、《水库大坝安全管理条例》和《水利水电建设工程验收规程》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于库容1亿立方米以上的大型（包括新建、续建、改建、加固、修复等）水利水电建设工程。中型水利水电建设工程可参照执行。"},{"i":3,"n":"第三条","txt":"水库蓄水验收前必须进行蓄水安全鉴定。蓄水安全鉴定是大型水利水电建设工程蓄水验收的必要依据，未经蓄水安全鉴定不得进行蓄水验收。"},{"i":4,"n":"第四条","txt":"蓄水安全鉴定，由项目法人负责组织实施。设计、施工、监理、运行、设备制造等单位负责提供资料，并有义务协助鉴定单位开展工作。"},{"i":5,"n":"第五条","txt":"水利部负责监督和指导全国水利水电建设工程蓄水安全鉴定工作。各级水行政主管部门按照工程竣工验收的分级管理权限负责监督和指导蓄水安全鉴定工作。"},{"i":6,"n":"第六条","txt":"已竣工投入运行的水利水电工程，其安全鉴定工作遵照《水库大坝安全鉴定办法》（水利部水管〔1995〕86号）执行。"},{"i":7,"n":"第七条","txt":"蓄水安全鉴定的依据是有关法律、法规和技术标准，批准的初步设计报告、专题报告，设计变更及修改文件，监理签发的技术文件及说明，合同规定的质量和安全标准等。"},{"i":8,"n":"第八条","txt":"进行蓄水安全鉴定时，鉴定范围内的工程形象面貌应基本达到《水利水电建设工程验收规程》规定的蓄水验收条件，安全鉴定使用的资料已准备齐全。"},{"i":9,"n":"第九条","txt":"蓄水安全鉴定的范围是以大坝为重点，包括挡水建筑物、泄水建筑物、引水建筑物的进水口工程、涉及工程安全的库岸边坡及下游消能防护工程等与蓄水安全有关的工程项目。"},{"i":10,"n":"第十条","txt":"蓄水安全鉴定工作的重点是检查工程施工过程中是否存在影响工程安全的因素，以及工程建设期发现的影响工程安全的问题是否得到妥善解决，并提出工程安全评价意见；对不符合有关技术标准、设计文件并涉及工程安全的，分析其对工程安全的影响程度，并作出评价意见；对虽符合有关技术标准、设计文件，但专家认为构成工程安全运行隐患的，也应对其进行分析和作出评价。"},{"i":11,"n":"第十一条","txt":"蓄水安全鉴定内容： 1.检查工程形象面貌是否符合蓄水要求。 2.检查工程质量（包括设计、施工等）是否存在影响工程安全的隐患。 对关键部位、出现过质量事故的部位以及有必要检查的其他部位要进行重点检查，包括抽查工程原始资料和施工、设备制造验收签证，必要时应当使用钻孔取样、充水试验等技术手段进行检测。 3.检查洪水设计标准。工程泄洪设施的泄洪能力，消能设施的可靠性，下闸蓄水方案的可靠性，以及调度运行方案是否符合防洪和度汛安全的要求。 4.检查工程地质条件、基础处理、滑坡及处理、工程防震是否存在不利于建筑物的隐患。 5.检查工程安全检测设施、检测资料是否完善并符合要求。"},{"i":12,"n":"第十二条","txt":"蓄水安全鉴定工作中，不进行工程质量等级的评定。"},{"i":13,"n":"第十三条","txt":"蓄水安全鉴定程序： 1.安全鉴定前，安全鉴定单位制定蓄水安全鉴定工作大纲，明确鉴定的主要内容，提出鉴定工作所需资料清单。 2.听取项目法人、设计、施工、监理、运行等建设各方的情况介绍。 3.进行现场调查，收集资料。 4.设计、施工、监理、运行等建设各方分别编写自检报告。 5.专家组集中分析、研究有关工程资料，与建设各方沟通情况，必要时进行设计复核、现场检查或检测。专家组讨论并提出鉴定报告初稿。 6.在与建设各方充分交换意见的基础上，作出工程安全评价，完成蓄水安全鉴定报告，专家组全体成员签字认可。"},{"i":14,"n":"第十四条","txt":"项目法人认为工程符合蓄水安全鉴定条件时，可决定组织蓄水安全鉴定。蓄水安全鉴定，由项目法人委托具有相应鉴定经验和能力的单位承担，与之签定蓄水安全鉴定合同，并报工程验收主持单位核备。接受委托负责蓄水安全鉴定的单位（即鉴定单位）应成立专家组，并将专家组组成情况报工程验收主持单位和相应的水利工程质量监督部门核备。"},{"i":15,"n":"第十五条","txt":"鉴定专家组应由专业水平高、工程设计、施工经验丰富、具有高级工程师以上职称的专家组成，包括水文、地质、水工、施工、机电、金属结构等有关专业。鉴定专家组三分之一以上人员须聘请责任单位以外的专家参加。"},{"i":16,"n":"第十六条","txt":"项目法人、设计、施工、监理、运行、设备制造等参建单位的在职人员或从事过本工程设计、施工、管理的其它人员，不能担任专家组成员。"},{"i":17,"n":"第十七条","txt":"项目法人应组织建设各方认真做好配合鉴定专家组进行的工作，包括： 1.准确、及时提供鉴定工作所需的各种工程资料。 2.根据专家组的要求，组织相对固定的专业人员和工作人员，向专家组介绍有关工程情况，对专家组提出的问题进行解答。 3.根据专家组的要求，对有关问题进行补充分析工作，并提出相应的专题报告。 4.为专家组在现场工作提供必要的工作条件。"},{"i":18,"n":"第十八条","txt":"鉴定单位应将鉴定报告提交给项目法人，并抄报工程验收主持单位和水利工程质量监督部门。工程验收前，项目法人应负责将鉴定报告分送给验收委员会各成员。"},{"i":19,"n":"第十九条","txt":"项目法人应组织建设各方，对鉴定报告中指出的工程安全问题和提出的建议，进行认真的研究和处理，并将处理情况书面报告验收委员会。"},{"i":20,"n":"第二十条","txt":"建设各方应对所提供资料的准确性负责。凡在工程安全鉴定工作中提供虚假资料，发现工程安全隐患隐瞒不报或谎报的单位，由项目主管上级部门或责成有关单位按有关规定对责任者进行处理。"},{"i":21,"n":"第二十一条","txt":"鉴定单位应独立地进行工作，提出客观、公正、科学的鉴定报告，并对鉴定结论负责。项目法人等任何单位或个人，均不得妨碍和干预鉴定单位和鉴定专家组独立地作出鉴定意见。"},{"i":22,"n":"第二十二条","txt":"建设各方对鉴定报告有重大分歧意见的，应形成书面意见送鉴定单位，并抄报工程验收主持单位和水利工程质量监督部门。"},{"i":23,"n":"第二十三条","txt":"进行工程验收时，验收委员会依据鉴定报告，并听取建设各方的意见，作出验收结论。当对个别疑难问题难以作出结论时，主任委员单位应组织有关专家或委托科研单位进一步论证，提出结论意见。"},{"i":24,"n":"第二十四条","txt":"蓄水安全鉴定不代替和减轻建设各方由于工程设计、施工、运行、制造、管理等方面存在问题应负的工程安全责任。"},{"i":25,"n":"第二十五条","txt":"蓄水安全鉴定工作所需费用，由项目法人负责从工程验收费中列支。"},{"i":26,"n":"第二十六条","txt":"本规定由水利部负责解释。"},{"i":27,"n":"第二十七条","txt":"本规定自颁布之日起执行。"}],"shuilibuxingzhengfuyigongzuozanxingguiding":[{"i":1,"n":"第一条","txt":"为防止和纠正违法的或者不当的具体行政行为，保护公民、法人和其他组织的合法权益，保障和监督有关水行政主管部门、流域管理机构依法行使职权，根据《中华人民共和国行政复议法》（以下简称《行政复议法》）及有关水法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"水利部及其所属的长江、黄河、海河、淮河、珠江、松辽水利委员会和太湖流域管理局等流域管理机构（以下简称流域机构）的行政复议工作，适用本规定。"},{"i":3,"n":"第三条","txt":"水利部负责行政复议工作的机构是政策法规司。流域机构负责行政复议工作的机构是负责法制工作的机构。 水利部政策法规司、流域机构负责法制工作的机构（以下简称复议工作机构）负责办理有关的行政复议事项，履行行政复议受理、调查取证、审查、提出处理建议和行政应诉等职责；各司局和有关单位、流域机构各有关业务主管局（处、室）（以下统称主管单位）协同办理与本单位主管业务有关的行政复议的受理、举证、审查等工作。"},{"i":4,"n":"第四条","txt":"行政复议工作应当遵循合法、公正、公开、及时、便民的原则。坚持有错必纠，保障水法规的正确实施。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，公民、法人或者其他组织可以依照《行政复议法》、有关法律、行政法规和本规定向水利部或者流域机构申请行政复议： （一）对水利部、流域机构、流域机构所属管理机构或者省级水行政主管部门作出的行政处罚决定、行政强制措施决定不服的； （二）对水利部、流域机构或者省级水行政主管部门作出的取水许可证、水利工程建设监理资质证、采砂许可证等证书变更、中止、撤销的决定不服的； （三）对水利部、流域机构或者省级水行政主管部门作出的关于确认水流的使用权的决定不服的； （四）认为水利部、流域机构或者省级水行政主管部门侵犯合法的经营自主权的； （五）认为水利部、流域机构或者省级水行政主管部门违法集资或者违法要求履行其他义务的； （六）认为符合法定条件，申请水利部、流域机构或者省级水行政主管部门颁发取水许可证、采砂许可证、水利工程建设监理资质证等证书，或者申请审查同意河道管理范围内建设项目、开发建设"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织可以按照下列规定申请行政复议： （一）对水利部或者流域机构作出的具体行政行为不服的，向水利部申请行政复议。 （二）对省级水行政主管部门作出的具体行政行为不服的，可以向省、自治区、直辖市人民政府申请行政复议，也可以向水利部申请行政复议。 （三）对流域机构所属管理机构作出的具体行政行为不服的，向流域机构申请行政复议。"},{"i":7,"n":"第七条","txt":"对水利部、流域机构、流域机构所属管理机构或者省级水行政主管部门作出具体行政行为所依据的水利部的规定认为不合法的，公民、法人或者其他组织在申请行政复议时可以一并提出对该规定的审查申请。 流域机构受理的行政复议申请中，申请人提出前款要求的，流域机构应在受理行政复议申请之日起七日内通过直接送达、邮寄送达等方式将申请人对水利部的规定的审查申请移送水利部，水利部应当在六十日内依法处理。 水利部受理的行政复议申请中，申请人提出前款要求的，水利部应当在三十日内依法处理。 处理期间，中止对具体行政行为的审查并应及时通知申请人、被申请人及第三人。 前款所称规定，不含水利部颁布的规章。"},{"i":8,"n":"第八条","txt":"申请人申请行政复议，可以书面申请，也可以口头申请；口头申请的，水利部或者流域机构应当当场填写行政复议口头申请书，记录申请人的基本情况、行政复议请求、申请行政复议的主要事实、申请理由、时间等。"},{"i":9,"n":"第九条","txt":"水利部或者流域机构收到行政复议申请后，应当在五日内进行审查，对不符合《行政复议法》规定的行政复议申请，决定不予受理；对符合《行政复议法》规定，但不属于水利部或者流域机构受理的行政复议申请，告知申请入向有关行政复议机关提出。 除前款规定外，行政复议申请自复议工作机构收到之日起即为受理。 复议工作机构负责办理行政复议申请的受理事项，涉及有关主管单位业务的，有关主管单位应当予以配合。"},{"i":10,"n":"第十条","txt":"行政复议原则上采取书面审查的办法。 复议工作机构认为有必要时，可以向有关组织和人员调查情况，听取申请入、被申请人和第三人的意见。 对水利部作出的具体行政行为或者制定的规定申请行政复议的，政策法规司应当对具体行政行为或者规定进行审查。涉及有关司局主管业务的，政策法规司应当自行政复议申请受理之日起七日内，将行政复议申请书副本或口头申请书复印件发送有关司局，有关司局应当自收到行政复议申请书副本或口头申请书复印件之日起十日内，提交当初作出具体行政行为的证据、依据和其他有关材料，或者提交制定规定的依据和其他有关材料，并提出书面复议意见。 对流域机构或者省级水行政主管部门作出的具体行政行为申请行政复议的，政策法规司应当对被申请人作出的具体行政行为进行审查。涉及有关司局主管业务的，应会同有关司局共同进行审查。 对流域机构所属管理机构作出的具体行政行为申请行政复议的，流域机构的复议工作机构应当对被申请"},{"i":11,"n":"第十一条","txt":"水利部政策法规司对被申请行政复议的具体行政行为审查后，应当提出书面意见，并报谓主管副部长和部长审核同意，主管副部长或部长认为必要，可将行政复议审查意见提交部长办公会议审议，按照《行政复议法》第二十八条、三十一条的规定作出行政复议决定，由政策法规司制作行政复议决定书、加盖部印章后送达申请人。 流域机构的复议工作机构对被申请行政复议的具体行政行为审查后，应当提出书面意见，并报请主管副主任（局长）和主任（局长）审核同意，主管副主任（局长）或主任（局长）认为必要。可将行政复议审查意见提交主任（局长）办公会议审议，按照《行政复议法》第二十八条、三十一条的规定作出行政复议决定，由复议工作机构制作行政复议决定书、加盖流域机构印章后送达申请人。"},{"i":12,"n":"第十二条","txt":"公民、法人或者其他组织对水利部作出的行政复议决定不服的，可以依照《行政诉讼法》、《行政复议法》的规定向人民法院提起行政诉讼，也可以向国务院申请裁决。 公民、法人或者其他组织对流域机构作出的行政复议决定不服的，可以依照《行政诉讼法》、《行政复议法》的规定向人民法院提起行政诉讼。"},{"i":13,"n":"第十三条","txt":"水利部或者流域机构受理行政复议申请，不得向申请人收取任何费用。 水利部、流域机构应当保证行政复议工作经费，以确保行政复议工作按期、高效完成。"},{"i":14,"n":"第十四条","txt":"复议申请登记表、复议申请书、受理复议通知书、不予受理决定书、复议答辩书、复议决定书、复议文书送达回证、准予撤回行政复议申请决定书等行政复议文书格式，由水利部统一制订。"},{"i":15,"n":"第十五条","txt":"本规定未尽事项，依照《行政复议法》的有关规定办理。"},{"i":16,"n":"第十六条","txt":"流域机构可以依据本规定对其行政复议工作作出具体规定，并报部备案。"},{"i":17,"n":"第十七条","txt":"本规定由水利部负责解释。"},{"i":18,"n":"第十八条","txt":"本规定自公布之日起施行。"}],"shuitubaochishengtaihuanjingjiancewangluoguanliban65f343":[{"i":1,"n":"第一条","txt":"为加强水土保持生态环境监测网络的建设和管理，规范水土保持生态环境监测工作，根据《中华人民共和国水土保持法》、《中华人民共和国水土保持法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"水土保持生态环境监测工作应遵守本办法的规定。"},{"i":3,"n":"第三条","txt":"水土保持生态环境监测工作的任务是通过建立全国水土保持生态环境监测站网，对全国水土流失和水土保持状况实施监测，为国家制定水土保持生态环境政策和宏观决策提供科学依据，为实现国民经济和社会的可持续发展服务。"},{"i":4,"n":"第四条","txt":"水土保持生态环境监测工作实行统一管理，分级负责的原则。 水利部统一管理全国的水土保持生态环境监测工作，负责制订有关规章、规程和技术标准，组织全国水土保持生态环境监测、国内外技术合作与交流，发布全国水土保持公告。 水利部各流域机构在授权范围内管理水土保持生态环境监测工作。 县级以上水行政主管部门或地方政府设立的水土保持机构、以及经授权的水土保持监督管理机构，对辖区内的水土保持生态环境监测实施管理。"},{"i":5,"n":"第五条","txt":"水土保持生态环境监测工作按水利部制定的技术规范和标准进行。"},{"i":6,"n":"第六条","txt":"省级以上水土保持生态环境监测管理机构编制水土保持生态环境监测规划，作为水土保持生态环境建设规划的重要组成部分，经同级人民政府批准后组织实施。对水土保持生态环境监测规划进行修订的，须经原批准机关审查同意。"},{"i":7,"n":"第七条","txt":"在水土保持生态环境监测工作中成绩显著的单位和个人，由水土保持生态环境监测管理机构或报请同级人民政府给予奖励。"},{"i":8,"n":"第八条","txt":"在水土保持生态环境监测规划的指导下，按基本建设程序建设全国水土保持生态环境监测站网，其运行实行分级负责制。"},{"i":9,"n":"第九条","txt":"全国水土保持生态环境监测站网由以下四级监测机构组成：一级为水利部水土保持生态环境监测中心，二级为大江大河（长江、黄河、海河、淮河、珠江、松花江及辽河、太湖等）流域水土保持生态环境监测中心站，三级为省级水土保持生态环境监测总站，四级为省级重点防治区监测分站。 省级重点防治区监测分站，根据全国及省级水土保持生态环境监测规划，设立相应监测点。具体布设应结合目前水土保持科研所（站、点）及水文站点的布设情况建设，避免重复，部分监测项目可委托相关站进行监测。 国家负责一、二级监测机构的建设和管理，省（自治区、直辖市）负责三、四级及监测点的建设和管理。按水土保持生态环境监测规划建设的监测站点不得随意变更，确需调整的须经规划批准机关的审查同意。"},{"i":10,"n":"第十条","txt":"有水土流失防治任务的开发建设项目，建设和管理单位应设立专项监测点对水土流失状况进行监测，并定期向项目所在地县级监测管理机构报告监测成果。"},{"i":11,"n":"第十一条","txt":"下级监测机构应接受上级监测机构的业务指导。"},{"i":12,"n":"第十二条","txt":"水土保持生态环境监测工作，须由具有相应监测能力的单位承担。"},{"i":13,"n":"第十三条","txt":"从事水土保持生态环境监测的专业技术人员须经专门技术培训，具备相应的工作能力。"},{"i":14,"n":"第十四条","txt":"省级以上水土保持生态环境监测机构的主要职责是：编制水土保持生态环境监测规划和实施计划，建立水土保持生态环境监测信息网，承担并完成水土保持生态环境监测任务，负责对监测工作的技术指导、技术培训和质量保证，开展监测技术、监测方法的研究及国内外科技合作和交流，负责汇总和管理监测数据，对下级监测成果进行鉴定和质量认证，及时掌握和预报水土流失动态，编制水土保持生态环境监测报告。除本款规定的职责外，各级监测机构还有以下职责： 水利部水土保持生态环境监测中心对全国水土保持生态环境监测工作实施具体管理。负责拟定水土保持生态环境监测技术规范、标准，组织对全国性、重点区域、重大开发建设项目的水土保持监测，负责对监测仪器、设备的质量和技术认证，承担对申报水土保持生态环境监测资质单位的考核、验证工作。 大江大河流域水土保持生态环境监测中心站参与国家水土保持生态环境监测、管理和协调工作，负责组织和开展跨省际区域、"},{"i":15,"n":"第十五条","txt":"省级重点防治区监测分站的主要职责：按国家、流域及省级水土保持生态环境监测规划和计划，对列入国家及省级水土流失重点预防保护区、重点治理区、重点监督区的水土保持动态变化进行监测，汇总和管理监测数据，编制监测报告。 监测点的主要职责：按有关技术规程对监测区域进行长期定位观测，整编监测数据，编报监测报告。"},{"i":16,"n":"第十六条","txt":"开发建设项目的专项监测点，依据批准的水土保持方案，对建设和生产过程中的水土流失进行监测，接受水土保持生态环境监测管理机构的业务指导和管理。"},{"i":17,"n":"第十七条","txt":"水土保持生态环境监测数据和成果由水土保持生态环境监测管理机构统一管理。"},{"i":18,"n":"第十八条","txt":"水土保持生态环境监测数据实行年报制度，上报时间为次年元月底前。 下级监测机构向上级监测机构报告本年度监测数据及其整编成果。开发建设项目的监测数据和成果，向当地水土保持生态环境监测管理机构报告。 年报内容按有关技术规范编制。"},{"i":19,"n":"第十九条","txt":"国家和省级水土保持生态环境监测成果实行定期公告制度，监测公告分别由水利部和省级水行政主管部门依法发布。省级监测公告发布前须经国家水土保持生态环境监测机构的审查。 监测公告的主要内容：水土流失面积、分布状况和流失程度，水土流失危害及发展趋势，水土保持情况及效益等。 国家水土保持公告每五年发布一次，重点省、重点区域、重大开发建设项目的监测成果根据实际需要发布。"},{"i":20,"n":"第二十条","txt":"各级水土保持生态环境监测机构对外提供监测数据须经同级水土保持生态环境监测管理机构同意。"},{"i":21,"n":"第二十一条","txt":"对在水土保持生态环境监测中无故不上报监测数据，不按规定开展监测工作，在监测工作中弄虚作假，未经同意擅自对外提供监测数据的，按有关规定处理。"},{"i":22,"n":"第二十二条","txt":"本办法由水利部负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自发布之日起实施。"}],"shuigongchengjiansheguihuatongyishuzhiduguanlibanfdf1688":[{"i":1,"n":"第一条","txt":"为加强对水工程建设的监督管理，保障水工程建设符合流域综合规划和防洪规划的要求，根据《中华人民共和国水法》、《中华人民共和国防洪法》和《中华人民共和国行政许可法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在江河、湖泊上新建、扩建以及改建并调整原有功能的水工程，适用本办法。 本办法所称水工程，是指水库、拦河闸坝、引（调、提）水工程、堤防、水电站（含航运水电枢纽工程）等在江河、湖泊上开发、利用、控制、调配和保护水资源的各类工程。"},{"i":3,"n":"第三条","txt":"水利部负责水工程建设规划同意书制度实施的监督管理。 水利部所属流域管理机构（以下简称流域管理机构）和县级以上地方人民政府水行政主管部门按照分级管理权限，具体负责水工程建设规划同意书制度的实施和监督管理。"},{"i":4,"n":"第四条","txt":"水工程未取得流域管理机构或者县级以上地方人民政府水行政主管部门按照管理权限审查签署的水工程建设规划同意书的，建设单位不得开工建设。 水工程建设规划同意书的内容，包括对水工程建设是否符合流域综合规划和防洪规划审查并签署的意见。"},{"i":5,"n":"第五条","txt":"下列水工程建设规划同意书，由流域管理机构负责审查并签署： （一）长江、黄河、淮河、海河、珠江、松花江、辽河的干流及其主要一级支流和太湖以及其他跨省、自治区、直辖市的重要江河上建设的水工程； （二）省际边界河流（河段）、湖泊上建设的水工程； （三）国际河流（含跨界、边界河流和湖泊）及其主要支流上建设的水工程； （四）流域管理机构直接管理的河流（河段）、湖泊上建设的水工程。 前款第一项中的主要一级支流和其他跨省、自治区、直辖市的重要江河，第三项中的主要支流以及第四项中的流域管理机构直接管理的河流（河段）、湖泊的名录和范围由水利部规定。 本条第一款规定以外的其他水工程建设规划同意书，由县级以上地方人民政府水行政主管部门按照省、自治区、直辖市人民政府水行政主管部门规定的管理权限负责审查并签署。"},{"i":6,"n":"第六条","txt":"水工程建设单位（以下简称建设单位）应当向有水工程建设规划同意书审查签署权限的流域管理机构或者县级以上地方人民政府水行政主管部门（以下简称审查签署机关）提出水工程建设规划同意书申请，并提交下列材料： （一）水工程建设规划同意书申请表； （二）拟报批水工程的（预）可行性研究报告（项目申请报告、备案材料）； （三）与第三者利害关系的相关说明； （四）审查签署机关要求的其他材料。"},{"i":7,"n":"第七条","txt":"审查签署机关应当自收到申请之日起5个工作日内对申请材料进行审查，并根据下列情况分别作出处理： （一）属于本机关受理范围，申请材料齐全、符合法定形式的，应当予以受理，并出具书面受理凭证； （二）申请材料不齐全或者不符合法定形式的，应当一次告知建设单位予以补正； （三）不属于本机关受理范围的，应当作出不予受理的决定，并告知建设单位向有受理权限的机关提出申请。"},{"i":8,"n":"第八条","txt":"审查签署机关对受理的水工程建设规划同意书申请，应当依据有关法律、法规以及流域综合规划和防洪规划进行审查；对符合下列条件的，作出批准的决定，并签署水工程建设规划同意书： （一）水工程建设规模、任务符合流域综合规划和防洪规划的总体要求； （二）建设规模等级（别）和标准符合《防洪标准》及其他有关技术和管理规定的要求； （三）不影响其他水工程，或者有消除影响的补救措施。 水工程建设不符合前款规定条件之一的，审查签署机关应当作出不予批准的决定，并下达水工程建设规划同意书不予签署通知书。 水工程建设规划同意书可以对水工程的设计方案和管理措施提出有关要求。 审查签署机关签署的水工程建设规划同意书，应当抄送与水工程有关的下一级水行政主管部门。流域管理机构签署的水工程建设规划同意书，应当抄送与水工程有关的省、自治区、直辖市人民政府水行政主管部门。"},{"i":9,"n":"第九条","txt":"水工程所在江河、湖泊的流域综合规划或者防洪规划尚未编制或者批复的，建设单位应当就水工程是否符合流域治理、开发、保护的要求或者防洪的要求编制专题论证报告。建设单位可以委托流域综合规划、防洪规划的编制单位或者其他有关单位承担专题论证报告编制工作。 审查签署机关应当组织专家对专题论证报告进行审查，水工程符合流域治理、开发、保护和防洪要求的，作出批准的决定，并签署水工程建设规划同意书。"},{"i":10,"n":"第十条","txt":"审查签署机关在审查过程中，必要时应当征求与水工程有关的下一级水行政主管部门的意见。流域管理机构在审查过程中，必要时应当征求与水工程有关的省、自治区、直辖市人民政府水行政主管部门的意见。"},{"i":11,"n":"第十一条","txt":"审查签署机关应当自受理水工程建设规划同意书申请之日起20个工作日内作出决定。20个工作日内不能作出决定的，经本机关负责人批准，可以延长10个工作日，并应当将延长期限的理由告知建设单位。 执行本办法第九条规定所需的时间不计算在前款规定的审查期限内，但审查签署机关应当将所需时间告知建设单位。"},{"i":12,"n":"第十二条","txt":"水工程建设规划同意书签署后，水工程的（预）可行性研究报告（项目申请报告、备案材料）未获得审批（核准、备案）需要重新编制的，建设单位应当重新申请水工程建设规划同意书。"},{"i":13,"n":"第十三条","txt":"省级人民政府水行政主管部门应当在每年的3月1日前，向流域管理机构报送本行政区域内上一年度水工程建设规划同意书审查签署情况。流域管理机构应当在每年的4月1日前，向水利部报送本流域内上一年度水工程建设规划同意书审查签署情况。"},{"i":14,"n":"第十四条","txt":"审查签署机关应当对其审查签署水工程建设规划同意书的水工程的建设情况进行监督管理。审查签署机关在进行监督检查时，有权进行实地调查，建设单位应当给予配合，如实提供有关情况和材料。"},{"i":15,"n":"第十五条","txt":"审查签署机关及其工作人员违反本办法规定的，按照《中华人民共和国水法》、《中华人民共和国防洪法》和《中华人民共和国行政许可法》的有关规定予以处理。"},{"i":16,"n":"第十六条","txt":"建设单位未取得水工程建设规划同意书擅自建设水工程，或者违反水工程建设规划同意书的要求建设水工程的，按照《中华人民共和国水法》和《中华人民共和国防洪法》的有关规定予以处罚。"},{"i":17,"n":"第十七条","txt":"水工程建设规划同意书申请表、水工程建设规划同意书、水工程建设规划同意书不予签署通知书的格式见附录。"},{"i":18,"n":"第十八条","txt":"省、自治区、直辖市人民政府水行政主管部门或者流域管理机构，可以依据本办法制定实施细则。"},{"i":19,"n":"第十九条","txt":"本办法自公布之日起施行。"}],"shuikudabazhucedengjibanfa":[{"i":1,"n":"第一条","txt":"为掌握水库大坝的安全状况，加强水库大坝的安全管理和监督，根据国务院发布的《水库大坝安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内库容在10万立方米以上已建成的水库大坝。所指大坝包括永久性挡水建筑物以及与其配合运用的泄洪、输水等建筑物。"},{"i":3,"n":"第三条","txt":"县级及以上水库大坝主管部门是注册登记的主管部门。水库大坝注册登记实行分部门分级负责制。 省一级或以上各大坝主管部门负责登记所管辖的库容在1亿立方米以上大型水库大坝和直管的水库大坝；地（市）一级各大坝主管部门负责登记所管辖的库容在1000万至1亿立方米（不含1亿立方米）的中型水库大坝和直管的水库大坝；县一级各大坝主管部门负责登记所管辖的库容在10－1000万立方米（不含1000万立方米）的小型水库大坝。登记结果应进行汇编、建档，并逐级上报。各级水库大坝主管部门可指定机构受理大坝注册登记工作。"},{"i":4,"n":"第四条","txt":"国务院水行政主管部门负责全国水库大坝注册登记的汇总工作。国务院各大坝主管部门和各省、自治区、直辖市水行政主管部门负责所管辖水库大坝注册登记的汇总工作，并报国务院水行政主管部门。"},{"i":5,"n":"第五条","txt":"凡符合本办法第二条规定已建成运行的大坝管理单位，应到指定的注册登记机构申报登记。没有专管机构的大坝，由乡镇水利站申报登记。 大坝注册登记需履行下列程序： （一）申报：已建成运行的大坝管理单位应携带大坝主要技术经济指标资料和申请书，按第三条的规定向大坝主管部门或指定的注册登记机构申报登记。注册登记受理机构认可后，即应发给相应的登记表，由大坝管理单位认真填写，经所管辖水库大坝的主管部门审查后上报。 （二）审核：注册登记机构收到大坝管理单位填报的登记表后，即应进行审查核实。 （三）发证：经审查核实，注册登记受理机构应向大坝管理单位发给注册登记证。注册登记证要注明大坝安全类别，属险坝者，应限期进行安全加固，并规定限制运行的指标。"},{"i":6,"n":"第六条","txt":"已建成的水库大坝，自本办法施行之日起，6个月内不申报登记的，属违章运行，造成大坝事故的，按《水库大坝安全管理条例》罚则的有关规定处理。"},{"i":7,"n":"第七条","txt":"已注册登记的大坝完成扩建、改建的；或经批准升、降级的；或大坝隶属关系发生变化的，应在此后3个月内，向登记机构办理变更事项登记。大坝失事后应即向主管部门和登记机构报告。"},{"i":8,"n":"第八条","txt":"水库大坝应按国务院各大坝主管部门规定的制度进行安全鉴定。鉴定后，大坝管理单位应在3个月内，将安全鉴定情况和安全类别报原登记机构，大坝安全类别发生变化者，应向原登记受理机构申请换证。"},{"i":9,"n":"第九条","txt":"经主管部门批准废弃的大坝，其管理单位应在撤销前，向注册登记机构申请注销，填报水库大坝注销登记表，并交回注册登记证。"},{"i":10,"n":"第十条","txt":"水库大坝注册登记的数据和情况应实事求是、真实准确，不得弄虚作假。注册登记机构有权对大坝管理单位的登记事项进行检查，并每隔5年对大坝管理单位的登记事项普遍复查一次。"},{"i":11,"n":"第十一条","txt":"经发现已登记的大坝有关安全的数据和情况发生变更而未及时申报换证或在具体事项办理中有弄虚作假行为，由县级以上水库大坝主管部门对大坝管理单位处以警告或1000元以下罚款，对有关责任人员由其上级主管部门给予行政处分。"},{"i":12,"n":"第十二条","txt":"水库大坝注册登记证和登记表应按照附件格式由国务院各大坝主管部门统一印制。国务院各大坝主管部门，可根据本部门需要增加登记表的附页。 大坝注册登记时，登记机构可收取注册登记表证的工本费。"},{"i":13,"n":"第十三条","txt":"本办法自1996年1月1日起施行。"}],"shuikujiangdengyubaofeiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强水库安全管理，规范水库降等与报废工作，根据《中华人民共和国水法》《中华人民共和国防洪法》《水库大坝安全管理条例》等法律法规和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于已建水库的降等与报废。"},{"i":3,"n":"第三条","txt":"水利部负责全国水库降等与报废工作的组织指导和监督管理。 水利部所属流域管理机构（以下简称流域管理机构）负责管辖权限范围内水库降等与报废工作的组织实施和监督管理。 县级以上地方人民政府水行政主管部门按照职责负责本行政区域内水库降等与报废工作的组织实施和监督管理。 依照法律、法规的有关规定，县级以上人民政府住房和城乡建设、交通运输、农业农村、能源等其他水库大坝主管部门按照职责负责其管辖的水库降等与报废工作。"},{"i":4,"n":"第四条","txt":"水库降等与报废工作坚持安全第一、严格管理的原则，强化综合治理，统筹考虑工程安全、功能和效益发挥以及技术可行性、经济合理性等因素，进行科学论证，合理妥善实施，同步解决好生态保护和修复等相关问题。 水库降等与报废，必须经过论证和审批程序。"},{"i":5,"n":"第五条","txt":"降等是指将原设计工程等别降低进行运行管理，以保证工程安全和发挥相应效益的措施。符合下列条件之一的水库，可以予以降等： （一）现有库容低于原设计规模，或者不能按照原设计规模正常蓄水，且按原设计规模恢复库容或者正常蓄水不具备条件，或者技术上不可行、经济上不合理的； （二）原设计功能大部分已被其他工程替代或者水库功能萎缩已达不到原设计的； （三）工程病险严重，除险加固不具备条件或者技术上不可行、经济上不合理，降等可以保证安全和发挥相应效益的； （四）因其他原因需要降等的。"},{"i":6,"n":"第六条","txt":"报废是指水库失去原有功能和利用价值，去除大坝蓄水作用和碍洪影响，以确保安全的措施。符合下列条件之一的水库，可以予以报废： （一）水库功能基本丧失且不具备恢复条件，或者水库原设计功能被其他工程替代，无进一步开发利用价值的； （二）库容基本淤满，无合理有效措施恢复的； （三）工程严重毁坏或者病险严重，除险加固不具备条件或者技术上不可行、经济上不合理，降等仍不能保证安全的； （四）因其他原因需要报废的。"},{"i":7,"n":"第七条","txt":"水库需要降等或者报废的，按照下列管理权限组织论证，编制水库降等或者报废评估报告。 （一）水利部、流域管理机构管理的水库，由流域管理机构组织编制评估报告； （二）地方人民政府水行政主管部门管理的水库，按照省、自治区、直辖市的规定组织编制评估报告，或者按照管理权限由县级以上地方人民政府水行政主管部门组织编制。 水库降等或者报废评估报告应当依据水利部有关技术标准，论证降等或者报废的理由、依据和应当采取的措施等。根据水库等别，评估报告可以委托具有相应勘察设计资质或者能力的单位编制。 水库降等为塘坝等其他蓄水工程的，应当明确管理责任主体和管理措施。 水库报废的，原则上应当拆除大坝；经评估可以不全部拆除大坝的，应当满足安全行洪要求，保留的结构物存在安全隐患的，应当采取措施消除隐患。"},{"i":8,"n":"第八条","txt":"经评估符合降等或者报废条件的，流域管理机构和县级以上地方人民政府水行政主管部门应当向有审批权限的审批机关提出水库降等或者报废申请，并提交降等或者报废评估报告、征求相关方意见和水库资产核定情况等材料。 水库降等或者报废按照以下权限审批： （一）水利部或者流域管理机构管理的水库，由水利部审批或者按程序报请审批。 （二）地方人民政府水行政主管部门管理的水库中，省级人民政府水行政主管部门管理的，由流域管理机构审批；其他大型水库和市级人民政府水行政主管部门管理的，由省级人民政府水行政主管部门审批；其他水库由市级人民政府水行政主管部门审批。"},{"i":9,"n":"第九条","txt":"审批机关收到水库降等或者报废申请后，应当组织或者委托有关单位进行审查。审查时根据需要，邀请有关部门、单位代表和水利规划、水文水资源、工程地质、水工结构、工程管理、生态环境等方面专家参加。 地方人民政府水行政主管部门批复降等或者报废的水库涉及流域防洪、调水、联合调度的，应当征得流域管理机构同意。"},{"i":10,"n":"第十条","txt":"审批机关应当自收到水库降等或者报废申请之日起三个月内予以批复。审批结果应当报水库建设原审批部门备案。 其他水库大坝主管部门管辖水库的降等与报废，审批结果报同级水行政主管部门备案。"},{"i":11,"n":"第十一条","txt":"县级以上地方人民政府水行政主管部门、流域管理机构应当根据批复意见，及时组织实施水库降等或者报废的有关工作。"},{"i":12,"n":"第十二条","txt":"水库降等的组织实施包括以下措施： （一）必要的工程处置措施； （二）修订并完成水库调度规程（方案、运用计划）、大坝安全管理（防汛）应急预案的审批或者备案，落实各项运行管理制度； （三）重新划定水库管理与保护范围； （四）重新确定生态流量目标； （五）按照机构编制有关规定开展水库管理机构变更或者撤销； （六）水库管理人员安置； （七）相关资料整编和归档； （八）批复意见确定的其他措施。"},{"i":13,"n":"第十三条","txt":"水库报废的组织实施包括以下措施： （一）工程处置措施； （二）安全行洪和度汛措施； （三）必要的生态修复措施； （四）按照机构编制有关规定开展水库管理机构变更或者撤销； （五）水库管理人员安置； （六）相关资料整编、归档和移交； （七）批复意见确定的其他措施。 工程处置措施涉及大坝拆除的，应当按照国家有关规定实施。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府水行政主管部门或者流域管理机构应当加强对水库降等或者报废措施完成情况的监督管理，对降等或者报废水库措施完成不到位的，责令限期整改。 水库降等或者报废措施完成后，县级以上地方人民政府水行政主管部门或者流域管理机构应当将完成情况及时报告审批机关。"},{"i":15,"n":"第十五条","txt":"水库降等或者报废后，产生的土地等收益应当按照有关规定优先用于水库管理人员安置；涉及资产处置的，按照国家有关规定执行。"},{"i":16,"n":"第十六条","txt":"水库管理单位或者其主管部门应当负责水库降等或者报废工作中的安全管理。 水库降等或者报废工作中，县级以上地方人民政府应当依法采取措施，保障本行政区域内水库的工程安全、度汛安全和施工安全。县级以上人民政府水行政主管部门和流域管理机构应当依法加强对水库安全的监督管理。 水库降等或者报废后保留的设施和新增的土地，应当做好保护和后续利用，不得影响防洪安全。"},{"i":17,"n":"第十七条","txt":"水库降等或者报废工作完成后，应当按照水库大坝注册登记的有关规定，办理变更登记或者注销登记手续。"},{"i":18,"n":"第十八条","txt":"水库降等与报废工作所需经费，按照国家和地方有关规定予以保障。 鼓励通过社会资本参与、水生态产品价值实现等机制，拓宽水库降等与报废工作的经费渠道。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府水行政主管部门、流域管理机构和有关单位的工作人员在水库降等或者报废实施过程中玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予政务处分。 在水库降等或者报废实施过程中，发现因前期工作、工程建设、运行管理等违法违规行为造成水库降等或者报废的，县级以上人民政府水行政主管部门和流域管理机构应当按照职责依法处理。"},{"i":20,"n":"第二十条","txt":"省级人民政府水行政主管部门可以根据本办法制定实施细则。"},{"i":21,"n":"第二十一条","txt":"其他水库大坝主管部门管辖的水库降等与报废工作，按照该主管部门的规定执行；没有规定的，可以参照本办法执行。"},{"i":22,"n":"第二十二条","txt":"本办法自2025年12月1日起施行。2003年5月26日水利部发布的《水库降等与报废管理办法（试行）》同时废止。"}],"shuikujiangdengyubaofeiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强水库安全管理，规范水库降低等别（以下简称降等）与报废工作，根据《中华人民共和国水法》和《水库大坝安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于总库容在10万立方米以上（含10万立方米）的已建水库。"},{"i":3,"n":"第三条","txt":"降等是指因水库规模减小或者功能萎缩，将原设计等别降低一个或者一个以上等别运行管理，以保证工程安全和发挥相应效益的措施。 报废是指对病险严重且除险加固技术上不可行或者经济上不合理的水库以及功能基本丧失的水库所采取的处置措施。"},{"i":4,"n":"第四条","txt":"县级以上人民政府水行政主管部门按照分级负责的原则对水库降等与报废工作实施监督管理。 水库主管部门（单位）负责所管辖水库的降等与报废工作的组织实施；乡镇人民政府负责农村集体经济组织所管辖水库的降等与报废工作的组织实施。 前款规定的水库降等与报废工作的组织实施部门（单位）、乡镇人民政府，统称为水库降等与报废工作组织实施责任单位。"},{"i":5,"n":"第五条","txt":"水库降等与报废，必须经过论证、审批等程序后实施。"},{"i":6,"n":"第六条","txt":"报废的国有水库资产的处理，执行国有资产管理的有关规定。"},{"i":7,"n":"第七条","txt":"符合下列条件之一的水库，应当予以降等： （一）因规划、设计、施工等原因，实际工程规模达不到《水利水电工程等级划分及洪水标准》（SL252-2000）规定的原设计等别标准，扩建技术上不可行或者经济上不合理的； （二）因淤积严重，现有库容低于《水利水电工程等级划分及洪水标准》（SL252-2000）规定的原设计等别标准，恢复库容技术上不可行或者经济上不合理的； （三）原设计效益大部分已被其它水利工程代替，且无进一步开发利用价值或者水库功能萎缩已达不到原设计等别规定的； （四）实际抗御洪水标准不能满足《水利水电工程等级划分及洪水标准》（SL252-2000）规定或者工程存在严重质量问题，除险加固经济上不合理或者技术上不可行，降等可保证安全和发挥相应效益的； （五）因征地、移民或者在库区淹没范围内有重要的工矿企业、军事设施、国家重点文物等原因，致使水库自建库以来不能按照原设计标准正常蓄水，且难"},{"i":8,"n":"第八条","txt":"符合下列条件之一的水库，应当予以报废： （一）防洪、灌溉、供水、发电、养殖及旅游等效益基本丧失或者被其它工程替代，无进一步开发利用价值的； （二）库容基本淤满，无经济有效措施恢复的； （三）建库以来从未蓄水运用，无进一步开发利用价值的； （四）遭遇洪水、地震等自然灾害或战争等不可抗力，工程严重毁坏，无恢复利用价值的； （五）库区渗漏严重，功能基本丧失，加固处理技术上不可行或者经济上不合理的； （六）病险严重，且除险加固技术上不可行或者经济上不合理，降等仍不能保证安全的； （七）因其它原因需要报废的。"},{"i":9,"n":"第九条","txt":"凡符合本办法第七条、第八条规定，应当予以降等或者报废的水库，由水库降等与报废工作组织实施责任单位根据水库规模委托符合《工程勘察资质分级标准》和《工程设计资质分级标准》（建设部建设〔2001〕22号）规定的具有相应资质的单位提出水库降等或者报废论证报告。 水库降等论证报告内容应当包括水库的原设计及施工简况、运行现状、运用效益、洪水复核、大坝质量评价、降等理由及依据、实施方案。 水库报废论证报告内容应当包括水库的运行现状、运用效益、洪水复核、大坝质量评价、报废理由及依据、风险评估、环境影响及实施方案。 小型水库，根据其潜在的危险程度，参照本条第二款、第三款规定确定论证内容，可以适当从简。"},{"i":10,"n":"第十条","txt":"水库降等或者报废论证报告完成后，需要降等或者报废的，水库降等与报废工作组织实施责任单位应当逐级向有审批权限的机关提出申请。申请材料包括： （一）降等或者报废申请书； （二）降等或者报废论证报告； （三）报废水库的资产核定材料； （四）其它有关材料。"},{"i":11,"n":"第十一条","txt":"水行政主管部门及农村集体经济组织管辖的水库降等，由水行政主管部门或者流域机构按照以下规定权限审批，并报水库原审批部门备案： （一）跨省际边界或者对大江大河防洪安全起重要作用的大（1）型水库，由国务院水行政主管部门审批； （二）对大江大河防洪安全起重要作用的大（2）型水库和跨省际边界的其他水库，由流域机构审批； （三）除第（一）项、第（二）项以外的大型和中型水库由省级水行政主管部门审批； （四）上述规定以外的小（1）型水库由市（地）级水行政主管部门审批，小（2）型水库由县级水行政主管部门审批； （五）在一个省（自治区、直辖市）范围内的跨行政区域的水库降等报共同的上一级水行政主管部门审批。 水库报废按照同等规模新建工程基建审批权限审批。 其他部门（单位）管辖的水库降等与报废，审批权限按照该部门（单位）的有关规定执行。审批结果应当及时报同级水行政主管部门及防汛抗旱指挥机构备案。"},{"i":12,"n":"第十二条","txt":"审批机关应当组织或委托有关单位组成由计划、财政、水行政等有关部门（单位）代表及相关专家参加的专家组，对水库降等或者报废论证报告进行审查，并在自接到降等或者报废申请后三个月内予以批复。"},{"i":13,"n":"第十三条","txt":"水库降等与报废工作组织实施责任单位应当根据批复意见，及时组织实施水库降等或者报废的有关工作。"},{"i":14,"n":"第十四条","txt":"水库降等的组织实施包括以下措施： （一） 必要的加固措施； （二） 相应运行调度方案的制定； （三） 富余职工安置； （四） 资料整编和归档； （五） 批复意见确定的其他措施。"},{"i":15,"n":"第十五条","txt":"水库报废的组织实施包括以下措施： （一） 安全行洪措施的落实； （二） 资产以及与水库有关的债权、债务合同、协议的处置； （三） 职工安置； （四） 资料整编和归档； （五） 批复意见确定的其他措施。"},{"i":16,"n":"第十六条","txt":"水库报废的组织实施责任单位应当妥善安置原水库管理人员，库区和管理范围内的设施、土地的开发利用要优先用于原水库管理人员的安置。"},{"i":17,"n":"第十七条","txt":"水库降等与报废工作所需经费，由水库降等与报废工作组织实施责任单位负责筹措。"},{"i":18,"n":"第十八条","txt":"水库降等与报废实施方案实施后，由水库降等与报废工作组织实施责任单位提出申请，审批部门组织验收。"},{"i":19,"n":"第十九条","txt":"水库降等与报废工作经验收后，应当按照《水库大坝注册登记办法》的有关规定，办理变更或者注销手续。"},{"i":20,"n":"第二十条","txt":"对应当予以降等和报废的水库不及时降等和报废以及违反本办法规定进行降等、报废的，由县级以上人民政府水行政主管部门或者流域机构责令相关责任单位限期改正；造成安全事故等严重后果的，对负有责任的主管人员和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"各省、自治区、直辖市人民政府水行政主管部门可以根据本办法制定实施细则。"},{"i":22,"n":"第二十二条","txt":"本办法由水利部负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自2003年7月1日起施行。"}],"shuizhengjianchagongzuozhangcheng":[{"i":1,"n":"第一条","txt":"为贯彻《中华人民共和国水法》、《中华人民共和国水土保持法》、《中华人民共和国防洪法》等法律法规，加强水行政执法队伍建设和管理，强化水行政执法，特制定本章程。"},{"i":2,"n":"第二条","txt":"县级以上人民政府水行政主管部门、水利部所属的流域管理机构或者法律法规授权的其他组织（以下统称水行政执法机关）应当组建水政监察队伍，配备水政监察人员，建立水政监察制度，依法实施水政监察。 前款所称水政监察是指水行政执法机关依据水法规的规定对公民、法人或者其他组织遵守、执行水法规的情况进行监督检查，对违反水法规的行为依法实施行政处罚、采取其他行政措施等行政执法活动。"},{"i":3,"n":"第三条","txt":"水利部组织、指导全国的水政监察工作。 水利部所属的流域管理机构负责法律、法规、规章授权范围内的水政监察工作。 县级以上地方人民政府水行政主管部门按照管理权限负责本行政区域内的水政监察工作。"},{"i":4,"n":"第四条","txt":"水政监察以法律、行政法规、地方性法规和规章为依据。 县级以上地方人民政府根据法律、行政法规、地方性法规和规章制定、发布的规范性文件，也作为水政监察的依据。"},{"i":5,"n":"第五条","txt":"各级水行政执法机关应当加强对水政监察的领导和监督，不断提高水政监察人员素质，建设廉洁、文明、高效的水政监察队伍。"},{"i":6,"n":"第六条","txt":"省（自治区、直辖市）人民政府水行政主管部门设置水政监察总队； 市（地、州、盟）人民政府水行政主管部门设置水政监察支队； 县（市、区、旗）人民政府水行政主管部门设置水政监察大队。 水利部所属的流域管理机构根据实际情况设置水政监察总队、水政监察支队、水政监察大队。 根据有关法律法规的要求和实际工作需要，省（自治区、直辖市）、市（地、州、盟）、县（市、区、旗）水政监察队伍内部按照水土保持生态环境监督、水资源管理、河道监理等自行确定设置相应的内部机构（支队、大队、中队）。"},{"i":7,"n":"第七条","txt":"地方各级水政监察队伍由同级人民政府水行政主管部门报同级编制主管部门批准成立。 水利部所属的长江、黄河、淮河、海河、珠江、松辽水利委员会和太湖流域管理局等流域管理机构（以下简称流域机构）水政监察队伍由水利部批准成立；流域机构所属的管理单位水政监察队伍由流域机构批准成立。"},{"i":8,"n":"第八条","txt":"省（自治区、直辖市）、市（地、州、盟）、县（市、区、旗）水行政主管部门根据执法工作需要，可在其所属的水利工程管理单位设置派驻的水政监察队伍。"},{"i":9,"n":"第九条","txt":"水政监察队伍的主要职责是： 1、宣传贯彻《中华人民共和国水法》、《中华人民共和国水土保持法》、《中华人民共和国防洪法》等水法规； 2、保护水资源、水域、水工程、水土保持生态环境、防汛抗旱和水文监测等有关设施； 3、对水事活动进行监督检查，维护正常的水事秩序。对公民、法人或其他组织违反水法规的行为实施行政处罚或者采取其他行政措施； 4、配合和协助公安和司法部门查处水事治安和刑事案件； 5、对下级水政监察队伍进行指导和监督； 6、受水行政执法机关委托，办理行政许可和征收行政事业性规费等有关事宜。"},{"i":10,"n":"第十条","txt":"水行政执法机关的法制工作机构负责管理同级水政监察队伍。水政监察队伍的主要负责人由同级水行政执法机关的法制工作机构的负责人兼任。"},{"i":11,"n":"第十一条","txt":"水政监察人员是实施水政监察的执法人员。"},{"i":12,"n":"第十二条","txt":"水政监察人员必须具备下列条件： （一）通过水法律、法规、规章和相关的法律知识的考核； （二）有一定水利专业知识； （三）遵纪守法、忠于职守、秉公执法、清正廉洁； （四）具有高中以上文化水平，其中水政监察总队、支队、大队的负责人必须具有大专以上文化水平。"},{"i":13,"n":"第十三条","txt":"水政监察人员上岗前应按规定经过资格培训，并考核合格。 水政监察人员上岗前的资格培训和考核工作由流域机构或者省、自治区、直辖市水行政主管部门统一负责。"},{"i":14,"n":"第十四条","txt":"水政监察人员由同级水行政执法机关任免。地方水政监察队伍主要负责人的任免需征得上一级水行政执法机关法制工作机构的审核同意。"},{"i":15,"n":"第十五条","txt":"水政监察人员实行任期制，任期为3年。 水政监察人员任期届满，经考核合格可以继续连任。考核不合格或因故调离工作，任期自动中止，由任免机关免除任命，收回执法证件和标志。"},{"i":16,"n":"第十六条","txt":"水政监察人员在执行公务时，可依法行使下列职权： （一）进行现场检查、勘测和取证等； （二）要求被调查的公民、法人或其他组织提供有关情况和材料； （三）询问当事人和有关证人，作出笔录、录音或录像等； （四）责令有违反水法规行为的单位或个人停止违反水法规的行为。必要时，可采取防止造成损害的紧急处理措施； （五）对违反水法规的行为依法实施行政处罚或者采取其他行政措施。"},{"i":17,"n":"第十七条","txt":"水政监察人员执行公务时，应当持有并按规定出示水政监察证件。水政监察证件的制作和管理由水利部规定。"},{"i":18,"n":"第十八条","txt":"水政监察人员每年应当接受法律知识培训。 水行政执法机关应当制定长期培训规划和年度培训计划，不断提高水政监察人员的执法水平。"},{"i":19,"n":"第十九条","txt":"水政监察队伍实行执法责任制和评议考核制。"},{"i":20,"n":"第二十条","txt":"水政监察队伍应当建立和完善执法责任分解制度、水政监察巡查制度、错案责任追究制度、执法统计制度、执法责任追究制度以及水行政执法案件的登记、立案、审批、审核及目标管理等水政监察工作制度。"},{"i":21,"n":"第二十一条","txt":"每年年底水行政执法机关的法制工作机构和上一级水政监察队伍负责对水政监察队伍执法责任制的执行情况进行考核。 水行政执法机关对在水政监察工作中作出显著成绩的水政监察队伍和水政监察人员，应当给予表彰或奖励。"},{"i":22,"n":"第二十二条","txt":"水行政执法机关应当为水政监察队伍配备必要的交通、通讯、勘察、音像等专用执法装备，改善办公条件，给予水政监察人员与执法任务相适应的执法津贴，投人身伤害保险等。 水政监察工作的装备标准由水利部另行规定。"},{"i":23,"n":"第二十三条","txt":"各级水行政执法机关应当保证水政监察经费。水政监察经费从水利事业费中核拨，不足部分在依法征收的行政事业性规费中列支，并应严格贯彻执行中央关于“收支两条线”的规定。"},{"i":24,"n":"第二十四条","txt":"水政监察人员应当忠于职守、遵纪守法，不得徇私舞弊。对有违法、违纪、失职、渎职行为的水政监察人员，由水行政执法机关视其情节轻重，给予批评教育或行政处分；构成犯罪的，由有关部门依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本章程由水利部负责解释。"},{"i":26,"n":"第二十六条","txt":"本章程自发布之日起施行。1990年8月15日发布的水利部令第1号《水政监察组织暨工作章程（试行）》同时废止。"}],"shuiwenzhuanyeyouchangfuwushoufeiguanlishixingbanfae88a0":[{"i":1,"n":"第一条","txt":"为了规范水利系统水文专业有偿服务收费，加强水文收费管理工作，促进水文事业的发展，根据原国家物价局、财政部《关于发布中央管理的水利系统行政事业性收费项目及标准的通知》（〔1992〕价费字181号）和《关于放开部分行政事业性收费的通知》（〔1993〕价费字134号）及国家有关政策，特制定本办法。"},{"i":2,"n":"第二条","txt":"凡水文单位从事水文专业有偿服务活动时执行本办法。"},{"i":3,"n":"第三条","txt":"水文专业有偿服务收费范围按以下原则确定。 一、水文部门为工农业、交通运输业、地质矿产、环境保护、水利、电力等行业的企事业单位和个体从业者以及党、政、军领导机关所属、企、事业  单位提供服务均按《水文专业有偿服务收费标准》（本办法附件）收费。 二、水文部门为党、政、军领导机关组织防汛、抢险、抗洪、救灾而提供的决策性水文情报不实行有偿服务，只收电讯费。 三、国际交换资料按对等原则或双方签定的合同执行。"},{"i":4,"n":"第四条","txt":"专业服务项目 一、水文勘测与测绘 二、水文资料审查、水文分析计算、水资源调查评价 三、水文情报预报 四、水质监测、分析 五、资料与成果 六、水文自动测报系统及常规仪器维修"},{"i":5,"n":"第五条","txt":"水文收费标准以生产水文勘测产品所耗费的材料费、燃料动力费、工资、管理费、其他费用为基础，考虑使用频率、更新周期、技术处理费用等因素确定。"},{"i":6,"n":"第六条","txt":"下列特殊情况按以下原则处理： 一、在十类或十类以上工资地区作业时，按标准增加10%。 二、需在高温、高寒地区进行作业的项目，按标准增加10%～20%。 三、在海拔高度超过2000米作业时，加收10%；超过3000米时，加收20%；超过4000米时，加收30%。 四、受潮汐影响时，按标准增加20%～30%。"},{"i":7,"n":"第七条","txt":"水文部门向使用水文资料提供的水文勘测资料只供该单位使用，未经负责该项资料观测和整理的水文部门同意，不得转让给第三者使用。否则，按有关法律、法规条款追究责任。"},{"i":8,"n":"第八条","txt":"水文单位从事水文专业有偿服务工作时必须先与委托方签订任务合同书。水文单位必须按合同要求完成任务并确保成果质量，委托单位必须按合同要求向水文单位交纳费用，否则，任何一方可停止执行合同并按经济合同法追究对方责任。各流域机构、省、直辖市、自治区水文主管部门应根据自身水文业务情况统一规定合同格式。"},{"i":9,"n":"第九条","txt":"各级水文部门应加强对水文有偿服务收费的管理，不得擅  自提高收费标准。各省、自治区、直辖市颁发的水文专业有偿服务收费标  准不得高于本办法规定的标准。"},{"i":10,"n":"第十条","txt":"本办法自1994年7月1日起执行。"},{"i":11,"n":"第十一条","txt":"本办法由水利部负责解释。 附件：水文专业有偿服务收费标准.pdf"}],"shuiwenjiancehuanjinghesheshibaohubanfa":[{"i":1,"n":"第一条","txt":"为了加强水文监测环境和设施保护，保障水文监测工作正常进行，根据《中华人民共和国水法》和《中华人民共和国水文条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国家基本水文测站（以下简称水文测站）水文监测环境和设施的保护。 本办法所称水文监测环境，是指为确保准确监测水文信息所必需的区域构成的立体空间。 本办法所称水文监测设施，是指水文站房、水文缆道、测船、测船码头、监测场地、监测井（台）、水尺（桩）、监测标志、专用道路、仪器设备、水文通信设施以及附属设施等。"},{"i":3,"n":"第三条","txt":"国务院水行政主管部门负责全国水文监测环境和设施保护的监督管理工作，其直属的水文机构具体负责组织实施。 国务院水行政主管部门在国家确定的重要江河、湖泊设立的流域管理机构（以下简称流域管理机构），在所管辖范围内按照法律、行政法规和本办法规定的权限，组织实施有关水文监测环境和设施保护的监督管理工作。 省、自治区、直辖市人民政府水行政主管部门负责本行政区域内的水文监测环境和设施保护的监督管理工作，其直属的水文机构接受上级业务主管部门的指导，并在当地人民政府的领导下具体负责组织实施。"},{"i":4,"n":"第四条","txt":"水文监测环境保护范围应当因地制宜，符合有关技术标准，一般按照以下标准划定： （一）水文监测河段周围环境保护范围：沿河纵向以水文基本监测断面上下游各一定距离为边界，不小于五百米，不大于一千米；沿河横向以水文监测过河索道两岸固定建筑物外二十米为边界，或者根据河道管理范围确定。 （二）水文监测设施周围环境保护范围：以监测场地周围三十米、其他监测设施周围二十米为边界。"},{"i":5,"n":"第五条","txt":"有关流域管理机构或者水行政主管部门应当根据管理权限并按照本办法第四条规定的标准拟定水文监测环境保护范围，报水文监测环境保护范围所在地县级人民政府划定，并在划定的保护范围边界设立地面标志。"},{"i":6,"n":"第六条","txt":"禁止在水文监测环境保护范围内从事下列活动： （一）种植树木、高秆作物，堆放物料，修建建筑物，停靠船只； （二）取土、挖砂、采石、淘金、爆破、倾倒废弃物； （三）在监测断面取水、排污，在过河设备、气象观测场、监测断面的上空架设线路； （四）埋设管线，设置障碍物，设置渔具、锚锭、锚链，在水尺（桩）上栓系牲畜； （五）网箱养殖，水生植物种植，烧荒、烧窑、熏肥； （六）其他危害水文监测设施安全、干扰水文监测设施运行、影响水文监测结果的活动。"},{"i":7,"n":"第七条","txt":"国家依法保护水文监测设施。任何单位和个人不得侵占、毁坏、擅自移动或者擅自使用水文监测设施，不得使用水文通信设施进行与水文监测无关的活动。"},{"i":8,"n":"第八条","txt":"未经批准，任何单位和个人不得迁移水文测站。因重大工程建设确需迁移的，建设单位应当在建设项目立项前，报请对该水文测站有管理权限的流域管理机构或者水行政主管部门批准，所需费用由建设单位承担。"},{"i":9,"n":"第九条","txt":"在水文测站上下游各二十公里（平原河网区上下游各十公里）河道管理范围内，新建、改建、扩建下列工程影响水文监测的，建设单位应当采取相应措施，在征得对该水文测站有管理权限的流域管理机构或者水行政主管部门同意后方可建设： （一）水工程； （二）桥梁、码头和其他拦河、跨河、临河建筑物、构筑物，或者铺设跨河管道、电缆； （三）取水、排污等其他可能影响水文监测的工程。 因工程建设致使水文测站改建的，所需费用由建设单位承担，水文测站改建后应不低于原标准。"},{"i":10,"n":"第十条","txt":"建设本办法第九条规定的工程，建设单位应当向有关流域管理机构或者水行政主管部门提出申请，并提交下列材料： （一）在水文测站上下游建设影响水文监测工程申请书； （二）自行或者委托有关单位编制的建设工程对水文监测影响程度的分析评价报告； （三）补救措施和费用估算； （四）工程施工计划； （五）审批机关要求的其他材料。"},{"i":11,"n":"第十一条","txt":"有关流域管理机构或者水行政主管部门对受理的在水文测站上下游建设影响水文监测工程的申请，应当依据有关法律、法规以及技术标准进行审查，自受理申请之日起二十日内作出行政许可决定。对符合下列条件的，作出同意的决定，向建设单位颁发审查同意文件： （一）对水文监测影响程度的分析评价真实、准确； （二）建设单位采取的措施切实可行； （三）工程对水文监测的影响较小或者可以通过建设单位采取的措施补救。"},{"i":12,"n":"第十二条","txt":"水文测站因不可抗力遭受破坏的，所在地人民政府和有关水行政主管部门、流域管理机构应当采取措施，组织力量修复，确保其正常运行。"},{"i":13,"n":"第十三条","txt":"在通航河道中或者桥上进行水文监测作业时，应当依法设置警示标志，过往船只、排筏、车辆应当减速、避让。航行的船只，不得损坏水文测船、浮艇、潮位计、水位监测井（台）、水尺、过河缆道、水下电缆等水文监测设施和设备。 水文监测专用车辆、船只应当设置统一的标志。"},{"i":14,"n":"第十四条","txt":"水文机构依法取得的无线电频率使用权和通信线路使用权受国家保护。任何单位和个人不得挤占、干扰水文机构使用的无线电频率，不得破坏水文机构使用的通信线路。"},{"i":15,"n":"第十五条","txt":"水文监测环境和设施遭受人为破坏影响水文监测的，水文机构应当及时告知有关地方人民政府水行政主管部门。被告知的水行政主管部门应当采取措施确保水文监测正常进行；必要时，应当向本级人民政府汇报，提出处置建议。该水行政主管部门应当及时将处置情况书面告知水文机构。"},{"i":16,"n":"第十六条","txt":"新建、改建、扩建水文测站所需用地，由对该水文测站有管理权限的流域管理机构或者水行政主管部门报请水文测站所在地县级以上人民政府土地行政主管部门，依据水文测站用地标准合理确定，依法办理用地审批手续。已有水文测站用地应当按照有关法律、法规的规定进行确权划界，办理土地使用证书。"},{"i":17,"n":"第十七条","txt":"国家工作人员违反本办法规定，在水文监测环境和设施保护工作中玩忽职守、滥用职权的，按照法律、法规的有关规定予以处理。"},{"i":18,"n":"第十八条","txt":"违反本办法第六条、第七条、第九条规定的，分别依照《中华人民共和国水文条例》第四十三条、第四十二条和第三十七条的规定给予处罚。"},{"i":19,"n":"第十九条","txt":"专用水文测站的水文监测环境和设施保护可以参照本办法执行。"},{"i":20,"n":"第二十条","txt":"本办法自2011年4月1日起施行。"}],"shuiwenjianceziliaohuijiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强和规范水文监测资料汇交工作，促进资料利用，充分发挥水文服务国民经济和社会发展的作用，根据《中华人民共和国水法》和《中华人民共和国水文条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"国家对水文监测资料实行统一汇交制度。在中华人民共和国领域内从事地表水和地下水资源、水量、水质监测的单位以及其他从事水文监测的单位，应当汇交水文监测资料。 水文监测资料是指通过水文站网对江河、湖泊、渠道、水库的水位、流量、水质、水温、泥沙、冰情、水下地形和地下水资源，以及降水量、蒸发量、墒情、风暴潮等实施监测和水文调查所得资料及其整理分析的成果。"},{"i":3,"n":"第三条","txt":"国务院水行政主管部门负责全国水文监测资料汇交的监督管理。 国务院水行政主管部门在国家确定的重要江河、湖泊设立的流域管理机构（以下简称流域管理机构），负责管理范围内水文监测资料汇交的监督管理，其所属的流域水文机构具体负责组织实施。 省、自治区、直辖市人民政府水行政主管部门负责本行政区域内水文监测资料汇交的监督管理，其所属的省级水文机构具体负责组织实施。"},{"i":4,"n":"第四条","txt":"下列水文监测资料应当进行汇交： （一）国家基本水文测站和专用水文测站的水文监测资料； （二）地表水水源地，行政区界断面、生态流量控制断面、干支流控制断面等重要断面的水文监测资料； （三）重要地下水源地、超采区、海水入侵区等区域的水文监测资料，以及其他区域有关地下水的水文监测资料； （四）水库、引调水工程、水电站、灌区以及其他取用水工程的取（退）水、蓄（泄）水资料； （五）城市防洪排涝、中小河流、山洪灾害易发区及土壤墒情的水文监测资料； （六）河道和湖泊水下地形资料，水文调查、水资源评价资料，水文应急监测资料。"},{"i":5,"n":"第五条","txt":"水文监测资料按照资料管理权限向有关水文机构汇交： （一）流域管理机构所属水文测站的水文监测资料，向所在地流域水文机构汇交，地方人民政府水行政主管部门所属水文测站的水文监测资料，向所在地地方水文机构汇交； （二）其他部门所属测站（断面）的水文监测资料，向所在地地方水文机构汇交，其中位于流域管理机构管理范围的，向所在地流域水文机构汇交。 省级水文机构应当将本行政区域内汇交的水文监测资料向有关流域水文机构汇交。流域水文机构接收的水文监测资料纳入国家水文数据库。 国务院水行政主管部门与国务院有关部门对水文监测资料汇交有协议的，按照协议纳入国家水文数据库。"},{"i":6,"n":"第六条","txt":"流域管理机构和省级人民政府水行政主管部门应当会同有关行业管理部门，建立管理范围内汇交水文监测资料的单位（以下简称汇交单位）名录，并告知汇交单位汇交水文监测资料的范围、内容、期限以及接收汇交资料的水文机构。"},{"i":7,"n":"第七条","txt":"国务院水行政主管部门建立国家水文数据库，建设国家水文监测资料汇交管理平台，统一制定汇交资料格式等相关技术标准。 汇交单位应当通过国家水文监测资料汇交管理平台进行汇交。不能通过汇交管理平台进行汇交的，通过电子介质资料、纸介质资料等方式进行汇交。"},{"i":8,"n":"第八条","txt":"流域水文机构和省级水文机构应当对汇交单位的水文监测资料汇交工作进行业务指导。"},{"i":9,"n":"第九条","txt":"汇交单位应当依照水文监测规程规范和资料使用要求，按月份或者按年度汇交水文监测资料。按月份进行汇交的，应当在次月10日前完成。按年度进行汇交的，国家基本水文测站的水文监测资料应当在次年1月底前完成，其他测站（断面）的水文监测资料应当在次年3月底前完成。 因水旱灾害防御、水资源管理等需要，对水文监测资料报送有时效要求的，汇交单位应当按照有关规定报送。"},{"i":10,"n":"第十条","txt":"汇交水文监测资料应当符合水文监测技术规范的要求，并同时提交以下资料： （一）水文监测资料清单； （二）水文监测资料说明； （三）首次汇交的，还应当提供水文监测站点基础信息以及沿革情况，基础信息有变化的，提供变化情况。"},{"i":11,"n":"第十一条","txt":"接收汇交资料的水文机构应当自收到汇交资料之日起10个工作日内完成汇交资料内容和格式核验，将核验结果告知汇交单位，并向通过核验的汇交单位出具汇交凭证。"},{"i":12,"n":"第十二条","txt":"接收汇交资料的水文机构应当按照国家有关规定和技术规范要求，妥善存储和保管汇交资料。电子介质资料应当进行备份，并对备份介质进行安全管理。纸介质资料的存储环境应当符合国家有关规定。"},{"i":13,"n":"第十三条","txt":"水文机构应当根据国民经济和社会发展需要对水文监测资料进行加工整理形成水文监测成果。 流域水文机构应当将接收的水文监测资料统一编号，整理形成汇交资料目录，报国务院水行政主管部门按年度予以公布。 国家基本水文测站的水文监测资料应当依法公开。 汇交单位有权使用有关水文监测资料。其他单位和个人使用水文监测资料的，按照有关资料使用管理的规定执行。水文监测资料使用时应当注明资料来源。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府水行政主管部门和流域管理机构应当加强对水文监测资料汇交情况的监督检查，对违反水文监测资料汇交有关规定的行为依法实施行政处罚。"},{"i":15,"n":"第十五条","txt":"丢失、毁坏、伪造水文监测资料，或者擅自转让、转借水文监测资料的，依照《中华人民共和国水文条例》第三十六条的规定追究法律责任。"},{"i":16,"n":"第十六条","txt":"汇交单位应当按照规定的时间汇交水文监测资料。未按照规定时间汇交，或者汇交的水文监测资料未通过核验的，应当限期补交；逾期不补交的，视为不汇交水文监测资料。 拒不汇交水文监测资料的，依照《中华人民共和国水文条例》第四十条的规定追究法律责任。"},{"i":17,"n":"第十七条","txt":"水文监测资料属于国家秘密的，对其密级的确定、变更、解密，以及对资料的汇交、传递、存储、使用和管理，依照国家保密法律法规的规定执行。"},{"i":18,"n":"第十八条","txt":"流域管理机构和省级人民政府水行政主管部门可以根据本办法制定具体规定。 本办法实施前尚未汇交的水文监测资料，参照本办法规定进行汇交。"},{"i":19,"n":"第十九条","txt":"本办法自2020年12月1日起施行。"}],"shuiwenzhanwangguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强水文站网管理，充分发挥水文站网功能和作用，根据《中华人民共和国水法》、《中华人民共和国水文条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域内从事水文站网规划、建设和管理等活动，适用本办法。 本办法所称水文站网，是指在流域或者区域内，由适当数量各类水文测站构成的水文监测资料收集系统。"},{"i":3,"n":"第三条","txt":"国务院水行政主管部门负责全国水文站网规划、建设和管理工作，其直属的水文机构具体负责组织实施。 国务院水行政主管部门在国家确定的重要江河、湖泊设立的流域管理机构（以下简称流域管理机构），负责所属水文站网规划、建设与管理工作，并在所管辖范围内按照法律、行政法规规定和本办法规定的权限对水文站网规划、建设与管理工作进行指导和监督。 省、自治区、直辖市人民政府水行政主管部门负责本行政区域内水文站网规划、建设与管理工作，其直属的水文机构（以下简称省级水文机构）具体负责组织实施。"},{"i":4,"n":"第四条","txt":"水文测站分为国家基本水文测站和专用水文测站。 国家基本水文测站按其重要性分为国家重要水文测站和一般水文测站。省、自治区、直辖市人民政府水行政主管部门可以根据实际情况，确定本行政区域内的省级重要水文测站。 根据水文实验研究或者其他科学研究的需要，可以设立水文实验站。"},{"i":5,"n":"第五条","txt":"国家重要水文测站由省、自治区、直辖市人民政府水行政主管部门或者流域管理机构提出，报国务院水行政主管部门直属水文机构审查后，由国务院水行政主管部门确定并公布。"},{"i":6,"n":"第六条","txt":"符合下列条件之一的国家基本水文测站应当确定为国家重要水文测站： （一）向国家防汛抗旱总指挥部报汛且集水面积3000平方公里以上的水文测站。 （二）集水面积10000平方公里以上且年径流量3亿立方米以上，或者集水面积5000平方公里以上且年径流量5亿立方米以上，或者年径流量25亿立方米以上的水文测站；集水面积大于1000平方公里的独流入海河流的控制站。 （三）常年水面面积500平方公里以上且常年蓄水量10亿立方米以上的湖泊代表站。 （四）库容5亿立方米以上，或者库容1亿立方米以上且下游有大中型城市、重要铁路公路干线、大型骨干企业，或者库容不足1亿立方米但国务院水行政主管部门直属水文机构认为对流域防灾减灾有重要影响的水库站；供水人口50万人以上的水库站。 （五）在国家确定的重要江河、湖泊上设置的水量调度控制站；集水面积大于1000平方公里的省际河流边界控制站，或者对省际水事纠纷调处工作有重"},{"i":7,"n":"第七条","txt":"国家对水文站网建设实行统一规划，水文站网规划是水文站网建设、管理的依据。水文站网规划应当依据水文事业发展规划编制，并与有关专项规划相衔接。 水文站网规划应当坚持流域与区域相结合、区域服从流域，布局合理、防止重复，兼顾当前和长远需要的原则。"},{"i":8,"n":"第八条","txt":"水文站网规划主要包括站网现状与分析、规划原则与目标、站网功能、站网布局、站网组成、监测项目、测验方式、管理方式、保障措施和效益评价等内容。"},{"i":9,"n":"第九条","txt":"国务院水行政主管部门直属水文机构负责组织编制全国水文站网规划，报国务院水行政主管部门批准。 流域管理机构负责组织编制流域水文站网规划，报国务院水行政主管部门直属水文机构批准。 省级水文机构负责组织编制本行政区域水文站网规划，经流域管理机构审核，报省、自治区、直辖市人民政府水行政主管部门批准，并报国务院水行政主管部门直属水文机构备案。"},{"i":10,"n":"第十条","txt":"水文站网规划应当根据江河湖库的变化情况和经济社会发展的需求适时修改。修改水文站网规划，应当按照规划编制程序经原批准机关批准。"},{"i":11,"n":"第十一条","txt":"设立专用水文测站，不得与国家基本水文测站重复。有关专业规划中涉及设立专用水文测站的，应当与水文站网规划衔接。有关主管部门批准该专业规划前，应当就专用水文测站的设置征求省级水文机构或者流域管理机构的意见。"},{"i":12,"n":"第十二条","txt":"国家基本水文测站的设立，应当依据水文站网规划，按照国家固定资产投资项目建设程序实施。"},{"i":13,"n":"第十三条","txt":"国家重要水文测站和流域管理机构管理的一般水文测站的设立和调整，由省、自治区、直辖市人民政府水行政主管部门或者流域管理机构报国务院水行政主管部门直属水文机构批准。 其他一般水文测站的设立和调整，由省、自治区、直辖市人民政府水行政主管部门批准，报国务院水行政主管部门直属水文机构备案。其中，在省、自治区、直辖市界河，以及跨省、自治区、直辖市河流交界河段设立和调整水文测站的，有关省、自治区、直辖市水行政主管部门应当就设站方案或者调整方案协商一致；不能协商一致的，由流域管理机构商有关省、自治区、直辖市水行政主管部门提出设站方案或者调整方案，报国务院水行政主管部门直属水文机构确定。"},{"i":14,"n":"第十四条","txt":"国家基本水文测站的设立和调整，建设单位应当进行技术论证，技术论证应当包括以下内容： （一）设立和调整的原因、目的、作用和任务； （二）测验河段站址选择依据、观测项目、测验设施布置； （三）测验、通信方案，人员配备，运行管理方案等； （四）基础设施建设及技术装备是否符合有关技术标准； （五）因重大工程建设影响导致水文测站迁移的，还应当提出相应投资概算及增加运行管理成本的预算。"},{"i":15,"n":"第十五条","txt":"有下列情况之一的，应当按照相关规程规范的要求设立专用水文测站： （一）大中型水库、水电站和具有重要防汛任务的小型水库、水电站； （二）大中型城镇供水工程； （三）大中型灌区； （四）重要的引、调水工程； （五）其他应当设立专用水文测站的重大建设工程。"},{"i":16,"n":"第十六条","txt":"在国家基本水文测站覆盖的区域，确需设立专用水文测站的，应当就设站的必要性作出说明，按照管理权限报流域管理机构或者省级水文机构批准后，方可设立。该测站应当具备以下条件： （一）具有开展水文监测工作必要的场地和基础设施； （二）具有必需的水文监测专用技术装备和计量器具； （三）具有相应专业的技术人员。 流域管理机构或者省级水文机构应当自收到设立专用水文测站申请之日起20个工作日内作出审查决定，但进行技术审查和现场查勘所需时间除外。 撤销专用水文测站，应当报原批准机关批准。"},{"i":17,"n":"第十七条","txt":"因交通、航运、环境保护等需要而设立专用水文测站的，或者在国家基本水文测站未覆盖的区域设立专用水文测站的，有关主管部门在批准前，应当征求相关流域管理机构或者省级水文机构的意见。"},{"i":18,"n":"第十八条","txt":"专用水文测站和从事水文活动的其他单位，应当接受国务院水行政主管部门直属水文机构、流域管理机构和省级水文机构的行业管理。 县、市管理的水文测站，应当接受省级水文机构的行业管理。 专用水文测站达到国务院水行政主管部门规定的国家基本水文测站标准的，在有关省级水文机构或者流域管理机构与该专用水文测站管理单位协商一致，并按照本办法第十三条规定的程序报请批准后，可以将其作为国家基本水文测站管理，其资料纳入省级水文机构或者流域管理机构水文资料整汇编。"},{"i":19,"n":"第十九条","txt":"水文实验站的设立和调整，由水文实验站建设单位报经有关流域管理机构或者省、自治区、直辖市人民政府水行政主管部门提出审查意见后，报国务院水行政主管部门直属水文机构批准。"},{"i":20,"n":"第二十条","txt":"国家水文站网应当保持稳定。未经批准，任何单位和个人不得裁撤、改级和迁移国家基本水文测站；因重大工程建设确需迁移的，建设单位应当在建设项目立项前，报请对该站有管理权限的水行政主管部门批准，所需费用由建设单位承担。 在国家基本水文测站上下游各20公里（平原河网区上下游各10公里）河道管理范围内新建、改建、扩建有关工程影响水文监测、致使国家基本水文测站改建的，按照《中华人民共和国水文条例》和《水文监测环境和设施保护办法》（水利部令第43号）的有关规定执行。"},{"i":21,"n":"第二十一条","txt":"省级水文机构管理的跨界河流水文测站和对流域水资源管理、防灾减灾有重大作用的水文测站，应当接受流域管理机构的业务指导和监督。经流域管理机构与管理该水文测站的省级水文机构协商一致，可由流域管理机构与省级水文机构共同建设，共同管理。"},{"i":22,"n":"第二十二条","txt":"省级水文机构管理的水文测站，根据所在地经济社会发展的需求，经省级水文机构和所在地设区的市级或者县级人民政府协商一致，可同时接受所在地设区的市级或者县级人民政府的管理。"},{"i":23,"n":"第二十三条","txt":"对水文测站设立和调整具有审批权限的有关行政机关、流域管理机构、水文机构，不依法履行审批、监督职责，情节严重的，对直接负责的主管人员和其他直接责任人员给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"未经批准擅自设立水文测站的，依照《中华人民共和国水文条例》第三十七条的规定给予处罚。"},{"i":25,"n":"第二十五条","txt":"本办法自2012年2月1日起施行。"}],"shuixingzhengchufashishibanfa":[{"i":1,"n":"第一条","txt":"为了规范水行政处罚行为，保障和监督行政机关有效实施水行政管理，维护公共利益和社会秩序，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》、《中华人民共和国水法》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织违反水行政管理秩序的行为，依法给予水行政处罚的，由县级以上人民政府水行政主管部门或者法律、法规授权的组织（以下统称水行政处罚机关）依照法律、法规、规章和本办法的规定实施。"},{"i":3,"n":"第三条","txt":"水行政处罚遵循公正、公开的原则。实施水行政处罚必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当。对违法行为给予水行政处罚的规定必须公布；未经公布的，不得作为水行政处罚的依据。 实施水行政处罚，纠正违法行为，应当坚持处罚与教育相结合，教育公民、法人或者其他组织自觉守法。"},{"i":4,"n":"第四条","txt":"水行政处罚的种类： （一）警告、通报批评； （二）罚款、没收违法所得、没收非法财物； （三）暂扣许可证件、降低资质等级、吊销许可证件； （四）限制开展生产经营活动、责令停产停业、责令关闭、限制从业； （五）法律、行政法规规定的其他水行政处罚。"},{"i":5,"n":"第五条","txt":"下列水行政处罚机关在法定授权范围内以自己的名义独立行使水行政处罚权： （一）县级以上人民政府水行政主管部门； （二）国务院水行政主管部门在国家确定的重要江河、湖泊设立的流域管理机构（以下简称流域管理机构）及其所属管理机构； （三）省、自治区、直辖市决定行使水行政处罚权的乡镇人民政府、街道办事处； （四）法律、法规授权的其他组织。"},{"i":6,"n":"第六条","txt":"县级以上人民政府水行政主管部门可以在其法定权限内委托符合本办法第七条规定条件的水政监察专职执法队伍、水行政执法专职机构或者其他组织实施水行政处罚。 受委托组织在委托权限内，以委托水行政主管部门名义实施水行政处罚；不得再委托其他组织或者个人实施水行政处罚。"},{"i":7,"n":"第七条","txt":"受委托组织应当符合下列条件： （一）依法成立并具有管理公共事务职能； （二）具有熟悉有关法律、法规、规章和水利业务，并取得行政执法资格的工作人员； （三）需要进行技术检查或者技术鉴定的，应当有条件组织进行相应的技术检查或者技术鉴定。"},{"i":8,"n":"第八条","txt":"委托实施水行政处罚，委托水行政主管部门应当同受委托组织签署委托书。委托书应当载明下列事项： （一）委托水行政主管部门和受委托组织的名称、地址、法定代表人姓名、统一社会信用代码； （二）委托实施水行政处罚的具体事项、权限和委托期限； （三）违反委托事项应承担的责任； （四）其他需载明的事项。 委托水行政主管部门和受委托组织应当将委托书向社会公布。 受委托组织实施水行政处罚，不得超越委托书载明的权限和期限。 委托水行政主管部门发现受委托组织不符合委托条件的，应当解除委托，收回委托书并向社会公布。"},{"i":9,"n":"第九条","txt":"委托水行政主管部门应当对受委托组织实施水行政处罚的行为负责监督，并对该行为的后果承担法律责任。"},{"i":10,"n":"第十条","txt":"水行政处罚由违法行为发生地的水行政处罚机关管辖。 流域管理机构及其所属管理机构按照法律、行政法规、部门规章的规定和国务院水行政主管部门授予的权限管辖水行政处罚。 法律、行政法规、部门规章另有规定的，从其规定。"},{"i":11,"n":"第十一条","txt":"水行政处罚由县级以上地方人民政府具有水行政处罚权的行政机关管辖。法律、行政法规另有规定的，从其规定。"},{"i":12,"n":"第十二条","txt":"对当事人的同一违法行为，两个以上水行政处罚机关都有管辖权的，由最先立案的水行政处罚机关管辖。 两个以上水行政处罚机关发生管辖争议的，应当在七个工作日内协商解决，协商不成的，报请共同的上一级水行政主管部门指定管辖；也可以直接由共同的上一级水行政主管部门指定管辖。 省际边界发生管辖争议的，应当在七个工作日内协商解决，协商不成的，报请国务院水行政主管部门或者由国务院水行政主管部门授权违法行为发生地所属流域管理机构指定管辖；也可以由国务院水行政主管部门指定流域管理机构负责查处。 指定管辖机关应当在接到申请之日起七个工作日内作出管辖决定，并对指定管辖案件执行情况进行监督。"},{"i":13,"n":"第十三条","txt":"水行政处罚机关实施行政处罚时，应当责令当事人改正或者限期改正违法行为。"},{"i":14,"n":"第十四条","txt":"对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚。同一个违法行为违反多个法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。 两个以上当事人共同实施违法行为的，应当根据违法情节和性质，分别给予水行政处罚。"},{"i":15,"n":"第十五条","txt":"当事人有下列情形之一，应当从轻或者减轻水行政处罚： （一）主动消除或者减轻违法行为危害后果的； （二）受他人胁迫或者诱骗实施违法行为的； （三）主动供述水行政处罚机关尚未掌握的违法行为的； （四）配合水行政处罚机关查处违法行为有立功表现的； （五）法律、法规、规章规定的其他应当从轻或者减轻水行政处罚的。 违法行为轻微并及时改正，没有造成危害后果的，不予水行政处罚。初次违法且危害后果轻微并及时改正的，可以不予水行政处罚。对当事人的违法行为依法不予水行政处罚的，应当对当事人进行教育并记录在案。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府水行政主管部门和流域管理机构可以依法制定管辖范围的水行政处罚裁量基准。 下级水行政主管部门制定的水行政处罚裁量基准与上级水行政主管部门制定的水行政处罚裁量基准冲突的，应当适用上级水行政主管部门制定的水行政处罚裁量基准。 水行政处罚裁量基准应当向社会公布。 水行政处罚机关应当规范行使水行政处罚裁量权，坚持过罚相当、宽严相济，避免畸轻畸重、显失公平。"},{"i":17,"n":"第十七条","txt":"水事违法行为在二年内未被发现的，不再给予水行政处罚；涉及公民生命健康安全且有危害后果的，上述期限延长至五年。法律另有规定的除外。 前款规定的期限，从违法行为发生之日起计算；违法行为有连续或者继续状态的，从行为终了之日起计算。"},{"i":18,"n":"第十八条","txt":"水行政处罚机关应当公示执法主体、人员、职责、权限、立案依据、实施程序和救济渠道等信息。"},{"i":19,"n":"第十九条","txt":"水行政处罚应当由两名以上具有行政执法资格的执法人员实施。 水行政执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当回避，当事人也有权申请其回避。当事人提出回避申请的，水行政处罚机关应当依法审查，由水行政处罚机关负责人决定。决定作出之前，不停止调查。"},{"i":20,"n":"第二十条","txt":"水行政处罚机关在作出水行政处罚决定之前，应当书面告知当事人拟作出的水行政处罚内容及事实、理由、依据，并告知当事人依法享有陈述、申辩、要求听证等权利。不得限制或者变相限制当事人享有的陈述权、申辩权。"},{"i":21,"n":"第二十一条","txt":"水行政处罚机关在告知当事人拟作出的水行政处罚决定后，当事人申请陈述、申辩的，应当充分听取当事人的陈述、申辩，对当事人提出的事实、理由和证据进行复核。当事人提出的事实、理由或者证据成立的，水行政处罚机关应当采纳。 水行政处罚机关未向当事人告知拟作出的水行政处罚内容及事实、理由、依据，或者拒绝听取当事人的陈述、申辩，不得作出水行政处罚决定。当事人明确放弃或者未在规定期限内行使陈述权、申辩权的除外。 水行政处罚机关不得因当事人陈述、申辩而给予更重的处罚。"},{"i":22,"n":"第二十二条","txt":"水行政处罚的启动、调查取证、审核、决定、送达、执行等应当进行全过程记录并归档保存。 查封扣押财产、强制拆除等直接涉及生命健康、重大财产权益的现场执法活动和执法办案场所，应当进行全程音像记录。"},{"i":23,"n":"第二十三条","txt":"水行政处罚机关应当在行政处罚决定作出之日起七个工作日内，公开执法机关、执法对象、执法类别、执法结论等信息。危及防洪安全、供水安全或者水生态安全等后果严重、具有一定社会影响的案件，其行政处罚决定书应当依法公开，接受社会监督。 公开的水行政处罚决定被依法变更、撤销、确认违法或者确认无效的，水行政处罚机关应当在三个工作日内撤回处罚决定信息，并公开说明理由。 涉及国家秘密、商业秘密、个人隐私的，依照相关法律法规规定处理。"},{"i":24,"n":"第二十四条","txt":"水行政处罚证据包括书证、物证、视听资料、电子数据、证人证言、当事人的陈述、鉴定意见、勘验笔录和现场笔录。 证据收集应当严格遵守法定程序。证据经查证属实后方可作为认定案件事实的根据。 采用暴力、威胁等非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":25,"n":"第二十五条","txt":"水行政处罚机关依照法律、行政法规规定利用电子技术监控设备收集、固定违法事实的，应当经过法制和技术审核，确保电子技术监控设备符合标准、设置合理、标志明显，设置地点应当向社会公布。 电子技术监控设备记录违法事实应当真实、清晰、完整、准确。"},{"i":26,"n":"第二十六条","txt":"水行政处罚机关及其工作人员对实施行政处罚过程中知悉的国家秘密、商业秘密或者个人隐私，应当依法予以保密。"},{"i":27,"n":"第二十七条","txt":"违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的，可以当场作出水行政处罚决定。"},{"i":28,"n":"第二十八条","txt":"当场作出水行政处罚决定的，水行政执法人员应当遵守下列程序： （一）向当事人出示行政执法证件； （二）当场收集违法证据； （三）告知当事人违法事实、处罚理由和依据，并告知当事人依法享有陈述和申辩的权利； （四）听取当事人的陈述和申辩。对当事人提出的事实、理由和证据进行复核，当事人明确放弃陈述或者申辩权利的除外； （五）填写预定格式、编有号码的水行政处罚决定书，并由水行政执法人员签名或者盖章； （六）将水行政处罚决定书当场交付当事人，当事人拒绝签收的，应当在水行政处罚决定书上注明； （七）在五个工作日内（在水上当场处罚，自抵岸之日起五个工作日内）将水行政处罚决定书报所属水行政处罚机关备案。 前款处罚决定书应当载明当事人的违法行为，水行政处罚的种类和依据、罚款数额、时间、地点，申请行政复议、提起行政诉讼的途径和期限以及水行政处罚机关名称。"},{"i":29,"n":"第二十九条","txt":"除本办法第二十七条规定的可以当场作出的水行政处罚外，水行政处罚机关对依据水行政监督检查或者通过投诉举报、其他机关移送、上级机关交办等途径发现的违法行为线索，应当在十个工作日内予以核查。案情复杂等特殊情况无法按期完成核查的，经本机关负责人批准，可以延长五个工作日。 公民、法人或者其他组织有符合下列条件的违法行为的，水行政处罚机关应当予以立案： （一）有涉嫌违法的事实； （二）依法应当给予水行政处罚； （三）属于本水行政处罚机关管辖； （四）违法行为未超过追责期限。"},{"i":30,"n":"第三十条","txt":"水行政执法人员依法调查案件，应当遵守下列程序： （一）向当事人出示行政执法证件； （二）告知当事人要调查的范围或者事项以及其享有陈述权、申辩权以及申请回避的权利； （三）询问当事人、证人、与案件有利害关系的第三人，进行现场勘验、检查； （四）制作调查询问、勘验检查笔录。"},{"i":31,"n":"第三十一条","txt":"水行政执法人员可以要求当事人及其他有关单位、个人在一定期限内提供证明材料或者与涉嫌违法行为有关的其他材料，并由材料提供人在有关材料上签名或者盖章。 当事人采取暴力、威胁的方式阻碍调查取证的，水行政处罚机关可以提请有关部门协助。 调查取证过程中，无法通知当事人、当事人不到场或者拒绝配合调查，水行政执法人员可以采取录音、录像或者邀请有关人员作为见证人等方式记录在案。"},{"i":32,"n":"第三十二条","txt":"水行政执法人员收集证据时，可以采取抽样取证的方法。在证据可能灭失或者以后难以取得的情况下，经水行政处罚机关负责人批准，可以先行登记保存。情况紧急，需要当场采取先行登记保存措施的，水行政执法人员应当在二十四小时内向水行政处罚机关负责人报告，并及时补办批准手续。水行政处罚机关负责人认为不应当采取先行登记保存措施的，应当立即解除。"},{"i":33,"n":"第三十三条","txt":"水行政执法人员先行登记保存有关证据，应当当场清点，开具清单，由当事人和水行政执法人员签名或者盖章，并当场交付先行登记保存证据通知书。当事人不在场或者拒绝到场、拒绝签收的，可以邀请有关人员作为见证人签名或者盖章，采用录音、录像等方式予以记录，并由两名以上水行政执法人员在清单上注明情况。 登记保存物品时，在原地保存可能妨害公共秩序、公共安全或者对证据保存不利的，可以异地保存。 先行登记保存期间，当事人或者有关人员不得销毁或者转移证据。"},{"i":34,"n":"第三十四条","txt":"对于先行登记保存的证据，应当在七个工作日内分别作出以下处理决定： （一）需要采取记录、复制、拍照、录像等证据保全措施的，采取证据保全措施； （二）需要进行检测、检验、鉴定、评估、认定的，送交有关机构检测、检验、鉴定、评估、认定； （三）依法应当由有关部门处理的，移交有关部门； （四）不需要继续登记保存的，解除先行登记保存； （五）依法需要对船舶、车辆等物品采取查封、扣押的，依照法定程序查封、扣押； （六）法律、法规规定的其他处理方式。 逾期未采取相关措施的，先行登记保存措施自动解除。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一，经水行政处罚机关负责人批准，中止案件调查，并制作中止调查决定书： （一）水行政处罚决定必须以相关案件的裁判结果或者其他行政决定为依据，而相关案件尚未审结或者其他行政决定尚未作出的； （二）涉及法律适用等问题，需要送请有权机关作出解释或者确认的； （三）因不可抗力致使案件暂时无法调查的； （四）因当事人下落不明致使案件暂时无法调查的； （五）其他应当中止调查的情形。 中止调查的原因消除后，应当立即恢复案件调查。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一，经水行政处罚机关负责人批准，终止调查，并制作终止调查决定书： （一）违法行为已过追责期限的； （二）涉嫌违法的公民死亡或者法人、其他组织终止，并且无权利义务承受人，致使案件调查无法继续进行的； （三）其他需要终止调查的情形。"},{"i":37,"n":"第三十七条","txt":"案件调查终结，水行政执法人员应当及时提交调查报告。调查报告应当包括当事人的基本情况、违法事实、违法后果、相关证据、法律依据等，并提出依法是否应当给予水行政处罚以及给予何种水行政处罚的处理意见。"},{"i":38,"n":"第三十八条","txt":"调查终结，水行政处罚机关负责人应当对调查结果进行审查，根据不同情况，分别作出下列决定： （一）确有应受水行政处罚的违法行为的，根据情节轻重及具体情况，作出水行政处罚决定； （二）违法行为轻微，依法可以不予水行政处罚的，不予水行政处罚； （三）违法事实不能成立的，不予水行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一，在水行政处罚机关负责人作出水行政处罚的决定之前，应当进行法制审核；未经法制审核或者审核未通过的，不得作出决定： （一）涉及防洪安全、供水安全、水生态安全等重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）法律、法规规定应当进行法制审核的其他情形。 前款规定情形以外的，可以根据案件情况进行法制审核。 法制审核由水行政处罚机关法制工作机构负责；未设置法制工作机构的，由水行政处罚机关确定承担法制审核工作的其他机构或者专门人员负责。 案件调查人员不得同时作为该案件的法制审核人员。"},{"i":40,"n":"第四十条","txt":"法制审核内容： （一）水行政处罚主体是否合法，水行政执法人员是否具备执法资格； （二）水行政处罚程序是否合法； （三）案件事实是否清楚，证据是否合法充分； （四）适用法律、法规、规章是否准确，裁量基准运用是否适当； （五）水行政处罚是否按照法定或者委托权限实施； （六）水行政处罚文书是否完备、规范； （七）违法行为是否涉嫌犯罪、需要移送司法机关； （八）法律、法规规定应当审核的其他内容。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一，在作出水行政处罚决定前，水行政处罚机关负责人应当集体讨论： （一）拟作出较大数额罚款、没收较大数额违法所得、没收较大价值非法财物决定的； （二）拟作出限制开展生产经营活动、降低资质等级、吊销许可证件、责令停产停业、责令关闭、限制从业决定的； （三）水行政处罚机关负责人认为应当提交集体讨论的其他案件。 前款第（一）项所称“较大数额”“较大价值”，对公民是指人民币（或者等值物品价值）五千元以上、对法人或者其他组织是指人民币（或者等值物品价值）五万元以上。地方性法规、地方政府规章另有规定的，从其规定。"},{"i":42,"n":"第四十二条","txt":"水行政处罚机关给予水行政处罚，应当制作水行政处罚决定书。水行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、法规、规章的事实和证据，以及当事人陈述、申辩和听证情况； （三）水行政处罚的种类和依据； （四）水行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出水行政处罚决定的水行政处罚机关名称和作出决定的日期。 对同一当事人的两个或者两个以上水事违法行为，可以分别制作水行政处罚决定书，也可以列入同一水行政处罚决定书。"},{"i":43,"n":"第四十三条","txt":"水行政处罚机关应当自立案之日起九十日内作出水行政处罚决定。因案情复杂或者其他原因，不能在规定期限内作出水行政处罚决定的，经本机关负责人批准，可以延长六十日。 案件办理过程中，中止调查、听证、公告、检测、检验、鉴定、评估、认定、送达等时间不计入前款规定的期限。"},{"i":44,"n":"第四十四条","txt":"水行政处罚机关送达水行政执法文书，可以采取下列方式：直接送达、留置送达、邮寄送达、委托送达、电子送达、转交送达、公告送达或者其他方式。送达水行政执法文书应当使用送达回证并存档。"},{"i":45,"n":"第四十五条","txt":"水行政执法文书应当在宣告后当场交付当事人；当事人不在场的，水行政处罚机关应当在七个工作日内依照《中华人民共和国民事诉讼法》的有关规定，将水行政处罚决定书送达当事人，由当事人在送达回证上签名或者盖章，并注明签收日期。签收日期为送达日期。 当事人拒绝接收水行政执法文书的，送达人可以邀请有关基层组织或者所在单位的代表到场见证，在送达回证上注明拒收事由和日期，由送达人、见证人签名或者盖章，把水行政执法文书留在当事人的住所；也可以将水行政执法文书留在当事人的住所，并采取拍照、录像等方式记录送达过程，即视为送达。 邮寄送达的，交由国家邮政机构邮寄。以回执上注明的收件日期为送达日期。 当事人同意并签订确认书的，水行政处罚机关可以采取传真、电子邮件、即时通讯信息等方式送达，到达受送达人特定系统的日期为送达日期。 当事人下落不明，或者采用其他方式无法送达的，水行政处罚机关可以通过本机关或者本级人民政府网"},{"i":46,"n":"第四十六条","txt":"水行政处罚机关拟作出下列水行政处罚决定，应当告知当事人有要求听证的权利，当事人要求听证的，水行政处罚机关应当组织听证： （一）较大数额罚款、没收较大数额违法所得、没收较大价值非法财物； （二）降低资质等级、吊销许可证件、责令停产停业、责令关闭、限制从业； （三）其他较重的水行政处罚； （四）法律、法规、规章规定的其他情形。 前款第（一）项所称“较大数额”“较大价值”，对公民是指人民币（或者等值物品价值）一万元以上、对法人或者其他组织是指人民币（或者等值物品价值）八万元以上。地方性法规、地方政府规章另有规定的，从其规定。"},{"i":47,"n":"第四十七条","txt":"听证应当由水行政处罚机关法制工作机构或者相应机构负责，依照以下程序组织： （一）当事人要求听证的，应当在水行政处罚机关告知后五个工作日内提出； （二）在举行听证会的七个工作日前应当向当事人及有关人员送达水行政处罚听证通知书，告知举行听证的时间、地点、听证人员名单及当事人可以申请回避和委托代理人等事项； （三）当事人可以亲自参加听证，也可以委托一至二人代理。当事人委托代理人参加听证的，应当提交授权委托书。当事人及其代理人应当按期参加听证，无正当理由拒不出席听证或者未经许可中途退出听证的，视为放弃听证权利，终止听证； （四）听证参加人由听证主持人、听证员、记录员、案件调查人员、当事人及其委托代理人、证人以及与案件处理结果有直接利害关系的第三人等组成。听证主持人、听证员、记录员应当由水行政处罚机关指定的法制工作机构或者相应机构工作人员等非本案调查人员担任； （五）当事人认为听证主持人、听证员"},{"i":48,"n":"第四十八条","txt":"听证结束后，水行政处罚机关应当根据听证笔录，依照本办法第三十八条的规定，作出决定。"},{"i":49,"n":"第四十九条","txt":"水行政处罚决定作出后，当事人应当履行。 当事人对水行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。申请行政复议或者提起行政诉讼的，水行政处罚不停止执行，法律另有规定的除外。 当事人申请行政复议或者提起行政诉讼的，加处罚款的数额在行政复议或者行政诉讼期间不予计算。"},{"i":50,"n":"第五十条","txt":"除当场收缴的罚款外，作出水行政处罚决定的水行政处罚机关及其执法人员不得自行收缴罚款。 当事人应当自收到水行政处罚决定书之日起十五日内，到指定的银行或者通过电子支付系统缴纳罚款。"},{"i":51,"n":"第五十一条","txt":"当场作出水行政处罚决定，依法给予一百元以下罚款或者不当场收缴罚款事后难以执行的，水行政执法人员可以当场收缴罚款。 当事人提出异议的，不停止当场执行。法律、法规另有规定的除外。 在边远、水上、交通不便地区，水行政处罚机关及其水行政执法人员依法作出罚款决定后，当事人到指定银行或者通过电子支付系统缴纳罚款确有困难，经当事人提出，水行政处罚机关及其水行政执法人员可以当场收缴罚款。收缴罚款后应当向被处罚人出具相关凭证。"},{"i":52,"n":"第五十二条","txt":"水行政执法人员当场收缴的罚款，应当自收缴罚款之日起二个工作日内，交至水行政处罚机关；在水上当场收缴的罚款，应当自抵岸之日起二个工作日内交至水行政处罚机关；水行政处罚机关应当在二个工作日内将罚款缴付指定的银行。"},{"i":53,"n":"第五十三条","txt":"当事人确有经济困难，需要延期或者分期缴纳罚款的，应当提出书面申请，经作出水行政处罚决定的水行政处罚机关批准后，可以暂缓或者分期缴纳。"},{"i":54,"n":"第五十四条","txt":"当事人逾期不履行水行政处罚决定的，作出水行政处罚决定的水行政处罚机关可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款，加处罚款的数额不得超出罚款的数额； （二）根据法律规定，将查封、扣押的财物拍卖、依法处理抵缴罚款； （三）根据法律规定，申请人民法院强制执行或者采取其他行政强制执行方式。 水行政处罚机关批准延期、分期缴纳罚款的，申请人民法院强制执行的期限，自暂缓或者分期缴纳罚款期限结束之日起计算。"},{"i":55,"n":"第五十五条","txt":"水行政处罚机关申请人民法院强制执行前，有理由认为被执行人可能逃避执行的，可以申请人民法院采取财产保全措施。"},{"i":56,"n":"第五十六条","txt":"有下列情形之一，水行政执法人员应当制作结案审批表，经水行政处罚机关负责人批准后结案： （一）水行政处罚决定执行完毕的； （二）已经依法申请人民法院强制执行，人民法院依法受理的； （三）决定不予水行政处罚的； （四）案件已经移送管辖并依法受理的； （五）终止调查的； （六）水行政处罚决定被依法撤销的； （七）水行政处罚决定终结执行的； （八）水行政处罚机关认为可以结案的其他情形。"},{"i":57,"n":"第五十七条","txt":"案件承办人员应当在普通程序结案后三十日内，或者简易程序结案后十五日内，将案件材料立卷，并符合下列要求： （一）一案一卷，案卷可以分正卷、副卷； （二）与案件相关的各类文书应当齐全，手续完备； （三）案卷装订应当规范有序，符合档案管理要求。 立卷完成后应当立即统一归档。案卷保管及查阅，按档案管理有关规定执行。任何单位、个人不得非法伪造、涂改、增加、抽取案卷材料。"},{"i":58,"n":"第五十八条","txt":"县级以上人民政府水行政主管部门应当加强水行政执法队伍建设，合理配置与行政处罚职责相适应的执法人员；对水行政处罚权划转或者赋权到综合行政执法的地区，明晰行业监管与综合执法的职责边界，指导和监督综合行政执法部门开展水行政处罚。 县级以上地方人民政府水行政主管部门和流域管理机构应当依法为执法人员办理工伤保险、意外伤害保险；根据执法需要，合理配置执法装备，规划建设执法基地，提升水行政执法信息化水平。县级以上人民政府水行政主管部门应当结合执法实际，将执法装备需求提请本级人民政府纳入财政预算。"},{"i":59,"n":"第五十九条","txt":"水行政处罚机关应当建立健全跨区域联动机制、跨部门联合机制、与刑事司法衔接机制、与检察公益诉讼协作机制，推进涉水领域侵害国家利益或者社会公共利益重大水事案件查处，提升水行政执法效能。"},{"i":60,"n":"第六十条","txt":"水行政处罚机关应当建立健全水行政处罚监督制度，加强对下级水行政处罚机关实施水行政处罚的监督。 水行政处罚权交由乡镇人民政府、街道办事处行使的，县级人民政府水行政主管部门应当加强业务指导和监督，建立健全案件移送和协调协作机制。 对违法情节严重、社会影响恶劣、危害后果严重、涉案人员较多的事件，上级水行政处罚机关应当实行挂牌督办。省际边界重大涉水违法事件由国务院水行政主管部门、违法行为发生地所属流域管理机构或者国务院水行政主管部门指定的流域管理机构挂牌督办。"},{"i":61,"n":"第六十一条","txt":"县级以上人民政府水行政主管部门应当建立健全水行政执法评议制度，定期组织开展水行政执法评议、考核。"},{"i":62,"n":"第六十二条","txt":"水行政处罚机关及其执法人员违法实施水行政处罚的，按照《中华人民共和国行政处罚法》的规定，追究法律责任。"},{"i":63,"n":"第六十三条","txt":"其他行政机关行使水行政处罚职权的，按照本办法的规定执行。"},{"i":64,"n":"第六十四条","txt":"本办法自2023年5月1日起施行。1997年12月26日发布的《水行政处罚实施办法》同时废止。"}],"shuixingzhengxuketingzhengguiding":[{"i":1,"n":"第一条","txt":"为了规范水行政许可听证行为，保障水行政许可行为的合法性、科学性与公正性，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政许可法》、《水行政许可实施办法》等相关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"水行政许可实施机关组织水行政许可听证，适用本规定。法律、法规、规章另有规定的，从其规定。 水行政许可听证由拟作出水行政许可决定的水行政许可实施机关负责组织。"},{"i":3,"n":"第三条","txt":"水行政许可听证应当遵循合法、公开、公平、公正和便民原则，充分听取公民、法人和其他组织的意见，保障其陈述、申辩和质证的权利。"},{"i":4,"n":"第四条","txt":"法律、法规、规章规定实施水行政许可应当听证的事项，水行政许可实施机关在作出水行政许可决定前，应当举行听证。 下列水行政许可事项，水行政许可实施机关在作出水行政许可决定前，认为涉及公共利益需要听证的，应当举行听证： （一）涉及江河、湖泊和地下水资源配置的重大水行政许可事项； （二）涉及水域水生态系统保护的重大水行政许可事项； （三）涉及水工程安全的重大水行政许可事项； （四）涉及防洪安全的重大水行政许可事项； （五）涉及水土流失防治的重大水行政许可事项； （六）涉及不同行政区域边界河段或者跨界河段的重大水行政许可事项； （七）需要听证的其他涉及公共利益的重大水行政许可事项。"},{"i":5,"n":"第五条","txt":"水行政许可事项直接涉及申请人与他人之间重大利益关系的，水行政许可实施机关在作出水行政许可决定前，应当制作听证告知书，告知申请人、利害关系人享有要求听证的权利；申请人或者利害关系人在被告知听证权利之日起五日内要求听证的，应当提交听证申请书；逾期不申请的，视为放弃听证。 听证申请书应当包括以下内容： （一）申请人或者利害关系人的姓名（名称）、地址，法人、其他组织的法定代表人或者主要负责人姓名； （二）申请听证的具体事项和要求； （三）申请听证的依据和理由。 申请听证的申请人或者利害关系人还应当同时提供与申请听证事项相关的材料。"},{"i":6,"n":"第六条","txt":"水行政许可实施机关收到听证申请后，应当在五日内对申请材料进行审查。申请材料不齐备的，应当一次告知申请人、利害关系人需要补正的全部内容；申请材料符合形式和内容要求的，应当自收到申请材料之日起二十日内组织听证。"},{"i":7,"n":"第七条","txt":"水行政许可实施机关根据本规定第四条举行听证的，应当在举行听证二十日前，向社会公告听证内容和听证代表人的报名要求及产生方式，公告期限不得少于五日；公告期限届满后，应当根据公平、公正和公开的原则，兼顾有关各方的合法权益，从自愿报名的个人或者组织中确定听证代表人，听证代表人一般不超过十五名。 根据本规定第五条举行听证，申请听证的申请人或者利害关系人人数众多的，应当推荐听证代表人，听证代表人一般不超过十五名；推荐听证代表人确有困难的，水行政许可实施机关可以与申请人或者利害关系人协商确定听证代表人。"},{"i":8,"n":"第八条","txt":"水行政许可实施机关应当于举行听证的七日前将举行听证的时间、地点、听证主持人和其他听证工作人员名单通知听证参加人。 听证参加人无正当理由不按时参加听证的，或者未经听证主持人允许中途退场的，视为放弃听证。 放弃听证或者被视为放弃听证的，不得就同一事项再次要求听证。"},{"i":9,"n":"第九条","txt":"除涉及国家秘密、商业秘密或者个人隐私的外，听证应当公开举行。 水行政许可实施机关应当于举行听证的三日前，向社会公告，公民、法人或者其他组织的代表持居民身份证可以旁听。"},{"i":10,"n":"第十条","txt":"听证主持人、其他听证工作人员由水行政许可实施机关审查该水行政许可申请的工作人员以外的人员担任，负责听证的主持、记录等组织工作。 涉及重大、复杂或者争议较大的水行政许可事项的听证，可以由水行政许可实施机关法制工作机构的工作人员担任听证主持人。 听证主持人由水行政许可实施机关的负责人指定，其他听证工作人员由听证主持人指定。"},{"i":11,"n":"第十一条","txt":"听证主持人履行下列职责： （一）决定听证的时间、地点，并将听证通知书等材料送达听证参加人； （二）主持听证，维持听证秩序； （三）就听证事项询问听证参加人； （四）听取听证参加人的陈述、申辩； （五）接收并审核有关证据，要求听证参加人提供或者补充证据，决定证人出席作证等； （六）决定听证的延期、中止等程序事项； （七）法律、法规、规章规定的其他职责。"},{"i":12,"n":"第十二条","txt":"听证参加人包括水行政许可审查人、申请人、利害关系人、听证代表人、申请人或者利害关系人的代理人等。 申请人、利害关系人可以委托一至两名代理人参加听证。代理人参加听证的，应当提交由委托人签名或者盖章的授权委托书。授权委托书应当载明委托事项及权限。"},{"i":13,"n":"第十三条","txt":"听证参加人认为听证主持人、其他听证工作人员与该水行政许可事项有直接利害关系的，有权申请其回避；听证主持人、其他听证工作人员也可以自行回避。 听证主持人的回避由水行政许可实施机关的负责人决定，其他听证工作人员的回避由听证主持人决定。"},{"i":14,"n":"第十四条","txt":"听证按照下列程序进行： （一）听证主持人宣布听证事由和听证纪律； （二）听证主持人核实听证参加人的身份，告知听证参加人的权利和义务，询问听证参加人是否申请回避； （三）水行政许可申请的审查人员提出审查意见、理由和证据； （四）水行政许可的申请人、利害关系人、听证代表人或者其代理人发表意见，提出证据； （五）听证参加人各方进行申辩和质证； （六）听证参加人各方做最后陈述； （七）听证主持人宣布听证结束。"},{"i":15,"n":"第十五条","txt":"听证应当制作笔录。听证笔录应当载明下列事项： （一）听证主持人和其他听证工作人员的姓名、职务； （二）听证参加人的姓名（名称）、地址等基本情况； （三）听证的事由、时间和地点； （四）听证参加人提出的意见、理由和证据； （五）听证参加人的申辩、质证和陈述情况； （六）听证延期、中止的说明； （七）听证主持人对听证过程中有关事项的处理情况； （八）其他需要载明的事项。 听证结束前，应当向听证参加人宣读听证笔录或者交其阅读，听证参加人确认无误后签字或者盖章。听证参加人认为笔录有错误或者疏漏的，有权要求改正；听证参加人拒绝签名或者盖章的，应当在听证笔录中载明情况。"},{"i":16,"n":"第十六条","txt":"听证结束后，听证主持人应当就听证情况及审核意见写出听证报告，并与听证笔录一并报水行政许可实施机关；水行政许可实施机关应当根据听证笔录，作出准予水行政许可决定或者不予水行政许可决定，其中应当就听证情况作出专门说明。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，可以延期举行听证： （一）听证参加人提出回避申请理由成立，暂时不能确定听证主持人的； （二）听证参加人在听证过程中提出新的事实、理由和依据，需要调查核实的； （三）听证参加人申请延期，有正当理由的； （四）其他需要延期的情形。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，可以中止听证： （一）申请听证的公民死亡、法人或者其他组织终止，尚未确定其权利、义务承受人的； （二）听证参加人因不可抗力不能参加听证的； （三）应当中止听证的其他情形。"},{"i":19,"n":"第十九条","txt":"听证延期、中止的，应当通知听证参加人。 听证延期、中止的情形消失后，水行政许可实施机关应当在七日内决定恢复听证，并书面通知听证参加人。"},{"i":20,"n":"第二十条","txt":"听证参加人和旁听人应当遵守听证纪律，不得妨碍或者破坏听证秩序。 对违反前款规定的，听证主持人应当予以制止；拒不改正的，可以责令退场。"},{"i":21,"n":"第二十一条","txt":"听证参加人认为听证程序违反《中华人民共和国行政许可法》或者本规定的，可以向听证主持人或者水行政许可实施机关提出，听证主持人或者水行政许可实施机关应当作出相应的答复和说明。"},{"i":22,"n":"第二十二条","txt":"水行政许可实施机关及其工作人员违反本规定，有下列情形之一的，由有关行政机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分： （一）依法应当举行听证而不举行听证的； （二）违反听证程序的； （三）不履行法定告知义务的； （四）听证中的其他违法违纪行为。"},{"i":23,"n":"第二十三条","txt":"组织听证的费用，由水行政许可实施机关承担，申请人、利害关系人和听证代表人不承担听证费用。"},{"i":24,"n":"第二十四条","txt":"本规定自公布之日起施行。"}],"shuixingzhengxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范水行政许可，保护公民、法人和其他组织的合法权益，维护公共利益和社会秩序，保障和监督水行政许可实施机关有效实施水行政管理，根据《中华人民共和国行政许可法》、《中华人民共和国水法》、《中华人民共和国防洪法》、《中华人民共和国水土保持法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称水行政许可，是指水行政许可实施机关根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定水事活动的行为。 本办法所称水行政许可实施机关，是指县级以上人民政府水行政主管部门、法律法规授权的流域管理机构或者其他行使水行政许可权的组织。"},{"i":3,"n":"第三条","txt":"水行政许可的规定、实施和监督检查，适用本办法。 上级水行政主管部门对下级水行政主管部门，以及水行政主管部门对其直接管理的事业单位的人事、财务、外事等事项的审批，不属于水行政许可，不适用本办法。"},{"i":4,"n":"第四条","txt":"实施水行政许可，应当依照有关法律、法规、规章和本办法规定的权限、范围、条件、程序和期限。"},{"i":5,"n":"第五条","txt":"实施水行政许可，应当遵循公开、公平、公正的原则。 水行政许可实施机关应当公布水行政许可的权限、范围、条件、程序和期限等规定；应当公开水行政许可的实施过程和水行政许可决定的内容。但是，涉及国家秘密、商业秘密或者个人隐私的除外。 水行政许可实施机关应当建立核查、回避、听证、科学决策等制度，保障实施水行政许可的公平和公正。符合法定条件、标准的，申请人有依法取得水行政许可的平等权利，水行政许可实施机关不得歧视。"},{"i":6,"n":"第六条","txt":"实施水行政许可，应当遵循便民、高效的原则。 水行政许可实施机关应当精简办事环节，推行便民措施，提高办事效率，提供优质服务。"},{"i":7,"n":"第七条","txt":"实施水行政许可，应当为公民、法人或者其他组织依法行使陈述权、申辩权、损害赔偿权、申请行政复议权提供便利条件。 公民、法人或者其他组织有权就水行政许可的实施情况向有关水行政许可实施机关或者其他机关提出意见、建议、投诉、批评、检举或者控告；水行政许可实施机关应当认真进行审查，发现水行政许可有错的，应当主动改正。"},{"i":8,"n":"第八条","txt":"水行政许可实施机关实施水行政许可，应当自觉接受县级以上人民政府和上级水行政主管部门的监督以及社会监督。 水行政许可实施机关应当对公民、法人或者其他组织从事水行政许可事项的活动实施有效监督。"},{"i":9,"n":"第九条","txt":"在法律、行政法规和国务院决定设定的水行政许可事项范围内，国务院水行政主管部门可以制定规章，对实施该水行政许可的程序、条件、期限、须提交的材料目录等作出具体规定。 水行政许可实施机关可以根据法律、行政法规、国务院决定和有关规章，以规范性文件的形式对水行政许可执行中的具体问题予以明确。 规章和规范性文件对实施上位法规定的行政许可作出的具体规定，不得增设水行政许可和增设违反上位法的其他条件。"},{"i":10,"n":"第十条","txt":"县级以上地方人民政府水行政主管部门或者流域管理机构认为需要增设新的在全国统一实施的水行政许可，或者认为法律、行政法规、国务院决定设定的水行政许可不必要、不合理，需要修改或者废止的，可以向国务院水行政主管部门提出意见和建议。 国务院水行政主管部门认为需要增设新的水行政许可，或者认为法律、行政法规、国务院决定设定的水行政许可不必要、不合理，需要修改或者废止的，可以向国务院提出立法建议。"},{"i":11,"n":"第十一条","txt":"起草法律草案、法规草案和省、自治区、直辖市人民政府规章草案，拟设定水行政许可的，承担起草任务的水行政主管部门应当采取听证会、论证会等形式听取意见，全面评价设定该水行政许可的必要性、可行性、对经济和社会可能产生的影响，并向制定机关说明评价意见以及听取和采纳意见的情况。 水行政许可实施机关应当对水行政许可的实施情况及存在的必要性适时进行评价，并将评价意见报送该水行政许可的设定机关。 水行政许可评价管理办法由国务院水行政主管部门另行制定。"},{"i":12,"n":"第十二条","txt":"水行政许可由县级以上人民政府水行政主管部门在其法定职权范围内实施。 国务院水行政主管部门在国家确定的重要江河、湖泊设立的流域管理机构以及其他法律法规授权的组织，在法律、法规授权范围内，以自己的名义实施水行政许可。 水行政许可实施机关的内设机构不得以自己的名义实施水行政许可。"},{"i":13,"n":"第十三条","txt":"水行政许可实施机关在其法定职权范围内，依照法律、法规、规章的规定，可以委托其他县级以上人民政府水行政主管部门等行政机关实施水行政许可。委托机关应当将受委托机关和受委托实施水行政许可的内容予以公告。 委托机关对受委托机关实施水行政许可的行为应当负责监督，并对该行为的后果承担法律责任。 受委托机关在委托范围内，以委托机关名义实施水行政许可；不得再委托其他组织或者个人实施水行政许可。"},{"i":14,"n":"第十四条","txt":"水行政许可需要水行政许可实施机关内设的多个机构办理的，应当确定一个机构统一受理水行政许可申请、统一送达水行政许可决定，或者设立专门的水行政许可办事机构，集中办理水行政许可事项。"},{"i":15,"n":"第十五条","txt":"水行政许可实施机关的法制工作机构归口管理水行政许可工作。但是，水行政许可实施机关另有规定的除外。"},{"i":16,"n":"第十六条","txt":"水行政许可实施机关的法制工作机构或者其他水行政许可归口管理机构，承办下列事项： （一）组织制订水行政许可制度； （二）审查涉及水行政许可的法律、法规、规章和规范性文件草案； （三）审查和评价水行政许可的设定； （四）指导、协调、监督检查水行政许可的实施情况； （五）承办有关水行政许可的行政复议、行政应诉案件； （六）法律、法规、规章规定和水行政许可实施机关交办的其他水行政许可归口管理工作。"},{"i":17,"n":"第十七条","txt":"公民、法人或者其他组织从事特定水事活动，依法需要取得水行政许可的，应当直接向有水行政许可权的水行政许可实施机关提出申请。但是，本办法第三十三条第二款规定的情形除外。"},{"i":18,"n":"第十八条","txt":"申请水行政许可，可以由申请人到水行政许可实施机关的办公场所，以书面形式提出，也可以通过信函、电报、电传、传真、电子数据交换和电子邮件等方式提出。以电报、电传、传真、电子数据交换和电子邮件等方式提出的，申请人应当自提交申请之日起三日内提供能够证明其申请文件效力的材料；逾期未能提供的，视为放弃本次申请。"},{"i":19,"n":"第十九条","txt":"申请水行政许可，需要使用格式文本的，水行政许可实施机关应当向申请人提供，格式文本中不得包含与申请水行政许可事项没有直接关系的内容。"},{"i":20,"n":"第二十条","txt":"申请人可以委托代理人提出水行政许可申请。但是，依照法律、法规、规章应当由申请人本人到水行政许可实施机关的办公场所提出水行政许可申请的除外。 申请人委托代理人提出水行政许可申请的，应当出具授权委托书。委托人为自然人的，应当在授权委托书上签名；委托人为法人或者其他组织的，应当由法定代表人或者主要负责人在授权委托书上签名并加盖公章。授权委托书应当载明下列事项： （一）委托人和代理人的基本情况； （二）代为提出水行政许可申请、递交有关材料、收受法律文书、接受询问等代理事项和代理权限； （三）代理起止日期。"},{"i":21,"n":"第二十一条","txt":"水行政许可实施机关应当将法律、法规、规章规定的有关水行政许可的事项、依据、条件、数量、程序、期限、需要提交的全部材料的目录、申请书和授权委托书等格式文本及填写说明在办公场所公示。 水行政许可实施机关应当逐步推行电子政务，在网站上公示前款所列事项，为申请人采取数据电文等方式提出水行政许可申请、查询水行政许可办理情况和结果等提供必要便利。 水行政许可实施机关应当根据申请人的要求，对公示内容予以说明、解释。"},{"i":22,"n":"第二十二条","txt":"申请人应当按照有关法律、法规、规章要求如实提交申请书、有关证明文件和其他相关材料，并对其申请材料实质内容的真实性负责。水行政许可实施机关不得要求申请人提交与其申请的水行政许可事项无关的技术资料和其他材料。"},{"i":23,"n":"第二十三条","txt":"水行政许可实施机关收到水行政许可申请后，应当对下列事项进行审查： （一）申请事项是否依法需要取得水行政许可； （二）申请事项是否属于本机关的职权范围； （三）申请人是否具有依法不得提出水行政许可申请的情形； （四）申请材料是否齐全、符合法定形式。"},{"i":24,"n":"第二十四条","txt":"水行政许可实施机关对水行政许可申请审查后，应当根据下列情况分别作出处理： （一）申请事项依法不需要取得水行政许可的，应当即时制作《水行政许可申请不受理告知书》，告知申请人不受理； （二）申请事项依法不属于本机关职权范围或者具有依法不得提出水行政许可申请的情形的，应当即时制作《水行政许可申请不予受理决定书》。其中，申请事项依法不属于本机关职权范围的，应当告知申请人向有关行政机关申请； （三）申请材料存在文字、计算、装订等非实质内容错误的，应当允许申请人当场更正，但应当对更正内容签字或者盖章确认； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在五日内制作《水行政许可申请补正通知书》，一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理； （五）申请事项属于本机关职权范围，申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，应当制作《水行政"},{"i":25,"n":"第二十五条","txt":"省级以上人民政府水行政主管部门可以根据特定水行政许可的特点，规定在本行政区域内，在一定期限内集中受理水行政许可申请，并将受理期限予以公告。 流域管理机构参照前款执行。"},{"i":26,"n":"第二十六条","txt":"流域管理机构可以根据水行政许可的具体情况和便民的需要，委托其所属管理机构或者地方水行政主管部门代为受理水行政许可申请，并予以公告。"},{"i":27,"n":"第二十七条","txt":"水行政许可实施机关受理水行政许可申请后应当进行审查。审查一般以书面形式进行。 除能够当场作出水行政许可决定的外，根据法定条件和程序，需要对申请材料的实质内容进行核查的，应当指派两名以上工作人员进行。核查过程中需要进行现场检查或者调查询问有关人员的，应当制作笔录，由核查方与被核查方签字确认；被核查方拒绝签字的，应当在笔录中记明。"},{"i":28,"n":"第二十八条","txt":"水行政许可实施机关审查水行政许可申请时，发现该水行政许可事项直接关系他人重大利益的，应当告知申请人和利害关系人。其中，对于申请人和能够确定的利害关系人，应当直接送达《水行政许可陈述和申辩告知书》；利害关系人为不确定多数人的，应当公告告知。 告知书或者公告应当确定申请人和利害关系人陈述和申辩的合理期限，并说明该水行政许可的有关情况，但涉及国家秘密、商业秘密或者个人隐私的部分除外。申请人、利害关系人要求陈述和申辩的，应当听取，并制作笔录。申请人、利害关系人提出的事实、理由经审核成立的，应当采纳。"},{"i":29,"n":"第二十九条","txt":"法律、法规、规章规定实施水行政许可应当听证的事项，或者水行政许可实施机关认为需要听证的其他涉及公共利益的重大水行政许可事项，水行政许可实施机关应当向社会公告，并举行听证。 水行政许可直接涉及申请人与他人之间重大利益关系的，水行政许可实施机关在作出水行政许可决定前，应当制作《水行政许可听证告知书》，告知申请人、利害关系人享有要求听证的权利。 水行政许可听证的具体规定由国务院水行政主管部门另行制定。"},{"i":30,"n":"第三十条","txt":"办理水行政许可事项的工作人员是申请人、利害关系人的近亲属，或者与申请人、利害关系人有其他关系，可能影响公正的，应当自行申请回避。 申请人认为办理水行政许可事项的工作人员是水行政许可事项的利害关系人或者是利害关系人的近亲属，或者与利害关系人有其他关系，可能影响公正的，有权申请其回避。 利害关系人认为办理水行政许可事项的工作人员是申请人的近亲属，或者与申请人有其他关系，可能影响公正的，有权申请其回避。 办理水行政许可事项的工作人员的回避由水行政许可实施机关内承办该水行政许可的机构负责人决定，承办机构负责人的回避由水行政许可实施机关负责人决定。"},{"i":31,"n":"第三十一条","txt":"水行政许可实施机关可以根据法律、法规、规章的规定和水行政许可的需要，对水行政许可事项进行专家评审或者技术评估，并将评审或者评估意见作为水行政许可决定的参考依据。 水行政许可实施机关可以根据法律、法规、规章的规定和水行政许可的需要，征求有关水行政主管部门或者其他行政机关的意见。"},{"i":32,"n":"第三十二条","txt":"水行政许可实施机关审查水行政许可申请后，除当场作出水行政许可决定的外，应当在法定期限内按照法律、法规、规章和本办法规定的程序作出如下水行政许可决定： （一）水行政许可申请符合法律、法规、规章规定的条件、标准的，依法作出准予水行政许可的书面决定，制作《准予水行政许可决定书》，并应当在办公场所、指定报刊或者网站上公开，公众有权查阅； （二）水行政许可申请不符合法律、法规、规章规定的条件、标准的，依法作出不予水行政许可的书面决定，制作《不予水行政许可决定书》，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利和复议机关、受诉法院、时效等具体事项。"},{"i":33,"n":"第三十三条","txt":"除可以当场作出水行政许可决定的外，水行政许可实施机关应当自受理水行政许可申请之日起二十日内作出水行政许可决定。因水行政许可事项重大、复杂或者具有其他正当理由，二十日内不能作出决定的，经本机关负责人批准，可以延长十日，并应当制作《水行政许可延期告知书》，将延长期限的理由告知申请人。 依照法律、法规、规章规定，应当先经下级水行政许可实施机关审查后，报送上级水行政许可实施机关决定的水行政许可，下级水行政许可实施机关应当按照本办法的规定受理和审查，并应当自受理之日起二十日内将审查意见和全部申请材料，直接报送上级水行政许可实施机关审查决定。上级水行政许可实施机关不得要求申请人重复提供申请材料，并应当自收到下级水行政许可实施机关报送的初步审查意见和全部申请材料之日起二十日内作出水行政许可决定。 法律、法规对水行政许可期限另有规定的，依照其规定。"},{"i":34,"n":"第三十四条","txt":"申请人在水行政许可实施机关作出水行政许可决定之前，可以书面申请撤回水行政许可申请。"},{"i":35,"n":"第三十五条","txt":"水行政许可实施机关作出准予水行政许可的决定，需要颁发水行政许可证件、证书的，应当自作出水行政许可决定之日起十日内向申请人颁发、送达。"},{"i":36,"n":"第三十六条","txt":"水行政许可实施机关作出水行政许可决定，依法需要听证、招标、拍卖、检验、检测、鉴定、评估和专家评审的，所需时间不计算在本办法规定的期限内，但应当制作《水行政许可除外时间告知书》，将所需时间书面告知申请人。"},{"i":37,"n":"第三十七条","txt":"水行政许可的适用范围没有地域限制的，申请人取得的水行政许可在全国范围内有效；水行政许可的适用范围有地域限制的，《准予水行政许可决定书》或者水行政许可证件、证书上应当注明。 水行政许可有期限的，《准予水行政许可决定书》或者水行政许可证件、证书上应当注明其有效期限。"},{"i":38,"n":"第三十八条","txt":"水行政许可实施机关应当依照民事诉讼法的有关规定，送达水行政许可法律文书、证件和证书。"},{"i":39,"n":"第三十九条","txt":"被许可人在取得水行政许可后，因姓名（名称）、住所、法定代表人（主要负责人）等发生变化，要求变更水行政许可事项的，应当向作出水行政许可决定的水行政许可实施机关提出变更申请，并提交有关证明文件。 水行政许可实施机关应当对变更申请进行审查，并于收到变更申请之日起十日内作出决定。符合法定条件、标准的，应当准予变更，制作《准予变更水行政许可决定书》，并依法办理变更手续；因有关事项的变更，会导致被许可人不再符合法律、法规、规章规定的准予水行政许可的条件、标准的，水行政许可实施机关不得准予变更，并制作《不予变更水行政许可决定书》。 依法取得的水行政许可，不得转让。法律、法规另有规定的除外。"},{"i":40,"n":"第四十条","txt":"被许可人需要延续依法取得的水行政许可的有效期限的，应当在该水行政许可有效期届满三十日前向作出水行政许可决定的水行政许可实施机关提出申请。但是，法律、法规、规章另有规定的，依照其规定。 水行政许可实施机关对延续申请进行审查后，应当作出决定。仍符合取得水行政许可的条件的，准予延续，制作《准予延续水行政许可决定书》；不再符合取得水行政许可的条件的，不予延续，制作《不予延续水行政许可决定书》。 前款决定应当在该水行政许可有效期届满前作出；逾期未作决定的，视为准予延续。"},{"i":41,"n":"第四十一条","txt":"水行政许可实施机关不得擅自改变已经生效的水行政许可。 水行政许可所依据的法律、法规、规章修改或者废止，或者准予水行政许可所依据的客观情况发生重大变化的，为了公共利益的需要，水行政许可实施机关可以依法变更或者撤回已经生效的水行政许可。由此给公民、法人或者其他组织造成财产损失的，应当依法给予补偿。"},{"i":42,"n":"第四十二条","txt":"水行政许可实施机关实施水行政许可和对水行政许可事项进行监督检查，不得收取任何费用。但是，法律、行政法规另有规定的，依照其规定。 水行政许可实施机关提供水行政许可申请书等格式文本，不得收费。 水行政许可实施机关实施水行政许可所需经费，应当列入本机关年度预算，实行预算管理。"},{"i":43,"n":"第四十三条","txt":"水行政许可实施机关实施水行政许可，依照法律、行政法规收取费用的，应当按照公布的法定项目和标准收费；所收取的费用必须全部上缴国库，不得以任何形式截留、挪用、私分或者变相私分。"},{"i":44,"n":"第四十四条","txt":"上级水行政主管部门应当采取执法检查、处理投诉、责任追究或者个案督办等方式加强对下级水行政许可实施机关实施水行政许可的监督检查，及时纠正水行政许可实施中的违法行为。"},{"i":45,"n":"第四十五条","txt":"水行政许可实施机关应当建立健全监督制度，按照管理权限和职责分工，对公民、法人或者其他组织从事水行政许可事项的活动履行监督检查责任。 省、自治区、直辖市人民政府水行政主管部门应当依法明确本行政区域内各级水行政主管部门的具体监督检查职责，流域管理机构应当依法明确其下属管理机构的具体监督检查职责。"},{"i":46,"n":"第四十六条","txt":"监督检查一般采用核查反映被许可人从事水行政许可事项活动情况的有关材料进行。可以根据监督检查的需要对被许可人生产经营场所依法进行实地检查。检查时，可以依法查阅或者要求被许可人报送有关材料；被许可人应当如实提供有关情况和材料。 水行政许可实施机关依法实施监督检查时，应当将监督检查的情况和处理结果予以记录，由监督检查人员签字后归档，公众有权查阅。"},{"i":47,"n":"第四十七条","txt":"水行政许可实施机关实施监督检查，不得妨碍被许可人正常的生产经营活动，不得索取或者收受被许可人的财物，不得谋取其他利益，并应当保守与此有关的国家秘密、商业秘密和个人隐私。"},{"i":48,"n":"第四十八条","txt":"被许可人在作出水行政许可决定的水行政许可实施机关管辖区域外违法从事水行政许可事项活动的，由违法行为发生地的水行政许可实施机关按照管辖权限依法进行处理，并于五日内将被许可人的违法事实、处理结果抄告作出水行政许可决定的水行政许可实施机关。"},{"i":49,"n":"第四十九条","txt":"任何个人和组织发现违法从事水行政许可事项的活动，有权向水行政许可实施机关举报，水行政许可实施机关应当及时核实、处理。"},{"i":50,"n":"第五十条","txt":"有下列情形之一的，作出水行政许可决定的水行政许可实施机关，或者其上级水行政主管部门，根据利害关系人的请求或者依据职权，可以撤销水行政许可： （一）水行政许可实施机关工作人员滥用职权、玩忽职守作出准予水行政许可决定的； （二）超越法定职权作出准予水行政许可决定的； （三）违反法定程序作出准予水行政许可决定的； （四）对不具备申请资格或者不符合法定条件的申请人准予水行政许可的； （五）依照法律、法规、规章可以撤销水行政许可的其他情形。 被许可人以欺骗、贿赂等不正当手段取得水行政许可的，应当予以撤销。 依照前两款的规定撤销水行政许可，可能对公共利益造成重大损害的，不予撤销。 依照本条第一款的规定撤销水行政许可，被许可人的合法权益受到损害的，应当依法给予赔偿。依照本条第二款的规定撤销水行政许可的，被许可人基于水行政许可取得的利益不受保护。"},{"i":51,"n":"第五十一条","txt":"有下列情形之一的，水行政许可实施机关应当依法办理有关水行政许可的注销手续： （一）水行政许可有效期届满未申请延续或者未获准延续的； （二）赋予公民特定资格的水行政许可，该公民死亡或者丧失行为能力的； （三）法人或者其他组织依法终止的； （四）水行政许可依法被撤销、撤回，或者水行政许可证件、证书等依法被吊销的； （五）因不可抗力导致水行政许可事项无法实施的； （六）法律、法规规定的应当注销水行政许可的其他情形。"},{"i":52,"n":"第五十二条","txt":"县级以上地方人民政府水行政主管部门，违反《行政许可法》第十七条规定设定水行政许可的，有关机关应当责令其限期改正或者依法予以撤销。 流域管理机构有前款行为的，由国务院水行政主管部门依照前款处理。"},{"i":53,"n":"第五十三条","txt":"水行政许可实施机关及其工作人员违法实施水行政许可的，依照《行政许可法》第七十二条、第七十三条、第七十四条、第七十五条、第七十七条规定予以处理。"},{"i":54,"n":"第五十四条","txt":"水行政许可实施机关违法实施水行政许可，给当事人的合法权益造成损害的，应当依照国家赔偿法的规定给予赔偿。 水行政许可实施机关因违法实施水行政许可承担赔偿责任的，可以责令有故意或者重大过失的主管人员以及直接责任人员承担部分或者全部赔偿费用。"},{"i":55,"n":"第五十五条","txt":"水行政许可申请人隐瞒有关情况或者提供虚假材料申请水行政许可的，水行政许可实施机关应当不予受理或者不予水行政许可，并给予警告；水行政许可申请属于直接关系防洪安全、水利工程安全、水生态环境安全、人民群众生命财产安全事项的，申请人在一年内不得再次申请该水行政许可。"},{"i":56,"n":"第五十六条","txt":"被许可人以欺骗、贿赂等不正当手段取得水行政许可的，除可能对公共利益造成重大损害的，水行政许可实施机关应当予以撤销，并给予警告。被许可人从事非经营活动的，可以处一千元以下罚款；被许可人从事经营活动，有违法所得的，可以处违法所得三倍以下罚款，但是最高不得超过三万元，没有违法所得的，可以处一万元以下罚款，法律、法规另有规定的除外。取得的水行政许可属于直接关系防洪安全、水利工程安全、水生态环境安全、人民群众生命财产安全事项的，申请人在三年内不得再次申请该水行政许可；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"被许可人有《行政许可法》第八十条规定的行为之一的，水行政许可实施机关根据情节轻重，应当给予警告或者降低水行政许可资格（质）等级。被许可人从事非经营活动的，可以处一千元以下罚款；被许可人从事经营活动，有违法所得的，可以处违法所得三倍以下罚款，但是最高不得超过三万元，没有违法所得的，可以处一万元以下罚款，法律、法规另有规定的除外；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"公民、法人或者其他组织未经水行政许可，擅自从事依法应当取得水行政许可的活动的，水行政许可实施机关应当责令停止违法行为，并给予警告。当事人从事非经营活动的，可以处一千元以下罚款；当事人从事经营活动，有违法所得的，可以处违法所得三倍以下罚款，但是最高不得超过三万元，没有违法所得的，可以处一万元以下罚款，法律、法规另有规定的除外；构成犯罪的，依法追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"本办法规定的水行政许可实施机关实施水行政许可的期限以工作日计算，不含法定节假日。"},{"i":60,"n":"第六十条","txt":"水行政许可法律文书示范格式文本由国务院水行政主管部门另行制定。"},{"i":61,"n":"第六十一条","txt":"本办法由国务院水行政主管部门负责解释。"},{"i":62,"n":"第六十二条","txt":"本办法自发布之日起施行。"}],"shuiliangfenpeizanxingbanfa":[{"i":1,"n":"第一条","txt":"为实施水量分配，促进水资源优化配置，合理开发、利用和节约、保护水资源，根据《中华人民共和国水法》，制定本办法。"},{"i":2,"n":"第二条","txt":"水量分配是对水资源可利用总量或者可分配的水量向行政区域进行逐级分配，确定行政区域生活、生产可消耗的水量份额或者取用水水量份额（以下简称水量份额）。 水资源可利用总量包括地表水资源可利用量和地下水资源可开采量，扣除两者的重复量。地表水资源可利用量是指在保护生态与环境和水资源可持续利用的前提下，通过经济合理、技术可行的措施，在当地地表水资源中可供河道外消耗利用的最大水量；地下水资源可开采量是指在可预见的时期内，通过经济合理、技术可行的措施，在不引起生态与环境恶化的条件下，以凿井的方式从地下含水层中获取的可持续利用的水量。 可分配的水量是指在水资源开发利用程度已经很高或者水资源丰富的流域和行政区域或者水流条件复杂的河网地区以及其他不适合以水资源可利用总量进行水量分配的流域和行政区域，按照方便管理、利于操作和水资源节约与保护、供需协调的原则，统筹考虑生活、生产和生态与环境用水，确定的用于分配的"},{"i":3,"n":"第三条","txt":"本办法适用于跨省、自治区、直辖市的水量分配和省、自治区、直辖市以下其他跨行政区域的水量分配。 跨省、自治区、直辖市的水量分配是指以流域为单元向省、自治区、直辖市进行的水量分配。省、自治区、直辖市以下其他跨行政区域的水量分配是指以省、自治区、直辖市或者地市级行政区域为单元，向下一级行政区域进行的水量分配。 国际河流（含跨界、边界河流和湖泊）的水量分配不适用本办法。"},{"i":4,"n":"第四条","txt":"跨省、自治区、直辖市的水量分配方案由水利部所属流域管理机构（以下简称流域管理机构）商有关省、自治区、直辖市人民政府制订，报国务院或者其授权的部门批准。 省、自治区、直辖市以下其他跨行政区域的水量分配方案由共同的上一级人民政府水行政主管部门商有关地方人民政府制订，报本级人民政府批准。 经批准的水量分配方案需修改或调整时，应当按照方案制定程序经原批准机关批准。"},{"i":5,"n":"第五条","txt":"水量分配应当遵循公平和公正的原则，充分考虑流域与行政区域水资源条件、供用水历史和现状、未来发展的供水能力和用水需求、节水型社会建设的要求，妥善处理上下游、左右岸的用水关系，协调地表水与地下水、河道内与河道外用水，统筹安排生活、生产、生态与环境用水。"},{"i":6,"n":"第六条","txt":"水量分配应当以水资源综合规划为基础。 尚未制定水资源综合规划的，可以在进行水资源及其开发利用的调查评价、供需水预测和供需平衡分析的基础上，进行水量分配试点工作。跨省、自治区、直辖市河流的试点方案，经流域管理机构审查，报水利部批准；省、自治区、直辖市境内河流的试点方案，经流域管理机构审核后，由省级水行政主管部门批准。水资源综合规划制定或者本行政区域的水量份额确定后，试点水量分配方案不符合要求的，应当及时进行调整。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市人民政府公布的行业用水定额是本行政区域实施水量分配的重要依据。 流域管理机构在制订流域水量分配方案时，可以结合流域及各行政区域用水实际和经济技术条件，考虑先进合理的用水水平，参考流域内有关省、自治区、直辖市的用水定额标准，经流域综合协调平衡，与有关省、自治区、直辖市人民政府协商确定行政区域水量份额的核算指标。"},{"i":8,"n":"第八条","txt":"为满足未来发展用水需求和国家重大发展战略用水需求，根据流域或者行政区域的水资源条件，水量分配方案制订机关可以与有关行政区域人民政府协商预留一定的水量份额。预留水量的管理权限，由水量分配方案批准机关决定。 预留水量份额尚未分配前，可以将其相应的水量合理分配到年度水量分配方案和调度计划中。"},{"i":9,"n":"第九条","txt":"水量分配应当建立科学论证、民主协商和行政决策相结合的分配机制。 水量分配方案制订机关应当进行方案比选，广泛听取意见，在民主协商、综合平衡的基础上，确定各行政区域水量份额和相应的流量、水位、水质等控制性指标，提出水量分配方案，报批准机关审批。"},{"i":10,"n":"第十条","txt":"水量分配方案包括以下主要内容： （一）流域或者行政区域水资源可利用总量或者可分配的水量。 （二）各行政区域的水量份额及其相应的河段、水库、湖泊和地下水开采区域。 （三）对应于不同来水频率或保证率的各行政区域年度用水量的调整和相应调度原则。 （四）预留的水量份额及其相应的河段、水库、湖泊和地下水开采区域。 （五）跨行政区域河流、湖泊的边界断面流量、径流量、湖泊水位、水质，以及跨行政区域地下水水源地地下水水位和水质等控制指标。"},{"i":11,"n":"第十一条","txt":"各行政区域使用跨行政区域河流、湖泊和地下水水源地的水量通过河流的边界断面流量、径流量和湖泊水位以及地下水水位监控。监测水量或者水位的同时，应当监测水体的水质。"},{"i":12,"n":"第十二条","txt":"流域管理机构或者县级以上地方人民政府水行政主管部门应当根据批准的水量分配方案和年度预测来水量以及用水需求，结合水工程运行情况，制定年度水量分配方案和调度计划，确定用水时段和用水量，实施年度总量控制和水量统一调度。 当出现旱情紧急情况或者其他突发公共事件时，应当按照经批准的旱情紧急情况下的水量调度预案或者突发公共事件应急处置预案进行调度或处置。"},{"i":13,"n":"第十三条","txt":"为预防省际水事纠纷的发生，在省际边界河流、湖泊和跨省、自治区、直辖市河段的取用水量，由流域管理机构会同有关省、自治区、直辖市人民政府水行政主管部门根据批准的水量分配方案和省际边界河流（河段、湖泊）水利规划确定，并落实调度计划、计量设施以及监控措施。 跨省、自治区、直辖市地下水水源地的取用水量，由流域管理机构会同有关省、自治区、直辖市人民政府水行政主管部门根据批准的水量分配方案和省际边界地区地下水开发利用规划确定，并落实开采计划、计量设施以及监控措施。"},{"i":14,"n":"第十四条","txt":"流域管理机构和各级水行政主管部门应当加强水资源管理监控信息系统建设，提高水量、水质监控信息采集、传输的时效性，保障水量分配方案的有效实施。"},{"i":15,"n":"第十五条","txt":"已经实施或者批准的跨流域调水工程调入的水量，按照规划或者有关协议实施分配。"},{"i":16,"n":"第十六条","txt":"流域管理机构和各省、自治区、直辖市人民政府水行政主管部门可以根据本办法制定实施细则，报水利部备案。"},{"i":17,"n":"第十七条","txt":"本办法自2008年2月1日起施行。"}],"hedaoguanlifanweineijianshexiangmuguanlideyouguang7c5f8e":[{"i":1,"n":"第一条","txt":"为加强在河道管理范围内进行建设的管理，确保江河防洪安全，保障人民生命财产安全和经济建设的顺利进行，根据《中华人民共和国水法》和《中华人民共和国河道管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在河道（包括河滩地、湖泊、水库、人工水道、行洪区、蓄洪区、滞洪区）管理范围内新建、扩建、改建的建设项目，包括开发水利（水电）、防治水害、整治河道的各类工程，跨河、穿河、穿堤、临河的桥梁、码头、道路、渡口、管道、缆线、取水口、排污口等建筑物，厂房、仓库、工业和民用建筑以及其它公共设施（以下简称建设项目）。"},{"i":3,"n":"第三条","txt":"河道管理范围内的建设项目，必须按照河道管理权限，经河道主管机关审查同意后，方可开工建设。 以下河道管理范围内的建设项目由水利部所属的流域机构（以下简称流域机构）实施管理，或者由所在的省、自治区、直辖市的河道主管机关根据流域统一规划实施管理： （一）在长江、黄河、松花江、辽河、海河、淮河、珠江主要河段的河道管理范围内兴建的大中型建设项目，主要河段的具体范围由水利部划定； （二）在省际边界河道和国境边界的河道管理范围内兴建的建设项目； （三）在流域机构直接管理的河道、水库、水域管理范围内兴建的建设项目； （四）在太湖、洞庭湖、鄱阳湖、洪泽湖等大湖、湖滩地兴建的建设项目。 其它河道范围内兴建的建设项目由地方各级河道主管机关实施分级管理。分级管理的权限由省、自治区、直辖市水行政主管部门会同计划主管部门规定。"},{"i":4,"n":"第四条","txt":"河道管理范围内建设项目必须符合国家规定的防洪标准和其它技术要求，维护堤防安全，保持河势稳定和行洪、航运通畅。 蓄滞洪区、行洪区内建设项目还应符合《蓄滞洪区安全与建设指导纲要》的有关规定。"},{"i":5,"n":"第五条","txt":"建设单位编制立项文件时必须按照河道管理权限，向河道主管机关提出申请，申请时应提供以下文件： （1）申请书； （2）建设项目所依据的文件； （3）建设项目涉及河道与防洪部分的初步方案； （4）占用河道管理范围内土地情况及该建设项目防御洪涝的设防标准与措施； （5）说明建设项目对河势变化、堤防安全，河道行洪、河水水质的影响以及拟采取的补救措施。 对于重要的建设项目，建设单位还应编制更详尽的防洪评价报告。"},{"i":6,"n":"第六条","txt":"河道主管机关接到申请后，应及时进行审查，审查主要内容为： （1）是否符合江河流域综合规划和有关的国土及区域发展规划，对规划实施有何影响； （2）是否符合防洪标准和有关技术要求； （3）对河势稳定、水流形态、水质、冲淤变化有无不利影响； （4）是否防碍行洪、降低河道泄洪能力； （5）对堤防、护岸和其它水工程安全的影响； （6）是否妨碍防汛抢险； （7）建设项目防御洪涝的设防标准与措施是否适当； （8）是否影响第三人合法的水事权益； （9）是否符合其它有关规定和协议。 流域机构在对重大建设项目进行审查时，还应征求有关省、自治区、直辖市的意见。"},{"i":7,"n":"第七条","txt":"河道主管机关应在法定期限内将审查意见书面通知申请单位，同意兴建的，应发给审查同意书，并抄知上级水行政主管部门和建设单位的上级主管部门。建设单位在取得河道主管机关的审查同意书后，方可开工建设。 审查同意书可以对建设项目设计、施工和管理提出有关要求。"},{"i":8,"n":"第八条","txt":"河道主管机关对建设单位的申请进行审查后，作出不同意建设的决定，或者要求就有关问题进一步修改补充后再行审查的，应当在批复中说明理由和依据。建设单位对批复持有异议的，可依法提出行政复议申请。"},{"i":9,"n":"第九条","txt":"计划主管部门在审批项目时，如对建设项目的性质、规模、地点作较大变动时，应事先征得河道主管机关的同意。建设单位应重新办理审查同意书。"},{"i":10,"n":"第十条","txt":"建设项目开工前，建设单位应当将施工安排送河道主管机关备案。施工安排应包括施工占用河道管理范围内土地的情况和施工期防汛措施。"},{"i":11,"n":"第十一条","txt":"建设项目施工期间，河道主管机关应对其是否符合同意书要求进行检查，被检查单位应如实提供情况。如发现未按审查同意书或经审核的施工安排的要求进行施工的，或者出现涉及江河防洪与建设项目防汛安全方面的问题，应及时提出意见，建设单位必须执行；遇重大问题，应同时抄报上级水行政主管部门。"},{"i":12,"n":"第十二条","txt":"河道管理范围内的建筑物和设施竣工后，应经河道主管机关检验合格后方可启用。建设单位应在竣工验收6个月内向河道主管机关报送有关竣工资料。"},{"i":13,"n":"第十三条","txt":"河道主管机关应定期对河道管理范围内的建筑物和设施进行检查，凡不符合工程安全要求的，应提出限期改建的要求，有关单位和个人应当服从河道主管机关的安全管理。"},{"i":14,"n":"第十四条","txt":"未按本规定的规定在河道管理范围内修建建设项目的，县级以上地方人民政府河道主管机关可根据《河道管理条例》责令其停止建设、限期拆除或采取其它补救措施，可并处1万元以下罚款。"},{"i":15,"n":"第十五条","txt":"本规定由水利部负责解释。"}],"hedaocaishashoufeiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强河道的整治和管理，合理采挖河道砂石，依据《中华人民共和国河道管理条例》第四十条规定制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称河道采砂是指在河道管理范围内的采挖砂、石，取土和淘金（包括淘金其它金属及非金属）。"},{"i":3,"n":"第三条","txt":"河道采砂必须服从河道整治规划。河道采砂实行许可证制度，按河道管理权限实行管理。河道采砂许可证由省级水利部门与同级财政部门统一印制，由所在河道主管部门或由其授权的河道管理单位负责发放。"},{"i":4,"n":"第四条","txt":"采砂单位或个人必须提出河道采砂申请书，说明采砂范围和作业方式，报经所在河道主管部门审批，在领取河道采砂许可证后方可开采。从事淘金和营业性采砂取土的，在获准许可后，还应按当地工商、物价、税务部门的有关规定办理。"},{"i":5,"n":"第五条","txt":"河道采砂必须交纳河道采砂管理费。"},{"i":6,"n":"第六条","txt":"河道采砂管理费的计收： （一）由发放河道采砂许可证的单位计收采砂管理费。 （二）河道采砂管理费的收费标准由各省、自治区、直辖市水利部门报同级物价、财政部门核定。收费单位应按规定向当地物价部门申请收费许可证，并使用财政部门统一印制的收费票据。"},{"i":7,"n":"第七条","txt":"河道采砂管理费用于河道与堤防工程的维修、工程设施的更新改造及管理单位的管理费。结余资金可以连年结转，继续使用，其它任何部门不得截留或挪用。"},{"i":8,"n":"第八条","txt":"河道主管单位要加强财务及收费管理，建立健全财务制度，收好、管好、用好河道采砂管理费。河道采砂管理费按预算外资金管理，专款专用，专户存储。各级财政、物价和水利部门要负责监督检查各项财务制度的执行情况和资金使用效果。"},{"i":9,"n":"第九条","txt":"违反本办法第三、四、五条规定的，按《河道管理条例》第四十四条规定办理。"},{"i":10,"n":"第十条","txt":"河道管理、监理人员在河道采砂收费管理中，滥用职权、徇私舞弊、收受贿赂的，按《河道管理条例》第四十八条规定办理。"},{"i":11,"n":"第十一条","txt":"各省、自治区、直辖市水利部门可以根据本办法的规定，结合实际情况，商同级财政、物价部门制定本地区河道采砂收费管理实施细则。"},{"i":12,"n":"第十二条","txt":"本办法由水利部负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自公布之日起施行。"}],"haiheduliujianheyongdingxinhehekouguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强海河流域海河、独流减河、永定新河入海河口的管理，维护河口的行洪、排涝和纳潮等功能，保障海河流域中下游地区防洪安全，促进河口地区经济社会的可持续发展，根据《中华人民共和国水法》、《中华人民共和国防洪法》和《中华人民共和国河道管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在海河、独流减河、永定新河入海河口（以下称三河口）管理范围内进行治理、开发、保护和管理活动，适用本办法。"},{"i":3,"n":"第三条","txt":"三河口的治理、开发和保护，应当遵循统一规划、综合整治、兴利与除害相结合的原则，保障行洪排涝畅通，维护潮汐吞吐，改善生态环境。"},{"i":4,"n":"第四条","txt":"海河水利委员会负责三河口治理、开发和保护活动的统一监督管理。 天津市人民政府水行政主管部门按照本办法规定的权限，负责永定新河河口治理、开发和保护活动的监督管理。"},{"i":5,"n":"第五条","txt":"三河口综合整治规划是三河口治理、开发、保护和管理的基本依据。 三河口综合整治规划需要修改时，必须按照规定的程序经原批准机关批准。 三河口管理范围内的港区建设、航道整治、滩涂开发、铁路、公路、水产养殖等专业规划，应当与三河口综合整治规划相衔接。"},{"i":6,"n":"第六条","txt":"三河口规划治导线是三河口整治与开发工程建设的外缘控制线，除河口整治水利工程外，其他工程建设不得超越规划治导线。 整治河口和修建控制引导河水流向、保护堤岸等工程，应当按照规划治导线实施，不得任意改变河水流向。 规划治导线确需调整的，必须经科学论证，并按照规定的程序经原批准机关批准。"},{"i":7,"n":"第七条","txt":"根据三河口综合整治规划，三河口管理范围为： （一）海河河口管理范围： 1．纵向为海河防潮闸闸上500米至闸下14300米，横向闸上以河道两岸防洪墙为界，闸下以规划治导线为界，有导堤的以导堤外坡脚线以外15米为界； 2．河口防洪清淤排泥场以围堤外坡脚线以外15米为界； 3．河口疏浚工作场地。 （二）独流减河河口管理范围： 1．纵向为独流减河防潮闸闸上500米至闸下9000米，横向闸上以河道两岸堤防外坡脚线以外30米为界，闸下左侧3080米以上以左堤为界，3080米以下至9000米以规划治导线以外200米为界，闸下右侧2965米以上以右堤外坡脚线以外30米、海挡和大港分洪道南堤及其延长线为界，2965米以下至9000米以规划治导线以外2500米为界； 2．河口防洪清淤排泥场以围堤外坡脚线以外15米为界； 3．河口疏浚工作场地。 （三）永定新河河口管理范围： 1．纵向为永定新河防潮闸闸上50"},{"i":8,"n":"第八条","txt":"在三河口管理范围内，新建、扩建、改建以及调整原有功能的水工程的，应当由海河水利委员会按照水工程建设规划同意书制度的有关规定审查并签署水工程建设规划同意书，并实施监督管理。 前款所称水工程，是指水库、拦河闸坝、引（调、提）水工程、堤防、水电站（含航运水电枢纽工程）等开发、利用、控制、调配和保护水资源的各类工程。"},{"i":9,"n":"第九条","txt":"在海河和独流减河的河口管理范围内，新建、扩建、改建跨河、穿河、穿堤、临河的桥梁、码头、道路、输送带、渡口、管道、缆线、排污口、海岸防护整治工程等工程设施的，由海河水利委员会按照河道管理范围内建设项目管理等有关规定审查同意并实施监督管理。 在永定新河的河口管理范围内，新建、扩建、改建前款所列大中型工程设施的，经天津市人民政府水行政主管部门提出意见后，由海河水利委员会按照河道管理范围内建设项目管理等有关规定审查同意并实施监督管理；前款所列的其他工程设施，由天津市人民政府水行政主管部门按照河道管理范围内建设项目管理等有关规定审查同意并实施监督管理，并报海河水利委员会备案。"},{"i":10,"n":"第十条","txt":"在三河口管理范围内，进行城市建设、工业、交通、港区生产运营、石油开采、盐业、农业、渔业、旅游、滩涂开发等有关活动，必须符合三河口综合整治规划，不得妨碍行洪、排涝、纳潮和河口整治水利工程建设与管理。"},{"i":11,"n":"第十一条","txt":"在三河口管理范围内，从事各种开发利用活动造成河口淤积或者行洪障碍，影响河口行洪、排涝和纳潮的，有关单位或者个人应当承担清淤或者清除责任。 三河口管理范围内已修建的本办法第九条所列的工程设施，对河口行洪、排涝和纳潮有不利影响的，建设单位或者个人应当采取补救措施；必要时，建设单位或者个人应当按照海河水利委员会或者天津市人民政府水行政主管部门的要求，进行改建或者拆除。"},{"i":12,"n":"第十二条","txt":"防洪清淤排泥场需要占用的土地，由所在地的县级以上地方人民政府依照有关法律法规的规定解决。"},{"i":13,"n":"第十三条","txt":"任何单位和个人不得侵占防洪清淤排泥场用地，破坏清淤工程设施。 需要开发利用海河河口和独流减河河口防洪清淤排泥场的，必须经海河水利委员会同意；需要开发利用永定新河河口防洪清淤排泥场的，必须经天津市人民政府水行政主管部门同意。"},{"i":14,"n":"第十四条","txt":"在三河口管理范围内禁止下列活动： （一）修建围堤、阻水渠道、阻水道路； （二）种植阻碍行洪的林木和高秆作物； （三）弃置矿渣、石渣、煤灰、泥土、垃圾等； （四）在堤防和护堤地上建房、开渠、打井、挖窖、葬坟、存放物料、开采地下资源、进行考古发掘以及开展集市贸易等活动； （五）损坏闸坝和堤防上的设施、标志桩、水文和测量标志、通信设施等。"},{"i":15,"n":"第十五条","txt":"在海河河口和独流减河河口管理范围内进行下列活动，应当报经海河水利委员会批准；在永定新河河口管理范围内进行下列活动，应当报经天津市人民政府水行政主管部门批准： （一）采砂、取土、爆破、钻探、弃置砂石或者淤泥、挖筑鱼塘； （二）在河口滩地和滩涂上存放物料、修建厂房或者其他建筑设施； （三）在河口滩地和滩涂上开渠，开采地下资源及进行考古发掘。"},{"i":16,"n":"第十六条","txt":"在三河口地区开采地下水，应当经过科学论证，并采取措施，防止地面沉降和海水入侵。"},{"i":17,"n":"第十七条","txt":"三河口整治与建设，应当符合三河口综合整治规划和国家规定的防洪等有关技术要求。"},{"i":18,"n":"第十八条","txt":"海河水利委员会和天津市人民政府水行政主管部门应当根据三河口综合整治规划，按照规定的权限分别对三河口进行清淤疏浚，维持行洪、排涝和纳潮畅通。 防洪清淤排泥场和导堤建设工程应当纳入国家基本建设计划，由海河水利委员会和天津市人民政府水行政主管部门按照基本建设程序和规定的权限组织实施。"},{"i":19,"n":"第十九条","txt":"海河水利委员会管理的河口整治水利工程的维修养护经费，按照国务院办公厅转发的《水利工程管理体制改革实施意见》的规定筹集。 天津市人民政府水行政主管部门管理的河口整治水利工程的维修养护经费，按照国务院办公厅转发的《水利工程管理体制改革实施意见》及天津市人民政府的有关规定筹集。"},{"i":20,"n":"第二十条","txt":"违反本办法第六条规定，未按照规划治导线整治河口和修建控制引导河水流向、保护堤岸等工程，影响防洪的，由海河水利委员会或者天津市人民政府水行政主管部门依照《中华人民共和国防洪法》的有关规定采取行政措施，并给予行政处罚。"},{"i":21,"n":"第二十一条","txt":"违反本办法第八条规定，未取得水工程建设规划同意书，在三河口管理范围内擅自建设水工程，或者违反水工程建设规划同意书的要求建设水工程的，由海河水利委员会依照《中华人民共和国水法》和《中华人民共和国防洪法》的有关规定采取行政措施，并给予行政处罚。"},{"i":22,"n":"第二十二条","txt":"违反本办法第九条规定，未经海河水利委员会或者天津市人民政府水行政主管部门对其工程建设方案审查同意，或者未按照审查批准的位置、界限，在三河口管理范围内从事工程设施建设活动的，由海河水利委员会或者天津市人民政府水行政主管部门依照《中华人民共和国水法》和《中华人民共和国防洪法》的有关规定采取行政措施，并给予行政处罚。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十三条规定，侵占防洪清淤排泥场用地，破坏清淤工程设施的，由海河水利委员会或者天津市人民政府水行政主管部门依照《中华人民共和国水法》和《中华人民共和国防洪法》的有关规定采取行政措施，并给予行政处罚。"},{"i":24,"n":"第二十四条","txt":"违反本办法第十四条和第十五条规定的，由海河水利委员会或者天津市人民政府水行政主管部门依照《中华人民共和国水法》和《中华人民共和国防洪法》的有关规定采取行政措施，并给予行政处罚。"},{"i":25,"n":"第二十五条","txt":"海河水利委员会和天津市人民政府水行政主管部门及其工作人员不依法履行管理和监督检查职责，或者发现违法行为不予查处的，对负有责任的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"本办法所称防洪清淤排泥场，是指为维护河口行洪、排涝、纳潮畅通，实施河口清淤疏浚工程设置的贮泥场地。"},{"i":27,"n":"第二十七条","txt":"本办法自2009年7月1日起施行。"}],"zhujianghekouguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强珠江河口及其整治开发活动的管理，保障珠江河口地区的防洪安全，发挥河口综合功能，根据《中华人民共和国防洪法》、《中华人民共和国河道管理条例》制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于珠江河口的八大口门区及河口延伸区。 八大口门区：自虎门黄埔（东江北干流大盛、南支流泅盛、北江干流沙湾水道三沙口水位站）：蕉门南沙、洪奇门万顷沙西、横门水位站、磨刀门灯笼山、鸡啼门黄金、虎跳门西炮台、崖门黄冲水位站以下至伶仃洋赤湾半岛、内伶仃、横琴、三灶、高栏、荷苞、大襟岛、赤溪半岛间的连线之间的河道、水域及岸线。 河口延伸区：自上述赤湾、赤溪半岛连线以下，与从深圳河口起沿广东省与香港特别行政区水域分界线至南面海域段18号点（北纬22°08′54．5″，东经114°14′09．6″）和由18号点与外伶仃岛、横岗岛、万山岛、小襟岛南面外沿、赤溪半岛鹅头颈的连线之间的水域及岸线。 香港特别行政区管辖的珠江河口水域以及珠江河口澳门附近水域不属本办法管理范围。"},{"i":3,"n":"第三条","txt":"凡在珠江河口管理范围内进行整治开发及管理活动都必须遵守本办法。 珠江河口管理范围依照《中华人民共和国防洪法》和《中华人民共和国河道管理条例》界定。"},{"i":4,"n":"第四条","txt":"珠江河口的整治开发，必须遵循有利于泄洪、维护潮汐吞吐、便利航运、保护水产、改善生态环境的原则，统一规划，加强监督管理，保障珠江河口各水系延伸、发育过程中入海尾闾畅通。"},{"i":5,"n":"第五条","txt":"珠江河口整治开发实行水行政统一管理和分级管理相结合的管理体制。 珠江河口整治开发活动由水利部珠江水利委员会（以下简称珠江水利委员会）和广东省人民政府水行政主管部门按照本办法划定的权限实施监督管理。"},{"i":6,"n":"第六条","txt":"珠江河口整治规划是珠江河口整治开发的总体部署，是珠江河口整治开发活动和管理的基本依据。 珠江河口整治规划由水利部会同国务院有关部门和广东省人民政府制定。河口整治规划如需变动，需经原批准机关核准。 珠江河口整治规划治导线是珠江河口整治与开发工程建设的外缘控制线，未经充分科学论证并取得规划治导线原批准机关的同意，任何工程建设都不得外伸。"},{"i":7,"n":"第七条","txt":"珠江河口管理范围内的水利规划和岸线利用、航道整治、供水、水产养殖等专业规划，应与珠江河口整治规划相衔接。上述规划在报批前，应征求广东省人民政府水行政主管部门的意见，并报珠江水利委员会审查并出具书面意见。"},{"i":8,"n":"第八条","txt":"在珠江河口管理范围内开发利用滩涂，必须符合流域防洪要求，按照开发服从整治、整治与开发相结合的原则，进行科学论证，统一规划，明确开发·程序。滩涂开发利用规划在报请广东省人民政府批准前，应经广东省人民政府水行政主管部门初审后，由珠江水利委员会审查并出具书面意见。"},{"i":9,"n":"第九条","txt":"在珠江河口管理范围内规划滩涂开发利用、河道整治、航道整治、桥梁、港口、码头等建设项目时，工程规划方案应经广东省人民政府水行政主管部门初审后报珠江水利委员会就其是否符合河口整治规划的总体安排、是否超出规划治导线、是否符合防洪和河口水质要求等进行审查，并取得珠江水利委员会出具的规划意见。"},{"i":10,"n":"第十条","txt":"在珠江河口管理范围内建设防洪工程和其他水工程、滩涂开发利用工程以及跨河、穿河、穿堤、临河的桥梁、码头、道路、渡口、管道、缆线、取水、排水等工程设施，必须依照《中华人民共和国防洪法》、《中华人民共和国河道管理条例》以及国家计委、水利部联合颁布的《河道管理范围内建设项目管理的有关规定》，将其工程建设方案报水行政主管部门审查同意，并取得《防洪规划同意书》或《河道管理范围内建设项目审查同意书》（以下简称审查同意文书）。 前款大中型建设项目，经广东省人民政府水行政主管部门初审后，由珠江水利委员会审查同意。其他建设项目，由广东省人民政府水行政主管部门审查同意。"},{"i":11,"n":"第十一条","txt":"建设单位提出工程建设方案审查申请时，应提供以下文件： （一）工程建设方案审查申请书； （二）工程建设方案； （三）工程建设使用水域、滩涂、岸线的情况及防御洪涝标准与措施； （四）工程建设可能对河口泄洪、纳潮、排涝、河势稳定、堤防安全、水质产生影响的论证材料及拟采取的补救措施； （五）其他说明材料。"},{"i":12,"n":"第十二条","txt":"水行政主管部门审查工程建设方案的主要内容为： （一）是否符合防洪规划、河口整治规划，是否超出河口整治规划治导线； （二）是否妨碍河口泄洪、纳潮； （三）对河口河势稳定、水流形态、水质、冲淤变‘化有无不利影响，拟采取的补救措施是否适当； （四）对堤防、护岸和其他水利工程安全的影响及拟采取的补救措施； （五）是否妨碍防汛抢险； （六）建设项目防御洪涝的设防标准与措施是否符合要求； （七）是否影响第三人的合法水事权益； （八）是否符合其他有关规定和协议。"},{"i":13,"n":"第十三条","txt":"水行政主管部门受理建设单位申请后，同意兴建的，出具审查同意文书。不同意建设或要求就有关问题进一步修改补充后再行审查的，应当在批复中说明理由和依据。建设单位在取得河道主管机关的审查同意书后，方可开工建设。"},{"i":14,"n":"第十四条","txt":"建设单位如对建设项目的性质、规模、地点作重大变更，应当重新办理工程建设方案审查同意文书。"},{"i":15,"n":"第十五条","txt":"在珠江河口管理范围内修建各类临时建筑物，应经广东省县级以上人民政府水行政主管部门批准，具体权限由广东省人民政府水行政主管部门划定。"},{"i":16,"n":"第十六条","txt":"建设项目开工前，建设单位应当将施工安排送出具审查同意文书的水行政主管部门备案。施工安排应包括占用水域、滩涂、岸线情况或跨越河道、穿越河床的位置和界限以及施工期间防汛措施。安排施工时，应当按照水行政主管部门审查批准的位置和界限进行。"},{"i":17,"n":"第十七条","txt":"建设项目施工期间，水行政主管部门应对其是否符合审查同意文书的要求进行检查，被检查单位应当如实提供有关情况和资料。 建设项目竣工验收时，应当通知出具审查同意文书的水行政主管部门参加，水行政主管部门应当对河道和堤防安全严格把关。建设单位应在竣工验收后6个月内报送有关竣工资料。"},{"i":18,"n":"第十八条","txt":"禁止在珠江河口管理范围内建设妨碍泄洪、纳潮的建筑物、构筑物，倾倒垃圾、渣土，从事影响河势稳定、危害堤防安全和其他妨碍河口泄洪、纳潮的活动。 禁止超出整治规划治导线在主泄洪、纳潮区内种植阻碍泄洪、纳潮的林木和高秆作物。"},{"i":19,"n":"第十九条","txt":"在珠江河口管理范围内建设各类工程、开辟高速航线、从事水产养殖等，对防洪排涝、河势稳定、堤防、护岸等水利工程带来不利影响的，由业主采取补救措施，并承担相应的补偿责任。"},{"i":20,"n":"第二十条","txt":"对珠江河口管理范围内阻碍泄洪、纳潮的各类障碍物，由广东省人民政府水行政主管部门会同珠江水利委员会鉴定确认，制定拆除或改建计划，依照《中华人民共和国防洪法》的规定处置。"},{"i":21,"n":"第二十一条","txt":"广东省人民政府水行政主管部门应当会同珠江水利委员会根据珠江河口整治规划的总体安排，划定珠江河口管理范围内河道砂石的可采区、禁采区。 采砂活动必须遵循分期、分步骤和适时、适度开采的原则，经水行政主管部门批准后方可进行。批准权限由广东省人民政府水行政主管部门规定。"},{"i":22,"n":"第二十二条","txt":"对违反本办法规定的单位和个人，由珠江水利委员会和广东省县级以上人民政府水行政主管部门依照《中华人民共和国防洪法》、《中华人民共和国河道管理条例》的规定采取行政措施，并给予处罚。"},{"i":23,"n":"第二十三条","txt":"本办法由水利部负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自发布之日起施行。"}],"shengchanjianshexiangmushuitubaochifanganguanlibana75e69":[{"i":1,"n":"第一条","txt":"为了规范和加强生产建设项目水土保持方案管理，预防和治理生产建设项目可能造成的水土流失，根据《中华人民共和国水土保持法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"生产建设项目水土保持方案编报和审批、方案实施、设施验收和监督检查，适用本办法。"},{"i":3,"n":"第三条","txt":"水利部负责生产建设项目水土保持方案监督管理工作。 水利部所属流域管理机构（以下简称流域管理机构）根据法律、行政法规规定和水利部授权，负责所管辖范围内生产建设项目水土保持方案监督管理工作。 县级以上地方人民政府水行政主管部门负责本行政区域内生产建设项目水土保持方案监督管理工作。"},{"i":4,"n":"第四条","txt":"生产建设单位是生产建设项目水土流失防治的责任主体，应当加强全过程水土保持管理，优化施工工艺和时序，提高水土资源利用效率，减少地表扰动和植被损坏，及时采取水土保持措施，有效控制可能造成的水土流失。 任何单位和个人都有保护水土资源、预防和治理水土流失的义务，并有权对破坏水土资源、造成水土流失的行为进行举报。"},{"i":5,"n":"第五条","txt":"在山区、丘陵区、风沙区以及县级以上人民政府或者其授权的部门批准的水土保持规划确定的容易发生水土流失的其他区域开办可能造成水土流失的生产建设项目，生产建设单位应当编报水土保持方案。 本办法所称可能造成水土流失的生产建设项目，是指在生产建设过程中进行地表扰动、土石方挖填，并依法需要办理审批、核准、备案手续的项目。"},{"i":6,"n":"第六条","txt":"水土保持方案由生产建设单位自行或者委托具备相应技术条件和能力的单位编制。 开展水土保持方案审批、技术评审、监督检查的部门和单位不得为生产建设单位推荐或者指定水土保持方案编制单位。"},{"i":7,"n":"第七条","txt":"水土保持方案分为报告书和报告表。 征占地面积5公顷以上或者挖填土石方总量5万立方米以上的生产建设项目，应当编制水土保持方案报告书。征占地面积0.5公顷以上、不足5公顷或者挖填土石方总量1000立方米以上、不足5万立方米的生产建设项目，应当编制水土保持方案报告表。 征占地面积不足0.5公顷并且挖填土石方总量不足1000立方米的生产建设项目，不需要编制水土保持方案，但应当按照水土保持有关技术标准做好水土流失防治工作。"},{"i":8,"n":"第八条","txt":"水土保持方案应当包括水土流失预防和治理的范围、目标、措施和投资等内容。 水土保持方案报告书和报告表的具体内容和格式，由水利部规定。"},{"i":9,"n":"第九条","txt":"生产建设单位应当在生产建设项目开工建设前完成水土保持方案编报并取得批准手续。生产建设单位未编制水土保持方案或者水土保持方案未经批准的，生产建设项目不得开工建设。"},{"i":10,"n":"第十条","txt":"水土保持方案实行分级审批。 国务院或者国务院有关部门审批、核准、备案的生产建设项目，其水土保持方案由水利部审批。 县级以上地方人民政府及其有关部门审批、核准、备案的生产建设项目，其水土保持方案由同级人民政府水行政主管部门审批。 跨行政区域的生产建设项目，其水土保持方案由共同的上一级人民政府水行政主管部门审批。"},{"i":11,"n":"第十一条","txt":"生产建设单位申请审批水土保持方案的，应当向有审批权的水行政主管部门提交申请，提供水土保持方案报告书或者水土保持方案报告表一式三份。"},{"i":12,"n":"第十二条","txt":"水行政主管部门应当自收到全部申请材料之日起5个工作日内，依法作出受理或者不予受理的决定。"},{"i":13,"n":"第十三条","txt":"水行政主管部门审批水土保持方案报告书，应当自受理申请之日起10个工作日内作出行政许可决定。10个工作日内不能作出决定的，经审批部门负责人批准，可以延长10个工作日，并将延长期限的理由告知申请人。 水行政主管部门可以组织技术评审机构对水土保持方案报告书进行技术评审。技术评审费用由审批部门承担并按照有关规定纳入部门预算。技术评审所需时间不计算在本条第一款规定的期限内，但不得超过30个工作日。 水利部作出生产建设项目水土保持方案报告书审批决定前，应当征求相关流域管理机构的意见。 对水土保持方案报告表，实行承诺制管理。申请人依法履行承诺手续，水行政主管部门在受理后即时办结。"},{"i":14,"n":"第十四条","txt":"技术评审机构应当严格按照法律法规和技术标准开展技术评审，并对技术评审意见负责。 技术评审机构不得向生产建设单位、从事水土保持方案编制工作的单位收取任何费用。"},{"i":15,"n":"第十五条","txt":"水土保持方案应当符合法律法规和技术标准的要求。 存在下列情形之一的，水行政主管部门应当作出不予行政许可的决定： （一）水土流失防治目标、防治责任范围不合理的； （二）弃土弃渣未开展综合利用调查或者综合利用方案不可行，取土场、弃渣场位置不明确、选址不合理的； （三）表土资源保护利用措施不明确，水土保持措施配置不合理、体系不完整、等级标准不明确的； （四）生产建设项目选址选线涉及水土流失重点预防区、重点治理区，但未按照水土保持标准、规范等要求优化建设方案、提高水土保持措施等级的； （五）水土保持方案基础资料数据明显不实，内容存在重大缺陷、遗漏的； （六）存在法律法规和技术标准规定不得通过水土保持方案审批的其他情形的。"},{"i":16,"n":"第十六条","txt":"水土保持方案经批准后存在下列情形之一的，生产建设单位应当补充或者修改水土保持方案，报原审批部门审批： （一）工程扰动新涉及水土流失重点预防区或者重点治理区的； （二）水土流失防治责任范围或者开挖填筑土石方总量增加30%以上的； （三）线型工程山区、丘陵区部分线路横向位移超过300米的长度累计达到该部分线路长度30%以上的； （四）表土剥离量或者植物措施总面积减少30%以上的； （五）水土保持重要单位工程措施发生变化，可能导致水土保持功能显著降低或者丧失的。 因工程扰动范围减少，相应表土剥离和植物措施数量减少的，不需要补充或者修改水土保持方案。"},{"i":17,"n":"第十七条","txt":"在水土保持方案确定的弃渣场以外新设弃渣场的，或者因弃渣量增加导致弃渣场等级提高的，生产建设单位应当开展弃渣减量化、资源化论证，并在弃渣前编制水土保持方案补充报告，报原审批部门审批。"},{"i":18,"n":"第十八条","txt":"水土保持方案自批准之日起满3年，生产建设项目方开工建设的，其水土保持方案应当报原审批部门重新审核。原审批部门应当自收到生产建设项目水土保持方案之日起10个工作日内，将审核意见书面通知生产建设单位。"},{"i":19,"n":"第十九条","txt":"生产建设单位应当按照经批准的水土保持方案，采取水土流失预防和治理措施。 需要编制初步设计的生产建设项目，其初步设计应当包括水土保持篇章，明确水土流失防治措施、标准和水土保持投资，其施工图设计应当细化水土保持措施设计。 生产建设单位应当将水土保持工作任务和内容纳入施工合同，落实施工单位水土保持责任，在建设过程中同步实施水土保持方案提出的水土保持措施，保证水土保持措施的质量、实施进度和资金投入。"},{"i":20,"n":"第二十条","txt":"对可能造成严重水土流失的大中型生产建设项目，生产建设单位应当组织对生产建设活动造成的水土流失进行监测，及时定量掌握水土流失及防治状况，科学评价防治成效，按照有关规定向水行政主管部门报送监测情况。"},{"i":21,"n":"第二十一条","txt":"生产建设项目的水土保持监理，应当按照水利工程建设监理的规定和水土保持监理规范执行。"},{"i":22,"n":"第二十二条","txt":"生产建设项目投产使用前，生产建设单位应当按照水利部规定的标准和要求，开展水土保持设施自主验收，验收结果向社会公开并报审批水土保持方案的水行政主管部门备案。水行政主管部门应当出具备案回执。 其中，编制水土保持方案报告书的，生产建设单位组织第三方机构编制水土保持设施验收报告。承担生产建设项目水土保持方案技术评审、水土保持监测、水土保持监理工作的单位不得作为该生产建设项目水土保持设施验收报告编制的第三方机构。"},{"i":23,"n":"第二十三条","txt":"水土保持设施未经验收或者验收不合格的，生产建设项目不得投产使用。 存在下列情形之一的，水土保持设施验收结论应当为不合格： （一）未依法依规履行水土保持方案编报审批程序或者开展水土保持监测、监理的； （二）弃土弃渣未堆放在经批准的水土保持方案确定的专门存放地的； （三）水土保持措施体系、等级和标准或者水土流失防治指标未按照水土保持方案批复要求落实的； （四）存在水土流失风险隐患的； （五）水土保持设施验收材料明显不实、内容存在重大缺项、遗漏的； （六）存在法律法规和技术标准规定不得通过水土保持设施验收的其他情形的。"},{"i":24,"n":"第二十四条","txt":"生产建设项目水土保持设施验收合格后，生产建设单位或者运行管理单位应当依法防治生产运行过程中发生的水土流失，加强对水土保持设施的管理维护，确保水土保持设施长期发挥效益。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府水行政主管部门应当实行水土保持方案审批事项清单管理，依法公开审批范围、程序、结果，推进水土保持方案审批标准化、规范化、便利化，提高审批效率。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府水行政主管部门、流域管理机构应当按照职责加强水土保持方案全链条全过程监管，充分运用卫星遥感、无人机、大数据、“互联网+监管”等手段，对生产建设项目水土保持方案实施、水土保持监测、水土保持监理、水土保持设施验收等情况进行监督检查，对发现的问题依法依规处理。 县级以上人民政府水行政主管部门、流域管理机构在监督检查中发现生产建设项目水土保持设施自主验收存在弄虚作假或者不满足验收标准和条件而通过验收的，视同为水土保持设施验收不合格。 县级以上人民政府水行政主管部门、流域管理机构应当建立监管信息共享、违法线索互联、案件通报移送等协同监管和联动执法制度，健全行政执法与刑事司法衔接、与检察公益诉讼协作机制，做好水土保持方案监管和监督检查工作。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府水行政主管部门、流域管理机构应当依照有关规定加强对生产建设单位以及水土保持方案编制、技术评审、监测、监理、施工、验收等单位的信用监管；相关单位及其人员未按照规定开展工作或者在工作中弄虚作假、隐瞒问题、编造篡改数据的，依法纳入信用记录。"},{"i":28,"n":"第二十八条","txt":"生产建设单位应当配合水行政主管部门和流域管理机构的监督检查，需要依法改正的，应当按照要求制定改正计划和措施，在规定期限内改正。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府水行政主管部门、流域管理机构及其工作人员在水土保持方案审批和监督检查中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予政务处分。"},{"i":30,"n":"第三十条","txt":"违反本办法规定，生产建设单位有下列行为之一的，依照《中华人民共和国水土保持法》等法律法规的规定处罚： （一）依法应当编制水土保持方案的生产建设项目，未编制水土保持方案或者编制的水土保持方案未经批准而开工建设的； （二）生产建设项目的地点、规模发生重大变化，未补充、修改水土保持方案或者补充、修改的水土保持方案未经原审批机关批准的； （三）水土保持方案实施过程中，未经原审批机关批准，对水土保持措施作出重大变更的； （四）水土保持设施未经验收或者验收不合格，生产建设项目投产使用的； （五）在水土保持方案确定的专门存放地以外的区域倾倒砂、石、土、矸石、尾矿、废渣等的； （六）开办生产建设项目造成水土流失，不进行治理的。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府确定的其他水土保持方案审批部门，按照本办法的规定行使水土保持方案审批职责。"},{"i":32,"n":"第三十二条","txt":"开发区内生产建设项目水土保持方案管理的办法，由水利部另行制定。"},{"i":33,"n":"第三十三条","txt":"省级人民政府水行政主管部门可以根据本办法制定具体规定，并报水利部备案。"},{"i":34,"n":"第三十四条","txt":"本办法自2023年3月1日起施行。1995年5月30日水利部发布的《开发建设项目水土保持方案编报审批管理规定》同时废止。"}],"changjianghedaocaishaguanlitiaolishishibanfa":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国长江保护法》和《长江河道采砂管理条例》（以下简称条例）等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在长江宜宾以下干流河道内从事开采砂石（以下简称长江采砂）及其管理活动的，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"长江采砂应当坚持保护优先、科学规划、总量控制、有序开采、严格管理的原则。"},{"i":4,"n":"第四条","txt":"长江水利委员会应当加强对长江采砂的统一管理和监督检查，做好有关组织、协调、指导工作，并具体负责省际边界重点河段（名录见附录）采砂的管理和监督检查。 沿江县级以上地方人民政府水行政主管部门具体负责本行政区域内长江采砂的管理和监督检查工作。"},{"i":5,"n":"第五条","txt":"长江采砂规划是长江采砂许可、管理和监督检查的依据。长江采砂规划由长江水利委员会会同沿江省、直辖市人民政府水行政主管部门编制，依法征求有关部门和单位意见后，报国务院水行政主管部门批准。 沿江省、直辖市人民政府水行政主管部门可以拟订本行政区域内长江采砂规划实施方案，报本级人民政府批准后实施，并依法报长江水利委员会等单位备案。编制的长江采砂规划实施方案必须符合长江采砂规划的要求。 因长江河势变化、河道变迁、砂石补给、生态环境保护以及经济社会发展等情况，需要修改长江采砂规划的，由长江水利委员会依法履行报批手续。 因整修长江堤防进行吹填固基或者整治长江河道、航道采砂的，不受长江采砂规划关于采砂区、采砂量等的限制，但应当进行充分论证并按照条例和本办法的规定履行有关法定手续。"},{"i":6,"n":"第六条","txt":"每年6月1日至9月30日为长江采砂的禁止采砂期，其中，长江寸滩水文站流量大于25000立方米每秒时，为长江干流三峡库区段采砂的禁止采砂期。"},{"i":7,"n":"第七条","txt":"在本办法和长江采砂规划确定的禁采区、禁采期外增加禁采范围、延长禁采期限的，沿江省、直辖市人民政府水行政主管部门报本级人民政府决定并公告后，应当报长江水利委员会备案。"},{"i":8,"n":"第八条","txt":"长江采砂实行总量控制制度。实际审批的年度采砂总量不得超过长江采砂规划确定的年度采砂控制总量。每一可采区实际审批的年度采砂量不得超过该可采区的年度采砂控制量。 根据河势及航道变化、砂石补给、航运和采砂管理需要等情况，长江水利委员会可以依据长江采砂规划，对每一可采区的年度采砂控制量进行调整。"},{"i":9,"n":"第九条","txt":"长江采砂实行可行性论证报告制度。采砂可行性论证报告按可采区分区进行，由申请人按照要求自行或者委托有关机构编制，审批部门不得要求申请人必须委托特定中介机构提供服务。 长江水利委员会和沿江省、直辖市人民政府水行政主管部门按照管理权限，对采砂可行性论证报告进行审查。"},{"i":10,"n":"第十条","txt":"采砂可行性论证报告应当包括下列内容： （一）采砂河段河道演变分析； （二）采砂区选择原则与布置、砂石补给分析、采砂区可利用砂石总量分析、开采控制条件、堆卸砂场设置、运砂方案等； （三）采砂对河势稳定、防洪安全、供水安全、通航安全、生态环境保护和基础设施安全运行的影响分析，以及减免不利影响的对策与措施； （四）采砂作业方式、作业时间、采砂机具、现场应急处置方案等； （五）采砂作业管理措施； （六）论证的主要结论。"},{"i":11,"n":"第十一条","txt":"实施采砂许可应当遵循公开、公平、公正、非歧视的原则，依法组织河道采砂许可证的发放。 鼓励长江河道砂石统一开采管理，推进集约化、规模化、规范化开采。"},{"i":12,"n":"第十二条","txt":"在省际边界重点河段采砂的，由长江水利委员会审批发放河道采砂许可证。在省际边界重点河段范围以外采砂的，由有关省、直辖市人民政府水行政主管部门审批发放河道采砂许可证；其中单项工程吹填造地采砂规模为10万吨以上的，在批准前应当征求长江水利委员会的意见。 因整修长江堤防进行吹填固基或者整治长江河道采砂的，应当按照条例规定报长江水利委员会批准；因整治长江航道采砂的，应当事先征求长江水利委员会的意见。"},{"i":13,"n":"第十三条","txt":"从事长江采砂活动的单位和个人依照条例第十条规定提出采砂申请，长江水利委员会或者沿江省、直辖市人民政府水行政主管部门按照管理权限作出是否批准的决定。 应当由长江水利委员会审批的采砂申请实行集中受理，受理时间由长江水利委员会确定并公告。沿江省、直辖市人民政府水行政主管部门可以决定对由本部门审批的采砂申请实行集中受理。"},{"i":14,"n":"第十四条","txt":"申请从事长江采砂活动的单位和个人应当符合条例第十条规定的条件，提交下列材料： （一）采砂申请书； （二）营业执照的复印件及其他相关材料； （三）采砂活动与第三者有利害关系的，与第三者达成的协议或者有关文件； （四）采砂可行性论证报告。 采砂申请书应当包括下列内容： （一）申请单位的名称、统一社会信用代码、地址、法定代表人或者负责人的姓名和职务，申请个人的姓名、住址、身份证号码； （二）采砂的性质和种类； （三）采砂地点和范围（附具范围图和控制点坐标）； （四）年度开采量； （五）开采时限； （六）作业方式和控制开采高程； （七）砂石堆放地点和弃料处理方案； （八）采砂设备基本情况； （九）采砂技术人员基本情况； （十）其他有关事项。 进行水上作业的，申请书还应当包括船名、船号、船主姓名、船机数量、采砂功率等内容，并提供船员证书、船舶证书的复印件。"},{"i":15,"n":"第十五条","txt":"采砂申请有下列情形之一的，长江水利委员会和有关省、直辖市人民政府水行政主管部门不予批准： （一）不符合长江采砂规划确定的可采区和可采期要求的； （二）不符合年度采砂控制总量要求的； （三）采砂设备功率超过1250千瓦，不具备平缓移动开采作业方式的； （四）不符合采砂船只数量控制要求的； （五）采砂船舶、船员证书不全，未按规定标明船名、船号的； （六）无符合要求的采砂设备和采砂技术人员的； （七）有采砂失信行为或者不良记录，尚未修复的。"},{"i":16,"n":"第十六条","txt":"河道采砂许可证实行按可采区一船一证，并采用电子证照。河道采砂许可证的有效期限不得超过一个可采期，届满自行失效。 可采区累计采砂量达到河道采砂许可证规定的采砂总量时，采砂单位、个人应当终止采砂行为，负责现场监管的水行政主管部门应当及时报告发证机关，发证机关应当注销河道采砂许可证并发布公告。 可采期内出现影响长江河势稳定或者防洪安全的自然灾害或者其他重大事件，需要暂停采砂活动的，采砂单位或者个人应当及时中止采砂活动；上述影响消除后，长江水利委员会或者县级以上地方人民政府水行政主管部门及时告知采砂单位或者个人可以恢复采砂活动。"},{"i":17,"n":"第十七条","txt":"实施河道整治、航道整治等涉水工程建设或者维护性清淤疏浚项目所产生的砂石，需要上岸综合利用的，应当严格履行相关手续，纳入河道采砂监管。所利用砂石应当按照沿江省、直辖市的有关规定处置，不得擅自销售。 禁止利用河道整治、航道整治、清淤疏浚等名义开展非法采砂活动。"},{"i":18,"n":"第十八条","txt":"长江水利委员会应当组织对长江省际边界重点河段范围内可采区采砂前后河床变化进行监测。沿江省、直辖市人民政府水行政主管部门应当组织对本行政区域内长江河道可采区采砂前后河床变化进行监测，并将监测资料报长江水利委员会备案。"},{"i":19,"n":"第十九条","txt":"集中停放的采砂船舶因修理、保养、采砂作业等正当理由确需离开指定地点，跨省级行政区移动的，应当经有管辖权的省级人民政府水行政主管部门或者其他部门确认；在省、直辖市内移动的，按相应省、直辖市有关规定执行。"},{"i":20,"n":"第二十条","txt":"长江采砂实行砂石采运管理单制度，砂石采运管理单信息纳入长江河道采砂管理信息平台。具体办法由国务院水行政主管部门会同有关部门制定。"},{"i":21,"n":"第二十一条","txt":"长江水利委员会应当组织沿江省、直辖市人民政府水行政主管部门建立省际边界长江采砂管理合作机制。 长江水利委员会和沿江省、直辖市人民政府水行政主管部门之间应当及时通报采砂许可、采砂船舶登记造册、集中停放、违法行为处理等情况，互相配合，互通信息，共同加强长江采砂管理。 长江水利委员会、县级以上地方人民政府水行政主管部门应当加强长江河道采砂执法能力建设，会同有关部门建立执法协调机制，依法开展联合执法，加强行政执法与刑事司法衔接。"},{"i":22,"n":"第二十二条","txt":"长江水利委员会和县级以上地方人民政府水行政主管部门应当依法依规加强对长江采砂活动的监督检查。监督检查的主要内容包括： （一）持有河道采砂许可证或者有关批准文件的情况； （二）按照河道采砂许可证或者有关批准文件的规定进行采砂的情况； （三）执行河道砂石采运管理单制度要求的情况； （四）砂石堆放和砂石弃料清理的情况； （五）采砂船舶停放的情况； （六）疏浚砂综合利用的情况； （七）应当监督检查的其他情况。"},{"i":23,"n":"第二十三条","txt":"长江水利委员会或者县级以上地方人民政府水行政主管部门在办理非法采砂案件时，发现不属于本机关管辖的，应当依法移送有管辖权的水行政主管部门或者长江水利委员会查处。"},{"i":24,"n":"第二十四条","txt":"依照条例第十八条、第十九条规定没收的非法采砂船舶和挖掘机械等作业设备、工具，应当按照国家有关规定予以拍卖；难以拍卖或者拍卖不掉的，可以拆卸、销毁，在拆卸、销毁过程中应当避免造成环境污染。"},{"i":25,"n":"第二十五条","txt":"在省际边界重点河段采砂，违反本办法规定，有下列情形之一的，由长江水利委员会依照条例的规定予以处罚： （一）未办理河道采砂许可证，擅自采砂的； （二）虽持有河道采砂许可证，但在禁采区、禁采期采砂的； （三）未按照河道采砂许可证规定的要求采砂的； （四）伪造、变造、转让、出租、出借河道采砂许可证的。"},{"i":26,"n":"第二十六条","txt":"运砂船舶在长江采砂地点装运非法采砂船舶偷采的河砂的，属于与非法采砂船舶共同实施非法采砂行为，依照条例第十八条规定予以处罚。"},{"i":27,"n":"第二十七条","txt":"未经批准或者未按批准文件实施整修长江堤防吹填固基或者整治长江河道、航道采砂的，由长江水利委员会依照有关规定处理。"},{"i":28,"n":"第二十八条","txt":"长江省际边界重点河段范围需要调整的，应当由长江水利委员会提出修订意见，报国务院水行政主管部门批准。"},{"i":29,"n":"第二十九条","txt":"本办法自2025年1月1日起施行。2003年6月2日水利部发布的《长江河道采砂管理条例实施办法》（水利部令第19号）同时废止。 附录 长江省际边界重点河段名录 （2000国家大地坐标系） 鄂赣边界河段：左岸上起湖北省武穴市李顶武村（东经115°30′21.65″，北纬29°50′54.35″），下至湖北省武穴市龙坪镇（东经115°42′16.97″，北纬29°52′4.29″）。右岸上起江西省瑞昌市下巢湖闸（东经115°30′1.52″，北纬29°50′10.22″），下至江西省九江市柴桑区城子镇（东经115°41′36.02″，北纬29°50′19.23″）； 赣皖边界河段：左岸上起安徽省望江县龙潭口（东经116°40′0.02″，北纬30°5′19.48″），下至安徽省望江县华阳河口以上3公里处（东经116°45′7.38″，北纬30°4′45.74″）。右岸上起江西省彭泽县马垱矶"}],"changjiangliuyukongzhixingshuigongchenglianhediaodb28160":[{"i":1,"n":"第一条","txt":"为了加强长江流域控制性水工程联合调度管理，发挥控制性水工程在流域水旱灾害防御、水资源利用、水生态保护中的重要作用，根据《中华人民共和国水法》《中华人民共和国防洪法》《中华人民共和国长江保护法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"长江流域控制性水工程联合调度的组织、协调、实施和监督，适用本办法。 本办法所称控制性水工程，是指位于长江干支流和湖泊，在流域水旱灾害防御、水资源利用和水生态保护等方面具有关键作用和较大影响的水库（含水电站、航电枢纽）、蓄滞洪区、泵站、水闸、引调水工程等。 控制性水工程名录由长江水利委员会商有关部门、单位提出，报水利部批准。"},{"i":3,"n":"第三条","txt":"控制性水工程联合调度应当坚持安全第一、统筹兼顾，兴利与除害相结合，遵循电调（航调）服从水调、区域服从流域、局部服从全局的原则，处理好上下游、左右岸、干支流、单个工程调度与多工程联合调度的关系，实现多目标协同。"},{"i":4,"n":"第四条","txt":"控制性水工程联合调度实行统一调度、分级管理、分级负责。 水利部负责控制性水工程联合调度的指导协调、组织实施和监督管理。 长江水利委员会根据法律、行政法规规定和水利部授权，负责管辖范围内控制性水工程联合调度的组织实施和监督管理。 长江流域有关县级以上地方人民政府水行政主管部门按照管理权限，负责本行政区域内控制性水工程联合调度的组织实施和监督管理。"},{"i":5,"n":"第五条","txt":"控制性水工程运行管理单位应当将联合调度要求纳入水工程运行调度规程，并负责具体执行。"},{"i":6,"n":"第六条","txt":"长江水利委员会应当加强数字孪生长江建设，组织长江流域有关省级人民政府水行政主管部门和控制性水工程运行管理单位等，建设具有预报、预警、预演、预案功能的控制性水工程联合调度信息平台，提高联合调度的数字化、网络化、智能化水平。 鼓励控制性水工程运行管理单位建设数字孪生工程，接入控制性水工程联合调度信息平台，实现雨情、水情、咸情、工情、调度情况等实时传输和共享。"},{"i":7,"n":"第七条","txt":"长江水利委员会应当加强江湖关系、流量泥沙测验、咸情监测、河势演变、水文气象预报、水旱灾害防御、洪水资源化利用、生态流量（水位）、多目标联合调度等方面的关键科技问题研究，推广应用先进适用技术，提升控制性水工程联合调度的科技创新支撑能力。"},{"i":8,"n":"第八条","txt":"实施控制性水工程联合调度，应当制定联合调度运用计划。 联合调度运用计划由长江水利委员会组织长江流域有关省级人民政府水行政主管部门编制，征求相关部门、单位以及控制性水工程运行管理单位意见后，报水利部批准。"},{"i":9,"n":"第九条","txt":"编制联合调度运用计划，应当统筹控制性水工程调度规程和运行状况，依据经批准的长江防御洪水方案、长江洪水调度方案、水量分配方案、水资源调度方案、用水总量控制指标、生态流量（水位）控制指标、应急水量调度预案等，与跨流域引调水工程年度调度计划相协调。"},{"i":10,"n":"第十条","txt":"联合调度运用计划主要包括以下内容： （一）纳入联合调度的控制性水工程名录； （二）防洪、水资源、生态等调度的原则、目标和调度方案； （三）水库、河道湖泊、蓄滞洪区、泵站、水闸、引调水工程等的调度方式和调度管理权限； （四）监测计量、信息报送和共享要求等。"},{"i":11,"n":"第十一条","txt":"经批准的联合调度运用计划是开展控制性水工程联合调度的基本依据，长江水利委员会、长江流域有关县级以上地方人民政府水行政主管部门、控制性水工程运行管理单位必须严格执行。"},{"i":12,"n":"第十二条","txt":"控制性水工程运用条件等发生重大变化时，联合调度运用计划应当及时作出调整。 遇到特殊情况不能按照联合调度运用计划实施调度时，由地方负责调度的，省级水行政主管部门应当及时提出调整方案，报长江水利委员会同意后实施；由长江水利委员会负责调度的，长江水利委员会应当及时提出调整方案，报水利部同意后实施；涉及水利部调度权限的，按照程序报批后实施。"},{"i":13,"n":"第十三条","txt":"控制性水工程运行管理单位应当依据联合调度运用计划和水工程运行调度规程等，结合当年水工程运行状况和雨情、水情、咸情等情况，编制水工程年度调度方案。 控制性水工程存在病险的，运行管理单位应当对水工程汛期调度运用制定针对性的年度汛期调度方案。"},{"i":14,"n":"第十四条","txt":"长江流域防洪调度应当坚持蓄泄兼筹、以泄为主，在确保水工程安全前提下，通过河道湖泊泄水、水库群拦蓄、蓄滞洪区运用、泵站和水闸控制运用等措施，实现流域防洪目标，提高整体防洪效益，兼顾水资源综合利用要求。"},{"i":15,"n":"第十五条","txt":"水库的防洪调度按照以下分级管理权限实施： （一）三峡水库、丹江口水库由水利部、长江水利委员会按照相关调度规程实施调度，其中遭遇超标准洪水和重大突发事件时，由水利部提出调度运用方案，按照程序报送批准后执行； （二）水库承担长江干流联合防洪任务，或者水库防洪影响范围、承担的防洪任务跨省级行政区的，由长江水利委员会负责调度并报水利部备案，或者由长江水利委员会提出调度运用方案，按照程序报送批准后执行； （三）陆水水库由长江水利委员会负责调度； （四）水库防洪影响范围和承担的防洪任务不跨省级行政区域的，由所在省级人民政府水行政主管部门按照调度管理权限负责组织调度并报长江水利委员会备案，或者由省级人民政府水行政主管部门提出调度运用方案，按照程序报送批准后执行。 汛期水库水位不高于防洪限制水位、不需要实施防洪调度的，由水库运行管理单位负责调度。"},{"i":16,"n":"第十六条","txt":"蓄滞洪区的防洪运用按照以下分级管理权限实施： （一）荆江分洪区的运用，由水利部提出调度运用方案，按照程序报送批准后执行； （二）其他蓄滞洪区的运用，由长江水利委员会商蓄滞洪区所在地省级人民政府决定，并报水利部备案，或者由长江水利委员提出调度运用方案，按照程序报送批准后执行。 蓄滞洪区启用前，有关地方人民政府应当依法及时组织人员安全转移。"},{"i":17,"n":"第十七条","txt":"泵站、水闸的防洪调度按照以下分级管理权限实施： （一）长江中下游发生大洪水需要控制运用时，由长江水利委员会统一调度； （二）其他情形由有关县级以上地方人民政府水行政主管部门按照管理权限负责调度。"},{"i":18,"n":"第十八条","txt":"水利部、长江水利委员会、长江流域有关县级以上地方人民政府水行政主管部门依据经批准的洪水调度方案、联合调度运用计划以及水工程调度规程等，充分考虑流域防洪形势和汛情发展，按照调度权限实施防洪调度，组织制订实时调度方案，经调度会商后，作出调度决定，下达防洪调度指令。 防洪调度指令应当以书面形式下达；紧急情况下，可以通过电话等方式下达，并及时补发书面调度指令。防洪调度指令应当抄送调度影响范围内的有关部门和单位。 省级人民政府水行政主管部门下达的防洪调度指令，应当报水利部、长江水利委员会备案。"},{"i":19,"n":"第十九条","txt":"控制性水工程运行管理单位应当严格执行防洪调度指令，按照规定的时间节点和要求进行调度操作，做好调度记录，并及时向下达防洪调度指令的部门反馈执行情况。 特殊情况不能按照联合调度运用计划和防洪调度指令进行调度的，控制性水工程运行管理单位应当向有调度管理权限的部门提出报告，经批准后实施。遇到紧急水情工情并危及水工程安全的，控制性水工程运行管理单位可以根据相关预案，先行采取应急调度措施，并及时向有调度管理权限的部门报告。"},{"i":20,"n":"第二十条","txt":"长江流域控制性水工程实施水资源调度，应当依据经批准的联合调度运用计划、河流年度水量调度计划以及水工程调度规程等，优先满足城乡居民生活用水，保障基本生态用水，统筹农业、工业用水以及航运等需要，发挥水资源综合效益。 需要转入防洪调度的，按照防洪调度的规定执行。"},{"i":21,"n":"第二十一条","txt":"长江水利委员会、长江流域有关省级人民政府水行政主管部门在调度管理权限内负责水量调度方案、年度水量调度计划的组织实施。 调度影响范围不跨省级行政区域的，由所在省级人民政府水行政主管部门组织实施，报长江水利委员会备案；调度影响范围跨省级行政区域，或者对流域供水、灌溉、生态、发电、航运用水影响较大的，由长江水利委员会组织实施。 流域供水、灌溉、生态、发电、航运等对控制性水库和引调水工程的调度运用无特殊要求时，由控制性水工程运行管理单位按照调度规程和调度方案等负责调度。"},{"i":22,"n":"第二十二条","txt":"水库水位汛前消落，应当与长江中下游防洪相协调，由水库运行管理单位按照联合调度运用计划明确的运行控制水位、时间节点等实施。消落进度不能满足联合调度运用计划要求时，长江水利委员会或者省级人民政府水行政主管部门可以依据调度管理权限向水库运行管理单位直接下达调度指令。"},{"i":23,"n":"第二十三条","txt":"水库蓄水和供水调度由水库运行管理单位按照联合调度运用计划、年度水量调度计划等实施，满足控制断面最小下泄流量或者水量要求，保障生活、生态、生产用水安全。 汛末需要提前蓄水的，水库运行管理单位应当根据工程运行状况、雨情、水情、汛情、咸情以及相关行业用水需求，在确保水库安全和防洪安全前提下，编制水库提前蓄水计划，按照调度管理权限报水利部、长江水利委员会或者省级水行政主管部门批准后实施。 控制断面最小下泄流量或者水量达不到要求时，长江水利委员会、省级人民政府水行政主管部门可以依据调度管理权限向水库运行管理单位直接下达调度指令。"},{"i":24,"n":"第二十四条","txt":"引调水工程的水量调度应当统筹调出区域和调入区域用水需求，合理配置水资源，并按照经批准的引调水工程年度水量调度计划实施。 长江水利委员会、省级人民政府水行政主管部门依据相关法律法规规定和水利部授权，按照调度管理权限负责引调水工程水量调度的组织实施。"},{"i":25,"n":"第二十五条","txt":"发生干旱灾害，长江水利委员会、省级人民政府水行政主管部门应当依据经批准的应急水量调度预案，统筹流域或者所辖区域内的水库、湖泊等所蓄水量，开展抗旱减灾供水调度，保障生活、生产、生态等用水需求。"},{"i":26,"n":"第二十六条","txt":"当发生水污染事故、水工程事故、水上安全事故、咸潮入侵等突发事件，可能造成供水危机、危害公共安全时，长江水利委员会或者省级人民政府水行政主管部门应当按照有关规定和管理权限及时启动联合应急水量调度。 开展联合应急水量调度前，应当向有关部门和单位通报，做好协调工作，并按照有关规定及时向社会通报。"},{"i":27,"n":"第二十七条","txt":"长江水利委员会负责组织跨省河流生态流量保障和重要湖泊生态水位保障的生态调度。省级人民政府水行政主管部门负责管辖范围内河流生态流量保障和湖泊生态水位保障的生态调度。 长江水利委员会可以根据需要组织开展以促进鱼类繁殖、缓解下泄水流滞温效应、抑制水华等为目标的生态调度。 控制性水工程运行管理单位应当将生态调度纳入水工程运行调度规程，保证河流生态流量和湖泊生态水位。"},{"i":28,"n":"第二十八条","txt":"长江水利委员会、长江流域有关县级以上地方人民政府水行政主管部门下达调度指令时，应当抄送调度影响范围内的有关部门和单位。 控制性水工程运行管理单位应当严格执行调度指令，按照规定的时间节点和要求进行调度操作，做好调度记录，并及时向下达调度指令的部门反馈执行情况；遇到紧急水情工情并危及水工程安全的，可以根据相关预案，先行采取应急调度措施，并及时向有调度管理权限的部门报告。"},{"i":29,"n":"第二十九条","txt":"长江水利委员会、长江流域有关县级以上地方人民政府水行政主管部门、控制性水工程运行管理单位应当采取多种措施，完善监测体系，提升水文气象预报水平和控制性水工程联合调度数字化、网络化、智能化决策能力。"},{"i":30,"n":"第三十条","txt":"长江水利委员会、长江流域有关省级人民政府水行政主管部门负责控制性水工程联合调度信息报送与信息共享的组织、协调、指导和监督工作。 控制性水工程运行管理单位应当按照规定向有调度管理权限的水行政主管部门和长江水利委员会报送工程运行和调度执行情况。"},{"i":31,"n":"第三十一条","txt":"水利部、长江水利委员会、长江流域有关县级以上地方人民政府水行政主管部门应当按照调度管理权限加强对控制性水工程联合调度执行情况的监督检查，对发现的问题提出整改要求并督促落实。监督检查主要包括： （一）调度指令下达情况； （二）联合调度运用计划和调度指令执行情况； （三）调度相关信息发布和报送情况； （四）调度信息记录和反馈情况； （五）涉及控制性水工程联合调度的其他事项。"},{"i":32,"n":"第三十二条","txt":"长江水利委员会应当组织长江流域有关省级人民政府水行政主管部门以及控制性水工程运行管理单位对联合调度工作进行定期总结与评估。"},{"i":33,"n":"第三十三条","txt":"本办法自2023年3月1日起施行。"}],"huanghexiayoufuqiaojiansheguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强黄河河道管理，发挥河道的综合效益，根据《中华人民共和国水法》、《中华人民共和国河道管理条例》及有关黄河河道管理的规定，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于黄河下游干流河道上架设的民用浮桥。"},{"i":3,"n":"第三条","txt":"河南、山东两省交界河段的浮桥建设方案，由黄河水利委员会审查；其它河段的浮桥建设方案，分别由省黄河河务局审查。 建设单位应当按照河道管理权限，于开工前将浮桥建设方案一式五份报送当地黄河河道主管机关，经审查同意后，方可开工建设。"},{"i":4,"n":"第四条","txt":"建设方案应包括以下主要内容： 1、建设单位，施工单位，管理单位； 2、建设地点（位置）； 3、建设时间和使用期限； 4、社会效益和经济效益； 5、浮桥长度、宽度、结构、设计负荷； 6、施工安排； 7、防洪、防凌措施及责任制； 8、收费管理办法； 9、占用黄河防洪兴利工程的情况； 10、其它应予说明的事项。"},{"i":5,"n":"第五条","txt":"浮桥建设和运用不得缩窄河道，浮桥两岸不得设立永久性的桥头建筑物。"},{"i":6,"n":"第六条","txt":"浮桥建设和运用不得影响水文测验和河道观测，不得影响黄河工程管理。水文测验断面及引黄涵闸上下游各500米内不准架设浮桥。"},{"i":7,"n":"第七条","txt":"位于主航道部位的浮桥桥体应便于拆装，以满足通航的需要。抢险调船、运送料物、水文测验、河道查勘等船只急需通行时，建设单位、管理单位必须保证在船到桥位30分钟前将主航道桥体拆除，拆除宽度必须满足船只安全通过的需要。"},{"i":8,"n":"第八条","txt":"浮桥的架设必须符合防洪防凌的要求： 1、黄河伏秋大汛（7—10月）期间，不准架设新的浮桥，当预报花园口流量3000立方米／秒以上时，已架设浮桥必须在24小时内拆除；凌汛期（12月至次年2月）艾山以下河段不准架设新的浮桥，已有浮桥一律拆除；艾山以上河段已架设浮桥，当洛口河面出现淌凌时，必须在24小时之内拆除。 2、遇特殊情况，建设单位必须按照黄河河道主管机关的要求，在指定的时间内拆除浮桥。"},{"i":9,"n":"第九条","txt":"建设单位应在浮桥开工前将施工方案报送当地黄河河道主管机关备案。施工完毕后必须经河道主管机关验收合格后方可启用。"},{"i":10,"n":"第十条","txt":"浮桥在施工运用期间，建设单位应加强管理，严禁破坏河道水利工程及其附属设施，不得动用防汛料物。"},{"i":11,"n":"第十一条","txt":"黄河河道主管机关对浮桥架设和拆除实施监督管理。"},{"i":12,"n":"第十二条","txt":"凡通过黄河防洪工程的浮桥，须按规定向当地黄河河道主管机关交纳工程管理维护费用。不按规定交纳工程管理维护费用的，由黄河河道主管机关责令其交纳，并可处以罚款。其中，对非经营性的浮桥，可以处1000元以下的罚款；对经营性的浮桥，可以处10000元以上，30000元以下的罚款。"},{"i":13,"n":"第十三条","txt":"违反本办法规定，有下列行为之一者，由黄河河道主管机关责令停止违法行为，赔偿损失，采取补救措施，并依照《防洪法》和《河道管理条例》的有关规定予以处罚；对有关责任人员，由其所在单位或上级主管机关给予行政处分；违反《中华人民共和国治安管理处罚法》的，报公安机关查处；触犯刑律的，依法提请司法机关追究刑事责任。 1、未经黄河河道主管机关同意，擅自建设浮桥的； 2、浮桥不按审查同意的方案建设的； 3、因浮桥施工管理不善，造成黄河河道及工程设施受到破坏的； 4、违反黄河防汛总指挥部有关命令的； 5、阻碍执法人员依法执行公务的。"},{"i":14,"n":"第十四条","txt":"本办法由黄河水利委员会负责解释。"},{"i":15,"n":"第十五条","txt":"本办法自颁布之日起施行。"}],"huanghehekouguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强黄河河口管理，保障黄河防洪、防凌安全，促进黄河河口地区经济社会可持续发展，根据《中华人民共和国水法》、《中华人民共和国防洪法》和《中华人民共和国河道管理条例》等法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在黄河河口黄河入海河道管理范围内进行治理开发及管理活动，适用本办法。 前款所称黄河河口，是指以山东省东营市垦利县宁海为顶点，北起徒骇河口，南至支脉沟河口之间的扇形地域以及划定的容沙区范围；黄河入海河道是指清水沟河道、刁口河故道以及黄河河口综合治理规划或者黄河入海流路规划确定的其他以备复用的黄河故道。"},{"i":3,"n":"第三条","txt":"黄河河口的治理与开发，应当遵循统一规划、除害与兴利相结合、开发服从治理、治理服务开发的原则，保持黄河入海河道畅通，改善生态环境。"},{"i":4,"n":"第四条","txt":"黄河水利委员会及其所属的黄河河口管理机构按照规定的权限，负责黄河河口黄河入海河道管理范围内治理开发活动的统一管理和监督检查工作。"},{"i":5,"n":"第五条","txt":"黄河水利委员会及其所属的黄河河口管理机构以及有关部门和单位，应当运用现代科学技术，加强河口演变规律、河口治理措施、河口生态环境保护对策措施以及水沙资源利用的研究，不断提高科学治河水平。"},{"i":6,"n":"第六条","txt":"黄河河口综合治理规划由国务院水行政主管部门会同国务院有关部门和山东省人民政府，根据黄河流域综合规划编制，报国务院或者其授权的部门批准。 黄河河口综合治理规划是黄河河口治理、开发和保护的基本依据。 黄河河口综合治理规划批准前，经批准的黄河入海流路规划是黄河河口治理、开发和保护的依据。"},{"i":7,"n":"第七条","txt":"修改黄河河口综合治理规划，应当按照规划编制程序经原批准机关批准。"},{"i":8,"n":"第八条","txt":"黄河河口综合治理规划，应当与黄河河口地区国民经济和社会发展规划以及土地利用总体规划、海洋功能区划、城市总体规划和环境保护规划相协调。"},{"i":9,"n":"第九条","txt":"在黄河河口进行城市、工业、交通、农业、渔业、牧业等建设，必须符合黄河河口综合治理规划或者黄河入海流路规划，不得对流路和泥沙入海形成障碍。"},{"i":10,"n":"第十条","txt":"黄河河口入海流路淤积延伸出的土地属于国家所有，由县级以上地方人民政府根据黄河河口综合治理规划或者黄河入海流路规划统一管理。"},{"i":11,"n":"第十一条","txt":"有堤防的黄河入海河道，其管理范围为两岸堤防之间的水域、沙洲、滩地（包括可耕地）、两岸堤防及护堤地，由黄河水利委员会所属的黄河河口管理机构会同县级以上地方人民政府划定。其中，护堤地的宽度从堤脚算起，有淤临、淤背区的堤段从其坡脚算起，并应当依照下列标准划定： （一）北大堤、南大堤、防洪堤临河、背河各五十米； （二）东大堤、民坝临河七米、背河十米。 堤防护堤地地面淤高后，其宽度应维持原地面高程所划定的边界不变；大堤加培加固后，护堤地相应外延。"},{"i":12,"n":"第十二条","txt":"无堤防的黄河入海河道，其管理范围由黄河水利委员会所属的黄河河口管理机构会同县级以上地方人民政府，根据历史最高洪水位或者设计洪水位， 依照下列标准划定： （一）清水沟河道左岸自北大堤末端至清水沟北股河口（北纬37°57′02″，东经119°00′10″），右岸自防洪堤末端至宋春荣沟河口（北纬37°35′39″，东经118°57′14″）之间的容沙区； （二）刁口河河道左岸自民坝末端至挑河河口（北纬38°00′31″，东经118°33′02″），右岸自东大堤末端至神仙沟河口（北纬38°02′15″，东经118°56′49″）之间的容沙区。"},{"i":13,"n":"第十三条","txt":"其他以备复用的黄河故道，其管理范围为改道前划定的管理范围。"},{"i":14,"n":"第十四条","txt":"在清水沟河道和刁口河故道管理范围内禁止下列活动： （一）修建围堤、隔堤、阻水渠道、阻水道路等工程、生产设施； （二）在清水沟河道管理范围内种植阻碍行洪（凌）的林木和高秆作物； （三）弃置矿渣、石渣、煤灰、泥土、垃圾等； （四）在堤防和护堤地上建房、放牧、开渠、打井、挖窖、葬坟、存放物料、开采地下资源、进行考古发掘以及开展集市贸易活动等； （五）损坏堤防上的设施、标志桩、水文和测量标志以及通信、铁路等附属设施； （六）清洗装贮过油类或者有毒污染物的车辆、容器。"},{"i":15,"n":"第十五条","txt":"在清水沟河道和刁口河故道管理范围内进行下列活动，应当报经黄河水利委员会或者其所属的黄河河口管理机构批准： （一）爆破、钻探； （二）在河道滩地安排货场存放物料； （三）在河道滩地开采地下资源及进行考古发掘； （四）从事挖河、开渠、堵复河汊、筑堤围地、筑堤蓄水以及其他影响防洪、防凌安全的活动。"},{"i":16,"n":"第十六条","txt":"在清水沟河道和刁口河故道管理范围内采砂、取土的，应当按照国家有关规定报经黄河水利委员会或者其所属的黄河河口管理机构批准。 在清水沟河道和刁口河故道管理范围内采砂、取土，不得影响河势稳定和危及河道工程安全。黄河水利委员会应当划定禁采区和规定禁采期，并予以公告。"},{"i":17,"n":"第十七条","txt":"在清水沟河道和刁口河故道管理范围内，从事河道整治以及建设跨河、穿河、穿堤、临河的桥梁、码头、渡口、道路、管道、缆线、取水、排水、排污、海岸防护整治工程等各类建筑物、构筑物，由黄河水利委员会及其所属的黄河河口管理机构，按照河道管理范围内建设项目管理等有关规定实施管理。"},{"i":18,"n":"第十八条","txt":"清水沟河道管理范围内已修建的本办法第十七条所列工程设施，出现影响河道行水、输沙、泄洪、排凌的，原工程建设单位或主管部门应当按照黄河水利委员会或者其所属的黄河河口管理机构的要求，进行改建或者拆除，并承担费用。"},{"i":19,"n":"第十九条","txt":"清水沟河道和刁口河故道管理范围内已修建的建设项目设计使用年限期满后，影响黄河防洪和占用河道、水工程及其附属设施的部分，有关单位或者个人应当及时拆除，恢复原状。确需超期使用的，有关单位或者个人应当按照河道管理范围内建设项目管理等规定重新办理审查手续。"},{"i":20,"n":"第二十条","txt":"刁口河故道以及黄河河口综合治理规划或者黄河入海流路规划确定的其他以备复用的黄河故道管理范围内的建设项目的建设，不得影响备用河道的使用。 对已经修建的建设项目，由黄河水利委员会所属的黄河河口管理机构登记备案。对影响备用河道使用的建设项目和阻水林木，黄河水利委员会或者其所属的黄河河口管理机构应当责令建设或者使用单位在备用河道启用前予以改建、拆除或者清除。"},{"i":21,"n":"第二十一条","txt":"黄河河口综合治理规划或者黄河入海流路规划确定的其他以备复用的黄河故道应当保持原状，不得擅自开发利用。确需开发利用的，应当报经黄河水利委员会所属的黄河河口管理机构批准。开发利用活动造成黄河故道损坏或淤积的，由责任者负责修复、清淤，并承担费用。"},{"i":22,"n":"第二十二条","txt":"黄河入海河道整治与建设，应当服从黄河河口综合治理规划或者黄河入海流路规划，符合国家规定的防洪标准等有关技术要求。"},{"i":23,"n":"第二十三条","txt":"黄河入海河道的治理工程，应当纳入国家基本建设计划，按照基本建设程序统一组织实施。"},{"i":24,"n":"第二十四条","txt":"黄河水利委员会及其所属的黄河河口管理机构应当根据黄河河口综合治理规划或者黄河入海流路规划，对现行的清水沟河道进行清淤疏浚，延长其使用年限。"},{"i":25,"n":"第二十五条","txt":"黄河入海河道管理范围内的引黄涵闸、大堤、险工及控导（护滩）等防洪工程以及入海河道治理工程，需要由黄河水利委员会所属的黄河河口管理机构统一管理的，须经黄河水利委员会报国务院水行政主管部门批准。 按照前款规定由黄河水利委员会所属的黄河河口管理机构统一管理的工程，其维修养护岁修资金，按照国务院办公厅转发的《水利工程管理体制改革实施意见》的规定筹集。 其他各类工程设施，由建设单位自行管理维护，黄河水利委员会或者其所属的黄河河口管理机构有权对其防汛和运行情况进行监督检查。"},{"i":26,"n":"第二十六条","txt":"刁口河故道以及黄河河口综合治理规划或者黄河入海流路规划确定的其他以备复用的黄河故道管理范围内原有的防洪工程设施及防汛储备物料，由黄河水利委员会所属的黄河河口管理机构统一管理使用，任何单位和个人不得侵占或者破坏。"},{"i":27,"n":"第二十七条","txt":"对违反本办法规定的行为，由黄河水利委员会或者其所属的黄河河口管理机构依照有关法律法规的规定采取行政措施，给予行政处罚。"},{"i":28,"n":"第二十八条","txt":"黄河水利委员会或者其所属的黄河河口管理机构及其工作人员不依法履行管理和监督检查职责，或者发现违法行为不予查处的，对负有责任的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"本办法所称容沙区，是指黄河河口综合治理规划或者黄河入海流路规划确定的、无堤防控制以下河道至浅海区需要沉沙的区域。 前款所称浅海区，由山东省海洋行政主管部门和黄河水利委员会所属的黄河河口管理机构共同组织划定，并报经山东省人民政府批准。"},{"i":30,"n":"第三十条","txt":"本办法由国务院水行政主管部门负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2005年1月1日起施行。"}],"heiheganliushuiliangdiaoduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强黑河干流水量统一调度，合理配置黑河流域水资源，促进流域经济社会发展和生态环境改善，根据《中华人民共和国水法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"黑河流域的青海省、甘肃省、内蒙古自治区（以下称三省区）和东风场区的黑河干流水量调度和管理，适用本办法。"},{"i":3,"n":"第三条","txt":"国家对黑河干流水量实行统一调度，遵循总量控制、分级管理、分级负责的原则。 实施黑河干流水量调度，应当首先满足城乡居民生活用水，合理安排农业、工业、生态环境用水。"},{"i":4,"n":"第四条","txt":"水利部负责组织、协调、监督、指导黑河干流水量调度工作。 黄河水利委员会及其所属的黑河流域管理局依照本办法规定，负责黑河干流水量调度的组织实施和监督检查工作。 三省区有关县级以上地方人民政府水行政主管部门和东风场区水务部门按照规定的权限，负责所辖范围内黑河干流水量调度的实施和监督检查工作。"},{"i":5,"n":"第五条","txt":"黑河干流年度水量调度方案、月水量调度方案和实时调度指令的执行，实行地方人民政府行政首长负责制和黄河水利委员会、黑河流域管理局、东风场区主要领导以及水库、水电站主管部门或者单位主要领导负责制。 三省区有关县级以上地方人民政府水行政主管部门、东风场区水务部门、水库和水电站主管部门或者单位负责落实所辖范围内实施水量调度的责任，明确责任人。责任人名单应当逐级上报，由黄河水利委员会汇总上报水利部，向社会公告。"},{"i":6,"n":"第六条","txt":"在黑河流域新建、改建、扩建建设项目的水资源论证和取水许可制度的实施，由黄河水利委员会、黑河流域管理局以及三省区有关县级以上地方人民政府水行政主管部门按照《取水许可和水资源费征收管理条例》和水利部授予的权限办理。"},{"i":7,"n":"第七条","txt":"黑河流域内批准取水的总耗水量不得超过本流域水资源可利用量，三省区和东风场区批准取水的总水量不得超过国家规定的相应区域的取水许可总量控制指标。 在黑河流域取水，不得用于扩大农田灌溉面积。 黄河水利委员会、黑河流域管理局按照黑河流域取水许可总量控制的要求，负责黑河流域取水许可的监督管理。"},{"i":8,"n":"第八条","txt":"国务院批准的黑河干流水量分配方案和水利部批准的黑河干流年度水量调度方案是黑河干流水量调度的依据，有关地方人民政府、东风场区、黄河水利委员会及其所属的黑河流域管理局必须执行。"},{"i":9,"n":"第九条","txt":"黑河干流年度水量调度方案由黑河流域管理局商三省区人民政府水行政主管部门和东风场区水务部门编制，经黄河水利委员会审核后报水利部批准。 黑河干流年度水量调度方案根据国务院批准的黑河干流水量分配方案、三省区和东风场区用水计划建议、水库和水电站运行计划建议、莺落峡水文断面年度预测来水量，按照丰增枯减的原则编制。"},{"i":10,"n":"第十条","txt":"三省区人民政府水行政主管部门、东风场区水务部门、水库和水电站主管部门或者单位应当于每年3月1日前向黑河流域管理局报送年度用水计划建议和水库、水电站运行计划建议。"},{"i":11,"n":"第十一条","txt":"黑河干流水量调度按照年度水量调度方案、月水量调度方案和实时调度指令相结合的方式调度，实行年度断面水量控制和区域用水总量控制，逐月滚动修正。 黑河干流水量调度年度为当年11月11日至次年11月10日。其中，当年11月11日至次年6月30日为一般调度期，7月1日至11月10日为关键调度期。"},{"i":12,"n":"第十二条","txt":"在一般调度期，三省区有关县级以上地方人民政府水行政主管部门和东风场区水务部门应当根据年度水量调度方案及控制断面下泄水量的要求，合理安排各时段取水计划，必要时应采取全线闭口、集中下泄或者限制取水等措施。"},{"i":13,"n":"第十三条","txt":"关键调度期月水量调度方案由黑河流域管理局依据水利部批准的黑河干流年度水量调度方案，在本调度年度前期莺落峡、正义峡水文断面实测水量和后期莺落峡水文断面预测来水的基础上，商三省区人民政府水行政主管部门和东风场区水务部门制定；协商未能达成一致意见的，由黑河流域管理局上报黄河水利委员会决定，并由黄河水利委员会报水利部备案。 黑河流域管理局应当于每月5日前下达当月水量调度方案。"},{"i":14,"n":"第十四条","txt":"在关键调度期，三省区人民政府水行政主管部门、东风场区水务部门、水库和水电站主管部门或者单位应当于每月2日前向黑河流域管理局报送上月用水情况及当月用水计划建议和水库、水电站运行计划建议。"},{"i":15,"n":"第十五条","txt":"关键调度期水量调度，由三省区有关县级以上地方人民政府水行政主管部门和东风场区水务部门根据月水量调度方案，采取全线闭口、集中下泄或者限制取水等措施，保证各控制断面当月下泄水量指标的落实。 黑河流域管理局根据实时水情、雨情、旱情、墒情、水库、水电站蓄水量和用水等情况，可以对已下达的月水量调度方案作出调整，下达实时调度指令。"},{"i":16,"n":"第十六条","txt":"当莺落峡水文断面流量超过150立方米每秒时，实施洪水期水量调度。 洪水期水量调度，由黑河流域管理局下达实时调度指令，三省区有关县级以上地方人民政府水行政主管部门和东风场区水务部门应当采取全线闭口、集中下泄或者限制取水等措施，负责组织实施所辖范围的水量调度。"},{"i":17,"n":"第十七条","txt":"流域内有关地区出现危及城乡生活供水安全等紧急情形或者预测年度正义峡水文断面少下泄水量可能超过年度水量调度方案中确定的控制指标的5%时，可以按照黑河干流应急水量调度预案，实施应急水量调度。 应急水量调度，由黑河流域管理局报黄河水利委员会批准后实施。 三省区县级以上地方人民政府水行政主管部门、东风场区水务部门、水库和水电站主管部门或者单位，按照应急水量调度实施方案和黑河流域管理局下达的实时调度指令，负责实施所辖范围内的应急水量调度，黑河流域管理局负责监督检查。 应急水量调度采用日调节的调度措施，优先保障生活用水，严格控制其他用水。 实施应急水量调度期间，三省区人民政府水行政主管部门、东风场区水务部门、水库和水电站主管部门或者单位应当每日向黑河流域管理局报送取（退）水量、水库和水电站蓄水量、坝前水位及进（出）库流量等相关资料。"},{"i":18,"n":"第十八条","txt":"黑河干流应急水量调度预案由黑河流域管理局会同三省区人民政府水行政主管部门、东风场区水务部门、水库和水电站主管部门或者单位编制，经黄河水利委员会审核后报水利部批准。 三省区人民政府水行政主管部门、东风场区水务部门、水库和水电站主管部门或者单位，应当根据批准的黑河干流应急水量调度预案制定实施方案，并报黑河流域管理局备案。"},{"i":19,"n":"第十九条","txt":"实施应急水量调度需要动用水库、水电站死库容的，由黑河流域管理局商三省区人民政府水行政主管部门和东风场区水务部门制定方案，经黄河水利委员会审核并报水利部批准后，由有关水库、水电站主管部门或者单位组织实施。"},{"i":20,"n":"第二十条","txt":"三省区有关县级以上地方人民政府水行政主管部门按照水量统一调度的要求，对所辖范围内的水库、水电站实施调度，水库、水电站主管部门或者单位必须服从；黑河流域管理局直接管理的水库、水电站，由黑河流域管理局实施调度。必要时，黑河流域管理局可以对有关省、自治区所辖范围内的水库、水电站下达实时调度指令。 水库、水电站主管部门或者单位应当根据黑河干流年度水量调度方案、月水量调度方案和实时调度指令安排发电、供水计划。 实施全线闭口、集中下泄期间，水库、水电站主管部门或者单位应当每日向本省、自治区人民政府水行政主管部门和黑河流域管理局报送水库、水电站蓄水量、坝前水位及进（出）库流量等相关资料。"},{"i":21,"n":"第二十一条","txt":"黑河干流水量调度分别以莺落峡、正义峡水文断面作为进入中游、下游的控制断面。在实际调度中，正义峡水文断面年度少下泄水量的误差不得超过年度水量调度方案确定的控制指标的5%。 甘肃省人民政府负责确保正义峡水文断面年度下泄水量，并确保下游鼎新灌区不超指标取水；内蒙古自治区人民政府负责合理安排管辖范围内的用水，确保输水到黑河下游东居延海，并用于生态用水；东风场区负责确保不超指标取水。"},{"i":22,"n":"第二十二条","txt":"黑河干流控制性水文断面的水文监测由所在的有关省、自治区人民政府水行政主管部门直属的水文机构承担；黄河水利委员会水文机构协助监测并负责监督，对水文监测资料进行审查，并及时报送黑河流域管理局。 三省区人民政府水行政主管部门和黄河水利委员会及其所属的黑河流域管理局按照管理权限负责落实水文监测和监督工作经费。"},{"i":23,"n":"第二十三条","txt":"三省区人民政府水行政主管部门和东风场区水务部门应当于每年11月30日前向黑河流域管理局报送上一调度年度水量调度实施情况的总结；黑河流域管理局应当于每年12月10日前向黄河水利委员会报送上一调度年度水量调度总结。"},{"i":24,"n":"第二十四条","txt":"黑河流域管理局应当于每月5日前向三省区人民政府水行政主管部门、东风场区水务部门、水库和水电站主管部门或者单位通报上月水量调度情况；每年12月31日前通报上一调度年度水量调度情况，并向社会公告。"},{"i":25,"n":"第二十五条","txt":"黑河干流水量调度实行分级督查和联合督查相结合的督查制度。 黄河水利委员会及其所属的黑河流域管理局、三省区有关县级以上地方人民政府水行政主管部门和东风场区水务部门，应当在各自的职责范围内对黑河干流水量调度实施情况进行监督检查；在实施全线闭口、集中下泄和应急水量调度期间，应当派出督查组，对取（退）水口的启闭及取（退）水情况、水库和水电站蓄泄水情况等进行巡回监督检查或者驻守监督检查；必要时，由黑河流域管理局会同有关省、自治区人民政府水行政主管部门和东风场区水务部门组成联合督查组，对黑河干流重要取（退）水口及水库、水电站实施重点监督检查。"},{"i":26,"n":"第二十六条","txt":"监督检查人员履行本办法规定的监督检查职责时，有权采取下列措施： （一）要求被检查单位提供有关文件和资料，进行查阅或者复制； （二）要求被检查单位就执行本办法的有关问题进行说明； （三）进入被检查单位的生产场所进行现场检查； （四）对取（退）水口的启闭及取（退）水情况进行现场监测； （五）责令被检查单位纠正违反本办法的行为。"},{"i":27,"n":"第二十七条","txt":"重要水文控制断面下泄水量未达到年度水量调度方案的要求，或者区域取用水量超过年度水量调度方案要求的，由黄河水利委员会对相关省、自治区或者单位予以通报。 实际取用水量超出年度水量调度方案确定的控制指标的，扣减该省、自治区或者单位下一调度年度取用水量指标；影响水量调度并造成严重后果的，应当暂停审批该省、自治区或者单位下一调度年度在黑河干流新增取水工程项目。 实际取用水量超出月水量调度方案确定的控制指标，对全年水量调度造成影响的，视情节扣减该省、自治区或者单位下一调度年度取用水量指标。 正义峡水文断面下泄水量连续3年达不到年度水量调度方案确定的控制指标时，应当暂停审批相关省在黑河干流新增取水工程项目。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定，有下列行为之一的，责令改正，予以通报批评，对负有责任的主管人员和其他直接责任人员，由其上级主管部门、单位或者监察机关依法给予处分；构成犯罪的，依法追究刑事责任： （一）不执行年度水量调度方案、月水量调度方案、应急水量调度预案及实施方案、实时调度指令的； （二）水库、水电站下泄流量和水量不符合规定的控制指标，对水量调度产生严重影响的； （三）未按要求及时上报、虚假填报或者篡改水文监测数据、取用水量数据、用水计划建议、水库和水电站运行计划建议及实施情况数据或者年度水量调度情况等资料，对水量调度产生严重影响的； （四）不履行监督检查职责，或者发现违法行为不予查处的； （五）其他滥用职权、玩忽职守、徇私舞弊的行为。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，有下列行为之一的，对负有责任的主管人员和其他直接责任人员，由其上级主管部门或者单位责令改正；情节严重的，由其上级主管部门、单位或者监察机关依法给予处分： （一）不及时编制水量调度方案的； （二）不及时下达月水量调度方案的； （三）不编制或者不及时审查应急水量调度预案及实施方案的。"},{"i":30,"n":"第三十条","txt":"违反本办法规定，有下列行为之一的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任： （一）妨碍、阻挠监督检查人员或者取水工程管理人员依法执行公务、履行职责的； （二）在水量调度中煽动群众闹事的。"},{"i":31,"n":"第三十一条","txt":"在黑河干流水量调度工作中做出显著成绩的单位和个人，由有关县级以上地方人民政府或者有关部门给予奖励。"},{"i":32,"n":"第三十二条","txt":"黑河干流水量调度文书格式及要求，由黄河水利委员会规定。"},{"i":33,"n":"第三十三条","txt":"在黑河干流水量调度中，涉及防洪、水资源管理、河道管理和水文等事项的，依照相关法律、法规和规章的规定执行。"},{"i":34,"n":"第三十四条","txt":"本办法所称全线闭口、集中下泄，是指在一定时段内，关闭中游地区的所有取水口门，集中向下游地区输水的调度措施。"},{"i":35,"n":"第三十五条","txt":"本办法自公布之日起施行。2000年6月14日水利部发布的《黑河干流水量调度管理暂行办法》（水资源〔2000〕221号）同时废止。"}]};
